Normal_String:
//0x704
Text_6E4:
.stringn "\x05FL|CHAP|BOLE||\x0C01\x0C13\x0701어이쿠야……\n"
.stringn "졌다 졌어, 항복이여.\n"
.stringn "후우, 역시\n"
.stringn "보레한테는 못 이기겠구마.\n"
.stringn "\x0713그래도 지금은 아까웠어.\n"
.stringn "아저씨도 강해졌고.\n"
.stringn "슬슬 특훈도 끝나가네.\n"
.stringn "\x0701그려?\n"
.stringn "나도 조금은 나아진 건가?\n"
.stringn "\x0713어디에 내놓아도 부끄럽지 않은\n"
.stringn "어엿한 병사라는 느낌이야.\n"
.stringn "\x0701그것참 다행이구먼.\n"
.stringn "모두의 짐이 되지 않으면\n"
.stringn "그걸로 충분하데이.\n"
.stringn "\x0713무슨 소리야.\n"
.stringn "이 정도면 종전 후에\n"
.stringn "왕궁 병사로 들어갈 수도 있을걸?\n"
.stringn "\x0701…나는 싸움이 지긋지긋혀.\n"
.stringn "이 전쟁이 끝나면\n"
.stringn "바로 제대해서 농민으로 돌아갈 거여.\n"
.stringn "\x0713…………\n"
.stringn "저기 아저씨.\n"
.stringn "솔직히 아저씨가 보기에\n"
.stringn "우리 용병은 어떻게 보여?\n"
.stringn "\x0701응?\n"
.stringn "\x0713이 세상에 용병은 널려 있지만,\n"
.stringn "대부분은 먹고 살기도 힘든 불량배들이야.\n"
.stringn "게다가 용병은 전쟁이 끝나면\n"
.stringn "변변한 일거리가 없어져서 몰락하지.\n"
.stringn "그 대부분의 말로는 마을 사람들로부터\n"
.stringn "돈을 빼앗는 도적들과 다를 바가 없어.\n"
.stringn "\x0701……보레.\n"
.stringn "\x0713우리는 그런 놈들과 달라.\n"
.stringn "하지만… 그건\n"
.stringn "겉으로만 봐서는 모르지.\n"
.stringn "가끔 거리를 돌아다니다 보면 자주 들어.\n"
.stringn "또 용병 놈들이 등쳐 먹으러 왔다…고.\n"
.stringn "나에 대해선 어떻게 말하든지 상관없지만,\n"
.stringn "동료들에게 그러는 건…… 조금 그래서.\n"
.stringn "\x0701……저기, 보레.\n"
.stringn "아무리 깨끗한 삶을 살려고 해도\n"
.stringn "누군가에게는 원망을 사 버린다.\n"
.stringn "그런 악의는 피할 수 없다고 생각혀.\n"
.stringn "하지만 나는 보레나 모두를\n"
.stringn "좋아하고, 존경도 하고, 감사하고 있데이.\n"
.stringn "그걸로 충분하지 않나.\n"
.stringn "\x0713…………\n"
.stringn "미안, 아저씨. ……고마워.\n"
.stringn "그걸로…… 충분하지.\n"
.stringn "영차, 그럼 다시 한번 힘내 볼까!\n"
.stringn "가자고!\n"
.stringn "\x0701엥!? 또, 또 하는 겨?\n"
.stringn "자, 잠깐만 기다리라, 보레!\n"
.stringn "후우 후우 후우"
db 0
.align 4
//MYELL_8_BOLE_CHAP_A

//0x2FC
Text_2DC:
.stringn "\x05FL|BOLE|CHAP||\x0C03\x0711후우 후우 후우\n"
.stringn "후우우……\n"
.stringn "미안하구먼, 보레.\n"
.stringn "늦어 버려서.\n"
.stringn "\x0703뭐, 발이 느린 건 어쩔 수 없으니까.\n"
.stringn "처음이라 어떨까 싶었는데,\n"
.stringn "아저씨, 의외로 잘 따라오네.\n"
.stringn "\x0711그려?\n"
.stringn "확실히 끈기만큼은\n"
.stringn "다른 사람보다 강할지도 모르겠구먼.\n"
.stringn "안 그래도 농사는 1년이 걸리니께.\n"
.stringn "끈기가 없다고 하면 섭섭혀.\n"
.stringn "\x0703흐~음……\n"
.stringn "저기, 밭일은 재밌어?\n"
.stringn "\x0711그야 재미있제.\n"
.stringn "날씨라든가 해충이라든가 여러 고충이 있지만,\n"
.stringn "수확할 때의 기쁨은 이루 말할 수가 없어.\n"
.stringn "\x0703그렇구나……\n"
.stringn "\x0711? 왜 그러는 겨?\n"
.stringn "\x0703아니,\n"
.stringn "용병 일과는\n"
.stringn "정반대구나 싶어서.\n"
.stringn "농민이 하는 일은 뭔가를 만드는 거잖아?\n"
.stringn "하지만 우리가 하는 일은 적을 쓰러뜨리는……\n"
.stringn "파괴적인 일들뿐이지. 그 뒤엔 남는 게 없어.\n"
.stringn "\x0711그런 식으로 말하지 말어……\n"
.stringn "사람들을 지키려고 싸우는 일이잖어.\n"
.stringn "나는 훌륭한 일이라고 생각하는디.\n"
.stringn "\x0703아, 착각하지 마.\n"
.stringn "난 이 일이 좋아서 하는 거니까.\n"
.stringn "그레일 용병단 말고 있을 곳이 없기도 하고.\n"
.stringn "그런데…… 말야.\n"
.stringn "\x0711응?\n"
.stringn "\x0703……너무 많이 쉬었는걸.\n"
.stringn "특훈 재개야. 다음으로 가자!\n"
.stringn "\x0711그, 그렇게 갑자기…\n"
.stringn "잠깐만 기다리래이~ 후우 후우"
db 0
.align 4
//MYELL_8_BOLE_CHAP_B

//0x20
Text_0:
.stringn "\x05FL|CHAP|BOLE||\x070-\x0C01\x0C13\x0701이야, 반갑구먼.\n"
.stringn "난 채프라고 혀.\n"
.stringn "너, 용병단 사람인 겨?\n"
.stringn "\x0713응? 당신은 분명\n"
.stringn "포로였던 아저씨 맞지?\n"
.stringn "난 보레야.\n"
.stringn "그레일 용병단 최고의 전사지.\n"
.stringn "\x0701호오~ 그려?\n"
.stringn "젊은 데도 대단하구먼.\n"
.stringn "\x0713뭐, 진짜 그 정도로 대단하진 않아.\n"
.stringn "근데 아저씨.\n"
.stringn "당신… 포로였던 것치고는\n"
.stringn "왠지 뚱뚱한걸.\n"
.stringn "그런 몸으로 제대로 싸울 수는 있어?\n"
.stringn "\x0701아니, 잘 싸우지도\n"
.stringn "못하제.\n"
.stringn "밭을 가는 건\n"
.stringn "문제 없었지마는.\n"
.stringn "\x0713아저씨, 농민이었어?\n"
.stringn "\x0701그려.\n"
.stringn "그나저나 이 상태로는…\n"
.stringn "모두에게 짐이 될 것 같아서\n"
.stringn "미안하구먼.\n"
.stringn "\x0713그럼 특훈하면 되지.\n"
.stringn "내가 같이 해 줄게.\n"
.stringn "\x0701차, 참말로?\n"
.stringn "그럼 미안하지만\n"
.stringn "잘 부탁혀."
db 0
.align 4
//MYELL_8_BOLE_CHAP_C

//0x1484
Text_1464:
.stringn "\x05FL|BOLE|MIST||\x0703오, 미스트.\n"
.stringn "\x0711…보레.\n"
.stringn "\x0703어, 야.\n"
.stringn "왜 그러고 있어, 괜찮아?\n"
.stringn "요즘 너답지 않다고.\n"
.stringn "무슨 일 있어?\n"
.stringn "\x0711보레에…\n"
.stringn "…흑 ………\n"
.stringn "\x0703우왁! 왜 그래!?\n"
.stringn "\x0711………많이… 있었어……\n"
.stringn "여러 가지… 잔뜩…\n"
.stringn "……나…… 나……\n"
.stringn "\x0703아… ……그래.\n"
.stringn "…뭔지는 잘 모르겠지만……\n"
.stringn "울고 싶을 때는 울어도 돼.\n"
.stringn "\x0711……흑 ………으흑\n"
.stringn "……………\n"
.stringn "\x0703진정되면\n"
.stringn "내가 얘기 들어줄 테니까.\n"
.stringn "마음껏 울고\n"
.stringn "마음껏 털어 놔.\n"
.stringn "그리고 편해지면 돼. 그렇지?\n"
.stringn "\x0711………응…… ……\n"
.stringn "………고…마워……\n"
.stringn "\x0703괜찮을 거야.\n"
.stringn "나…하고, 모두가 있으니까.\n"
.stringn "…괜찮아.\n"
.stringn "\x0711………응……"
db 0
.align 4
//MYELL_8_BOLE_MIST_A

//0x10A0
Text_1080:
.stringn "\x05FL|MIST|BOLE||\x0701어라?\n"
.stringn "어디 있지?\n"
.stringn "\x0713나 참, 어디로 간 거야……\n"
.stringn "\x0701아, 보레.\n"
.stringn "\x0713오, 미스트.\n"
.stringn "아이크 어디 있는지 알아?\n"
.stringn "\x0701아니, 나도 찾던 중이었어.\n"
.stringn "\x0713그러냐.\n"
.stringn "그 녀석 요즘\n"
.stringn "되게 바쁜가 보네.\n"
.stringn "그럼 포기하고\n"
.stringn "다른 녀석이나 찾아볼까.\n"
.stringn "\x0701훈련 상대?\n"
.stringn "\x0713그래. 역시 난\n"
.stringn "상대가 없으면 진심으로 못 하겠어.\n"
.stringn "\x0701나랑은… 안 되겠지?\n"
.stringn "\x0713응?\n"
.stringn "\x0701그, 상대가 안 된다는 건\n"
.stringn "알고 있어!\n"
.stringn "그치만… 나도\n"
.stringn "강해져야 된다고 생각해.\n"
.stringn "전장에서 살아남기 위해서… 그러니까…\n"
.stringn "\x0713그럼 부탁할게.\n"
.stringn "\x0701정말?\n"
.stringn "\x0713막대만 쥐고 있어도\n"
.stringn "허수아비보단 낫겠지.\n"
.stringn "\x0701너무해!\n"
.stringn "그래도 나는…\n"
.stringn "\x0713아빠의 딸인데, 맞지?\n"
.stringn "\x0701……우……\n"
.stringn "\x0713저번엔 미안했어.\n"
.stringn "말이 너무 심했지.\n"
.stringn "\x0701아냐… 내가\n"
.stringn "너무 들떠 있었던 건 사실이고.\n"
.stringn "듣고 나서 정신도 차렸어.\n"
.stringn "고마워, 보레.\n"
.stringn "\x0713………머\n"
.stringn "멍청아…!\n"
.stringn "갑자기 뭐라는 거야……\n"
.stringn "\x0701뭐라니 고맙다고…\n"
.stringn "아, 뭐야.\n"
.stringn "보레 왜 얼굴 빨개진 건데?\n"
.stringn "\x0713시끄러워!\n"
.stringn "\x0701아, 잠깐!\n"
.stringn "어디 가는 거야?\n"
.stringn "훈련해야지!?"
db 0
.align 4
//MYELL_8_BOLE_MIST_B

//0xD44
Text_D24:
.stringn "\x05FL|BOLE|?|MIST||\x0706얍!\n"
.stringn "핫!\n"
.stringn "으랴앗! ……영차.\n"
.stringn "후우…… 오늘은 이 정도면 되겠지.\n"
.stringn "요즘은 할 마음도 안 들고,\n"
.stringn "훈련은 여기까지……\n"
.stringn "\x0717보레!\n"
.stringn "똑바로 안 해!\n"
.stringn "\x0C06\x0703켁!?\n"
.stringn "제, 제대로 하고 있다고\n"
.stringn "티아마트씨…… 어라?\n"
.stringn "\x072-\x0721큭 큭\n"
.stringn "\x0703야!\n"
.stringn "얌마, 거기 서 미스트!\n"
.stringn "\x0C21\x0720훈련을 빼먹으려던\n"
.stringn "보레 잘못이지.\n"
.stringn "그렇게 땡땡이치다간\n"
.stringn "조만간 내가 더\n"
.stringn "강해지게 될걸.\n"
.stringn "\x0703그럴 리가 없잖아.\n"
.stringn "뻔뻔한 것도 정도가 있지.\n"
.stringn "\x0720그치만, 나\n"
.stringn "우리 아빠의 딸인데?\n"
.stringn "싸우는 재능은 있을 거라고 생각해.\n"
.stringn "\x0703……웃기시네.\n"
.stringn "전장에서 살아남을 수 있을지 없을지는\n"
.stringn "실전 경험이 얼마나 있느냐에 달렸어.\n"
.stringn "재능이 있다고\n"
.stringn "자만하다간 죽을걸.\n"
.stringn "\x0720왜 그래… 평소처럼 장난친 거잖아.\n"
.stringn "그렇게 무서운 얼굴 하지 마.\n"
.stringn "\x0703우리는 장난으로 싸우고 있는 게 아니야!\n"
.stringn "알았으면 저리 가.\n"
.stringn "훈련에 방해돼.\n"
.stringn "\x0720………미안.\n"
.stringn "\x0703………………"
db 0
.align 4
//MYELL_8_BOLE_MIST_C

//0x1E44
Text_1E24:
.stringn "\x05FL|BOLE|TIAMAT||\x070-\x0703티아마트씨!\n"
.stringn "겨우 찾았다……\n"
.stringn "티아마트씨는 최근 군사 회의 같은 데에만 있고\n"
.stringn "좀처럼 혼자 있지 않으니까……\n"
.stringn "\x071-\x0711뭐니, 보레.\n"
.stringn "오늘은 화낼 만한 일도 없는데.\n"
.stringn "\x0703아니, 별로 혼나고 싶은 게 아니고요.\n"
.stringn "……\n"
.stringn "티아마트씨, 지금 뭔가\n"
.stringn "갖고 싶은 거 있어요?\n"
.stringn "\x0711딱히 생각이 안 나는데…\n"
.stringn "왜?\n"
.stringn "\x0703저번에 받은 보수가 꽤 많거든요.\n"
.stringn "항상 신세를 지고 있는 티아마트 씨에게\n"
.stringn "뭐라도 사 드릴까 해서요.\n"
.stringn "\x0711후후, 한 사람 몫을 하게 됐다고 인정했더니\n"
.stringn "생각하는 것도 어른스러워졌는걸?\n"
.stringn "\x0703헤헤, 그러니까 뭐든지 말만 해 주세요.\n"
.stringn "새로운 어깨 보호대라든지, 무릎 보호대라든지,\n"
.stringn "굉장히 좋은 도끼라든지…?\n"
.stringn "\x0711마음만 받아 둘게.\n"
.stringn "자기가 번 돈이니까\n"
.stringn "자신을 위해서 사용하면 돼.\n"
.stringn "\x0703그러니까! 저는,\n"
.stringn "티아마트씨에게 뭔가를 해 주고 싶어요.\n"
.stringn "\x0711보레… 너, 설마……\n"
.stringn "\x0703저…\n"
.stringn "티아마트씨를 보면서\n"
.stringn "항상 생각했어요.\n"
.stringn "이렇게 아름다운 사람은 처음이라고.\n"
.stringn "\x0711보레, 마음은 고맙지만…\n"
.stringn "나는……\n"
.stringn "\x0703엄마라는 건\n"
.stringn "이런 느낌이구나 했죠.\n"
.stringn "\x0711………\n"
.stringn "\x0703으아! 쑥쓰러워 죽겠네!!\n"
.stringn "아, 진짜 부끄럽다.\n"
.stringn "\x0711……보레.\n"
.stringn "\x0703네?\n"
.stringn "\x0711너, 대체…\n"
.stringn "나를 몇 살이라고 생각하는 거야?\n"
.stringn "\x0703…………………\n"
.stringn "………음……\n"
.stringn "돌아가신 우리 엄마보다는… 아래?\n"
.stringn "\x0711…………\n"
.stringn "\x0703……\n"
.stringn "그건 그렇고 훈련해야지 훈련!\n"
.stringn "\x0711보레에!\n"
.stringn "거기 서어!!"
db 0
.align 4
//MYELL_8_BOLE_TIAMAT_A

//0x1AC0
Text_1AA0:
.stringn "\x05FL|TIAMAT|BOLE||\x0701보레.\n"
.stringn "\x0713티, 티아마트씨!?\n"
.stringn "아니, 땡땡이 안 쳤어요!\n"
.stringn "오늘도 제대로 기초 훈련 했는데!\n"
.stringn "\x0701아직 아무 말도 안 했어.\n"
.stringn "\x0713아, 그렇구나.\n"
.stringn "이젠 그런 흐름이\n"
.stringn "몸에 착 달라붙어서……\n"
.stringn "\x0701오늘은 화내러 온 게 아니야.\n"
.stringn "이젠 너도 잘 알고 있을 테니까.\n"
.stringn "싸움이 점점 치열해지는 와중에\n"
.stringn "늘어질 틈 따위는 없다는 걸.\n"
.stringn "\x0713……네.\n"
.stringn "\x0701얼마나 기술을 갈고닦았는가……\n"
.stringn "얼마나 육체를 단련했는가……\n"
.stringn "그것이 전장에서 목숨을 좌우하지……\n"
.stringn "……넌 이제 괜찮겠네, 보레.\n"
.stringn "그 무게를 제대로 알고 있을 테니까.\n"
.stringn "\x0713으에엑!?\n"
.stringn "\x0701뭐, 뭐야?\n"
.stringn "내가 뭐 이상한 말이라도 했어?\n"
.stringn "\x0713그야 이상하죠 티아마트씨.\n"
.stringn "그건 마치… 절\n"
.stringn "칭찬하는 것처럼 들리는데요?\n"
.stringn "\x0701칭찬하는 거 맞아.\n"
.stringn "이제야 한 사람 몫을 하게 됐잖아.\n"
.stringn "\x0713우와~…\n"
.stringn "왠지 불길한걸요…\n"
.stringn "혼나는 것보다 더 무서운데.\n"
.stringn "\x0701……그래. 그렇게나 혼나는 게\n"
.stringn "좋은 거구나……\n"
.stringn "그럼 앞으로도 사양 않고 화내도록 할게.\n"
.stringn "\x0713켁……!\n"
.stringn "아, 아니에요 티아마트씨!"
db 0
.align 4
//MYELL_8_BOLE_TIAMAT_B

//0x1700
Text_16E0:
.stringn "\x05FL|BOLE|TIAMAT||\x070353, 54, 55……\n"
.stringn "후우… 이런 운동은\n"
.stringn "혼자서 해 봤자…\n"
.stringn "상대가 없으면 의미가 없단 말이지.\n"
.stringn "그래, 아이크 녀석이라도 꼬셔서……\n"
.stringn "\x0711보레!\n"
.stringn "\x0703켁, 티아마트씨!\n"
.stringn "\x0711또 기초 훈련을 빼먹고\n"
.stringn "어디 갈 셈이야?\n"
.stringn "\x0703아니, 땡땡이가 아니라,\n"
.stringn "아이크랑 대련이라도\n"
.stringn "할까 하던 참이었어요.\n"
.stringn "실전으로 단련해야 된다고 생각하니까.\n"
.stringn "\x0711확실히, 우리들의 검술은\n"
.stringn "배운 수준에도 못 미쳐.\n"
.stringn "하지만 기초를 소홀히 하면 죽게 될 거야.\n"
.stringn "피폐해져서 제대로 판단이 안 설 때\n"
.stringn "몸에 배인 순간적인 몸놀림이\n"
.stringn "목숨을 좌우하는 일도 있는 법이니까.\n"
.stringn "\x0703하지만 상대가 없으면\n"
.stringn "별로 안 내킨다고나 할까……\n"
.stringn "\x0711곤란하네……\n"
.stringn "또 옛날처럼 진심으로\n"
.stringn "화내야 되는 걸까.\n"
.stringn "\x0703아, 아뇨 농담입니다!\n"
.stringn "지금까지 다 농담이었어요!\n"
.stringn "아아, 갑자기 엄청\n"
.stringn "훈련하고 싶은걸!\n"
.stringn "기초 훈련은 정말 재미있어요!\n"
.stringn "그쵸, 티아마트씨!\n"
.stringn "\x0711그래, 그거면 됐어.\n"
.stringn "보레, 넌 체격도\n"
.stringn "타고났으니까.\n"
.stringn "그럴 마음만 먹으면\n"
.stringn "나보다 우수한 전사가 될 수 있을 거야.\n"
.stringn "아무튼 열심히 하렴."
db 0
.align 4
//MYELL_8_BOLE_TIAMAT_C

//0x29CC
Text_29AC:
.stringn "\x05FL|VULCI|BOLE||\x0C05\x0713찾았다!\n"
.stringn "기다려 봐 우르키!\n"
.stringn "\x0705………\n"
.stringn "\x0713왜 날 피하는 거야?\n"
.stringn "내가 뭔가 잘못한 게 있으면\n"
.stringn "확실하게 말해도…\n"
.stringn "난 전혀 상관없어.\n"
.stringn "\x0C05\x0701…보레……\n"
.stringn "\x0713모처럼 라구즈인 너하고\n"
.stringn "친구가 될 수 있다고 생각했는데…\n"
.stringn "역시 내가 베오크라서\n"
.stringn "친해질 수 없다고… 생각하는 거야?\n"
.stringn "\x0701……아니…\n"
.stringn "…너는 좋은 녀석이다.\n"
.stringn "내가… 최악일 뿐이다……\n"
.stringn "\x0713그 『최악』이란 거\n"
.stringn "저번에도 말했었지?\n"
.stringn "대체 무슨 뜻이야?\n"
.stringn "\x0701………………\n"
.stringn "…네가 처음으로…\n"
.stringn "나한테 말을 걸어왔을 때,\n"
.stringn "나는… 너를 의심하고 있었다.\n"
.stringn "베오크가 라구즈인 나에게\n"
.stringn "친근하게 말을 걸며 다가오니…\n"
.stringn "뭔가 꾸미고 있는 게 틀림없다고……\n"
.stringn "\x0713응…? 그치만 우르키는\n"
.stringn "처음에 날 칭찬했었잖아?\n"
.stringn "그거… 거짓말이었어?\n"
.stringn "\x0701상대를 칭찬하는 것이\n"
.stringn "베오크의 인사법이라고 생각했다…\n"
.stringn "보레도 나에게 어울리지 않는\n"
.stringn "미사여구를 늘어놓았으니까.\n"
.stringn "\x0713그……\n"
.stringn "그건……\n"
.stringn "\x0701난 너랑 헤어지자마자…\n"
.stringn "너에 대해 조사했다.\n"
.stringn "이름은 무엇이고 어디 태생인지.\n"
.stringn "모든 것을 빈틈없이.\n"
.stringn "\x0713…………\n"
.stringn "그래서, 뭔가 찾았어?\n"
.stringn "\x0701그레일 용병단의 보레.\n"
.stringn "보이는 대로… 표리가 같은\n"
.stringn "쾌활한 전사였다.\n"
.stringn "\x0713………………\n"
.stringn "\x0701…너는 처음부터\n"
.stringn "호의를 보였지만…\n"
.stringn "나는 믿지 않았다.\n"
.stringn "의심하고 경계했지.\n"
.stringn "그래서 『최악』이라고 한 것이다.\n"
.stringn "넌 나와 우호를 다질 필요가 없어.\n"
.stringn "\x0713……베오크와 라구즈인가.\n"
.stringn "\x0701?\n"
.stringn "\x0713난 말이지, 처음에는…\n"
.stringn "우르키하고 친구가 될 수 있을지\n"
.stringn "완전 자신이 없었다고.\n"
.stringn "아이크처럼 자연스럽게…\n"
.stringn "라구즈랑 친해질 수 있을까 했지.\n"
.stringn "근데… 우연히 너하고\n"
.stringn "얘기를 해 보니\n"
.stringn "생각보다 별거 아니었다는 걸 안 거야.\n"
.stringn "그래서 기뻤어.\n"
.stringn "전장에서 널 찾아내서\n"
.stringn "일부러 가까이서 싸우고 있었지.\n"
.stringn "\x0701…보레.\n"
.stringn "\x0713베오크는 계속 라구즈와 적대해 왔어.\n"
.stringn "그러니까 우르키가 날 경계하고…\n"
.stringn "신상을 조사해 보는 건 어쩔 수 없겠지.\n"
.stringn "하지만 나한테 꿍꿍이가 없다는 걸 안 후에도\n"
.stringn "그렇게 벽을 치는 건 이해가 안 돼.\n"
.stringn "그래서는 평생 베오크와\n"
.stringn "라구즈가 서로 알아갈 수 없을 거야.\n"
.stringn "나는 그렇게 생각해…\n"
.stringn "우르키는 그래도 아직\n"
.stringn "날 피할 생각이야?\n"
.stringn "\x0701………아니.\n"
.stringn "보레, 정말로 미안했다.\n"
.stringn "네가 용서해 준다면\n"
.stringn "난 네 친구가 되고 싶다.\n"
.stringn "\x0713용서하고 자시고…\n"
.stringn "나는 처음부터\n"
.stringn "그럴 생각이었다고!"
db 0
.align 4
//MYELL_8_BOLE_VULCI_A

//0x2614
Text_25F4:
.stringn "\x05FL|BOLE|VULCI||\x070-\x0703어~이!\n"
.stringn "매 형씨!\n"
.stringn "\x0711…너였나.\n"
.stringn "전장 밖에서 만나는 건 오랜만이군.\n"
.stringn "\x0703그래.\n"
.stringn "아, 난 보레라고 해.\n"
.stringn "동료기도 하고, 『너』가 아니라\n"
.stringn "이름으로 불러 달라고?\n"
.stringn "\x0711알았다.… 난 우르키.\n"
.stringn "나도 『매 형씨』가 아니라\n"
.stringn "이름으로 불러 줬으면 좋겠군.\n"
.stringn "\x0703알았어.\n"
.stringn "그래서 우르키.\n"
.stringn "이런 곳에서 뭐 하고 있었어?\n"
.stringn "\x0711……작은 새들의 소리에 귀를 기울이고 있었다.\n"
.stringn "듣고 있으면 마음이 편해지지.\n"
.stringn "\x0703그래?\n"
.stringn "………………\n"
.stringn "안 되겠다. 나한테는 아무것도 안 들려.\n"
.stringn "너 정말 귀가 밝구나.\n"
.stringn "\x0711………\n"
.stringn "\x0703그나저나 조익족은 좋겠네~\n"
.stringn "하늘을 날 수 있다니 최강이잖아!\n"
.stringn "우르키가 싸우는 걸 가까이서\n"
.stringn "보고 있으면 굉장하다고.\n"
.stringn "라구즈의 강함을 느꼈어.\n"
.stringn "왜 베오크에게는 날개가 없는 걸까?\n"
.stringn "화신하기 전에는 비슷하게 생겼는데.\n"
.stringn "\x0711………\n"
.stringn "\x0703아, 미안. 왠지\n"
.stringn "나 혼자만 떠들고 있었네.\n"
.stringn "방해되면 그렇다고 말을…\n"
.stringn "\x0711……미안하다…\n"
.stringn "\x0703왜 그래, 갑자기?\n"
.stringn "\x0711나는… 최악이다.\n"
.stringn "\x0703자, 잠깐!\n"
.stringn "………뭐야 갑자기…"
db 0
.align 4
//MYELL_8_BOLE_VULCI_B

//0x2320
Text_2300:
.stringn "\x05FL|BOLE|VULCI||\x0703오…?\n"
.stringn "저 녀석은 우리 군의\n"
.stringn "매 라구즈잖아……\n"
.stringn "\x0711…………\n"
.stringn "\x0703우왓!?\n"
.stringn "\x0711……뭔가 볼일이 있나.\n"
.stringn "\x0703어?\n"
.stringn "\x0711부른 것 같아서 왔다.\n"
.stringn "아닌가?\n"
.stringn "\x0703뭐? 아,\n"
.stringn "설마… 아까 혼잣말한 거?\n"
.stringn "그만큼 떨어져 있었는데도 들은 거야?\n"
.stringn "\x0711선명하게.\n"
.stringn "\x0703괴, 굉장한데.\n"
.stringn "\x0711그래서…\n"
.stringn "나한테 무슨 볼일이지?\n"
.stringn "\x0703아니…… 뭐냐,\n"
.stringn "음…… 그게…\n"
.stringn "……기합이 들어간 얼굴이구나 해서……\n"
.stringn "\x0711?\n"
.stringn "……내 얼굴에 문제라도 있는 건가?\n"
.stringn "지극히 평범한 얼굴이다만.\n"
.stringn "\x0703아냐 아냐. 전혀 문제없어!\n"
.stringn "완전 세 보이고, 남자다워. 최고야!\n"
.stringn "\x0711………\n"
.stringn "\x0703…………\n"
.stringn "\x0711………너야말로,\n"
.stringn "건강하고 좋은 빛깔의 두발을 가지고 있군.\n"
.stringn "팔도 굵고 제법 강해 보여서 좋다.\n"
.stringn "\x0703응?\n"
.stringn "\x0711그럼, 오늘은 볼일이 있으니… 다음에 보지.\n"
.stringn "\x0703………………\n"
.stringn "나, 의외로\n"
.stringn "라구즈랑 잘 지낼 수 있을 것 같아, 응."
db 0
.align 4
//MYELL_8_BOLE_VULCI_C

//0x3B00
Text_3AE0:
.stringn "\x05FL|CALILL|GEOFFRAY||\x0C01\x0C13\x0701흐음, 그래서?\n"
.stringn "\x0713……그런 사정이 있어서,\n"
.stringn "공주님의 존재는 공표되지 않고…\n"
.stringn "왕궁 안쪽의 별궁에서 조용히 자라오셨던 거다.\n"
.stringn "\x0701우리 같은 평민 입장에서 보면\n"
.stringn "참 복잡한 이야기네.\n"
.stringn "모처럼 태어난 딸을\n"
.stringn "세간에 비밀로 하고 키워야 했다니…\n"
.stringn "\x0713하지만 공주님께선 결코 불행하지 않으셨다.\n"
.stringn "국왕 폐하 내외, 레닝님의\n"
.stringn "사랑을 한 몸에 받으셨고…\n"
.stringn "왕위를 이을 필요가 없다고 해도\n"
.stringn "기죽지 않으시며 지방 귀족의 영애처럼\n"
.stringn "평온하게 살고 계셨지.\n"
.stringn "\x0701그날, 데인이 쳐들어오지만 않았다면\n"
.stringn "지금까지도 그 행복은 계속됐겠지.\n"
.stringn "\x0713…………\n"
.stringn "\x0701아, 미안. 말이 심했어.\n"
.stringn "\x0713아니, 괜찮다.\n"
.stringn "\x0701으음, 지금 이야기로\n"
.stringn "공주님이 어떻게 자라오셨는지는 잘 알았어.\n"
.stringn "제프리는 공주님의 유모의 아들이었고,\n"
.stringn "어렸을 때부터 같이 놀던 친구라는 거지.\n"
.stringn "\x0713…지금 생각해 보면, 내 인생에서\n"
.stringn "가장 행복한 날들이었다.\n"
.stringn "크리미아는 평화롭고,\n"
.stringn "밝은 빛으로 가득 차 있었지.\n"
.stringn "공주님께서 계시고, 루키노 누나가 있고,\n"
.stringn "나는 두 사람의 뒤를 쫓아가고…\n"
.stringn "\x0701안 된다구. 그런 식으로\n"
.stringn "과거의 추억에 매달리지 마.\n"
.stringn "우린 아직 살아 있잖아?\n"
.stringn "이렇게 전쟁을 하면서\n"
.stringn "피땀 흘리는 나날들뿐이지만…\n"
.stringn "희망과 삶을 즐기는 마음은…\n"
.stringn "어떤 때라도 잊어선 안 돼.\n"
.stringn "\x0713…카릴 공.\n"
.stringn "미안하다, 나약한 소리를 한 거 같군.\n"
.stringn "\x0701딱히 상관없어.\n"
.stringn "난 완벽한 사람보다\n"
.stringn "어딘가 부족한 부분도 있는 사람이\n"
.stringn "인간미 있어서 좋으니까.\n"
.stringn "\x0713고맙다.\n"
.stringn "아무튼, 지금은 그저…\n"
.stringn "크리미아 부흥에 전력을 다할 뿐.\n"
.stringn "공주님에 대해선… 아무리 깊이 생각해 봤자\n"
.stringn "신분의 차는 넘을 수 없겠지.\n"
.stringn "그렇다면 적어도… 평생 곁에서 모시며,\n"
.stringn "가까이에서 공주님의 행복을 지켜보고 싶다.\n"
.stringn "그것만이… 내 소원이다.\n"
.stringn "\x0701그냥\n"
.stringn "낚아채서 도망가면 될 텐데.\n"
.stringn "……라고 해도\n"
.stringn "제프리 같은 고지식한 사람한테는 무리겠지.\n"
.stringn "알고 있어.\n"
.stringn "하지만… 왠지 안타깝네.\n"
.stringn "남의 일인데. 정말…\n"
.stringn "\x0713…………\n"
.stringn "카릴 공, 너는 좋은 사람이군.\n"
.stringn "\x0701뭐야, 이제야 눈치챘어?\n"
.stringn "나같이 좋은 여자,\n"
.stringn "요즘에는 좀처럼 없다구?\n"
.stringn "\x0713인정하지.\n"
.stringn "너는 훌륭한 여자야.\n"
.stringn "\x0701그, 그렇게 말해도\n"
.stringn "이미 늦었거든.\n"
.stringn "나는 나만을 바라봐 주고…\n"
.stringn "사랑해 주는 남자한테만 관심이 있으니까.\n"
.stringn "\x0713그렇군… 그거 아쉽게 됐어.\n"
.stringn "\x0701아하하, 우린\n"
.stringn "좋은 친구잖아?\n"
.stringn "뭐든지 상담해 줘, 힘이 되어 줄 테니까."
db 0
.align 4
//MYELL_8_CALILL_GEOFFRAY_A

//0x345C
Text_343C:
.stringn "\x05FL|CALILL|GEOFFRAY||\x070-\x0703아, 찾았다!\n"
.stringn "제프리님~!\n"
.stringn "\x071-\x0711응? 아아… 카릴 공.\n"
.stringn "무슨 일 있나?\n"
.stringn "\x0703우후후, 제대로\n"
.stringn "나를 기억해 주다니……\n"
.stringn "이거 가능성 있다고 봐도 되는 거겠지?\n"
.stringn "\x0711뭐라 얘기했었나?\n"
.stringn "\x0703아~뇨, 아무것도 아니에요.\n"
.stringn "저기, 제프리님은\n"
.stringn "크리미아 왕녀님의 기사라면서요?\n"
.stringn "그런 분과 가까워질 수 있다니,\n"
.stringn "저 무척 영광이에요!\n"
.stringn "\x0711그렇게 대단한 건 아니야.\n"
.stringn "카릴 공도 나와 같은 동료다,\n"
.stringn "신분 같은 걸로 구별하지 말고\n"
.stringn "평범하게 대해 주었으면 좋겠어.\n"
.stringn "\x0703네!? 그렇게 말하셔도… 아니지.\n"
.stringn "크흠 저야말로\n"
.stringn "잘 부탁드려요. 우후후후\n"
.stringn "\x0711그래.\n"
.stringn "\x0703그런데 제프리님.\n"
.stringn "저는 엘린시아 공주님에 대해…\n"
.stringn "잘 모르거든요……\n"
.stringn "도대체 어떤 분이신가요?\n"
.stringn "\x0711공주님께 흥미가 있는 건가?\n"
.stringn "\x0703네.\n"
.stringn "…그야, 연적이 될지도 모르니까.\n"
.stringn "\x0711지금 뭐라고 했…\n"
.stringn "\x0703아~뇨, 아무것도 얘기 안 했어요.\n"
.stringn "우리가 지켜야 할 소중한 분이시니\n"
.stringn "알아 두고 싶은 것은 당연하죠.\n"
.stringn "얘기해 주실 수 있나요?\n"
.stringn "\x0711물론이다. …다만\n"
.stringn "어떤 분이냐고 물어보니\n"
.stringn "뭐라고 대답해야 할지 모르겠군……\n"
.stringn "\x0703어째서인가요?\n"
.stringn "\x0711…어떤 말로도\n"
.stringn "공주님을 정확히 표현하는 것은 힘들다.\n"
.stringn "……어쨌든…\n"
.stringn "\x0703어쨌든?\n"
.stringn "\x0711모든 것이 훌륭하신 분이다.\n"
.stringn "가신이니까 그렇게 보는 거라고들 하지만,\n"
.stringn "결코 그렇지 않다.\n"
.stringn "무엇과도 바꿀 수 없는…\n"
.stringn "크리미아의 보물 그 자체로……\n"
.stringn "\x0703…………뭐야……\n"
.stringn "제프리님은 공주님께 푹 빠진 거야?\n"
.stringn "아~ 진짜! 어째서 이렇게\n"
.stringn "좋은 남자하고는 인연이 없는 건데!!\n"
.stringn "\x0711뭐……뭐라고!!?\n"
.stringn "기다려, 카릴 공!\n"
.stringn "오해야! 나는 그런…………\n"
.stringn "\x0703아~아…\n"
.stringn "강하신 기사님께서 당황하시기는…\n"
.stringn "정말이지 귀여워 죽겠네.\n"
.stringn "그래그래.\n"
.stringn "내 것이 될 수 없다는 건 유감이지만,\n"
.stringn "연애 얘기라면 또 카릴님의 특기 분야지.\n"
.stringn "순진한 기사님과 공주님이 이어지도록\n"
.stringn "발 벗고 나서 보실까."
db 0
.align 4
//MYELL_8_CALILL_GEOFFRAY_B

//0x31EC
Text_31CC:
.stringn "\x05FL|CALILL|GEOFFRAY||\x0701으~음… 어쩌지……\n"
.stringn "…………꺄악!?\n"
.stringn "\x0712! 위험해!\n"
.stringn "\x0701! ! !\n"
.stringn "\x0C12\x0C12\x0713괜찮나, 아가씨?\n"
.stringn "\x0701어, 어머……\n"
.stringn "아가씨라니……\n"
.stringn "괘, 괜찮아요.\n"
.stringn "성기사님 덕분에\n"
.stringn "아무래도 다치진 않은 것 같네요.\n"
.stringn "\x0713그런가. 다행이야.\n"
.stringn "생각하는 것도 좋지만, 발밑을\n"
.stringn "아무쪼록 조심하도록 해.\n"
.stringn "\x0701자, 잠깐! 잠깐만요!\n"
.stringn "\x0C13\x0714왜 그러지?\n"
.stringn "\x0701나는… 아니, 저는\n"
.stringn "카릴이라고 합니다만……\n"
.stringn "성기사님의 존함은 어떻게 되시나요?\n"
.stringn "\x0714제프리다.\n"
.stringn "그럼, 이만.\n"
.stringn "\x0701제프리님……\n"
.stringn "좋은데.\n"
.stringn "저런 고급스러운 남자야말로\n"
.stringn "이 카릴님에게 어울리는 상대지.\n"
.stringn "아아… 사랑은 정말\n"
.stringn "불쑥 찾아온다니까."
db 0
.align 4
//MYELL_8_CALILL_GEOFFRAY_C

//0x4998
Text_4978:
.stringn "\x05FL|CALILL|NEPHENEE||\x0C03\x0C11\x0703음? 네페니, 자루를 잔뜩 가져왔네.\n"
.stringn "어디 나갔다 온 거야?\n"
.stringn "\x0711근처에, 로슈 열매가……\n"
.stringn "열려서……\n"
.stringn "\x0703흐음…… 그래서,\n"
.stringn "그 로슈 열매라는 건… 뭔데?\n"
.stringn "\x0711벌레 물린 데 쓰는…… 약이에유.\n"
.stringn "\x0703흐~음, 그런 열매도 있구나.\n"
.stringn "시골의 지혜라는 건가?\n"
.stringn "나는 왕도에서 자라서 잘 모르지만.\n"
.stringn "뭐 됐어, 하나 줘 봐.\n"
.stringn "\x0711근디……\n"
.stringn "생것을 맨손으로 잘못 만지면……\n"
.stringn "피부가 까져유.\n"
.stringn "\x0703아아, 알고 있어.\n"
.stringn "이렇게 드는 거 맞지?\n"
.stringn "\x0711……어떻게 아는 거예유?\n"
.stringn "\x0703…………\n"
.stringn "\x0711왕도에서 자랐다고… 계속 그렇게 말했으면서……\n"
.stringn "\x0703시, 시끄러워!\n"
.stringn "네페니, 지금 건 비밀이다?\n"
.stringn "나는 세련된 도시 여자니까!\n"
.stringn "알았지!?\n"
.stringn "\x0711…………\n"
.stringn "\x0703뭐, 뭐 어때서.\n"
.stringn "시골뜨기 취급을 받기 싫은 건……\n"
.stringn "나도 마찬가지라는 거야.\n"
.stringn "그러니까 네 기분은… 잘 알고 있어…\n"
.stringn "\x0711…………알았어……\n"
.stringn "……하지만…… 그렇구나.\n"
.stringn "노력하면…… 카릴씨처럼\n"
.stringn "될 수 있데이…… 다행이다.\n"
.stringn "저…… 힘낼게유.\n"
.stringn "\x0703그래, 그 마음가짐이야.\n"
.stringn "좋은 남자 찾아서 마을로 돌아가자고!\n"
.stringn "힘내래이!"
db 0
.align 4
//MYELL_8_CALILL_NEPENEE_A

//0x4610
Text_45F0:
.stringn "\x05FL|CALILL|NEPHENEE||\x070-\x0C03\x0C11\x0703어머, 네페니.\n"
.stringn "요즘은 어때?\n"
.stringn "\x0711……카릴씨.\n"
.stringn "\x0703이리 와서 잠깐 얼굴 좀 들어 봐.\n"
.stringn "…으~음, 역시 그 투구가 안 된다니까.\n"
.stringn "모처럼 화장까지 해 줬는데. 연하긴 하지만.\n"
.stringn "\x0711괜찮아요……\n"
.stringn "들면…… 힐끔힐끔 볼 수 있고……\n"
.stringn "\x0703…은근슬쩍 자기가 귀엽다고\n"
.stringn "티 내는 거야?\n"
.stringn "\x0711네?\n"
.stringn "\x0703……자각이 없나 보네.\n"
.stringn "좋겠다…… 넌.\n"
.stringn "가슴도 큰 편이면서……\n"
.stringn "전부 숨기고 말이야……\n"
.stringn "왠지 좀 열받기 시작했어……\n"
.stringn "\x0711그, 그래도…… 난……\n"
.stringn "카릴씨처럼, 당당하게…… 못 산다.\n"
.stringn "시골뜨기……니까……\n"
.stringn "\x0703그렇겠지~\n"
.stringn "남의 시선을 신경 쓰면, 꽤나\n"
.stringn "자신을 꾸미기 힘들어져…\n"
.stringn "그래도 도시 사람들은 쌀쌀맞으니까 괜찮아.\n"
.stringn "남의 일 같은 건 신경 안 써.\n"
.stringn "\x0711……그래도……\n"
.stringn "카릴씨는, 친절한데……?\n"
.stringn "\x0703!\n"
.stringn "아, 아아, 그런가?\n"
.stringn "나는 도시 태생이지만, 상식인이니까!\n"
.stringn "어쨌든, 포기하지 마 네페니!\n"
.stringn "너는 귀여우니까, 알겠지?\n"
.stringn "\x0711…………네……"
db 0
.align 4
//MYELL_8_CALILL_NEPENEE_B

//0x42F8
Text_42D8:
.stringn "\x05FL|CALILL|NEPHENEE||\x0703음? 거기 너,\n"
.stringn "잠깐 기다려 봐.\n"
.stringn "\x0711……?\n"
.stringn "\x0703뭐야 뭐야,\n"
.stringn "젊은 아가씨가 그런 투구로 얼굴을 가려서야 되겠어.\n"
.stringn "화장이라도 하는 게 어때?\n"
.stringn "\x0711……딱히, 그런 건……\n"
.stringn "아무래도 좋아요……\n"
.stringn "\x0703…………\n"
.stringn "너, 태어난 곳은 어디야?\n"
.stringn "\x0711……어디든 상관없…잖아요.\n"
.stringn "\x0703붙임성 없는 아가씨네.\n"
.stringn "뭐어, 왜 그렇게\n"
.stringn "말하기 싫어하는지는 알겠어.\n"
.stringn "시골 사투리가 무심코\n"
.stringn "나올까 봐 그러는 거지?\n"
.stringn "\x0711! 어, 어떻게……\n"
.stringn "\x0703어떻게 알았냐고?\n"
.stringn "내 옛날 친구가…\n"
.stringn "너랑 똑같은 고민을 가지고 있었거든.\n"
.stringn "\x0711…………\n"
.stringn "\x0703그래,\n"
.stringn "내가 발벗고 나서 줄게.\n"
.stringn "너같이 촌스러운 애가 있으면\n"
.stringn "나까지 기운이 빠지니까.\n"
.stringn "기분 전환으로 화장하는 법을 가르쳐 줄게.\n"
.stringn "\x0711……피, 필요 없다…요.\n"
.stringn "\x0703자자, 이상한 말투 쓰지 말고.\n"
.stringn "이 카릴씨한테 전~부 맡겨 줘.\n"
.stringn "나쁜 짓은 안 할 테니까.\n"
.stringn "\x0711…………"
db 0
.align 4
//MYELL_8_CALILL_NEPENEE_C

//0x5424
Text_5404:
.stringn "\x05FL|CALILL|TOPUCK||\x0C01\x0713저기, 카릴 선생님…\n"
.stringn "내 마도, 어땠어?\n"
.stringn "\x0701…음.\n"
.stringn "\x0713……\n"
.stringn "\x0701열심히 했구나.\n"
.stringn "이제 내가 가르칠 건 없어.\n"
.stringn "\x0713해냈다!\n"
.stringn "이걸로 나도 제 몫을 하겠어!\n"
.stringn "\x0701후후, 네 덕분에\n"
.stringn "나도 자극받았어.\n"
.stringn "한 번 더 마도를 공부해 볼까\n"
.stringn "생각도 했었거든.\n"
.stringn "\x0713음…? 선생님도\n"
.stringn "아직 공부할 게 있는 거야?\n"
.stringn "\x0701무슨 소리야.\n"
.stringn "내가 알려 준 건\n"
.stringn "마도의 아주 작은 일부분이라고.\n"
.stringn "여기까진 수행을 거듭하면\n"
.stringn "누구나 습득할 수 있어.\n"
.stringn "앞으로 더 나아갈지 말지는…\n"
.stringn "자신의 자질에 달려 있지.\n"
.stringn "\x0713자질이라니…?\n"
.stringn "\x0701타고난 재능 말하는 거야.\n"
.stringn "마도의 극에 달하려면\n"
.stringn "그게 있느냐 없느냐가 중요해.\n"
.stringn "\x0713나, 나는 있어!?\n"
.stringn "내 마도의 자질은 어때…?\n"
.stringn "\x0701……유감이지만,\n"
.stringn "너도 나처럼 평범해.\n"
.stringn "대단한 자질은 없는 것 같네.\n"
.stringn "\x0713…그럼,\n"
.stringn "나는 여기까지인 거야?\n"
.stringn "아무리 노력해도\n"
.stringn "최강의 마도사가 될 순 없어?\n"
.stringn "\x0701……어떤 방법을 사용해서\n"
.stringn "마력을 높일 순 있지만\n"
.stringn "그것도 한계가 있고.\n"
.stringn "\x0713어, 어떤 방법인데!?\n"
.stringn "\x0701자기 몸에 정령을 새기는 거야.\n"
.stringn "소위 【정령의 부적】이라고 하지.\n"
.stringn "\x0713정령의… 부적?\n"
.stringn "\x0701그래.\n"
.stringn "마도의 근원은\n"
.stringn "대자연을 관장하는 정령의 힘.\n"
.stringn "그걸 몸속에 집어넣어서,\n"
.stringn "빠르게 자신의 마력을 올리는 방법이야.\n"
.stringn "간단히 말하면 자기 자신을 미끼로 삼아서\n"
.stringn "정령을 기르는 거라고 할 수 있지.\n"
.stringn "\x0713자, 잡아먹히는 거야?\n"
.stringn "\x0701영혼을 갉아먹힌다는 것 같아…\n"
.stringn "마력의 대가로 말이지.\n"
.stringn "그러니까 상당한 각오가 없다면\n"
.stringn "하지 않는 편이 좋아.\n"
.stringn "\x0713…그렇게 위험한 짓을\n"
.stringn "하는 녀석이 있어?\n"
.stringn "\x0701사실 꽤 많이들 해.\n"
.stringn "이 군의 참모 공도 아마 그럴 거고.\n"
.stringn "\x0713세네리오라는 녀석?\n"
.stringn "\x0701이마에 문양이 새겨져 있잖아.\n"
.stringn "정령과 계약하면\n"
.stringn "그런 증표가 나타나.\n"
.stringn "\x0713아, 그거구나…!\n"
.stringn "그거라면 나도 본 적 있어.\n"
.stringn "나한테 마도를 가르쳐 준\n"
.stringn "사막의 할아버지 손바닥에도 있었거든.\n"
.stringn "\x0701…베그니온이나 데인에서는,\n"
.stringn "【인붙이】라고 오해받는다는 이유로\n"
.stringn "꺼리는 사람도 많이 봤지만.\n"
.stringn "\x0713응?\n"
.stringn "뭐라고?\n"
.stringn "\x0701뭐, 아무튼\n"
.stringn "정령과의 계약은 하지 말라는 소리야.\n"
.stringn "\x0713그래도 말야…\n"
.stringn "나, 강해지고 싶은데…\n"
.stringn "\x0701계약을 하지 않아도\n"
.stringn "아직 노력할 여지는 있어.\n"
.stringn "평범한 사람들끼리\n"
.stringn "서로 돕는 거지.\n"
.stringn "\x0713그, 그렇구나.\n"
.stringn "좋아!\n"
.stringn "나, 최강의 평범한 마도사가 될 거야!!\n"
.stringn "\x0701아하하, 그 기세야."
db 0
.align 4
//MYELL_8_CALILL_TOPUCK_A

//0x5000
Text_4FE0:
.stringn "\x05FL|CALILL|TOPUCK||\x0C01\x0C13\x0701토팍!\n"
.stringn "적당히 좀 하라니까!!\n"
.stringn "\x0713상관없잖아.\n"
.stringn "빨리 다음 마법 알려 줘.\n"
.stringn "\x0701안 돼.\n"
.stringn "\x0713나 잘하고 있잖아!\n"
.stringn "화염도, 번개도, 바람도!\n"
.stringn "\x0701네 배우는 속도가 빠르다는 건 인정할게.\n"
.stringn "솔직히 대단하다고 생각해.\n"
.stringn "\x0713그치?\n"
.stringn "\x0701하지만, 알맹이가 없어.\n"
.stringn "한 번에 머리에 욱여넣어 봤자\n"
.stringn "하나하나 제대로 사용하지 못하면\n"
.stringn "습득했다고 할 순 없다고.\n"
.stringn "\x0713말은 그렇게 해 놓고\n"
.stringn "카릴은 내가 더\n"
.stringn "재능이 있는 게 부러운 거지!\n"
.stringn "추월당하는 게 싫어서 그런 거 아냐!?\n"
.stringn "\x0701…후우\n"
.stringn "알겠니? 잘 들어.\n"
.stringn "어설프게 주문을 외우다간,\n"
.stringn "언젠가 사고 난다?\n"
.stringn "\x0713사고?\n"
.stringn "\x0701마도를 오발시키는 사고.\n"
.stringn "손가락이 날아가거나…\n"
.stringn "아, 손가락뿐이면 다행이지.\n"
.stringn "팔이 사라지는 경우도 있고,\n"
.stringn "잘못하면 목숨을 잃는 경우도 있어.\n"
.stringn "\x0713가, 각오는 하고 있거든…\n"
.stringn "\x0701자기 목숨이라곤 한 적 없다.\n"
.stringn "\x0713뭐?\n"
.stringn "\x0701적을 맞히려고 했는데\n"
.stringn "아군에게 직격…\n"
.stringn "그렇게 소중한 사람을 잃는다……\n"
.stringn "\x0713……\n"
.stringn "\x0701마도는 말이지,\n"
.stringn "다른 무기하곤 달라.\n"
.stringn "사용자의 능력이 부족하면\n"
.stringn "큰 사고가 날 수도 있어.\n"
.stringn "이건 그냥 하는 말이 아니야.\n"
.stringn "\x0713……알았어.\n"
.stringn "\x0701그럼, 제대로 기초부터 해.\n"
.stringn "전장에서 아군의 발목을\n"
.stringn "잡고 싶진 않지?\n"
.stringn "\x0713응…!"
db 0
.align 4
//MYELL_8_CALILL_TOPUCK_B

//0x4D80
Text_4D60:
.stringn "\x05FL|CALILL|TOPUCK||\x0C01\x071-\x0713저기 저기,\n"
.stringn "예쁜 아줌마!\n"
.stringn "\x0701……\n"
.stringn "\x0713어라?\n"
.stringn "화려한 누나였던가?\n"
.stringn "\x0701예쁜!\n"
.stringn "누나!!\n"
.stringn "…라고 안 하면 대답 안 할 거야.\n"
.stringn "\x0713쳇\n"
.stringn "귀찮아.\n"
.stringn "\x0701그럼 관둬도 상관없는데?\n"
.stringn "나도\n"
.stringn "너 같은 꼬맹이한테\n"
.stringn "마도를 가르치는 건 사양…\n"
.stringn "\x0713예쁜 누나!\n"
.stringn "카릴씨!\n"
.stringn "부탁이니까\n"
.stringn "저한테 마도를 가르쳐 주세요!\n"
.stringn "\x0701…나 참.\n"
.stringn "계산적인 꼬맹이라니까.\n"
.stringn "그래서, 저번에 알려준 곳까지는\n"
.stringn "어떻게 됐어?\n"
.stringn "제대로 습득하지 않았다면\n"
.stringn "새로운 건 안 알려 줄 거야.\n"
.stringn "\x0713당연히 완벽하게 했지!\n"
.stringn "애초에 나,\n"
.stringn "이 책에 있는 건 전부 익혔거든.\n"
.stringn "\x0701정말이야?\n"
.stringn "\x0713지금부터 보여 줄게.\n"
.stringn "제대로 한 건지 확인해 줘?\n"
.stringn "\x0701네네."
db 0
.align 4
//MYELL_8_CALILL_TOPUCK_C

//0x63D0
Text_63B0:
.stringn "\x05FL|CHAP|NEPHENEE||\x0701어~이, 네페니.\n"
.stringn "\x071-\x0713아, 채프씨.\n"
.stringn "\x0701아까 젊은 애들한테서 들었다.\n"
.stringn "너 너무\n"
.stringn "다른 사람에게 입을 안 여는 거 아녀?\n"
.stringn "\x0713그, 그치만……\n"
.stringn "난 시골뜨기잖여,\n"
.stringn "부끄럽다 아이가……\n"
.stringn "\x0701뭐가 부끄럽단 기가,\n"
.stringn "시골이 얼마나 좋은디.\n"
.stringn "\x0713내 말투는\n"
.stringn "너무 사투리가 세다.\n"
.stringn "바보 취급 당할 기다……\n"
.stringn "채프씨처럼\n"
.stringn "평범하게 말도 잘 못 꺼내구……\n"
.stringn "\x0701무슨 말 하나 니, 이 단에는\n"
.stringn "그렇게 나쁜 사람 없다.\n"
.stringn "그렇게 딱딱하게 굴지 말고,\n"
.stringn "마을에 있을 때처럼\n"
.stringn "평범하게 하면 된데이.\n"
.stringn "\x0713…………\n"
.stringn "\x0701니는 나랑 얘기할 때는\n"
.stringn "환하게 잘 웃으면서.\n"
.stringn "그렇게 예쁜 미소를\n"
.stringn "숨기면 아깝제.\n"
.stringn "자, 시험 삼아 여기서 웃어 보는 건 어뗘?\n"
.stringn "\x0713뭐, 뭐꼬……?\n"
.stringn "\x0701자, 웃어라 웃어.\n"
.stringn "\x0713부, 부끄럽다 안 카나…… 정말.\n"
.stringn "이, 이렇게?\n"
.stringn "\x0701그래그래, 그거여.\n"
.stringn "그 미소여.\n"
.stringn "니는 얼굴이 이쁘장하니께\n"
.stringn "그러고 있으면\n"
.stringn "단의 젊은 남자들이 가만두지 않을 기다.\n"
.stringn "여기서 좋은 사람 찾아가지고\n"
.stringn "마을에 함께 돌아가는 건 어뗘?\n"
.stringn "\x0713저, 정말……\n"
.stringn "무슨 말 하는 겨, 채프씨!"
db 0
.align 4
//MYELL_8_CHAP_NEPENEE_A

//0x5EB8
Text_5E98:
.stringn "\x05FL|NEPHENEE|CHAP||\x0C03\x0711우리 병영은\n"
.stringn "대체 어디 있는 겨?\n"
.stringn "\x0703글쎄……?\n"
.stringn "\x0711다들 용케 안 헤매고\n"
.stringn "제대로 찾아가는구마.\n"
.stringn "매일매일 숙소가 바뀌니까\n"
.stringn "나는 왠지 안정되지가 않어.\n"
.stringn "\x0703어쩔 수 없다 아이가, 전쟁이다.\n"
.stringn "우리도\n"
.stringn "익숙해질 수밖에 없는 기라.\n"
.stringn "\x0711그렇구먼……\n"
.stringn "나도 니도\n"
.stringn "지금까지는 전쟁이랑\n"
.stringn "인연이 없었제.\n"
.stringn "\x0703맞다.\n"
.stringn "그래서 군에서 당연하다고 카는 게\n"
.stringn "잘 이해가 안 간데이.\n"
.stringn "\x0711그러고 보니 지원했을 때는\n"
.stringn "큰일이었제.\n"
.stringn "어찌 됐든 우린 그냥 민병이니께\n"
.stringn "사실상 마을 사람들 모임에 불과했지 않나.\n"
.stringn "이상은 있어도 힘과 기술이 없어서 곤란혀.\n"
.stringn "\x0703맞다 맞다.\n"
.stringn "장비도 수도 부족하다꼬 해서\n"
.stringn "나랑 채프씨 둘이서\n"
.stringn "활 하나만 쓰라카고.\n"
.stringn "게다가 둘 다 활 쓸 줄 모르는데, 참.\n"
.stringn "\x0711이번 전쟁은\n"
.stringn "정말로 갑작스러웠으니께.\n"
.stringn "우리가 제대로 한 훈련은\n"
.stringn "점호가 다고…\n"
.stringn "행군할 때마다 다들 도망치거나 뒤처져서\n"
.stringn "막상 싸우기 전부터 점점\n"
.stringn "사람이 줄고 있었데이.\n"
.stringn "그러니 져서 잡혀가는 것도 무리가 아녀.\n"
.stringn "그에 비하면 이 군은\n"
.stringn "엄청 우수하다 아이가.\n"
.stringn "\x0703그야 왕녀님의 군이니까 그러제.\n"
.stringn "그나저나 진짜로 어딘지 모르겠다.\n"
.stringn "\x0711뭐 괜찮다, 어쨌든 근처에 있는\n"
.stringn "누군가에게 물어보면 되니.\n"
.stringn "\x0703으, 응……\n"
.stringn "\x0711음? 왜 그려?\n"
.stringn "\x0703나…… 그다지\n"
.stringn "도시 사람하고 얘기하는 게 익숙지 않다.\n"
.stringn "\x0711무슨 말 하나 니.\n"
.stringn "언제나처럼\n"
.stringn "평범하게 말하면 되지 않나.\n"
.stringn "\x0703그, 그치만……\n"
.stringn "난 시골뜨기다……"
db 0
.align 4
//MYELL_8_CHAP_NEPENEE_B

//0x5BF8
Text_5BD8:
.stringn "\x05FL|NEPHENEE|CHAP||\x070-\x0C03\x071-\x0711오늘은 날씨가 좋구먼,\n"
.stringn "네페니.\n"
.stringn "\x0703응응, 증말로.\n"
.stringn "\x0711네페니,\n"
.stringn "너네 집은 어뗘?\n"
.stringn "지금쯤이면 밭 수확에 힘쓸 때인가?\n"
.stringn "\x0703응응, 그렇데이.\n"
.stringn "여동생과 남동생들이 어무이 일손으로 불려가서\n"
.stringn "분명 불평하고 있을 기다.\n"
.stringn "\x0711하하하, 그야 한창 놀고 싶을 때니께.\n"
.stringn "네페니네 집은 가족이 몇 명이었제?\n"
.stringn "\x0703여동생 둘에 남동생 셋.\n"
.stringn "남동생들은 세쌍둥이라,\n"
.stringn "아직 여섯 살밖에 안 된다.\n"
.stringn "\x0711딱 장난기 많을 나이구먼.\n"
.stringn "분명 집안이 북적거리겠구마.\n"
.stringn "\x0703응, 매일 어무이한테\n"
.stringn "야단맞고 있을 기다.\n"
.stringn "채프씨네는?\n"
.stringn "\x0711우리 집 애들은 좀 더 크대이.\n"
.stringn "제대로 애엄마를 도와주면\n"
.stringn "좋을 텐데 말여……\n"
.stringn "\x0703괜찮을 기다,\n"
.stringn "분명 잘하고 있겄제."
db 0
.align 4
//MYELL_8_CHAP_NEPENEE_C

//0x7210
Text_71F0:
.stringn "\x05FL|ZIHARK|CHAP||\x0C01\x071-\x0713…그래서 말이여.\n"
.stringn "첫째 딸은 나처럼 이렇게…\n"
.stringn "덩치가 크데이.\n"
.stringn "밭일도 사내놈만큼 하는 착한 아가씨라구.\n"
.stringn "너도 분명 마음에 들 거여.\n"
.stringn "\x0701아… 네.\n"
.stringn "\x0713그렇게 건성으로 대답하면 못 쓴데이.\n"
.stringn "제~대로 들어야제.\n"
.stringn "아내가 될지도 모르는\n"
.stringn "딸아이에 대한 일이니께.\n"
.stringn "\x0701채프씨……\n"
.stringn "지난번에도 말씀드렸지만,\n"
.stringn "저는 아직 가정을 가질 생각이 없어요.\n"
.stringn "\x0713얼레… 우째서?\n"
.stringn "\x0701……옛날에… 소중한 애인이 있었습니다.\n"
.stringn "사정이 있어서\n"
.stringn "함께하지 못했는데……\n"
.stringn "전 아직도 그 애한테 미련이 남았거든요.\n"
.stringn "잊을 수가 없어요.\n"
.stringn "그러니까, 채프씨의 마음은\n"
.stringn "기쁘지만… 죄송해요.\n"
.stringn "\x0713그랬구먼.\n"
.stringn "아쉬우이…\n"
.stringn "\x0701채프씨네 가족이\n"
.stringn "된다는 건…\n"
.stringn "꽤나 매력적이지만요.\n"
.stringn "\x0713……\n"
.stringn "그럼 둘째 딸은 어떤가?\n"
.stringn "나이 차가 조금 나긴 하지만,\n"
.stringn "뭐 신경 쓰지 말어.\n"
.stringn "얘가 또 마음씨가 그렇게 좋거든.\n"
.stringn "웃으면 이렇게, 통통하게 볼에 보조개가……\n"
.stringn "\x0701아니,\n"
.stringn "그런 게 아니라니까요.\n"
.stringn "곤란하게 됐네……"
db 0
.align 4
//MYELL_8_CHAP_ZIHARK_A

//0x6C5C
Text_6C3C:
.stringn "\x05FL|ZIHARK|CHAP||\x070-\x0C01\x071-\x0713이야, 지하크.\n"
.stringn "전에는 즐거웠데이.\n"
.stringn "\x0701맞아요.\n"
.stringn "채프씨는 말을 잘 하시니까\n"
.stringn "식사하는 내내 웃기만 했어요.\n"
.stringn "그렇게 즐거운 식사는 오랜만이었습니다.\n"
.stringn "\x0713그리 말해 주니 같이 가자고\n"
.stringn "말한 보람이 있구먼.\n"
.stringn "\x0701아, 그러고 보니 여기요.\n"
.stringn "제 몫입니다.\n"
.stringn "\x0713아이, 괜찮어.\n"
.stringn "내가 가자고 했으니께.\n"
.stringn "신경 쓰지 말어.\n"
.stringn "\x0701그럴 수는 없습니다.\n"
.stringn "갑작스러운 권유여서 돈을 못 드렸지만\n"
.stringn "오늘은 제대로 있거든요.\n"
.stringn "제대로 반만큼 내겠습니다.\n"
.stringn "\x0713그런 말을 들어도 말이지…\n"
.stringn "얼마 받았는지 기억도 안 난데이.\n"
.stringn "\x0701합쳐서 4하고 반 골드였습니다.\n"
.stringn "그러니까 2하고 4분의 1 골드를\n"
.stringn "드리면 빚은 남지 않죠.\n"
.stringn "\x0713허어~ 젊은데도\n"
.stringn "착실하구먼.\n"
.stringn "기억력도 좋고, 계산도 빠르구.\n"
.stringn "\x0701똑 부러진 것 천성입니다.\n"
.stringn "느긋한 용병 동료들은\n"
.stringn "꽤나 싫어하지만요.\n"
.stringn "\x0713아녀. 그거면 됐지.\n"
.stringn "잘생기고 성실하면 충분혀.\n"
.stringn "젊은 아가씨들에게\n"
.stringn "인기 있지 않어?\n"
.stringn "\x0701그렇지도 않습니다.\n"
.stringn "저 같은 녀석을 좋아해 주는\n"
.stringn "마음씨 착한 여성은…\n"
.stringn "좀처럼 없거든요.\n"
.stringn "\x0713허어어, 세상 일은 아무도 모르는 법이여.\n"
.stringn "나처럼 멍한 남자도\n"
.stringn "살림을 차리는데 말이제.\n"
.stringn "\x0701하하하, 채프씨는\n"
.stringn "좋은 남자예요. 제가 보장합니다.\n"
.stringn "\x0713아 맞다! 우리 딸을 데려가면 되겠데이.\n"
.stringn "\x0701네?\n"
.stringn "갑자기 무슨 말씀을 하시는 거죠?\n"
.stringn "\x0713자랑은 아니지먼,\n"
.stringn "착한 아이들 뿐이여.\n"
.stringn "나는 지하크가 마음에 들었으니,\n"
.stringn "딸내미들도 분명 마음에 들어할 겨.\n"
.stringn "\x0701채프씨, 농담은 그만…\n"
.stringn "\x0713어떤가,\n"
.stringn "첫째 딸이라면 나이도 딱\n"
.stringn "맞을 것 같은디?\n"
.stringn "\x0701아니… 곤란합니다.\n"
.stringn "전 그럴 생각은……"
db 0
.align 4
//MYELL_8_CHAP_ZIHARK_B

//0x67B0
Text_6790:
.stringn "\x05FL|ZIHARK|CHAP||\x0C03\x0711얼레……\n"
.stringn "너, 그런 데서\n"
.stringn "뭐 하는 거여?\n"
.stringn "\x0703아, 채프씨.\n"
.stringn "잠깐 어깨 보호대를 수리하고 있었어요.\n"
.stringn "보세요, 여기가 찢어졌거든요.\n"
.stringn "\x0711정말이구먼. 이 상태로\n"
.stringn "싸우거나 하면 위험하제……\n"
.stringn "가 아니라… 으음?\n"
.stringn "우째 내 이름을 알고 있는 겨?\n"
.stringn "\x0703아아… 저는 직업 때문에\n"
.stringn "사람의 얼굴과 이름을 잘 기억합니다.\n"
.stringn "인사도 하지 않았는데\n"
.stringn "놀래켜서 죄송해요.\n"
.stringn "저는 지하크.\n"
.stringn "앞으로도 잘 부탁합니다, 채프씨.\n"
.stringn "\x0711그래, 나도……\n"
.stringn "반가우이.\n"
.stringn "어깨 보호대를 고치는 직업이라면…\n"
.stringn "너는 가죽 장인이라도 되는 겨?\n"
.stringn "\x0703아닙니다. 저는 검사예요.\n"
.stringn "용병으로 아이크에게 고용되어 있죠.\n"
.stringn "\x0711흐음… 검사가 용케 이런 것도\n"
.stringn "수리할 수 있구먼. 참말로 재주가 좋아.\n"
.stringn "\x0703이 정도는 스스로 해야죠.\n"
.stringn "용병은 가난하니까요.\n"
.stringn "좋아, 이제 됐다.\n"
.stringn "\x0711호오… 훌륭하데이.\n"
.stringn "우리 둘째 아들도\n"
.stringn "본받으면 좋을 텐디.\n"
.stringn "\x0703채프씨네 아이는\n"
.stringn "모두 몇 명인가요?\n"
.stringn "\x0711아들 다섯에 딸 셋.\n"
.stringn "제일 큰 놈이 딱\n"
.stringn "너 정도 될 거여.\n"
.stringn "\x0703역시 아이가 많으시군요.\n"
.stringn "그럴 거 같은 느낌이 들었어요.\n"
.stringn "\x0711그건 대체 무슨 느낌이여?\n"
.stringn "\x0703마음씨 좋은 아버지요.\n"
.stringn "채프씨한테는 딱 맞지 않나요?\n"
.stringn "\x0711그, 그려?\n"
.stringn "그렇게 말해 주니\n"
.stringn "왠지 쑥스럽구먼."
db 0
.align 4
//MYELL_8_CHAP_ZIHARK_C

//0x7F48
Text_7F28:
.stringn "\x05FL|GATRIE|CHINON||\x0705…………\n"
.stringn "\x0713응?\n"
.stringn "\x0705…………\n"
.stringn "\x0713야, 뭘 멍하게\n"
.stringn "서 있냐 가트리?\n"
.stringn "\x0C05\x0C05\x0701아, 시논씨\n"
.stringn "저, 그녀를 기다리고 있슴다.\n"
.stringn "\x0713아아, 예의 여자인가.\n"
.stringn "그럼 잘된 거냐?\n"
.stringn "\x0701당연하죠!\n"
.stringn "시논씨가 골라 준\n"
.stringn "선물을 가지고 만나러 갔더니\n"
.stringn "그 애가 정말 기뻐했어요…\n"
.stringn "게다가 실은 말이죠,\n"
.stringn "곧 결혼하기로 했거든요.\n"
.stringn "\x0713그건 또…\n"
.stringn "급전개구만.\n"
.stringn "\x0701그런데 그 애, 무슨\n"
.stringn "불치병에 걸린 것 같아서\n"
.stringn "치료비로 쓸 골드를 지불하지 못하면\n"
.stringn "여생이 며칠 남지 않았다고 해요.\n"
.stringn "그래서, 지금은 제가\n"
.stringn "돈을 쓸 때라고 생각했기에……\n"
.stringn "\x0713돈을 건네줬다고?\n"
.stringn "\x0701네, 있는 거 전부요.\n"
.stringn "그랬더니 그 액수가\n"
.stringn "치료비하고 딱 맞는다고 하지 뭡니까!\n"
.stringn "이건 역시 운명이죠?\n"
.stringn "여신님께서 저와 그 애가 맺어지도록\n"
.stringn "도와주신 거라구요!\n"
.stringn "\x0713……그래서?\n"
.stringn "\x0701이런 때지만…\n"
.stringn "아니, 이런 때니까\n"
.stringn "바로 식을 올리기로 했슴다.\n"
.stringn "사실은 그 애가 오고 나서\n"
.stringn "모두에게 성대하게 발표하려고\n"
.stringn "했는데……\n"
.stringn "아직도 안 오네요.\n"
.stringn "……걱정입니다.\n"
.stringn "집에도 찾아가 봤는데,\n"
.stringn "제가 길을 잘못 든 건지\n"
.stringn "빈집들 뿐이었어요.\n"
.stringn "그래도 괜찮습니다.\n"
.stringn "그녀는 제가 이 군에 있다는 걸\n"
.stringn "알고 있으니까요.\n"
.stringn "\x0713…가트리……\n"
.stringn "너, 속은 거야.\n"
.stringn "\x0701네에!?\n"
.stringn "그럴 리가 없지 않슴까!?\n"
.stringn "그런 청순한 아이가!\n"
.stringn "\x0713어떻게 여생이 며칠 안 남은 사람이\n"
.stringn "거리를 어슬렁거리고 있냐?\n"
.stringn "\x0701그, 그건……\n"
.stringn "저를 만나기 위해서죠!\n"
.stringn "\x0713그럼 왜 안 나타나는데?\n"
.stringn "\x0701그건…… 그건 말이죠……\n"
.stringn "\x0713가트리…\n"
.stringn "\x0701……아하하하…\n"
.stringn "…역시, 저…\n"
.stringn "또 속은 거군요…\n"
.stringn "\x0713…그 여자의 인상이라든가 알려 줘 봐.\n"
.stringn "\x0701네? 그치만…\n"
.stringn "\x0713있는 돈을 전부 뜯어갔다니\n"
.stringn "보통 악질이 아니잖냐.\n"
.stringn "내가 붙잡아서\n"
.stringn "돈 되찾아 줄게.\n"
.stringn "\x0701……\n"
.stringn "으~음, 역시 괜찮슴다.\n"
.stringn "제가 준 돈이고요……\n"
.stringn "\x0713괜찮은 거냐?\n"
.stringn "그 여자, 지금쯤 널 비웃고 있을 텐데.\n"
.stringn "\x0701뭐, 그 애는 웃는 얼굴이 귀여웠으니까요.\n"
.stringn "\x0713하아… 얼마나 더\n"
.stringn "속아야 직성이 풀릴 거냐, 넌?\n"
.stringn "\x0701괜찮슴다…\n"
.stringn "그게 제 유일한 장점이니까요.\n"
.stringn "\x0713…뭐, 이걸로\n"
.stringn "돈을 어디에 쓸지는 고민 안 해도 되겠구만.\n"
.stringn "\x0701그렇네요, 그렇게 생각하면\n"
.stringn "오히려 다행임다!\n"
.stringn "\x0713…나 참.\n"
.stringn "술이나 마시지 않으면\n"
.stringn "못 해먹겠네.\n"
.stringn "\x0701아, 그럼! 저도 저도!\n"
.stringn "아… 맞다 돈이 없었지……\n"
.stringn "역시 전 됐슴다.\n"
.stringn "\x0713이리 와.\n"
.stringn "내가 한잔 사 줄게.\n"
.stringn "\x0701엇, 정말요?\n"
.stringn "\x0713그래.\n"
.stringn "\x0701…헤헤헤\n"
.stringn "\x0713뭘 그렇게 웃냐?\n"
.stringn "\x0701시논씨가 사 주는 술을 마실 수 있다니,\n"
.stringn "오늘은 운이 좋은 것 같아서요.\n"
.stringn "\x0713……뭐래.\n"
.stringn "태평한 놈이구만."
db 0
.align 4
//MYELL_8_CHINON_GATRIE_A

//0x7B20
Text_7B00:
.stringn "\x05FL|GATRIE|CHINON||\x0C03\x0C15\x0703저기, 시논씨~이!\n"
.stringn "\x0715지금은 바빠.\n"
.stringn "나중에 오라고 말했잖아.\n"
.stringn "\x0703무슨 일이 있더라도\n"
.stringn "바로 대답해 주셨으면 하는 게 있슴다.\n"
.stringn "\x0715안 돼.\n"
.stringn "\x0703오늘 술값도 제가 낼 테니까요.\n"
.stringn "\x0715시끄러워.\n"
.stringn "\x0703평소보다 비싼 술로 마셔도 돼요.\n"
.stringn "\x0715…안주는?\n"
.stringn "\x0703비장의 훈제 고기!\n"
.stringn "어떠심까!\n"
.stringn "\x0C15\x0C15\x0711어쩔 수 없지.\n"
.stringn "귀여운 동생 얼굴을 봐서라도\n"
.stringn "잠깐 시간 좀 내 볼까.\n"
.stringn "\x0703이 은혜는 꼭 갚겠슴다!\n"
.stringn "\x0711그래서, 뭔데?\n"
.stringn "\x0703뭐랄까, 이야아~\n"
.stringn "곤란해서 말이죠.\n"
.stringn "\x0711뭐가?\n"
.stringn "\x0703곤란하단 말이죠~\n"
.stringn "어떻게 할까나~…\n"
.stringn "그렇게 듣고 싶으세요?\n"
.stringn "\x0711켁, 죽을 때까지 그러고 있어라.\n"
.stringn "\x0703자, 잠깐만요!\n"
.stringn "기다려 주세요!\n"
.stringn "지금부터 이야기할 거라고요!!\n"
.stringn "\x0711나 참.\n"
.stringn "빨리 말해.\n"
.stringn "\x0703저…\n"
.stringn "여, 여, 여자친구가 생겼슴다!\n"
.stringn "\x0711호오? 그것참\n"
.stringn "별난 여자도 다 있구만.\n"
.stringn "\x0703저번에 마을에 나갔을 때 만났슴다!\n"
.stringn "엄청 귀여운 아이임다!\n"
.stringn "이번엔 정말로 운명의 빨간 실이라고요!\n"
.stringn "\x0711잘됐네.\n"
.stringn "그렇구만, 뭔지 알겠다.\n"
.stringn "그 여자에게 줄 선물을 나한테\n"
.stringn "상담하고 싶은 거지?\n"
.stringn "\x0703헤헤헤헤,\n"
.stringn "어떤 게 좋슴까?\n"
.stringn "\x0711그런 거라면 맡겨 달라고.\n"
.stringn "술 마시면서\n"
.stringn "차근차근 가르쳐 주지.\n"
.stringn "\x0703넵! 스승님!"
db 0
.align 4
//MYELL_8_CHINON_GATRIE_B

//0x75A0
Text_7580:
.stringn "\x05FL|GATRIE|CHINON||\x070-\x0705…하아\n"
.stringn "……후우…\n"
.stringn "아니, 그래도…\n"
.stringn "~~~ 역시 안 되겠어!!\n"
.stringn "\x0714야!\n"
.stringn "\x0C05\x0C05\x0701아?\n"
.stringn "…아, 시논씨.\n"
.stringn "\x0714『…아, 시논씨』 같은 소리 하네.\n"
.stringn "뭐야, 아까부터\n"
.stringn "정신 사납게.\n"
.stringn "\x0701……아무것도 아님다.\n"
.stringn "\x0714아, 그러셔.\n"
.stringn "그럼 난 간다.\n"
.stringn "\x0701기, 기다려 주세요! 거짓말이라구요!\n"
.stringn "심술부리지 말고\n"
.stringn "상담해 주세요~!!\n"
.stringn "\x0713오늘 술값은 네가 내는 거다?\n"
.stringn "\x0701으으… 알겠습니다.\n"
.stringn "\x0713좋~아.\n"
.stringn "그럼 얘기해 봐.\n"
.stringn "\x0701이번 보수를 어디에 쓸지 말인데요…\n"
.stringn "어떻게 할지 망설여집니다.\n"
.stringn "\x0713그런 건 사람마다 제각각이지.\n"
.stringn "마음대로 쓰면 되잖아.\n"
.stringn "\x0701마음대로 쓰고 나면\n"
.stringn "시논씨가\n"
.stringn "일일이 트집을 잡지 않습니까!\n"
.stringn "\x0713내가?\n"
.stringn "언제?\n"
.stringn "\x0701지난번에 산 『궁극의 방패』 때도…\n"
.stringn "\x0713아아, 그 요새 대문에서?\n"
.stringn "위병이 너를 도둑으로 봤었지.\n"
.stringn "제대로 돌려놨냐?\n"
.stringn "\x0701몸에 뿌리기만 해도\n"
.stringn "움직임이 빨라지는 비약\n"
.stringn "『대시 한 방!』 때도…\n"
.stringn "\x0713그 썩은 육즙?\n"
.stringn "너, 냄새 확인도 안 하고\n"
.stringn "자기 몸에 끼얹었지?\n"
.stringn "\x0701저, 그걸로 조금은\n"
.stringn "움직임이 빨라졌거든요!\n"
.stringn "\x0713들개 30마리한테\n"
.stringn "쫓기면서 말이지.\n"
.stringn "\x0701보세요! 트집 잡기만 하잖아요!!\n"
.stringn "\x0713아, 그거 때문에 상처 준 거구만, 내가.\n"
.stringn "사실대로 알려 주고\n"
.stringn "불평하지 않으면 성에 안 차긴 하지.\n"
.stringn "\x0701!! 저, 전\n"
.stringn "그렇게까지 말할 생각은…\n"
.stringn "저기… 죄송합니다…\n"
.stringn "\x0713너의 그 솔직한 점,\n"
.stringn "나는 제법 마음에 들어.\n"
.stringn "\x0701헤헤헤, 수줍어하시기는.\n"
.stringn "\x0713좋아, 마시러 가자고!\n"
.stringn "네 돈을 유용하게 쓰고 싶다며.\n"
.stringn "\x0701엇, 아니, 잠깐만요\n"
.stringn "시논씨!\n"
.stringn "그건 뭔가 다르잖아요!!"
db 0
.align 4
//MYELL_8_CHINON_GATRIE_C

//0x8E34
Text_8E14:
.stringn "\x05FL|CHINON|JANAFF||\x0C00\x071-\x0713오, 있다.\n"
.stringn "\x0700………\n"
.stringn "\x0713너,\n"
.stringn "시논이라고 했었지?\n"
.stringn "잠깐 얘기 좀 할까?\n"
.stringn "\x0700…뭐어?\n"
.stringn "신분 높은 반수분께서\n"
.stringn "일부러 지명해 주시다니\n"
.stringn "살다 보니 별일이 다 있구만.\n"
.stringn "\x0713기어오르지 마.\n"
.stringn "지난번에는, 미안했다.\n"
.stringn "\x0700………\n"
.stringn "\x0713나는 베오크를\n"
.stringn "오해하고 있었던 것 같아.\n"
.stringn "살육을 좋아하는 야만적인 종족이라고,\n"
.stringn "우리들 라구즈와는\n"
.stringn "서로 이해할 수 없는 존재라고 말이지.\n"
.stringn "\x0700…그런 것치고는\n"
.stringn "아이크 쪽이랑 잘 어울리시던데.\n"
.stringn "주인의 명령이라서 그런 거냐?\n"
.stringn "\x0713아냐. 우리하고 왕의 관계는\n"
.stringn "그렇게 일방적이지 않아.\n"
.stringn "우린 왕의 의견이 잘못되었다고 여기면\n"
.stringn "절대로 명령을 듣지 않거든.\n"
.stringn "\x0700그럼 어째선데?\n"
.stringn "\x0713그 녀석은 셀리노스의 동료를 구해줬어.\n"
.stringn "은혜에는 은혜로…\n"
.stringn "뤼시온 왕자의 호위로서\n"
.stringn "이 군에 가담했지만,\n"
.stringn "나 스스로도 그 녀석을 신뢰하고 있지.\n"
.stringn "\x0700……마음에 안 들어.\n"
.stringn "\x0713응?\n"
.stringn "\x0700나는 옛날부터 아이크가 싫었거든.\n"
.stringn "그놈은 뭐든지 가지고 있어.\n"
.stringn "…그리고 그게 당연하다고 생각하고 있지.\n"
.stringn "\x0713하지만 그건\n"
.stringn "그 녀석 잘못이 아니잖아?\n"
.stringn "\x0700알아.\n"
.stringn "하지만 열받는 것도\n"
.stringn "내 자유란 거지.\n"
.stringn "\x0713그건 그렇지만.\n"
.stringn "\x0700……그건 그렇고\n"
.stringn "내가 왜\n"
.stringn "너랑 이런 얘기를 하고 있냐.\n"
.stringn "\x0713…어쩌다 보니?\n"
.stringn "너, 젊었을 때의 나랑\n"
.stringn "비슷한 느낌이 들어.\n"
.stringn "\x0700뭐어?\n"
.stringn "\x0713나도 날개가 다 자랄 때까지는\n"
.stringn "심술쟁이었거든.\n"
.stringn "이것도 저것도 다 마음에 안 들었지.\n"
.stringn "\x0700……너, 몇 살인데?\n"
.stringn "\x0713110살 조금 넘었나.\n"
.stringn "\x0700…우리랑 나이 세는 법이\n"
.stringn "다르기라도 한 거냐?\n"
.stringn "\x0713봄, 여름, 가을, 겨울로 1년이라는 건\n"
.stringn "라구즈나 베오크나 마찬가지잖아.\n"
.stringn "\x0700……내가 27살이니까…\n"
.stringn "나보다 최소\n"
.stringn "85살… 정도는 연상인 건가?\n"
.stringn "\x0713그래, 우러러보라고.\n"
.stringn "애송아.\n"
.stringn "앞으로 무슨 일이 생기면\n"
.stringn "나한테 의지하도록 해.\n"
.stringn "연상만이 할 수 있는 조언들을 해 줄 테니까.\n"
.stringn "\x0700…야, 야!\n"
.stringn "잠깐 기다려!\n"
.stringn "너희들 대체 수명이…"
db 0
.align 4
//MYELL_8_CHINON_JANAFF_A

//0x8A64
Text_8A44:
.stringn "\x05FL|JANAFF|CHINON||\x0C04\x0710오, 또 만났구만.\n"
.stringn "꼬맹이 반수 놈.\n"
.stringn "\x0704뻔뻔하게 말 걸지 마시지.\n"
.stringn "애송이 인간 자식.\n"
.stringn "\x0710너, 페니키스 왕의 측근이라면서?\n"
.stringn "체격은 왜소한 주제에 팔자가 좋은데?\n"
.stringn "\x0704너는 베오크 대장과 오래 지낸 사이라던데.\n"
.stringn "용병단 동료들을 배신하고 데인에 붙었다가,\n"
.stringn "거기서 또 배신하고 크리미아에 붙었다며?\n"
.stringn "\x0710그게 뭐 어때서?\n"
.stringn "비겁하다고 말하고 싶은 거냐?\n"
.stringn "공교롭게도 나는 완전 용병 체질이거든.\n"
.stringn "동료 같은 거에 얽매일 생각은 없어.\n"
.stringn "\x0704동료도 안 두고, 주인도 따로 없고…\n"
.stringn "넌 대체\n"
.stringn "뭐 때문에 싸우는 거냐?\n"
.stringn "\x0710……살기 위해서지.\n"
.stringn "누구라도 그렇잖아.\n"
.stringn "그게 아니라면,\n"
.stringn "누가 좋아서 서로 죽이고 있겠냐고…\n"
.stringn "\x0704너…\n"
.stringn "\x0710왜?\n"
.stringn "\x0704넌 살육이 싫은 거야?\n"
.stringn "\x0710좋아하는 놈이 있겠냐?\n"
.stringn "\x0704…인간은 살육을 좋아하는 종족이잖아?\n"
.stringn "그래서 무기를 만들고,\n"
.stringn "먹지도 않는 동물을 사냥하지.\n"
.stringn "\x0710웃기지 마!\n"
.stringn "무기를 만드는 건, 너희들\n"
.stringn "반수로부터 몸을 지키기 위해서다!\n"
.stringn "사냥을 취미로 삼고 있는 건\n"
.stringn "시간이 썩어 남아도는 귀족들뿐이라고!!\n"
.stringn "\x0704………\n"
.stringn "\x0710켁\n"
.stringn "기분 더럽네.\n"
.stringn "\x0704야!\n"
.stringn "아직 얘기가……\n"
.stringn "칫, 어떻게 된 거야."
db 0
.align 4
//MYELL_8_CHINON_JANAFF_B

//0x881C
Text_87FC:
.stringn "\x05FL|JANAFF|CHINON||\x0700이봐!\n"
.stringn "거기 있는 놈, 멈춰!\n"
.stringn "\x0716……\n"
.stringn "\x0700야, 듣고 있냐?\n"
.stringn "\x0714음?\n"
.stringn "뭐냐 넌?\n"
.stringn "\x0700그건 내가 할 말이야.\n"
.stringn "너, 이 군에서는 본 적 없는데.\n"
.stringn "…신입인가? 이름은?\n"
.stringn "어느 부대 소속이야?\n"
.stringn "\x0714……반수 꼬맹이한테\n"
.stringn "대답할 이유는 없어.\n"
.stringn "\x0700뭐라고, 이 자식!?\n"
.stringn "\x0714어이쿠.\n"
.stringn "날 그런 태도로 대하다간\n"
.stringn "나중에 곤란해질걸?\n"
.stringn "\x0700너야말로\n"
.stringn "내가 누군지 알고 나서\n"
.stringn "후회해도 늦을 텐데?\n"
.stringn "\x0714………\n"
.stringn "\x0700………\n"
.stringn "\x0714…켁\n"
.stringn "오늘은 봐주지.\n"
.stringn "\x0700웃기지 마, 인간!\n"
.stringn "잘 들어, 내가\n"
.stringn "널 봐주는 거야.\n"
.stringn "착각하지 마라!!"
db 0
.align 4
//MYELL_8_CHINON_JANAFF_C

//0x9A0C
Text_99EC:
.stringn "\x05FL|CHINON|LOFA||\x0C01\x0C16\x0701어~이, 이제 그만\n"
.stringn "기분 풀어. 나 참.\n"
.stringn "\x0716……\n"
.stringn "\x0701그러니까, 나는\n"
.stringn "널 위해서 그런 거라고.\n"
.stringn "알잖아 그 정도는.\n"
.stringn "\x0716……\n"
.stringn "\x0701칫\n"
.stringn "고집불통 꼬맹이구만.\n"
.stringn "계속 그러고 있으면\n"
.stringn "나 이제 갈 거다?\n"
.stringn "괜찮지?\n"
.stringn "\x0716……그치만…\n"
.stringn "시논씨가 내가 만든 활…\n"
.stringn "………………버렸잖아.\n"
.stringn "\x0701야, 그런 걸 들고\n"
.stringn "전장에 나가 봐라.\n"
.stringn "한 방에 당할걸.\n"
.stringn "그걸 미리 막아 준 거잖아.\n"
.stringn "말하자면 생명의 은인인 거지.\n"
.stringn "오히려 감사해야 할 판이라고.\n"
.stringn "\x0C16\x0713………그건 그렇지만.\n"
.stringn "그치만… 시논씨를\n"
.stringn "기쁘게 해 주고 싶어서…\n"
.stringn "정성을 들여서 만든 건데.\n"
.stringn "나… 처음 싸울 때,\n"
.stringn "너무 무서워서 다리가… 떨렸지만……\n"
.stringn "시논씨가 준 활을\n"
.stringn "꽉 쥐니까… 용기가 났어.\n"
.stringn "난 할 수 있어, 실패하지 않을 거야, 라고.\n"
.stringn "왜냐면 시논씨가\n"
.stringn "가르쳐 줬으니까.\n"
.stringn "그러니까 지금까지 살아남아서\n"
.stringn "이거였구나… 했으니까……\n"
.stringn "\x0701……\n"
.stringn "뭘 그렇게까지…\n"
.stringn "나 같은 놈한테 기대고 있냐.\n"
.stringn "네게 활을 가르친 것도,\n"
.stringn "활을 만들어 준 것도\n"
.stringn "그냥 한가해서 그런 것뿐이야.\n"
.stringn "\x0713그래도, 기뻤어.\n"
.stringn "다른 형들은…\n"
.stringn "내가 아직 어린애라고\n"
.stringn "아무것도 시키지 않았거든.\n"
.stringn "시논씨가 활을 안 알려 줬다면…\n"
.stringn "지금도 계속 뒤에서 기다리고만 있었을 거야.\n"
.stringn "모두가 목숨을 걸고 싸우고 있는데…\n"
.stringn "그걸 가만히… 기다렸겠지.\n"
.stringn "어제는 살아 돌아왔어.\n"
.stringn "하지만… 오늘은? 내일은?\n"
.stringn "불안에 짓눌리면서\n"
.stringn "그저 기다릴 수밖에 없었어.\n"
.stringn "\x0701……어떻게 생각하든\n"
.stringn "네 마음이지만 말이야.\n"
.stringn "어른들은… 가능하면\n"
.stringn "꼬맹이들을 전장에 내보내려고 하지 않아.\n"
.stringn "어지간히 정신 나간 놈이 아니라면\n"
.stringn "다른 사람의 죽음에 관여하려고도 안 하지.\n"
.stringn "그게 꼬맹이라면…\n"
.stringn "더더욱.\n"
.stringn "이건 꼬맹이들을 위해서라기보단,\n"
.stringn "어른 쪽의 자부심이야.\n"
.stringn "자신들의 죄책감을 조금이라도\n"
.stringn "줄이려고 항상\n"
.stringn "머리를 쥐어짜고 있지.\n"
.stringn "사람은… 타인의 고통을 느낄 수 있는 생물이야.\n"
.stringn "그걸 무의식적으로 무시하려고 해도…\n"
.stringn "눈치채고 나면… 괴롭지.\n"
.stringn "\x0713……어려워.\n"
.stringn "\x0701…그래.\n"
.stringn "뭐, 어쨌든.\n"
.stringn "나도 어른의 자부심이라는 게\n"
.stringn "구역질 날 정도로 싫거든.\n"
.stringn "어린애들도 훌륭하게 잘 살 수 있어.\n"
.stringn "살아남는 법은\n"
.stringn "빨리 터득할수록 좋지.\n"
.stringn "\x0713그래서 나한테\n"
.stringn "활을 알려 준 거구나?\n"
.stringn "한가했던 게 아니라…\n"
.stringn "\x0701…… 칫\n"
.stringn "마음대로 생각하셔.\n"
.stringn "그래도 뭐, 그걸로 기분이 나아졌다면…\n"
.stringn "상관없나."
db 0
.align 4
//MYELL_8_CHINON_LOFA_A

//0x9810
Text_97F0:
.stringn "\x05FL|LOFA|CHINON||\x070-\x0C01\x0C13\x0701봐봐, 시논씨!\n"
.stringn "이건 제대로 만든 활 같지?\n"
.stringn "\x0713일단 『활』이라고 할 순 있겠네.\n"
.stringn "\x0701그럼, 시논씨가 써…\n"
.stringn "\x0713싫거든!\n"
.stringn "난 아직 죽고 싶지 않아.\n"
.stringn "\x0701흥!\n"
.stringn "…됐어.\n"
.stringn "내가 쓸 거야 그럼.\n"
.stringn "\x0713……잠깐!\n"
.stringn "\x0701왜?\n"
.stringn "\x0713…그 활 이리 줘 봐.\n"
.stringn "\x0701역시 갖고 싶어졌지?\n"
.stringn "\x0713그래.\n"
.stringn "갑자기 엄청 갖고 싶어졌어.\n"
.stringn "\x0701와~!\n"
.stringn "그럼, 여기!\n"
.stringn "\x0713고맙다.\n"
.stringn "그럼 이만.\n"
.stringn "\x0701……내가 만든 활을\n"
.stringn "시논씨가 쓰면\n"
.stringn "어떤 식을 보일까~\n"
.stringn "신경 쓰이는걸~………\n"
.stringn "………따라가 봐야지.\n"
.stringn "에헤헤"
db 0
.align 4
//MYELL_8_CHINON_LOFA_B

//0x9474
Text_9454:
.stringn "\x05FL|LOFA|CHINON||\x070-\x0701시논씨! 잠깐 잠깐!\n"
.stringn "\x0713음?\n"
.stringn "왜, 요파.\n"
.stringn "\x0701에헤헤… 여기!\n"
.stringn "\x0713뭐야 이건?\n"
.stringn "엄청 휘어지고 뒤틀린 막대기잖아……\n"
.stringn "\x0701활이야!\n"
.stringn "언젠가 시논씨랑 만나면\n"
.stringn "꼭 갚으려고 생각했거든.\n"
.stringn "그래서 조금씩 만들고 있었어.\n"
.stringn "모양은 별로지만\n"
.stringn "열심히 만들었으니까 써 줘!\n"
.stringn "\x0713……백번 양보해서 이게\n"
.stringn "활이라고 치자.\n"
.stringn "이렇게 약한 건 한 번 쓰면\n"
.stringn "부숴질 게 뻔하다고.\n"
.stringn "나보고 그렇게 전장에서 무방비하게 있으란 거냐?\n"
.stringn "\x0701아, 아니야!\n"
.stringn "\x0713애초에\n"
.stringn "선택한 나무부터 잘못됐어.\n"
.stringn "이런 딱딱한 나무로는 안 되지.\n"
.stringn "내가 널 위해 만들어 준 활은\n"
.stringn "이런 게 아니었잖아?\n"
.stringn "\x0701제대로 연구했어.\n"
.stringn "똑같이 생겼잖아!\n"
.stringn "\x0713하나도 안 똑같거든.\n"
.stringn "\x0701윽…\n"
.stringn "\x0713칫, 어쩔 수 없지.\n"
.stringn "다음에 좀 가르쳐 줄게.\n"
.stringn "\x0701정말!?\n"
.stringn "완전 좋아!\n"
.stringn "약속했으니까 꼭 지켜야 돼?\n"
.stringn "\x0713그래, 알았으니까\n"
.stringn "그렇게 강아지마냥\n"
.stringn "착 달라붙지 좀 마, 나 참."
db 0
.align 4
//MYELL_8_CHINON_LOFA_C

//0xA7D4
Text_A7B4:
.stringn "\x05FL|LARGO|DALAHOWE|?||\x0703다라하우, 잠깐 괜찮을까?\n"
.stringn "\x071-\x0711물론 전혀 상관없어~\n"
.stringn "\x0703그때는 겁이 나서\n"
.stringn "도망쳤지만……\n"
.stringn "정말 미안했어, 다라하우.\n"
.stringn "말도 안 되는 짓을 해 버렸어,\n"
.stringn "어떻게 용서를 빌지 쭉 생각해 봤는데…\n"
.stringn "사과하는 것밖에 생각이 안 나.\n"
.stringn "미안해, 다라하우…… 우하라다도.\n"
.stringn "\x0711아아~ 그렇게나 신경 써 준 거야~?\n"
.stringn "미안해 라르고, 우하라다는 괜찮아!\n"
.stringn "\x0703저, 정말이야!?\n"
.stringn "\x0711우하라다는 언제나 다라하우의 친구!\n"
.stringn "친구는 언제든지 곁에 있어야지~!\n"
.stringn "그러니까 이렇게 종이에 그려서…\n"
.stringn "중얼중얼중얼중얼~\n"
.stringn "짜~잔, 우하라다야!\n"
.stringn "\x0727오랜만이야, 라르고.\n"
.stringn "\x0703오오! 정말이네!\n"
.stringn "미안해 우하라다~!!\n"
.stringn "내가 그만 화를 내는 바람에\n"
.stringn "널 아프게……\n"
.stringn "\x0727괜찮아 라르고.\n"
.stringn "\x0711그래그래, 괜찮아 라르고~!\n"
.stringn "라르고는 다라하우의 친구니까\n"
.stringn "우하라다랑도 친구잖아~!\n"
.stringn "친구끼리 그런 거 신경 쓰지 마~!\n"
.stringn "\x0703다행이다…… 둘 다 고마워!\n"
.stringn "너희들 좋은 녀석들이구나! 와하하하하!\n"
.stringn "\x0711아냐아냐~ 라르고가 제일 착한 사람이야~\n"
.stringn "상냥한 라르고를 다라하우는 무척 좋아해~\n"
.stringn "앞으로도 잘 부탁해, 라르고~!\n"
.stringn "\x0703그래, 물론이지!"
db 0
.align 4
//MYELL_8_DALAHOWE_LARGO_A

//0xA4EC
Text_A4CC:
.stringn "\x05FL|LARGO|?|DALAHOWE||\x070-\x0701좋아, 오늘도 힘내 볼까!\n"
.stringn "응? 이건……\n"
.stringn "다라하우의 친구인 우하라다잖아.\n"
.stringn "이런 데 떨어져 있어도 되는 거야?\n"
.stringn "이봐, 괜찮아?\n"
.stringn "\x0717…………\n"
.stringn "\x0701……역시나.\n"
.stringn "이런 종이 쪼가리랑 대화할 수 있을 리 없나.\n"
.stringn "…………좀 열받는데……\n"
.stringn "돌돌 말아서 버려야지!\n"
.stringn "\x0717아, 아……파……\n"
.stringn "\x0701!!?\n"
.stringn "자, 잠깐! 진짜냐!?\n"
.stringn "지금 분명히 목소리가…………\n"
.stringn "미안해, 괜찮아 우하라다!?\n"
.stringn "\x0717……………………\n"
.stringn "\x0701이럴 수가……\n"
.stringn "난 대체 무슨 짓을……\n"
.stringn "\x072-\x0723라르고~!\n"
.stringn "거기서 뭐 해~?\n"
.stringn "\x0701우와앗!!\n"
.stringn "요, 용서해 줘~!!\n"
.stringn "\x0723……도망가 버렸네~\n"
.stringn "미안해 라르고~ 나쁜 건\n"
.stringn "깜빡 소재를 떨어뜨려 버린 다라하우야~\n"
.stringn "하지만 일족의 비기니까\n"
.stringn "절대로 들키면 안 되거든~…\n"
.stringn "죄책감이 드는걸~ ……하아."
db 0
.align 4
//MYELL_8_DALAHOWE_LARGO_B

//0xA224
Text_A204:
.stringn "\x05FL|DALAHOWE|LARGO|?||\x070-\x0701지금부터 비장의 재주를 보여 줄 거야~!\n"
.stringn "모두 보러 와~ 보고 가는 거야~!\n"
.stringn "\x071-\x0713오, 거리 공연이냐. 재밌겠는데.\n"
.stringn "구경꾼은 나밖에 없는 것 같은데,\n"
.stringn "하나 부탁해도 되냐?\n"
.stringn "\x0701물론이지~!\n"
.stringn "양피지에 이렇게 그림을 그려서~…\n"
.stringn "중얼중얼중얼중얼~\n"
.stringn "여~기, 다 됐다!\n"
.stringn "이 애는 다라하우의 친구인\n"
.stringn "우하라다야~\n"
.stringn "\x0713우하라다?\n"
.stringn "이건 그냥 낙서잖아.\n"
.stringn "\x0701아니야~\n"
.stringn "자, 귀를 귀울여 봐~\n"
.stringn "\x0713귀를?\n"
.stringn "\x0727안녕.\n"
.stringn "\x0713오오!? 뭐, 뭐야?\n"
.stringn "넌 말하지 않았는데\n"
.stringn "지금 어디선가 소리가 났어.\n"
.stringn "대체 어떻게 된 거지?\n"
.stringn "\x0701이 우하라다가 말하고 있는 거야~\n"
.stringn "우하라다, 인사~!\n"
.stringn "\x0727안녕 라르고.\n"
.stringn "\x0713와하하하하! 대단한데!\n"
.stringn "또 다른 건 없어?\n"
.stringn "\x0701물론 있지~!\n"
.stringn "자~ 다음은…………"
db 0
.align 4
//MYELL_8_DALAHOWE_LARGO_C

//0xB1A4
Text_B184:
.stringn "\x05FL|NEPHENEE|DALAHOWE||\x0703다라하우씨.\n"
.stringn "\x071-\x0711어라, 네페니가 먼저\n"
.stringn "말을 걸어오다니 별일도 다 있네~\n"
.stringn "다라하우 기뻐~\n"
.stringn "\x0703……다라하우씨는, 언제나 웃는 얼굴이네유…\n"
.stringn "싸움이라든가…… 힘들지 않나유?\n"
.stringn "지는 가끔씩……\n"
.stringn "울고 싶어지기도… 하는디……\n"
.stringn "\x0711………………\n"
.stringn "으~음…… 그렇지~…\n"
.stringn "확실히 싸우는 건 괴롭지만~…\n"
.stringn "그런 말을 하는 네페니를 보는 게\n"
.stringn "다라하우는 더 괴로워~…\n"
.stringn "\x0703다라하우씨……\n"
.stringn "\x0711다라하우, 사람의 웃는 얼굴을 정말 좋아해~\n"
.stringn "그래서 다라하우도 웃는 거야~\n"
.stringn "하지만, 괴로운데도 웃는 얼굴은 슬프지~\n"
.stringn "다라하우가 말했으니까\n"
.stringn "네페니도 열심히 웃어 주고 있는데\n"
.stringn "힘들어 보여~\n"
.stringn "전에 말한 죽은 아이를\n"
.stringn "떠올리게 돼~…\n"
.stringn "미안해, 네페니. 힘든 일을\n"
.stringn "시킨 모양이네~\n"
.stringn "\x0703죄송해유, 저……\n"
.stringn "마을 밖 사람들과 얘기하는 게 힘들어서…\n"
.stringn "사이좋은 사람도 별로 없거든유……\n"
.stringn "\x0711그랬구나~…\n"
.stringn "\x0703하지만 저…… 너무 안 좋은 일들만\n"
.stringn "생각한 것 같아유……\n"
.stringn "다라하우씨처럼 잔뜩 웃으면…\n"
.stringn "좋은 생각들을 할 수 있게 될까유……?\n"
.stringn "\x0711그야 당연하지~!\n"
.stringn "웃는 얼굴은 웃는 사람도, 보는 상대도 구하거든~!\n"
.stringn "\x0703……응, 그렇지유……\n"
.stringn "다라하우씨의 웃는 얼굴은 엄청 좋습니데이……\n"
.stringn "고마워유, 다라하우씨……"
db 0
.align 4
//MYELL_8_DALAHOWE_NEPENEE_A

//0xAE00
Text_ADE0:
.stringn "\x05FL|DALAHOWE|NEPHENEE||\x070-\x0C01\x0C13\x0701네페니,\n"
.stringn "할 얘기가 있는데~\n"
.stringn "\x0713다라하우씨……\n"
.stringn "할 얘기가 뭔, 가요……?\n"
.stringn "\x0701역시 얼굴이 무서워~\n"
.stringn "좀 더 웃는 게 어때~?\n"
.stringn "의미없이 웃어도 된다고\n"
.stringn "다라하우가 지난번에 알려 줬잖아~?\n"
.stringn "\x0713그치만……\n"
.stringn "어려워…서…\n"
.stringn "\x0701어렵다고? 왜~?\n"
.stringn "다라하우처럼\n"
.stringn "이렇게 웃기만 하면 되는 거야~\n"
.stringn "\x0713즐겁지… 않아요……\n"
.stringn "웃어도……\n"
.stringn "\x0701…네페니\n"
.stringn "또 그런다~\n"
.stringn "목소리도 작고, 수다도 안 떨고~\n"
.stringn "\x0713…………\n"
.stringn "\x0701다라하우가 들렀던 마을에 있지~\n"
.stringn "네페니 같은 아이가 있었거든~\n"
.stringn "그 아이, 다라하우에게\n"
.stringn "엄청 잘해 줬어~\n"
.stringn "하지만 그 아이, 마을을 덮친\n"
.stringn "산적들에게 죽었다~…\n"
.stringn "\x0713!\n"
.stringn "\x0701그 아이는 혼자서만 깊게 생각하는\n"
.stringn "성격이었던 거지~\n"
.stringn "모두랑 같이 가만히 숨어 있으면\n"
.stringn "됐을 텐데~\n"
.stringn "다라하우가 다른 산적들과 싸우고 있는 사이에\n"
.stringn "나가 버렸던 것 같아.\n"
.stringn "자기가 어떻게든 해야만 한다고\n"
.stringn "생각했던 거겠지~…\n"
.stringn "그러니까 네페니는\n"
.stringn "좀 더 다른 사람들과 수다를 떨고\n"
.stringn "웃어 줬으면 좋겠어~\n"
.stringn "\x0713…………"
db 0
.align 4
//MYELL_8_DALAHOWE_NEPENEE_B

//0xABF4
Text_ABD4:
.stringn "\x05FL|DALAHOWE|NEPHENEE||\x070-\x0701잠깐 잠깐, 거기 있는 사람~\n"
.stringn "다라하우 할 얘기가 있어~\n"
.stringn "\x0713……뭔, 가요?\n"
.stringn "\x0701다라하우 언제나 생각해~\n"
.stringn "너, 얼굴이 무서워~\n"
.stringn "\x0713………그렇, 습니까?\n"
.stringn "\x0701보고 있으면 무섭다고~\n"
.stringn "잔뜩, 잔뜩\n"
.stringn "웃는 편이 좋아~\n"
.stringn "너무 진지한 건, 좋지 않아~\n"
.stringn "오래 못 살게 되니까~\n"
.stringn "\x0713진지한 건……\n"
.stringn "아니라, 고… 생각하는데.\n"
.stringn "\x0701그래~?\n"
.stringn "그나저나 너, 이름이 뭐야~?\n"
.stringn "\x0713네페니……\n"
.stringn "\x0701다라하우 이제부터\n"
.stringn "네페니에게 웃는 법을 알려 줄게~\n"
.stringn "사양 안 해도 돼~\n"
.stringn "\x0713네에……"
db 0
.align 4
//MYELL_8_DALAHOWE_NEPENEE_C

//0xBBD4
Text_BBB4:
.stringn "\x05FL|TOPUCK|DALAHOWE||\x070-\x0703……후우\n"
.stringn "\x071-\x0711안 돼 토팍~\n"
.stringn "한숨을 쉬면 행복이 날아간다구~\n"
.stringn "\x0703……다라하우구나.\n"
.stringn "\x0711어라\n"
.stringn "오늘은 안 놀라네~ 조금 아쉬운걸~\n"
.stringn "\x0703다라하우는 좋겠다……\n"
.stringn "창술사가 되기 위해 태어났다는 느낌이야.\n"
.stringn "엄청 강하고~… 하아아…\n"
.stringn "\x0711토팍도 강하잖아~\n"
.stringn "\x0703……겉치레는 됐어.\n"
.stringn "나 스스로도 알고 있다구.\n"
.stringn "마도는 나랑 안 맞을지도 모른다는 걸……\n"
.stringn "\x0711누구나 정체기는 있는 법이야~\n"
.stringn "\x0703……내 경우는\n"
.stringn "그거랑 다르다는 느낌이 들어.\n"
.stringn "\x0711하나를 습득하기 위해서는~\n"
.stringn "언제나 끈기가 필요한 거야~\n"
.stringn "앞만 보고 서두르면~\n"
.stringn "소중한 것들을 못 보게 돼~\n"
.stringn "\x0703소중한 것들이라니?\n"
.stringn "\x0711예를 들면, 처음으로 마법을\n"
.stringn "사용했을 때의 기분이라든가~\n"
.stringn "어떤 기분이었는지 기억나~?\n"
.stringn "\x0703어땠냐니……\n"
.stringn "그야, 기뻤지.\n"
.stringn "\x0711조금씩 실력이 늘어갈 때는\n"
.stringn "어땠어~?\n"
.stringn "\x0703기쁘고…… 즐거웠어.\n"
.stringn "\x0711……왜 마법을 사용하게 돼서\n"
.stringn "기뻤던 건지 기억해 내 봐~\n"
.stringn "\x0703………그야 강해졌다고 생각했으니까.\n"
.stringn "…모두를 지킬 수 있는 힘을 가지게 돼서\n"
.stringn "굉장히 기뻤어……\n"
.stringn "\x0711그 기분을 잊으면 안 돼~\n"
.stringn "그것만 잘 기억한다면~\n"
.stringn "토팍은 더 성장할 수 있어~\n"
.stringn "\x0703…………\n"
.stringn "고마워, 다라하우!\n"
.stringn "뭔가… 너한테는 항상\n"
.stringn "중요한 걸 배우는 것 같아.\n"
.stringn "\x0711신경 쓰지 마~\n"
.stringn "아이를 이끌어 주는 건 어른의 의무니까~\n"
.stringn "그리고 말이지~ 다라하우도\n"
.stringn "답례를 받고 있거든~\n"
.stringn "\x0703답례?\n"
.stringn "\x0711토팍의 해맑은 미소야~\n"
.stringn "다라하우는 언제나~\n"
.stringn "아이들의 웃는 얼굴을 위해서 싸우고 있지~"
db 0
.align 4
//MYELL_8_DALAHOWE_TOPUCK_A

//0xB914
Text_B8F4:
.stringn "\x05FL|TOPUCK|DALAHOWE||\x0703아~ 이제 그만할래!\n"
.stringn "이런 건 못 한다고……\n"
.stringn "\x0714중간에 포기하는 건 좋지 않아~\n"
.stringn "\x0C03\x0701와아악!\n"
.stringn "어, 어느새……!\n"
.stringn "\x0C14\x0713아까부터 보고 있었어~\n"
.stringn "토팍은 상처 치료를\n"
.stringn "너무 대충해~\n"
.stringn "\x0701어쩔 수 없잖아.\n"
.stringn "상처약을 발라서 천으로 누르려고 해도\n"
.stringn "미끄러지기만 하고.\n"
.stringn "누가 와서 지팡이를 쓰는 편이\n"
.stringn "빠르고 확실하게 나아서 좋아.\n"
.stringn "\x0713바보!\n"
.stringn "\x0701응……?\n"
.stringn "\x0713바로 다른 사람한테 기대면 안 돼~\n"
.stringn "자기가 할 수 있는 일은\n"
.stringn "스스로 할 수 있게 되지 못하면~\n"
.stringn "전장에서는 살아남을 수 없어~\n"
.stringn "곤란할 때는 항상\n"
.stringn "누군가가 도와줄 수 있는 게 아니거든~\n"
.stringn "\x0701…그렇구나.\n"
.stringn "역시 너는 말솜씨가 좋아.\n"
.stringn "\x0713기본 중의 기본이지~\n"
.stringn "자아, 천을 빌려줘 봐~\n"
.stringn "잘 감는 법을 가르쳐 줄게~\n"
.stringn "\x0701그래!"
db 0
.align 4
//MYELL_8_DALAHOWE_TOPUCK_B

//0xB614
Text_B5F4:
.stringn "\x05FL|TOPUCK|DALAHOWE||\x0701나 참, 여기로 집합하라고\n"
.stringn "들었는데…… 아직도 안 온 건가?\n"
.stringn "\x071-\x0713기다리게 해서 미안해~!\n"
.stringn "\x0701우와아앗!!\n"
.stringn "\x0713우와아앗!\n"
.stringn "이라니, 뭘 보고 그렇게 놀란 거야~?\n"
.stringn "\x0701당연히 너지, 너!\n"
.stringn "갑자기 나타나면 심장에 안 좋다고.\n"
.stringn "아~ 내 수명 줄어들었을지도 몰라…\n"
.stringn "\x0713토팍은 조금 과장이 심하네~\n"
.stringn "그런 일로 수명이 줄어든다면~\n"
.stringn "다들 진작에 죽었을 거야~\n"
.stringn "그것보다, 일하자 일~!\n"
.stringn "참모씨에게 부탁받은 무기 손질을\n"
.stringn "얼른 끝내 버리자~!\n"
.stringn "\x0701하아아, 왜 이런 잡일을…\n"
.stringn "우리가 할 일은 아니지 않아?\n"
.stringn "\x0713좋은 경험이라고 생각해~\n"
.stringn "자기가 쓰는 무기뿐만 아니라~\n"
.stringn "다양한 무기를 알아 둔다면~\n"
.stringn "싸울 때 도움이 될 거야~\n"
.stringn "\x0701그렇긴 하지.\n"
.stringn "뭐야, 제법 말솜씨가 좋잖아.\n"
.stringn "\x0713칭찬받아서 영광이야~\n"
.stringn "\x0701그럼, 일단\n"
.stringn "검부터 시작해 보실까!"
db 0
.align 4
//MYELL_8_DALAHOWE_TOPUCK_C

//0xC750
Text_C730:
.stringn "\x05FL|ELAICE|GATRIE||\x0C01\x071-\x0713안녕, 이레이스!\n"
.stringn "얼마 전에 좋은 걸 얻었어.\n"
.stringn "봐봐, 이 조개껍데기!\n"
.stringn "어때? 예쁘지?\n"
.stringn "\x0701네에……\n"
.stringn "\x0713……관심 없어?\n"
.stringn "\x0701그런 게 아니고……\n"
.stringn "\x0713그럼, 관심 있어?\n"
.stringn "\x0701그런 게 아니고……\n"
.stringn "\x0713후우, 역시 안 되는구나.\n"
.stringn "뭔가 마음에 들어하면\n"
.stringn "그걸 계기로\n"
.stringn "식사에 초대하려고 했는데…\n"
.stringn "\x0701!!\n"
.stringn "아, 함께해도 좋아요……\n"
.stringn "\x0713응?\n"
.stringn "\x0701식사……\n"
.stringn "\x0713저, 정말이야!?\n"
.stringn "좋았어! 나한테 맡겨 줘!\n"
.stringn "이 내가 이레이스를 위해서\n"
.stringn "맛~~있는 음식을 만드는 곳을\n"
.stringn "찾아올 테니까!\n"
.stringn "\x0701……그렇군요.\n"
.stringn "가트리씨구나…\n"
.stringn "\x0713응? 내가 왜?\n"
.stringn "\x0701아뇨, 아무것도…\n"
.stringn "\x0713???\n"
.stringn "뭐어, 됐어.\n"
.stringn "그럼, 다음에 보자!\n"
.stringn "\x0701가트리씨, 가트리씨…\n"
.stringn "밥을 사 주는 사람이니까\n"
.stringn "기억해 둬야지……\n"
.stringn "맛있는 식사…… 아아, 기대된다……"
db 0
.align 4
//MYELL_8_ELAICE_GATRIE_A

//0xC498
Text_C478:
.stringn "\x05FL|ELAICE|GATRIE||\x0C01\x071-\x0713안녕, 이레이스!\n"
.stringn "\x0701……안녕하세요.\n"
.stringn "\x0713헤헤헤…\n"
.stringn "어때, 이 꽃, 예쁘지?\n"
.stringn "이렇게 귀엽고 예쁜 꽃은\n"
.stringn "이레이스랑 잘 어울린다고 생각했거든.\n"
.stringn "\x0701네에……\n"
.stringn "\x0713어라…… 저기,\n"
.stringn "혹시 마음에 안 들어?\n"
.stringn "\x0701그런 게 아니고…\n"
.stringn "\x0713그럼, 마음에 들어?\n"
.stringn "\x0701그런 게 아니고……\n"
.stringn "\x0713…………\n"
.stringn "그, 그럼, 이건 어때?\n"
.stringn "이 브로치, 예쁘지?\n"
.stringn "전에 들렀던 마을에서 팔고 있었다.\n"
.stringn "\x0701네에……\n"
.stringn "\x0713으음, 이것도 별로야?\n"
.stringn "\x0701그런 게 아니고……\n"
.stringn "\x0713…………\n"
.stringn "이, 일단, 이따가 다시 올게.\n"
.stringn "하하, 하하하…\n"
.stringn "\x0701네…… 실례할게요……\n"
.stringn "\x0713으~음, 꽤 까다로운걸…\n"
.stringn "그래도 난 포기하지 않아!\n"
.stringn "저렇게 귀여운 애를 놓치다간\n"
.stringn "벌 받는다고!"
db 0
.align 4
//MYELL_8_ELAICE_GATRIE_B

//0xC140
Text_C120:
.stringn "\x05FL|ELAICE|GATRIE||\x0C05\x071-\x0713크흠, 거기 아가씨.\n"
.stringn "\x0705……\n"
.stringn "\x0713아, 거기 귀여운 아가씨.\n"
.stringn "\x0705……\n"
.stringn "\x0713아,\n"
.stringn "거기 연보라색 양갈래 머리를 한\n"
.stringn "사랑스러운 아가씨.\n"
.stringn "\x0C05\x0701아… 저…인가요?\n"
.stringn "설마……\n"
.stringn "\x0713후우, 겨우 눈치채 주었구나.\n"
.stringn "자각이 없다니 이리 고상할 수가…!\n"
.stringn "이야아~! 아가씨 같은\n"
.stringn "귀엽고 근사한 여성과 같은 군에 있다니\n"
.stringn "행복한걸~!\n"
.stringn "\x0701네에……\n"
.stringn "\x0713그래서, 그,\n"
.stringn "아가씨는 이름이 뭐야?\n"
.stringn "\x0701이름……이요?\n"
.stringn "이레이스입니다……\n"
.stringn "\x0713이레이스라고 하는구나.\n"
.stringn "이야아~ 외모하고 어울리는\n"
.stringn "귀여운 이름이네! 진짜 최고야!\n"
.stringn "\x0701네에……\n"
.stringn "\x0713내 이름은 가트리야.\n"
.stringn "가트라고 불러도 좋아!\n"
.stringn "아니, 오히려 환영한달까?\n"
.stringn "\x0701네에……\n"
.stringn "\x0713그럼, 그렇게 됐으니까\n"
.stringn "앞으로도~ 잘 부탁해!\n"
.stringn "\x0701네에……\n"
.stringn "……실례할게요……\n"
.stringn "\x0713헤헤헤, 이걸로 내 인상은 확실히 남았겠지!\n"
.stringn "그렇구나, 이레이스라고 하는구나…\n"
.stringn "이제부터 매일이 즐거울 것 같은데!!"
db 0
.align 4
//MYELL_8_ELAICE_GATRIE_C

//0xD290
Text_D270:
.stringn "\x05FL|LUCHINO|ELAICE||\x0703이레이스? 이상하네.\n"
.stringn "여기서 기다리라고 했는데.\n"
.stringn "대체 어디에……\n"
.stringn "\x0717루키노……씨……\n"
.stringn "\x0703! 이레이스……!?\n"
.stringn "이레이스, 정신 차려!\n"
.stringn "왜 그래, 무슨 일 있었어?\n"
.stringn "\x0711아뇨…… 아무것도……\n"
.stringn "그저…… 배가, 고파서……\n"
.stringn "\x0703배, 배가 고프다니……\n"
.stringn "너, 제대로\n"
.stringn "밥은 먹고 다니는 거지?\n"
.stringn "\x0711아뇨…… 오늘은 아직……\n"
.stringn "겨우 3인분밖에……\n"
.stringn "\x0703뭐?\n"
.stringn "3인……분?\n"
.stringn "\x0711네……\n"
.stringn "\x0703……너, 평소에는\n"
.stringn "얼마나 먹는데?\n"
.stringn "\x0711최근에는 거의 못 먹고 있어요……\n"
.stringn "평범하게 5인분…… 정도밖에……\n"
.stringn "\x0703…………어 그게……\n"
.stringn "너, 혹시 라구즈는 아니지?\n"
.stringn "\x0711네……\n"
.stringn "\x0703……저기, 이레이스.\n"
.stringn "지난 며칠 동안, 나는 네게\n"
.stringn "여러 가지 훈련을 시켜 봤어.\n"
.stringn "그리고 생각을 해 봤는데……\n"
.stringn "너는 몸이 약한 것보다……\n"
.stringn "좀 더 근본적인 뭔가가 문제라고 생각해.\n"
.stringn "그래도 이대로 내버려 둘 수는 없지.\n"
.stringn "이왕 시작한 일이니……\n"
.stringn "같이 어떻게든 해 보자.\n"
.stringn "\x0711네…… 기뻐요.\n"
.stringn "루키노씨는 맛있는 요리를\n"
.stringn "만들어 줘요……\n"
.stringn "루키노씨는 예쁘고, 강하고,\n"
.stringn "좋은 냄새가 납니다……\n"
.stringn "루키노씨와 함께 있고 싶어요……\n"
.stringn "\x0703그, 그래.\n"
.stringn "그럼 어쨌든 먹을 걸……\n"
.stringn "\x0711루키노씨의 요리……\n"
.stringn "…… 꿀꺽.\n"
.stringn "\x0703…후우, 어쩔 수 없지.\n"
.stringn "뭐든지 좋아하는 걸 만들어 줄 테니까,\n"
.stringn "훈련도 열심히 해야 한다?\n"
.stringn "\x0711네! 기뻐요…!"
db 0
.align 4
//MYELL_8_ELAICE_LUCHINO_A

//0xCEA0
Text_CE80:
.stringn "\x05FL|ELAICE|LUCHINO||\x0C01\x0713그럼 이레이스, 시작해 봐.\n"
.stringn "\x0701네……\n"
.stringn "그럼…… 해 볼게요……\n"
.stringn "\x0713………………\n"
.stringn "기, 기다려 이레이스.\n"
.stringn "잠깐 이쪽으로 돌아와 볼래?\n"
.stringn "\x0701네……\n"
.stringn "왜 그러시나요……?\n"
.stringn "\x0713이레이스, 네가\n"
.stringn "몸이 약하는 건 잘 알아.\n"
.stringn "그래도 조금만 달려 보자.\n"
.stringn "천천히 해도 되니까.\n"
.stringn "\x0701네……\n"
.stringn "저, 열심히\n"
.stringn "달렸잖아요……\n"
.stringn "\x0713응……?\n"
.stringn "방금 그게…… 달린 거였니?\n"
.stringn "\x0701네……\n"
.stringn "\x0713………………\n"
.stringn "……잘 들어, 이레이스.\n"
.stringn "누구에게나 서투른 게 있는 법이야.\n"
.stringn "그걸 극복하기 위해서는\n"
.stringn "많은 시간과 노력이 필요해.\n"
.stringn "그러니까… 바로 결과가 나타나지 않아도\n"
.stringn "결코 서두르면 안 돼. 알았지?\n"
.stringn "\x0701네……\n"
.stringn "\x0713나도 함께할게.\n"
.stringn "같이 힘내 보자!\n"
.stringn "\x0701네… 힘낼게요……\n"
.stringn "\x0713그럼, 일단 휴식하자.\n"
.stringn "뭔가 마실 거라도…\n"
.stringn "\x0701먹는 게 좋아요.\n"
.stringn "\x0713그, 그래.\n"
.stringn "그럼, 먹을 걸 가져올게…\n"
.stringn "뭘 먹고 싶니?\n"
.stringn "\x0701지난번에 루키노씨가\n"
.stringn "만들어서 가져다주신 거…\n"
.stringn "전부 다시 먹고 싶어요.\n"
.stringn "\x0713그렇게나 마음에 들었니?\n"
.stringn "기쁘네.\n"
.stringn "그렇다면 다시\n"
.stringn "팔을 걷어 볼까.\n"
.stringn "\x0701네, 기뻐요…!"
db 0
.align 4
//MYELL_8_ELAICE_LUCHINO_B

//0xCA64
Text_CA44:
.stringn "\x05FL|ELAICE|LUCHINO||\x0C01\x071-\x0713안녕.\n"
.stringn "제법 귀여운 아이가 있나 했더니…\n"
.stringn "너는 마도사구나.\n"
.stringn "나는 루키노야.\n"
.stringn "크리미아 왕국군의 일원으로서\n"
.stringn "네가 이 전투에\n"
.stringn "참가해 준 것에 대해 감사하고 있어.\n"
.stringn "\x0701네……\n"
.stringn "저는 이레이스라고 해요……\n"
.stringn "그레일 용병단의……\n"
.stringn "… … …\n"
.stringn "\x0713왜, 왜 그래?\n"
.stringn "정신 차려 봐, 괜찮니?\n"
.stringn "\x0701네……\n"
.stringn "\x0713그건 그렇고……\n"
.stringn "이레이스는 무척 가냘프네.\n"
.stringn "그 상태로는 행군하는 것도 힘들지 않아?\n"
.stringn "\x0701네…… 행군 중에 자주……\n"
.stringn "쓰러져요……\n"
.stringn "\x0713그래선 안 돼.\n"
.stringn "만약 전장에서 그런 일이 생기면\n"
.stringn "바로 목숨을 잃게 될 거야.\n"
.stringn "조심해. 싸우는 중에는\n"
.stringn "체력 등의 자기 관리도 중요하니까.\n"
.stringn "\x0701네, 네에…\n"
.stringn "\x0713기어 들어갈 듯한 대답인걸.\n"
.stringn "정신 차려, 금방이라도 쓰러질 것 같은데?\n"
.stringn "일단 도와줄 테니까\n"
.stringn "네 천막으로 돌아가자.\n"
.stringn "\x0701…안 돼요. 배가 고파서……\n"
.stringn "움직일 수가… 없어요……\n"
.stringn "\x0713그렇게나 배고파?\n"
.stringn "기다려 봐. 내가 지금\n"
.stringn "식량을 좀 가지고 올 테니까.\n"
.stringn "\x0701정말인가요……?\n"
.stringn "\x0713그래. 어떤 걸\n"
.stringn "좋아하니?\n"
.stringn "\x0701…편식하진 않아요.\n"
.stringn "입에 들어가는 거라면 뭐든지 좋아요.\n"
.stringn "\x0713그, 그렇구나.\n"
.stringn "그 정도로 위험한 상태라는 거지?\n"
.stringn "알았어.\n"
.stringn "내가 돌아올 때까지 얌전히 있어야 해?\n"
.stringn "\x0701네, 기뻐요……"
db 0
.align 4
//MYELL_8_ELAICE_LUCHINO_C

//0xDDD0
Text_DDB0:
.stringn "\x05FL|MORDY|ELAICE||\x0C03\x071-\x0711모우디씨…… 저번에는\n"
.stringn "감사했습니다……\n"
.stringn "엄청, 도움이 됐어요……\n"
.stringn "\x0703그, 그래…… 신경 쓰지 마라.\n"
.stringn "그나저나 너, 많이 먹는다.\n"
.stringn "모우디가 12명 있는 것 같았다.\n"
.stringn "\x0711대접해 주신\n"
.stringn "요리는 맛있었지만……\n"
.stringn "양이 적어서 아쉬웠어요……\n"
.stringn "\x0703모우디는 이제 돈이 없다.\n"
.stringn "미안하지만 포기했으면 한다.\n"
.stringn "그나저나 이레이스는 정말 많이 먹는다.\n"
.stringn "그 많은 음식이 모두 어디로 가나?\n"
.stringn "\x0711배 안으로요……\n"
.stringn "\x0703으으음……\n"
.stringn "그러고 보니, 생각났다.\n"
.stringn "모우디랑 같이 숲에 사는 다람쥐는,\n"
.stringn "몸이 작은데도 항상 뭔가를 볼에 넣었다.\n"
.stringn "이레이스는 베오크지만,\n"
.stringn "분명 다람쥐랑 같은 부류일 거다.\n"
.stringn "\x0711그럴지도…… 모르겠네요……\n"
.stringn "다람쥐라… 귀여운 비유군요……\n"
.stringn "\x0703그래서…\n"
.stringn "이레이스는 언제 겨울잠을 자나?\n"
.stringn "\x0711겨울잠은 안 자요."
db 0
.align 4
//MYELL_8_ELAICE_MORDY_A

//0xDA50
Text_DA30:
.stringn "\x05FL|MORDY|ELAICE||\x0701으으으!\n"
.stringn "\x071-\x0713안녕하세요, 모우디씨……\n"
.stringn "짐을 나르고\n"
.stringn "계신 건가요……?\n"
.stringn "\x0701그렇다. 모우디는 힘이 세니까\n"
.stringn "이럴 때는 도움이 된다.\n"
.stringn "이제 이것만 나르면 끝이다.\n"
.stringn "\x0713그렇게 많은 짐을\n"
.stringn "한 번에…… 대단해요.\n"
.stringn "\x0701너도 잔뜩 먹어서\n"
.stringn "살을 붙이는 편이 좋다.\n"
.stringn "커지면 맞아도 버틸 수 있다.\n"
.stringn "\x0713사실은 저도 그렇게 되고 싶어요……\n"
.stringn "하지만 저는 돈이 없어서……\n"
.stringn "만족스럽게 먹을 수가 없거든요……\n"
.stringn "그러니까 금방이라도 쓰러지게 돼서……\n"
.stringn "\x0701으음, 그랬던 건가……\n"
.stringn "이레이스는, 먹고 싶은 걸 못 먹는다니…\n"
.stringn "그건 불쌍하다.\n"
.stringn "알았다. 모우디가 대접한다.\n"
.stringn "아무거나 먹고 싶은 대로 마음껏 먹어라.\n"
.stringn "\x0713네……?\n"
.stringn "그 말 정말……이신가요?\n"
.stringn "\x0701그래, 정말이다.\n"
.stringn "\x0713정말로…… 정말로요?\n"
.stringn "\x0701?\n"
.stringn "그렇다, 모우디는 거짓말 안 한다.\n"
.stringn "\x0713감사합니다……\n"
.stringn "당신은 마치… 여신님처럼\n"
.stringn "굉장한 분이시군요……\n"
.stringn "\x0701그런가?\n"
.stringn "그렇게 칭찬받으니 부끄럽다."
db 0
.align 4
//MYELL_8_ELAICE_MORDY_B

//0xD73C
Text_D71C:
.stringn "\x05FL|ELAICE|MORDY||\x0701아…\n"
.stringn "\x0713크, 큰일이다…!\n"
.stringn "괜찮나? 정신 차려라!\n"
.stringn "\x0701……아…\n"
.stringn "당신은… 확실히……\n"
.stringn "\x0713모우디다.\n"
.stringn "너는 분명… 이레이스?\n"
.stringn "얘기하는 거, 처음이다.\n"
.stringn "\x0701그렇네요…\n"
.stringn "같은 동료인데도……\n"
.stringn "저… 존재감이 없어서……\n"
.stringn "……자주 잊혀지거든요……\n"
.stringn "아……윽……\n"
.stringn "\x0713왜 그러나?\n"
.stringn "\x0701죄송합니다, 잠깐\n"
.stringn "발밑이 휘청거려서……\n"
.stringn "자주 있는 일이니까……\n"
.stringn "신경 쓰지 않으셔도 돼요……\n"
.stringn "\x0713으음…………\n"
.stringn "베오크 중에서도,\n"
.stringn "너는 무척 가늘어 보인다.\n"
.stringn "그런 가는 몸으로 싸울 수 있나?\n"
.stringn "\x0701네…… 어떻게든요.\n"
.stringn "\x0713하지만 그런 상태로는…\n"
.stringn "적이랑 부딪치기만 해도\n"
.stringn "쓰러져 버리지 않나?\n"
.stringn "\x0701그때는 어쩔 수 없죠……\n"
.stringn "그렇게 될 각오는 되어 있으니까요……\n"
.stringn "\x0713으으음…… 걱정이다……\n"
.stringn "알았다. 모우디가 너의 앞을 지킨다.\n"
.stringn "모우디가 벽이 돼서 적을 막을 테니까,\n"
.stringn "이레이스는 무리하지 마라.\n"
.stringn "\x0701아……\n"
.stringn "감사합니다……"
db 0
.align 4
//MYELL_8_ELAICE_MORDY_C

//0xE538
Text_E518:
.stringn "\x05FL|WAYU|ELAICE||\x0706으~음, 오늘은 상태가 별로네.\n"
.stringn "이래선 강적에게 웃음거리가 될 거야.\n"
.stringn "더 집중해야지!\n"
.stringn "……그러고 보니 이레이스, 요즘 안 보이네.\n"
.stringn "건강했으면 좋겠는데 왠지 걱정된다.\n"
.stringn "뭐, 생각해 봤자 소용없지!\n"
.stringn "그것보다 수행하자 수행……\n"
.stringn "어라?\n"
.stringn "\x0701뭐, 뭔가를 밟아 버렸는데?\n"
.stringn "\x071-\x0713……\n"
.stringn "\x0701우왓!?\n"
.stringn "왜 이런 데 쓰러져 있는 거야!\n"
.stringn "괜찮아!?\n"
.stringn "\x0713배가……\n"
.stringn "\x0701왜, 왜 그래?\n"
.stringn "배 아파?\n"
.stringn "\x0713……고파요.\n"
.stringn "\x0701응……?\n"
.stringn "\x0713뭔가…… 먹을 걸……\n"
.stringn "\x0701저기……\n"
.stringn "너 계속 휘청휘청거리던 게\n"
.stringn "설마 배고파서 그런 거였어?\n"
.stringn "\x0713네……\n"
.stringn "저, 먹어도 먹어도 바로 배가 고파져서……\n"
.stringn "쓰러져 버렸…… ……\n"
.stringn "\x0701엇, 자, 잠깐만!\n"
.stringn "나 지금 먹을 거 없는데!\n"
.stringn "이, 일단 다른 사람 불러올 테니까――\n"
.stringn "윽히에엑!?\n"
.stringn "\x0718가……가지 마세……요……\n"
.stringn "\x0701아, 다리!\n"
.stringn "다리 잡혀 버렸다!\n"
.stringn "힘 엄청 세잖아!\n"
.stringn "\x0C18\x0712뭔가, 먹을 걸……\n"
.stringn "\x0701아, 알았어! 알았다니까~!\n"
.stringn "도와줘~! 뭐라도 좋으니까\n"
.stringn "먹을 걸 가져와 줘!\n"
.stringn "안 그러면 얘랑 내가 위험하다고~!!"
db 0
.align 4
//MYELL_8_ELAICE_WAYU_A

//0xE2C8
Text_E2A8:
.stringn "\x05FL|WAYU|ELAICE||\x0C01\x0C13\x0701아, 너는 지난번에……\n"
.stringn "\x0713안녕하세요……\n"
.stringn "\x0701오늘도 왠지\n"
.stringn "휘청휘청거리는데, 어디 아파?\n"
.stringn "\x0713아뇨…… 아픈 곳은 없어요.\n"
.stringn "\x0701그래도 안색이 안 좋은 것 같은데?\n"
.stringn "한번 의사한테 봐 달라고 부탁해 봐.\n"
.stringn "\x0713정말로, 괜찮아요……\n"
.stringn "전에 봐 달라고 했을 때에도,\n"
.stringn "병은 없다고 들었거든요……\n"
.stringn "\x0701그래?\n"
.stringn "으~음, 그거 돌팔이 아니야?\n"
.stringn "왠지 금방이라도 쓰러질 것 같은데.\n"
.stringn "\x0713죄송해요……\n"
.stringn "\x0701뭐, 됐어.\n"
.stringn "안 아프다면 다행이긴 한데.\n"
.stringn "제대로 걸을 순 있어?\n"
.stringn "\x0713네…… 그럼 또 봐요……\n"
.stringn "\x0701아니 거긴 막다른 길이야!\n"
.stringn "\x0C13\x0C01정말, 내가 데려다줄게!\n"
.stringn "어디로 가는지 말해!\n"
.stringn "\x0713네……\n"
.stringn "당신은 상냥한 분이시군요……"
db 0
.align 4
//MYELL_8_ELAICE_WAYU_B

//0xE0B4
Text_E094:
.stringn "\x05FL|WAYU|ELAICE||\x070-\x0706좋았어, 오늘은 상태가 최고야!\n"
.stringn "뭔가 좋은 일이 있을 것만 같아!\n"
.stringn "숙명의 라이벌과 만날지도 몰라!\n"
.stringn "\x0711…………\n"
.stringn "\x0C06\x0703우와앗! 깜짝 놀랐네!\n"
.stringn "뭐, 뭐야?\n"
.stringn "간단하게 내 뒤를 잡다니\n"
.stringn "꽤 하잖아!\n"
.stringn "\x0711저기……\n"
.stringn "잠깐, 거기 좀 지나갈게요……\n"
.stringn "\x0703어? 아, 미안.\n"
.stringn "\x0711실례하겠습니다……\n"
.stringn "\x0703승부 상대로는……\n"
.stringn "역시 무리겠지.\n"
.stringn "그것보다 제대로 걸을 수나 있어?\n"
.stringn "\x0711네, 마음 써 주셔서\n"
.stringn "감사합니다……\n"
.stringn "\x0703엄청 연약한 여자애네……\n"
.stringn "나하고는 정반대인걸.\n"
.stringn "왠지 지켜 주고 싶어질 정도야……\n"
.stringn "아 이런, 수행하자 수행!"
db 0
.align 4
//MYELL_8_ELAICE_WAYU_C

//0xEE88
Text_EE68:
.stringn "\x05FL|ZIHARK|ELAICE||\x0C01\x0713아……\n"
.stringn "\x0701안녕, 이레이스.\n"
.stringn "요즘 자주 만나네?\n"
.stringn "\x0713…………네, 네에……\n"
.stringn "……………………\n"
.stringn "\x0701무슨 일 있어?\n"
.stringn "평소랑 조금… 상태가 다른데.\n"
.stringn "\x0713아, 아시겠나요……?\n"
.stringn "\x0701그래.\n"
.stringn "오늘은 왠지\n"
.stringn "평소 이상으로 귀여운 느낌이야.\n"
.stringn "\x0713!\n"
.stringn "그, 그런…가요?\n"
.stringn "\x0701…혹시……\n"
.stringn "\x0713………\n"
.stringn "\x0701평소보다도 더\n"
.stringn "배가 고픈 거야?\n"
.stringn "\x0713………네…?\n"
.stringn "\x0701넌 군 남자들 사이에서\n"
.stringn "꽤나 유명 인사거든.\n"
.stringn "귀여운 얼굴에 이끌려 다가갔다가\n"
.stringn "따끔한 맛을 봤다고.\n"
.stringn "\x0713그……\n"
.stringn "그래요……?\n"
.stringn "\x0701권유한 쪽에도 책임은 있지만,\n"
.stringn "비싼 밥값을 냈는데\n"
.stringn "다음 날 만나면\n"
.stringn "얼굴도 이름도 기억하지 못한다며?\n"
.stringn "너무한 거 같은데.\n"
.stringn "\x0713………저……\n"
.stringn "그…… 배가 너무 고프면……\n"
.stringn "쓰러져 버려요……\n"
.stringn "그러니… 여러분의 도움을… 바로…\n"
.stringn "받아들여… 버려서……………\n"
.stringn "\x0701…그렇다면 이름 정도는 외워야지.\n"
.stringn "속셈이 있었다곤 해도,\n"
.stringn "모두 네게 도움…이랄까\n"
.stringn "호의를 베풀고 있는 거잖아.\n"
.stringn "\x0713……죄…죄송합니다……\n"
.stringn "\x0701사과할 상대는 내가 아니라고.\n"
.stringn "\x0713……네………\n"
.stringn "\x0701…자 그럼, 같이 가자.\n"
.stringn "\x0713네…?\n"
.stringn "\x0701또 쓰러질 정도로 배가 고픈 거잖아?\n"
.stringn "멋대로 설교한 사죄로 밥 살게.\n"
.stringn "\x0713괜찮으신가요…?\n"
.stringn "\x0701너와는 비교적\n"
.stringn "오랜 동료 사이이기도 하고 말이야.\n"
.stringn "다만…\n"
.stringn "나는 부자가 아니니까, 기껏해야\n"
.stringn "2인분이 한계야.\n"
.stringn "\x0713이, 이런 은혜를…\n"
.stringn "저… 그걸로 충분해요…\n"
.stringn "너무 기뻐요…!\n"
.stringn "감사합니다……\n"
.stringn "…………앗, 그……\n"
.stringn "\x0701…지하크.\n"
.stringn "\x0713…죄…죄송합니다……\n"
.stringn "지하크씨…"
db 0
.align 4
//MYELL_8_ELAICE_ZIHARK_A

//0xEBB8
Text_EB98:
.stringn "\x05FL|ELAICE|ZIHARK||\x0C01\x0C13\x0701……저, 저기……\n"
.stringn "\x0713왜 그래, 이레이스?\n"
.stringn "또 배가 고픈 거야?\n"
.stringn "\x0701네, 네에……\n"
.stringn "\x0713너는 보기와는 다르게\n"
.stringn "대식가니까.\n"
.stringn "마법을 쓰는 건 그렇게나\n"
.stringn "체력이 소모되는 일인 거야?\n"
.stringn "\x0701글쎄요……\n"
.stringn "왜 그런지는 모르겠습니다만……\n"
.stringn "곧바로 배가 고파져요……\n"
.stringn "오늘은 다행히 4인분을 먹었지만……\n"
.stringn "평소에는 3인분밖에 없는 게…… 괴로워서……\n"
.stringn "\x0713하하, 그거 굉장한데.\n"
.stringn "그럼 먹은 만큼\n"
.stringn "열심히 일해서 갚아야지.\n"
.stringn "힘내.\n"
.stringn "\x0701아… 저기…\n"
.stringn "잠깐 기다려… 주세요……!\n"
.stringn "\x0C13\x0714왜 그래?\n"
.stringn "\x0701저기……\n"
.stringn "뭔가… 잊은 거 없으신가요…?\n"
.stringn "\x0714내가? ……아니,\n"
.stringn "딱히 아무것도 없다고 생각하는데?\n"
.stringn "\x0701……그렇…군요…\n"
.stringn "\x0714그럼, 다음에 보자.\n"
.stringn "\x0701………………\n"
.stringn "아무것도, 주지 않은 사람은……\n"
.stringn "처음이야…… ……"
db 0
.align 4
//MYELL_8_ELAICE_ZIHARK_B

//0xE8E8
Text_E8C8:
.stringn "\x05FL|ZIHARK|ELAICE||\x0C01\x0C13\x0701……이레이스?\n"
.stringn "아까부터 뭘 보는 거야?\n"
.stringn "\x0713네? 아……\n"
.stringn "그…… 허리에 찬 자루 말인데요……\n"
.stringn "\x0701별로 대단한 건\n"
.stringn "아니라고 생각하는데……\n"
.stringn "약이나 보존식을 넣어서 휴대하고 있어.\n"
.stringn "……이게 왜?\n"
.stringn "\x0713그, 그게……\n"
.stringn "맛있는 냄새가…… 나서……\n"
.stringn "\x0701…그렇게 냄새나?\n"
.stringn "말린 거밖에 안 넣었는데.\n"
.stringn "\x0713죄……죄송합니다……\n"
.stringn "저…… 그, 배가 고파서……\n"
.stringn "\x0701아까 네가 건강하게\n"
.stringn "식사하는 걸 봤는데?\n"
.stringn "아직 시간도 별로 안 지났잖아.\n"
.stringn "그렇게 소화가 잘 되다니\n"
.stringn "보기와는 다르게 꽤나 건강하구나.\n"
.stringn "그럼, 난 이만 갈게.\n"
.stringn "\x0713아……\n"
.stringn "\x0C01\x0C13………………\n"
.stringn "어떡하지…………\n"
.stringn "뭔가 먹어야 하는데…… 못 움직이겠어…\n"
.stringn "………………\n"
.stringn "달라고 할 걸 그랬…나……"
db 0
.align 4
//MYELL_8_ELAICE_ZIHARK_C

//0xF87C
Text_F85C:
.stringn "\x05FL|ERINCIA|GEOFFRAY||\x0C01\x071-\x0C13\x0701……지난번이랑은 반대군요.\n"
.stringn "제프리…? 제 말을 들어주세요.\n"
.stringn "\x0713……듣고 있습니다.\n"
.stringn "\x0701……제프리… 전장에서의 당신은,\n"
.stringn "저를 감싸려 하는 나머지……\n"
.stringn "너무 무리한 전투 방식을 취하고 있어요.\n"
.stringn "\x0713주군을 보호하고 감싸는 것이 기사의 역할입니다.\n"
.stringn "\x0701하지만 그것 때문에…\n"
.stringn "당신 자신이 여러 번 위험에 처했지요.\n"
.stringn "\x0713확실히, 몇 번인가…\n"
.stringn "얕지 않은 상처를 입었습니다.\n"
.stringn "\x0701당신은… 전에,\n"
.stringn "저를 위해서 목숨을 버리는 짓은\n"
.stringn "하지 않겠다고 약속했습니다.\n"
.stringn "그런데도…… 역시\n"
.stringn "자신의 목숨을 소중히 여기지 않고 있죠.\n"
.stringn "\x0713공주님… 그치만…!\n"
.stringn "\x0701저는, 전장에 나가지 않고…\n"
.stringn "본영에서 가만히 있는 편이\n"
.stringn "더 좋다는 것은……\n"
.stringn "알고 있습니다.\n"
.stringn "그래도……\n"
.stringn "제 손이 닿지 않는 곳에서…\n"
.stringn "소중한 사람의 목숨이 빼앗긴다는 것을……\n"
.stringn "더는… 견딜 수 없어서……\n"
.stringn "그 때문에……\n"
.stringn "제프리에게 부담을………\n"
.stringn "\x0713공주님… 공주님께선 눈치채지 못하셨군요.\n"
.stringn "당신이 전장에 나와서,\n"
.stringn "크리미아병들의 사기가…\n"
.stringn "얼마나 올라갔는지 모르십니까?\n"
.stringn "주군인 당신께서 전장에 계신다는 것은,\n"
.stringn "확실히… 엄청 불안한\n"
.stringn "일임에는 틀림없습니다.\n"
.stringn "하지만, 그렇기 때문에\n"
.stringn "우리는 질 수 없는 겁니다.\n"
.stringn "반드시 이겨야 한다고 생각해…\n"
.stringn "본래 갖추고 있는 것 이상의 힘을\n"
.stringn "발휘할 수 있는 겁니다.\n"
.stringn "\x0701………\n"
.stringn "\x0713확실히, 저는…\n"
.stringn "최근 무모한 전투 방식을 취했습니다.\n"
.stringn "그건… 공주님께서 가까이 계셨으면\n"
.stringn "했기 때문이었습니다.\n"
.stringn "제가 조금만 엉뚱한 짓을 하더라도…\n"
.stringn "공주님이 바로 옆에서 상처를 치유해 주시니……\n"
.stringn "그것에 너무 응석을 부렸던 모양입니다.\n"
.stringn "\x0701……저는…\n"
.stringn "폐를 끼치고 있는 게…… 아니었나요…?\n"
.stringn "\x0713공주님을 제외한 전투 방식은…\n"
.stringn "이제 생각할 수도 없습니다.\n"
.stringn "제 목숨을 아끼고 계신다면,\n"
.stringn "부디 앞으로도\n"
.stringn "전장에서 힘을 빌려주십시오.\n"
.stringn "\x0701제프리… 미안해요.\n"
.stringn "멋대로 오해하고\n"
.stringn "화를 내서… 당신을 괴롭게 했군요.\n"
.stringn "저는… 미숙한 주인입니다.\n"
.stringn "\x0713명령을 위반하는 저도, 그다지\n"
.stringn "칭찬받을 만한 신사는 아니라구요.\n"
.stringn "\x0701앞으로도 분명…\n"
.stringn "잔뜩 폐를 끼칠 거라 생각하지만……\n"
.stringn "계속 옆에 있어 줘요, 제프리.\n"
.stringn "\x0713엘린시아 공주님…\n"
.stringn "제 검은 평생 당신만의 것입니다."
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_GEOFFRAY_A

//0xF5A0
Text_F580:
.stringn "\x05FL|ERINCIA|GEOFFRAY||\x070-\x0C01\x0713……공주님?\n"
.stringn "공주님… 부디, 기분을 풀어 주십시오.\n"
.stringn "\x0701………\n"
.stringn "\x0713제가… 공주님의 명령을\n"
.stringn "지키지 않았던 것 때문에,\n"
.stringn "화가 나신 것은 알고 있습니다.\n"
.stringn "하지만…!\n"
.stringn "공주님의 기사인 제게…\n"
.stringn "전장에서 상관하지 말라니…\n"
.stringn "너무나도 무리한 명령이 아닌가 해서……\n"
.stringn "만약 제게 부족한 점이 있고,\n"
.stringn "그것을 불복으로 여기신다면…\n"
.stringn "차라리 기사의 칭호를 박탈해 주십시오.\n"
.stringn "\x0701………\n"
.stringn "\x0713공주님…!\n"
.stringn "\x0701……기사의 칭호를 빼앗으면…\n"
.stringn "제프리는 저를 지키는 것을\n"
.stringn "그만둬 주는 건가요?\n"
.stringn "\x0713!!\n"
.stringn "\x0701………\n"
.stringn "\x0713…공주님은… 그렇게까지 저를\n"
.stringn "불쾌하게 생각하신 겁니까……\n"
.stringn "\x0701! 아니에요…!\n"
.stringn "\x0713경솔한 말을 했습니다만…\n"
.stringn "조국 부흥의 날까지는…\n"
.stringn "……부디, 이대로……\n"
.stringn "공주님을 지키는 기사로 있게 해 주십시오.\n"
.stringn "………죄송합니다……\n"
.stringn "\x0701잠깐, 제프리…!\n"
.stringn "제프리……!!"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_GEOFFRAY_B

//0xF3D8
Text_F3B8:
.stringn "\x05FL|ERINCIA|GEOFFRAY||\x0701……\n"
.stringn "\x0713공주님?\n"
.stringn "누구를 찾으시는 겁니까?\n"
.stringn "\x0701제프리.\n"
.stringn "다행이다, 거기에 있었군요.\n"
.stringn "\x0713제게 용건이 있으십니까?\n"
.stringn "\x0701네. 저…\n"
.stringn "제프리에게 부탁이 있어요.\n"
.stringn "\x0713공주님께서 제게 부탁을 하시다니…\n"
.stringn "어떤 것이라도 상관없습니다.\n"
.stringn "명령을 내려 주십시오.\n"
.stringn "\x0701…정말로요?\n"
.stringn "\x0713예.\n"
.stringn "\x0701그럼, 말할게요.\n"
.stringn "제프리… 앞으로는 일절,\n"
.stringn "전장에서 저를 신경 쓰지 말아 주세요.\n"
.stringn "\x0713예!?\n"
.stringn "공주님, 그건…\n"
.stringn "\x0701반론은 듣지 않겠습니다.\n"
.stringn "이건… 명령이니까요.\n"
.stringn "반드시, 지켜 주세요.\n"
.stringn "\x0713…공주님……"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_GEOFFRAY_C

//0x107C4
Text_107A4:
.stringn "\x05FL|ERINCIA|IKE||\x0701…………\n"
.stringn "\x0713드디어 내일은 왕도구나.\n"
.stringn "\x0701……네.\n"
.stringn "\x0713기분은 어때?\n"
.stringn "\x0701…무척 불안해요. 하지만……\n"
.stringn "드디어 도착했다.\n"
.stringn "드디어 돌아왔다.\n"
.stringn "그 두 기쁨이 더 강해요.\n"
.stringn "\x0713강해졌구나.\n"
.stringn "\x0701바로 옆에…\n"
.stringn "좋은 본보기가 있었던 덕분이에요.\n"
.stringn "\x0713나쁜 본보기겠지.\n"
.stringn "너 남쪽 바다에서\n"
.stringn "자기가 뭐라고 했는지 잊었어?\n"
.stringn "\x0701뭐, 뭐라고 했나요…?\n"
.stringn "저 뭔가 이상한 말을 했었나요?\n"
.stringn "\x0713『냅다 날려 버려 주세요!』\n"
.stringn "였던가?\n"
.stringn "\x0701그… 그건…\n"
.stringn "한번 아이크님의 흉내를\n"
.stringn "내보고 싶어서 그랬어요.\n"
.stringn "저도 다른 분들처럼\n"
.stringn "용감해지고 싶어서……\n"
.stringn "\x0713아무리 그래도 그땐 당황했다니까.\n"
.stringn "\x0701후후 ……왠지\n"
.stringn "엄청 그립네요.\n"
.stringn "\x0C13\x0C01왕도에서 도망쳐 나왔을 때…\n"
.stringn "갈리아에서… 크리미아의 패전 소식을\n"
.stringn "들었을 때…\n"
.stringn "앞으로 절 기다리는 건\n"
.stringn "절망뿐이라고 생각하고 있었어요…\n"
.stringn "…그렇지만 이렇게 돌이켜 보니\n"
.stringn "희망은 얼마든지 있었네요……\n"
.stringn "너무나도 따뜻한 희망의 빛이……\n"
.stringn "\x0713그래……\n"
.stringn "\x0701저는… 이 희망을 가슴에 품고……\n"
.stringn "내일 전투에 임하겠어요.\n"
.stringn "데인 왕을 쓰러뜨리고,\n"
.stringn "크리미아를 되찾기 위해서.\n"
.stringn "\x0713난 네게 고용된 용병이야.\n"
.stringn "네 소망을 이루기 위해\n"
.stringn "전력을 다하겠다고 약속할게.\n"
.stringn "\x0701아이크님……"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_IKE_A

//0x10384
Text_10364:
.stringn "\x05FL|IKE|ERINCIA||\x0701…아직 여기에 있었구나.\n"
.stringn "\x0713아…… 아이크님.\n"
.stringn "그… 자율 훈련을 하고 있었어요…\n"
.stringn "조금이라도 발목을\n"
.stringn "잡고 싶지 않아서……\n"
.stringn "\x0701……그렇구나.\n"
.stringn "하지만 훈련이라면 누군가 상대가 있는 편이\n"
.stringn "좋지 않을까?\n"
.stringn "\x0713……이렇게 긴장한 상태인 데다가…\n"
.stringn "명백하게 실력이 뒤떨어지는 사람의\n"
.stringn "상대를 부탁드리는 건… 너무 죄송해서……\n"
.stringn "\x0701…지난번에 남에게 의지하는 걸\n"
.stringn "주저하지 말라고 했었는데…\n"
.stringn "잘 전해지지 않은 모양이네.\n"
.stringn "\x0713아뇨, 그…\n"
.stringn "충고해 주신 건 마음에 잘 새겨뒀어요.\n"
.stringn "하지만… 그게……\n"
.stringn "\x0701……자신의 나약함이 느껴지고,\n"
.stringn "초조한 마음이 드는 건 잘 알아.\n"
.stringn "나도 아버지가 남긴 그레일 용병단을\n"
.stringn "잇겠다고 결정했을 때에는……\n"
.stringn "안절부절못했었거든.\n"
.stringn "\x0713…………\n"
.stringn "\x0701뭐, 나라와 용병단의 무게는 전혀 다르겠지.\n"
.stringn "미안, 건방진 말을 해 버렸어.\n"
.stringn "\x0713아뇨……\n"
.stringn "말씀하신 대로입니다.\n"
.stringn "앞으로 제가 짊어져야 할 것의 크기를 생각하니\n"
.stringn "자신의 부족함이…… 괴로워서……\n"
.stringn "\x0701내가 지난 일 년 동안…\n"
.stringn "싸움을 통해서 배운 것은…\n"
.stringn "나 혼자서 해낸 일이\n"
.stringn "사실은 얼마 없다는 거야.\n"
.stringn "동료들이 나를 지지해 주고,\n"
.stringn "내가 그걸 의지할 수 있었기 때문에…\n"
.stringn "여기까지 올 수 있었던 게 아니었을까.\n"
.stringn "그렇게 생각해.\n"
.stringn "너도 똑같아.\n"
.stringn "넌 혼자가 아니야.\n"
.stringn "\x0713…………네……!"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_IKE_B

//0xFF88
Text_FF68:
.stringn "\x05FL|IKE|ERINCIA||\x0703엘린시아 공주.\n"
.stringn "왜 그러고 있어?\n"
.stringn "\x0711아…… 아이크님.\n"
.stringn "그, 싸울 준비를 하고 있었는데\n"
.stringn "검이 허리에 잘 안 채워져서……\n"
.stringn "\x0703잠깐 보여 줘 봐.\n"
.stringn "…아, 칼집이 묶인\n"
.stringn "허리띠가 제대로 안 잠겼네.\n"
.stringn "이걸 채우려면 조금 요령이 필요해.\n"
.stringn "잠시 움직이지 말아 줘.\n"
.stringn "…………\n"
.stringn "좋아, 이제 괜찮을 거야.\n"
.stringn "\x0711감사합니다, 아이크님.\n"
.stringn "……저, 한심하죠.\n"
.stringn "혼자서 싸울 준비도 못 하고……\n"
.stringn "다른 분들은 벌써 다 끝내셨는데…\n"
.stringn "\x0703처음에는 누구나 다 그래.\n"
.stringn "나도 전까지만 해도\n"
.stringn "공주랑 비슷했으니까.\n"
.stringn "\x0711아이크님이요?\n"
.stringn "\x0703그래.\n"
.stringn "하지만 나는 아버지한테 어떠한 환경에서도\n"
.stringn "살아갈 수 있는 기술과 검을 다루는 법을\n"
.stringn "다른 것보다도 먼저 배웠으니까,\n"
.stringn "공주와는 조금 다를지도 모르겠네.\n"
.stringn "\x0711그러셨군요……\n"
.stringn "\x0703그러니까 성급해하지 않아도 돼.\n"
.stringn "넌 태어날 때부터 우리들\n"
.stringn "용병과는 다르게 살아왔잖아.\n"
.stringn "낯선 곳에서 무리를 하면…\n"
.stringn "전장에서 죽을지도 몰라.\n"
.stringn "\x0711아, 알겠습니다……\n"
.stringn "\x0703……어쨌든 필요 이상으로\n"
.stringn "깊게 생각하지 마.\n"
.stringn "할 수 없는 것들을 자각하고\n"
.stringn "남에게 도움을 구하는 건…\n"
.stringn "부끄러운 일이 아니니까.\n"
.stringn "\x0711네……\n"
.stringn "\x0703…………"
db 0
.align 4
//MYELL_8_ERINCIA_QUEEN_IKE_C

//0x112B8
Text_11298:
.stringn "\x05FL|MARCIA|GATRIE||\x070-\x0703아, 가트리씨.\n"
.stringn "\x0711…………\n"
.stringn "\x0703어라, 왜 그러세요?\n"
.stringn "기운이 없네요.\n"
.stringn "\x0711……나 같은 패배자한테는\n"
.stringn "더 이상 말 걸지 않는 편이 좋아.\n"
.stringn "나 같은 건\n"
.stringn "널부러진 돌멩이를 보는 듯한 눈으로\n"
.stringn "바라봐 주면 돼……\n"
.stringn "\x0703네, 네에……\n"
.stringn "아, 혹시 가트리씨\n"
.stringn "지난번 일이 신경 쓰이시는 거예요?\n"
.stringn "훈련에서 아이크씨에게 완패……\n"
.stringn "\x0711이, 이제 그 일은\n"
.stringn "생각나게 하지 말아 줘~!\n"
.stringn "실컷 큰소리친 주제에\n"
.stringn "그렇게 꼴사나운 패배를\n"
.stringn "하필이면 네게 보여 주다니…\n"
.stringn "나는 이제 글렀어.\n"
.stringn "세계에서 제일 글러먹은 남자야……\n"
.stringn "\x0703그렇지 않아요.\n"
.stringn "확실히 그때는\n"
.stringn "아이크씨가 승리했지만……\n"
.stringn "그래도 가트리씨가\n"
.stringn "열심히 하는 모습, 멋있었거든요.\n"
.stringn "\x0711저, 정말이야!?\n"
.stringn "\x0703네, 둘 다 엄청 강했어요.\n"
.stringn "저도 질 수는 없죠.\n"
.stringn "다음에 같이 훈련하게 해 주세요.\n"
.stringn "아이크씨나 가트리씨에게\n"
.stringn "여러 가지를 배우고 싶으니까요.\n"
.stringn "\x0711무, 물론이지!\n"
.stringn "\x0703다행이다.\n"
.stringn "기대하고 있을게요!\n"
.stringn "그럼 이만!\n"
.stringn "\x0711…… …… ……\n"
.stringn "아이크, 나 살짝\n"
.stringn "너를 원망하고 있었는데……\n"
.stringn "지금은 고맙다는\n"
.stringn "마음뿐이야!\n"
.stringn "또 보자, 마샤!"
db 0
.align 4
//MYELL_8_GATRIE_MARCIA_A

//0x10F74
Text_10F54:
.stringn "\x05FL|MARCIA|GATRIE||\x0C01\x071-\x0C13\x0701무슨 일인가요, 가트리씨?\n"
.stringn "저한테 무슨 볼일이라도 있나요?\n"
.stringn "\x0713안녕, 잘 와줬어 마샤.\n"
.stringn "실은 내가 지금부터 아이크 녀석하고\n"
.stringn "실전 훈련을 하기로 했거든.\n"
.stringn "\x0701네에!?\n"
.stringn "가트리씨,\n"
.stringn "아이크씨랑 싸우는 거예요?\n"
.stringn "\x0713물론이지! 그래서 널 부른 거야.\n"
.stringn "내가 평소에 감추고 있는 진짜 힘을\n"
.stringn "너한테만 보여 주고 싶어서.\n"
.stringn "아이크는 단장이라서 강하지만,\n"
.stringn "내 진짜 실력은\n"
.stringn "그보다 더 위니까 말이지.\n"
.stringn "\x0701그렇군요……\n"
.stringn "가트리씨는 굉장히 강하시네요.\n"
.stringn "존경스럽습니다.\n"
.stringn "\x0713아니 뭐~ 하하하하하!\n"
.stringn "아무튼, 거기서 내 강함을\n"
.stringn "잘 지켜봐 줘 마샤.\n"
.stringn "\x0716오, 아이크!\n"
.stringn "준비는 됐냐? 간다!\n"
.stringn "\x0C01\x0718마샤,\n"
.stringn "너를 향한 사랑으로, 나는 이기겠어!\n"
.stringn "우오오오오오오~~~!!\n"
.stringn "……크헉!?\n"
.stringn "\x0701아~……\n"
.stringn "지금 거 아프겠다.\n"
.stringn "\x0718……자, 잠깐 아이크!\n"
.stringn "조금 봐줘…… 키에엑!?\n"
.stringn "\x0701가트리씨, 괜찮으려나……?"
db 0
.align 4
//MYELL_8_GATRIE_MARCIA_B

//0x10BE8
Text_10BC8:
.stringn "\x05FL|MARCIA|GATRIE||\x0C01\x071-\x0713안녕 마샤!\n"
.stringn "\x0701앗? 어떻게 제 이름을?\n"
.stringn "\x0713너같이 귀여운 애의\n"
.stringn "이름은 당연히 알고 있어야지!\n"
.stringn "그나저나 내가 예전에 있었을 때는\n"
.stringn "함께 싸우는 여성이라고 하면\n"
.stringn "티아마트씨밖에 없었는데……\n"
.stringn "잠시 떨어져 있는 사이에\n"
.stringn "좋은 용병단이 되었구나.\n"
.stringn "응응.\n"
.stringn "\x0701혹시…\n"
.stringn "예전에 그레일 용병단에 있었던 분이신가요?\n"
.stringn "\x0713맞아.\n"
.stringn "나는 그 아이크의\n"
.stringn "대선배라구.\n"
.stringn "\x0701아~ 역시!\n"
.stringn "제가 해적에게\n"
.stringn "습격당했을 때\n"
.stringn "도와주러 오셨던 분 맞죠!\n"
.stringn "\x0713어…!?\n"
.stringn "\x0701저, 그때의 일은\n"
.stringn "정말 감사하고 있어요…\n"
.stringn "받은 은혜를 갚기 위해서\n"
.stringn "열심히 하고 있습니다!\n"
.stringn "\x0713아, 아아. 그래!\n"
.stringn "너같이 우수한 천마 기사가\n"
.stringn "들어와 준 것만으로도 충분해!\n"
.stringn "실제로 나는…… 네가 이 용병단에\n"
.stringn "있어 주기만 한다면… 다른 건 필요 없다구!\n"
.stringn "\x0701그, 그렇게나 기대해 주시다니\n"
.stringn "조금 긴장되는걸요…………\n"
.stringn "아, 아무튼, 앞으로도\n"
.stringn "열심히 할 테니 잘 부탁드려요!\n"
.stringn "\x0713아아, 이 얼마나 귀여운 아이인가.\n"
.stringn "역시 이건……\n"
.stringn "운명이지? 그렇지?"
db 0
.align 4
//MYELL_8_GATRIE_MARCIA_C

//0x12034
Text_12014:
.stringn "\x05FL|GATRIE|STELLA||\x070-\x0C01\x071-\x0713가트리씨,\n"
.stringn "오늘도 잘 부탁드려요.\n"
.stringn "\x0701네!\n"
.stringn "어~ 그럼, 지난번의 이야기입니다만…\n"
.stringn "스텔라씨, 『임기응변』이라는 말이\n"
.stringn "무슨 의미인지 아시나요?\n"
.stringn "\x0713네, 알고 있어요.\n"
.stringn "\x0701예!?\n"
.stringn "알고 있나요?\n"
.stringn "\x0713그때그때의 상황이나 변화에 따라\n"
.stringn "적절하게 대처하는 것……이죠?\n"
.stringn "\x0701아, 과연!\n"
.stringn "뭐야, 그런 뜻이구나.\n"
.stringn "지난번의 대답은 그겁니다, 예!\n"
.stringn "역시 스텔라씨는 똑똑하시네요!\n"
.stringn "아니, 물론 저도 알고 있었습니다?\n"
.stringn "알고 있었는데, 잠깐\n"
.stringn "학생을 시험해 볼까 생각했을 뿐이에요.\n"
.stringn "이야 벌써 합격! 합격입니다!\n"
.stringn "\x0713네, 그런 식으로\n"
.stringn "칭찬해 주셔서 기뻐요.\n"
.stringn "\x0701뭐, 그런 식으로 선생과 학생의 사이도\n"
.stringn "깊어졌으니…\n"
.stringn "저기, 스, 스텔라씨는……\n"
.stringn "연인이라든가 있나요? 없겠죠?\n"
.stringn "\x0713연인……이요?\n"
.stringn "\x0701네!\n"
.stringn "아, 참고로 저는 연인은 없어요!\n"
.stringn "안심하세요!\n"
.stringn "\x0713연인은 없습니다.\n"
.stringn "하지만, 약혼자라면……\n"
.stringn "\x0701네?\n"
.stringn "야, 약혼자요?\n"
.stringn "\x0713네.\n"
.stringn "\x0701그, 그렇군요!\n"
.stringn "이야, 그거 경사스럽네요!\n"
.stringn "\x0713저기…… 어째서 눈물을?\n"
.stringn "\x0701아뇨, 저는 신경 쓰지 마세요…\n"
.stringn "괜찮아요!\n"
.stringn "스텔라씨가 행복하다면, 충분합니다!\n"
.stringn "\x0713아, 가트리씨 어디로……\n"
.stringn "\x0705하아…… 또 차여 버렸다.\n"
.stringn "이번에야말로 될 줄 알았는데.\n"
.stringn "……음, 근데 잠깐만?\n"
.stringn "스텔라씨,\n"
.stringn "약혼자가 있다고 했었지?\n"
.stringn "그런 걸 일부러 말한다는 건\n"
.stringn "돌려 말해서…… 자기를 가로채서\n"
.stringn "도망가자는 거 아닌가?\n"
.stringn "뭐야! 그런 거라면 그렇게 말해 주지!\n"
.stringn "기다려 주세요 스텔라씨~!\n"
db 0
.align 4
//MYELL_8_GATRIE_STELLA_A

//0x11AAC
Text_11A8C:
.stringn "\x05FL|STELLA|GATRIE||\x070-\x0C01\x071-\x0C13\x0701가트리씨.\n"
.stringn "말씀을 들으러 왔어요.\n"
.stringn "괜찮을까요?\n"
.stringn "\x0713네, 물론임다!\n"
.stringn "오히려 제가 찾고 있었을 정도로!\n"
.stringn "에, 엣헴\n"
.stringn "그럼, 설명할게요!\n"
.stringn "\x0701네.\n"
.stringn "\x0713어~ 우선!\n"
.stringn "용병단의 전투란 말이죠!\n"
.stringn "역할 분담이 중요하답니다!\n"
.stringn "동료끼리 서로 협력한다면,\n"
.stringn "단 3명이서도 10명분을 할 수 있을 것 같…\n"
.stringn "할 수 있다구요!\n"
.stringn "\x0701과연…… 역할 분담이군요.\n"
.stringn "네, 알겠습니다.\n"
.stringn "\x0713그레일 용병단에서의 제 역할은\n"
.stringn "적을 막는 방패임다.\n"
.stringn "일단, 제가 용감하게 앞에 나서서\n"
.stringn "적의 공격을 모두 막아 내고!\n"
.stringn "그 틈에 다른 모두가 공격하는 거죠!\n"
.stringn "활은 제 뒤에서,\n"
.stringn "기마는 일격을 가하고 바로 물러납니다!\n"
.stringn "뭐어, 이런 느낌인 것 같……\n"
.stringn "이런 느낌이에요!\n"
.stringn "\x0701무척 잘 알았습니다.\n"
.stringn "그럼 저는……\n"
.stringn "\x0713스텔라씨는 물론 제 뒤에죠!\n"
.stringn "너무 멀어지면 위험하니까,\n"
.stringn "지나치게 붙지 않았나 싶을 정도로\n"
.stringn "제게 붙어 있어 주세요! 헤헤!\n"
.stringn "\x0701네, 가능한 만큼 노력하겠습니다.\n"
.stringn "아, 그리고\n"
.stringn "하나 질문을 드려도 될까요?\n"
.stringn "\x0713네, 뭐든지요!\n"
.stringn "\x0701저는 기마병이고 가트리씨는 보병이니까,\n"
.stringn "행군의 박자가 안 맞는다는 느낌이 들어요.\n"
.stringn "이런 경우에는 어떻게 해야 하나요?\n"
.stringn "\x0713어 그게, 그런 경우에는 말이죠……\n"
.stringn "어라?\n"
.stringn "티아마트씨가 뭐라고 했었지?\n"
.stringn "\x0701?\n"
.stringn "\x0713아, 아니 지금 건 혼잣말임다!\n"
.stringn "그럼 그 건은\n"
.stringn "또 다음에 하는 걸로!\n"
.stringn "다음에는 확실하게 알려 드릴 테니까요!\n"
.stringn "\x0701네, 오늘은 대단히 공부가 됐어요.\n"
.stringn "또 부디 가르쳐 주세요.\n"
.stringn "그럼, 실례하겠습니다.\n"
.stringn "\x0713『또 가르쳐 주세요』라니~……\n"
.stringn "이건 즉 돌려 말해서 결혼해 달라는\n"
.stringn "의미겠지……?\n"
.stringn "아아, 곤란한걸~…"
db 0
.align 4
//MYELL_8_GATRIE_STELLA_B

//0x116B4
Text_11694:
.stringn "\x05FL|STELLA|GATRIE||\x070-\x0C01\x071-\x0713이야아, 스텔라씨!\n"
.stringn "당신과 이렇게 함께 싸울 수 있다니\n"
.stringn "정말 감격임다!\n"
.stringn "\x0701네, 앞으로도\n"
.stringn "잘 부탁드려요.\n"
.stringn "가트리씨는 이전에도\n"
.stringn "아이크씨의 용병단에\n"
.stringn "계신 적이 있다고 들었습니다만……\n"
.stringn "\x0713물론이죠!\n"
.stringn "저는 오래 전부터\n"
.stringn "여기서 일했던 고참이거든요!\n"
.stringn "모르는 게 있다면\n"
.stringn "뭐든지 물어보십쇼! 뭐든지요!\n"
.stringn "\x0701감사합니다.\n"
.stringn "그럼…… 제게\n"
.stringn "용병의 전투 방식을\n"
.stringn "가르쳐 주시겠어요?\n"
.stringn "\x0713용병의 전투 방식……이라뇨?\n"
.stringn "\x0701저는 전투 경험이\n"
.stringn "별로 없어요.\n"
.stringn "그래서 여러분들께\n"
.stringn "폐를 끼치지 않도록\n"
.stringn "배워 두고 싶어서……\n"
.stringn "\x0713과, 과연 그렇군요!\n"
.stringn "역시 스텔라씨!\n"
.stringn "……아, 하지만\n"
.stringn "지금은 조금 곤란함다.\n"
.stringn "티아마트씨도 없고,\n"
.stringn "다음에 만나기 전까지 몰래 듣……\n"
.stringn "\x0701?\n"
.stringn "\x0713아뇨, 아무것도 아님다!\n"
.stringn "이왕이면\n"
.stringn "제대로 준비한 다음에 하고 싶거든요!\n"
.stringn "날을 잡아서 다시 와 주세요!\n"
.stringn "\x0701네. 그럼, 다음 기회에.\n"
.stringn "잘 부탁드릴게요.\n"
.stringn "\x0713아아, 귀엽다……\n"
.stringn "나한테 전투 방식을\n"
.stringn "가르쳐 달라는 건……\n"
.stringn "역시, 스텔라씨는\n"
.stringn "나한테 관심이 있는 거겠지……\n"
.stringn "곤란하게 됐는걸……"
db 0
.align 4
//MYELL_8_GATRIE_STELLA_C

//0x12A34
Text_12A14:
.stringn "\x05FL|JILL|HAAR||\x0703하알씨.\n"
.stringn "\x071-\x0711여기다.\n"
.stringn "\x0703드디어 한 번에 대답을 해 주셨군요.\n"
.stringn "\x0711그러는 게 네 잔소리를\n"
.stringn "듣는 시간이 줄어들지도 모르니까.\n"
.stringn "\x0703정말…\n"
.stringn "상관없어요, 딱히.\n"
.stringn "\x0711…질, 너\n"
.stringn "이 전쟁이 끝나고 나서 어떻게 할 거냐?\n"
.stringn "\x0703……데인으로 돌아가고 싶습니다.\n"
.stringn "달레카의… 아버님의 무덤 근처에서 살 거예요.\n"
.stringn "\x0711그런가.\n"
.stringn "\x0703하알씨는요?\n"
.stringn "\x0711나는… 아슈나드 놈이랑\n"
.stringn "싸우고도 살아남을 수 있다면……\n"
.stringn "………어떻게 할까.\n"
.stringn "시하람님의 묘지 쪽은\n"
.stringn "네가 먼저 말해 버렸으니.\n"
.stringn "\x0703저, 저와 함께하는 건…\n"
.stringn "불만이라는 건가요!?\n"
.stringn "\x0711…네 쪽에서 나와 함께하는 걸\n"
.stringn "싫어할 것 같아서 사양했을 뿐이야.\n"
.stringn "\x0703……싫어할 리가, 없잖아요.\n"
.stringn "\x0711그럼, 만약 둘 다 살아남게 된다면\n"
.stringn "달레카에서 비룡을 쓰는\n"
.stringn "짐 운반이라도 하면서 살까?\n"
.stringn "\x0703네.\n"
.stringn "만약… 살아남게 된다면요."
db 0
.align 4
//MYELL_8_HAAR_JILL_A

//0x12784
Text_12764:
.stringn "\x05FL|JILL|HAAR||\x0703하알씨!\n"
.stringn "하알씨… 어디 계십니까!?\n"
.stringn "하알…\n"
.stringn "\x071-\x0711여기다.\n"
.stringn "\x0703들린다면 처음 불렀을 때\n"
.stringn "대답해 주세요!\n"
.stringn "『대장』이라고 부르지 않는다면\n"
.stringn "제대로 대답한다고\n"
.stringn "약속했을 텐데요.\n"
.stringn "\x0711…귀찮구만.\n"
.stringn "\x0703……계속 생각하고 있었습니다만,\n"
.stringn "하알씨가 군인다운\n"
.stringn "성실한 태도로 있었던 건…\n"
.stringn "아버님 앞에서만이었죠.\n"
.stringn "\x0711너도\n"
.stringn "그 올라간 눈썹이 내려가는 건\n"
.stringn "시하람님 앞에서만이었잖냐.\n"
.stringn "\x0703그, 그건…\n"
.stringn "어쩔 수 없잖아요?\n"
.stringn "아버님은 특별하니까요.\n"
.stringn "\x0711나도 그래.\n"
.stringn "시하람님은 특별한 존재였지.\n"
.stringn "그래서 그분 앞에서만큼은,\n"
.stringn "이렇게 게을러터진 모습을\n"
.stringn "보이지 않으려고 신경을 곤두세웠었다.\n"
.stringn "\x0703…하알씨.\n"
.stringn "\x0711흐아암… 졸리군.\n"
.stringn "얘기는 끝이야. 오늘은 이제 방해하지 마."
db 0
.align 4
//MYELL_8_HAAR_JILL_B

//0x12574
Text_12554:
.stringn "\x05FL|JILL|HAAR||\x0703하알 대장님!\n"
.stringn "하알 대장님… 어디 계십니까!?\n"
.stringn "하알 대장…\n"
.stringn "\x071-\x0711여기다.\n"
.stringn "너 말이야, 사람의 이름을\n"
.stringn "시장의 채소 장수처럼 부르지 말라고.\n"
.stringn "\x0703그럼 처음 불렀을 때\n"
.stringn "대답해 주세요!\n"
.stringn "\x0711네가 나를 『대장』이라고\n"
.stringn "부르지 않는다면.\n"
.stringn "\x0703그치만…\n"
.stringn "그럼, 어떻게 부르면 됩니까?\n"
.stringn "\x0711네 마음대로 해.\n"
.stringn "\x0703하알님…?\n"
.stringn "\x0711평범한걸.\n"
.stringn "\x0703하알씨.\n"
.stringn "\x0711뭔가 딱 안 오는데.\n"
.stringn "\x0703하알!\n"
.stringn "\x0711오오. 그거 좋은데.\n"
.stringn "\x0703싫어요.\n"
.stringn "전 상관을 경칭 없이 함부로 부르다니.\n"
.stringn "역시 하알씨라고 부르겠습니다.\n"
.stringn "\x0711뭐어… 상관은 없지만."
db 0
.align 4
//MYELL_8_HAAR_JILL_C

//0x130EC
Text_130CC:
.stringn "\x05FL|HAAR|MAKAROV||\x070-\x0C03\x0711아, 있다 있어.\n"
.stringn "하알 형님!\n"
.stringn "\x0703………\n"
.stringn "\x0711형~님.\n"
.stringn "일어나 보시라구요.\n"
.stringn "앗! 아이크 장군이 보고 있잖아!!\n"
.stringn "………\n"
.stringn "\x0703………\n"
.stringn "\x0711어라~ 안 일어나네.\n"
.stringn "그나저나 이 상태로 잘 수 있다니\n"
.stringn "대단한 신경이구만. 존경스러운데.\n"
.stringn "나도 빨리 이 경지까지 도달해야겠어~\n"
.stringn "빚쟁이도 울면서 도망갈 듯한\n"
.stringn "이런 박력을 몸에 익힐 수만 있다면\n"
.stringn "마구잡이로 해먹었을 텐데.\n"
.stringn "좋아! 특훈이다 특훈!\n"
.stringn "우선 어디서든지 잘 수 있게 되는 거야.\n"
.stringn "……………\n"
.stringn "쿨~… 드르렁드르렁\n"
.stringn "\x0703……시끄러워 죽겠네.\n"
.stringn "나 참, 누구 멋대로 형님이냐…\n"
.stringn "\x0711새근새근 음~…\n"
.stringn "마샤아… 오빠가 잘못했어……\n"
.stringn "\x0703………\n"
.stringn "\x0711…돈 좀 빌려주라…… 음냐음냐\n"
.stringn "\x0703……이 상태로 여태까지\n"
.stringn "살아남았다는 게\n"
.stringn "어떤 의미로는 기적이군.\n"
.stringn "어지간히 운이 좋은가 본데.\n"
.stringn "이왕 이렇게 됐으니 이대로 마지막까지\n"
.stringn "꼭 살아남았으면 좋겠군."
db 0
.align 4
//MYELL_8_HAAR_MAKAROV_A

//0x12E00
Text_12DE0:
.stringn "\x05FL|HAAR|MAKAROV||\x0701음…? 너는……\n"
.stringn "\x0713히에엑!?\n"
.stringn "\x0701전에 본 남자로군.\n"
.stringn "\x0C13\x0C01이봐, 도망가지 마.\n"
.stringn "\x0714하, 한 번만 봐주세요~!\n"
.stringn "꼭 갚을 테니까요~!\n"
.stringn "\x0701…뭔 소리야?\n"
.stringn "\x0714아, 아니, 그때는 하필\n"
.stringn "가진 게 없어가지고……\n"
.stringn "그렇다고 지금은 있냐고 하면\n"
.stringn "또 없습니다요……\n"
.stringn "부디, 조금만 더\n"
.stringn "빚 갚는 걸 기다려 주시면……\n"
.stringn "\x0701빚을 갚는다니…\n"
.stringn "무슨 말이야?\n"
.stringn "\x0714어라……?\n"
.stringn "혹시…\n"
.stringn "빚쟁이 아니신가요?\n"
.stringn "\x0701……내가 빚쟁이인가.\n"
.stringn "\x0714아, 아닙니까?\n"
.stringn "\x0701그랬던 기억은 없어.\n"
.stringn "\x0714뭐야, 괜히 겁먹었네~\n"
.stringn "그야 그런 얼굴을 하고 있으니까,\n"
.stringn "틀림없이 빚쟁이인 줄 알았죠.\n"
.stringn "\x0701…호오, 내가 틀림없이\n"
.stringn "빚쟁이일 거 같은 얼굴이란 건가.\n"
.stringn "\x0714아, 아뇨 아뇨!\n"
.stringn "말실수예요 말실수.\n"
.stringn "정말 착각해서\n"
.stringn "죄송했습니다~\n"
.stringn "\x0701………\n"
.stringn "자 그럼, 한숨 자 볼까."
db 0
.align 4
//MYELL_8_HAAR_MAKAROV_B

//0x12D08
Text_12CE8:
.stringn "\x05FL|HAAR|MAKAROV||\x070-\x0703………\n"
.stringn "\x0711!!\n"
.stringn "\x0703……응?\n"
.stringn "\x0711어, 어버버버……\n"
.stringn "\x0703뭐야, 넌?\n"
.stringn "\x0711옥 오, 오…\n"
.stringn "\x0703이봐, 왜 그래……\n"
.stringn "\x0711히~익!\n"
.stringn "사, 사람 살려~엇!!\n"
.stringn "\x0703………\n"
.stringn "날 데인병으로 착각한 건가?\n"
.stringn "…뭐, 아무래도 좋지만……\n"
.stringn "흐아암 …………"
db 0
.align 4
//MYELL_8_HAAR_MAKAROV_C

//0x13E5C
Text_13E3C:
.stringn "\x05FL|LAY|IKE||\x070-\x0701!\n"
.stringn "\x0713…라이, 왜 그래?\n"
.stringn "\x0701아이크였냐…\n"
.stringn "놀래키지 말라고.\n"
.stringn "\x0713……요즘\n"
.stringn "너무 긴장하는 거 아니야?\n"
.stringn "\x0701왕도에 가까워지니까…\n"
.stringn "데인 왕의……\n"
.stringn "아니, 그 녀석보다는\n"
.stringn "메달리온 쪽인가?\n"
.stringn "어쨌든 거기서 나오는\n"
.stringn "【부】의 기운 때문에…\n"
.stringn "온몸에 소름이 끼쳐.\n"
.stringn "\x0713라구즈는 예민한걸.\n"
.stringn "\x0701…이곳에 왔는데 아무 반응도 없는\n"
.stringn "베오크가 더 무섭다고.\n"
.stringn "어떻게 아무렇지도 않게 있을 수 있는 건지…\n"
.stringn "이… 위압감은……\n"
.stringn "심상치 않아.\n"
.stringn "\x0713나는 잠시 비켜 주는 게 좋을까?\n"
.stringn "\x0701그렇게 부탁…\n"
.stringn "……아니, 역시 옆에 있어 줘.\n"
.stringn "금방 가라앉을 테니까……\n"
.stringn "……………\n"
.stringn "\x0713………\n"
.stringn "\x0701…………후우\n"
.stringn "…미안해. 시간 쓰게 해서.\n"
.stringn "\x0713괜찮아?\n"
.stringn "\x0701그래. 이젠 좀 나아졌어.\n"
.stringn "내가\n"
.stringn "베오크에게 약한 모습을\n"
.stringn "보여주게 되다니… 말세구만.\n"
.stringn "\x0713날 못 믿는 거야?\n"
.stringn "\x0701믿어.\n"
.stringn "…하지만 완전히는 아니야.\n"
.stringn "나는 거의\n"
.stringn "너를 인정하고 있지만……\n"
.stringn "아직 다른 수아족 동료들처럼\n"
.stringn "대하는 건… 좀 힘들어.\n"
.stringn "\x0713나는 널 믿고 있어.\n"
.stringn "\x0701……정색하면서\n"
.stringn "말하는 거냐고~\n"
.stringn "정말, 너란 놈은…\n"
.stringn "\x0713너란 놈은?\n"
.stringn "\x0701바보구나.\n"
.stringn "\x0713뭐라고?\n"
.stringn "\x0701그렇게 아무나\n"
.stringn "믿고 다니다간…\n"
.stringn "언젠가 분명\n"
.stringn "발목 잡힌다고!\n"
.stringn "잊지 마라!!\n"
.stringn "\x0713잠깐 기다려! 라이!\n"
.stringn "…정말, 대하기 쉬운 건지\n"
.stringn "까다로운 건지 알 수 없는 녀석이야."
db 0
.align 4
//MYELL_8_IKE_LAY_A

//0x139C8
Text_139A8:
.stringn "\x05FL|IKE|LAY||\x0701라이.\n"
.stringn "\x071-\x0713응? 무슨 일이야?\n"
.stringn "\x0701……혹시 훈련 중?\n"
.stringn "\x0713오, 예리한데!\n"
.stringn "노력가 아이크 장군님께\n"
.stringn "뒤처지지 않기 위해서\n"
.stringn "잠깐 훈련하고 있었지.\n"
.stringn "\x0701좋은 마음가짐인걸.\n"
.stringn "\x0713아~… 됐어.\n"
.stringn "비아냥거리는 것도 안 통하는구나, 너.\n"
.stringn "훈련은 거짓말이야.\n"
.stringn "이 모습으로 해 봤자 의미 없다고.\n"
.stringn "\x0701그럼 뭘 하고 있었어?\n"
.stringn "근육을 풀고 있던 것처럼 보였는데.\n"
.stringn "\x0713맞아. 몸을 쭉 늘여서\n"
.stringn "긴장을 풀었을 뿐이야.\n"
.stringn "\x0701뭐야. 수아족의 특별한\n"
.stringn "훈련 방법인 줄 알고 기대했었다고.\n"
.stringn "\x0713기대를 저버려서 미안하지만\n"
.stringn "화신하지 않으면\n"
.stringn "나도 너랑 그렇게 다를 거 없어.\n"
.stringn "보는 대로 말이지.\n"
.stringn "\x0701그래?\n"
.stringn "꼬리가 있는 것밖에 차이가 없는 거구나.\n"
.stringn "\x0713꼬리는 좋다니까~\n"
.stringn "갑자기 몸을 돌릴 때나\n"
.stringn "높은 곳을 다닐 때,\n"
.stringn "균형을 잡을 때 엄청 편리해.\n"
.stringn "꼬리 없는 삶이라니\n"
.stringn "생각할 수 없어.\n"
.stringn "\x0701잘 때 방해될 거 같은데.\n"
.stringn "\x0713그건 맞아. 하지만\n"
.stringn "좋은 방법이 있지.\n"
.stringn "\x0701뭔데?\n"
.stringn "\x0713그건 말이지……\n"
.stringn "…이런, 위험했어.\n"
.stringn "아슬아슬하게 유도 신문에\n"
.stringn "걸릴 뻔했구만.\n"
.stringn "\x0701유도 신문은 무슨, 그냥 듣고 있기만 했는데.\n"
.stringn "\x0713잘 들어, 아이크.\n"
.stringn "이건 라구즈 종족 전체랑 관련된\n"
.stringn "비밀이야.\n"
.stringn "베오크인 네게 쉽게\n"
.stringn "폭로할 수는 없다고.\n"
.stringn "\x0701그래.\n"
.stringn "그럼 뭐 됐어.\n"
.stringn "\x0713야~아.\n"
.stringn "여기선 더 물고 늘어져야지?"
db 0
.align 4
//MYELL_8_IKE_LAY_B

//0x13400
Text_133E0:
.stringn "\x05FL|LAY|IKE||\x070-\x0C01\x0C13\x0701여어, 아이크.\n"
.stringn "그렇게나 강해졌는데 또 훈련하는 거야?\n"
.stringn "\x0713나는… 검 훈련을 빠뜨린 적이 없어.\n"
.stringn "아무리 짧은 시간이라도 여유가 생기면\n"
.stringn "반드시 검을 휘두르도록 하고 있지.\n"
.stringn "이러고 있으면 정신이 집중돼서\n"
.stringn "진정되는 것도 있고.\n"
.stringn "\x0701그렇구만.\n"
.stringn "네 강함은…\n"
.stringn "아버지에게서 물려받은\n"
.stringn "뛰어난 재능뿐만이 아니라\n"
.stringn "꾸준한 노력이 있었기에 가능했던 거였어.\n"
.stringn "어쩐지 만날 때마다 점점 성장하더라.\n"
.stringn "좋아 좋아………\n"
.stringn "\x0713…………\n"
.stringn "\x0701아, 나… 혹시 방해되나?\n"
.stringn "그럼 난 갈……\n"
.stringn "\x0713잠깐.\n"
.stringn "뭔가 볼일이 있어서 온 게 아니었어?\n"
.stringn "\x0701……조금 쓸데없는\n"
.stringn "걱정을 했을 뿐이야.\n"
.stringn "너 말이지, 아무리 쉬라고 해도\n"
.stringn "쉴 생각을 안 하잖아.\n"
.stringn "…지금도 말을 걸면\n"
.stringn "멈추겠지 싶었는데……\n"
.stringn "보기 좋게 실패한 것 같으니까 물러갈게.\n"
.stringn "\x0713……뭐야. 내가\n"
.stringn "그렇게나 걱정되는 거야?\n"
.stringn "\x0701그야 당연하지!!\n"
.stringn "너같이 강압적이고 고집 센 장군은\n"
.stringn "어디를 가도 없을걸.\n"
.stringn "『귀찮아! 마음대로 싸워!』라니\n"
.stringn "그게 무슨 작전인고, 기가 막혀서 원.\n"
.stringn "\x0713별로… 나는 나야.\n"
.stringn "다른 녀석들이랑 같지 않아도 상관없잖아.\n"
.stringn "\x0701……봐봐, 이렇잖아.\n"
.stringn "대체 뭐야? 그 근거 없는 자신감은.\n"
.stringn "베오크는 남들과 똑같이 행동하고\n"
.stringn "안심하는 종족이잖아…\n"
.stringn "넌 왠지 혼자 붕~붕 떠 있다고.\n"
.stringn "\x0713그거참 미안하게 됐어.\n"
.stringn "\x0701이렇게 말하면서도 베오크를\n"
.stringn "신경 쓰고 있는 나도…\n"
.stringn "혼자서 붕 뜬 라구즈지만.\n"
.stringn "물고기마냥 둥둥 떠 있는 거지.\n"
.stringn "\x0713……훗\n"
.stringn "고양이 주제에 자신을 생선에 비유하지 말라고.\n"
.stringn "\x0701오! 웃었다.\n"
.stringn "좋~아 좋아. 그 상태로 어깨에 힘 좀 빼라고.\n"
.stringn "\x0713알았어. 휴식할게.\n"
.stringn "쉬는 김에 차라도 마시면 되겠지?\n"
.stringn "\x0701물론이지. 밥 먹고 잠까지 자 두면 더 좋고."
db 0
.align 4
//MYELL_8_IKE_LAY_C

//0x14910
Text_148F0:
.stringn "\x05FL|RETHE|IKE||\x070-\x0703왔다, 아이크.\n"
.stringn "\x071-\x0711그래, 오늘도 하는 거지?\n"
.stringn "\x0703너는 최근에\n"
.stringn "눈부신 성장을 보이고 있으니까.\n"
.stringn "나도 질 수는 없지.\n"
.stringn "\x0711그래?\n"
.stringn "……너한테 칭찬받다니\n"
.stringn "기분이 좋은걸.\n"
.stringn "\x0703뭐야, 설마……\n"
.stringn "처음 만났을 때의 일을\n"
.stringn "아직도 신경 쓰고 있는 건가?\n"
.stringn "\x0711그런 게 아니야.\n"
.stringn "넌 강하니까.\n"
.stringn "그냥 강한 녀석한테\n"
.stringn "칭찬받는 게 기쁜 것뿐이야.\n"
.stringn "\x0703흥……\n"
.stringn "그건 과대평가다.\n"
.stringn "…………\n"
.stringn "저기, 아이크.\n"
.stringn "\x0711왜?\n"
.stringn "\x0703이 싸움이 끝나면……\n"
.stringn "모든 게 끝나고 나면……\n"
.stringn "갈리아로 오지 않겠나?\n"
.stringn "\x0711갈리아로?\n"
.stringn "\x0703그래. 갈리아에서 단련한다면,\n"
.stringn "너는 더욱더 강해질 수 있을 거다.\n"
.stringn "갈리아의 환경은 베오크에게\n"
.stringn "살아가기조차 힘든 땅이라고 하지.\n"
.stringn "하지만 그렇기 때문에 그 땅에서는\n"
.stringn "네가 아버지에게서 물려받은\n"
.stringn "그 검술을……\n"
.stringn "한계까지 이끌어 낼 수 있을 거라고 생각한다.\n"
.stringn "\x0711…단련 상대는 당연히\n"
.stringn "레테가 해 주는 거겠지?\n"
.stringn "\x0703네, 네가…\n"
.stringn "그걸로 괜찮다면… 나는 상관없다.\n"
.stringn "\x0711그럼 갈리아에서 사는 것도 나쁘지 않겠어.\n"
.stringn "\x0703좋아, 그럼 약속이다.\n"
.stringn "언제든지 네가 마음 내킬 때 와라.\n"
.stringn "나는 그때를 기대하고 있을 테니까.\n"
.stringn "\x0711알았어. 약속할게."
db 0
.align 4
//MYELL_8_IKE_LETHE_A

//0x145DC
Text_145BC:
.stringn "\x05FL|RETHE|IKE||\x0703어이.\n"
.stringn "\x0711레테구나.\n"
.stringn "무슨 일이야?\n"
.stringn "\x0703전의 싸움, 꽤 괜찮았다.\n"
.stringn "생각보다 한 실력 하는 것 같군.\n"
.stringn "\x0711나 말이야?\n"
.stringn "\x0703그래. 여기 너 말고 누가 있지?\n"
.stringn "\x0711……의외인걸.\n"
.stringn "난 너희들의 경이로운 힘에\n"
.stringn "항상 놀라고 있는데.\n"
.stringn "\x0703서로 완전히\n"
.stringn "다른 방식으로 싸우기 때문이겠지.\n"
.stringn "움직임이나 생각을\n"
.stringn "읽을 수 없는 것도 그렇지만…\n"
.stringn "너희들은 의외로 빠르고 세심한\n"
.stringn "반사 신경을 가지고 있다.\n"
.stringn "자신의 신체와는 별개인 칼날을\n"
.stringn "그렇게까지 잘 다루다니.\n"
.stringn "단련의 성과라는 건가.\n"
.stringn "\x0711그래.\n"
.stringn "우리는 너희처럼 발톱이나 이빨을\n"
.stringn "가지고 있지 않으니까.\n"
.stringn "어떻게든 무기를\n"
.stringn "자신의 신체의 일부로 만들기 위해……\n"
.stringn "날마다\n"
.stringn "훈련을 빠뜨릴 수는 없어.\n"
.stringn "\x0703흠…… 과연.\n"
.stringn "그럼 나도 너희들을 본받아\n"
.stringn "단련에 힘써야겠군.\n"
.stringn "지난번에 했던 약속은 기억하고 있겠지?\n"
.stringn "\x0711물론이지.\n"
.stringn "부탁해도 될까?\n"
.stringn "\x0703이쪽이야말로 잘 부탁한다.\n"
.stringn "서로 봐주는 건 없는 걸로.\n"
.stringn "알겠나?\n"
.stringn "\x0711알았어.\n"
.stringn "……간다!"
db 0
.align 4
//MYELL_8_IKE_LETHE_B

//0x142D8
Text_142B8:
.stringn "\x05FL|IKE|RETHE||\x0701좋아…… 이 쯤 해 둘까……\n"
.stringn "……응?\n"
.stringn "\x0713열심히 단련하고 있는 것 같군.\n"
.stringn "\x0701레테구나. 보고 있었어?\n"
.stringn "\x0713그래, 흥미가 있다.\n"
.stringn "앞으로는 베오크의 전투법을\n"
.stringn "얼마나 잘 알고 있는지가\n"
.stringn "승패를 가르게 될 테니까.\n"
.stringn "네놈들에게 뒤처질 수는 없지.\n"
.stringn "\x0701그래서 날 연구하는 거야?\n"
.stringn "\x0713안심해라, 뒤에서 네 목을\n"
.stringn "칠 생각은 없으니까.\n"
.stringn "그런 건 아무런 의미도 없고,\n"
.stringn "그렇게 얍삽하고 비겁한 수단을 쓰는 건\n"
.stringn "베오크들뿐이다.\n"
.stringn "\x0701그렇구나.\n"
.stringn "라구즈는 그럼 보통 정정당당하게\n"
.stringn "정면에서 싸우는 거야?\n"
.stringn "\x0713……대개 그렇지.\n"
.stringn "모두가 그렇다고 할 수는 없지만.\n"
.stringn "뭐, 어떤 잔재주를 부리든\n"
.stringn "우리들은 냄새로 알아챌 수 있다.\n"
.stringn "어둠 속으로 숨으려고 해도 소용없지.\n"
.stringn "……코를 찌부러트린다면 얘기는 다르지만.\n"
.stringn "\x0701레테.\n"
.stringn "다음에라도 좋으니까\n"
.stringn "수아족의 전투법에 대해서 알려 줄래?\n"
.stringn "\x0713그런 일이라면 맡겨라.\n"
.stringn "전력으로 상대해 주지.\n"
.stringn "\x0701그래, 부탁해."
db 0
.align 4
//MYELL_8_IKE_LETHE_C

//0x15530
Text_15510:
.stringn "\x05FL|OSCAR|IKE||\x0701아이크.\n"
.stringn "\x0713오스카?\n"
.stringn "……무슨 일이야?\n"
.stringn "\x0701…………\n"
.stringn "괜찮아?\n"
.stringn "\x0713괜찮아…… 문제없도록 할 테니까.\n"
.stringn "내가 불안하게 한 거야?\n"
.stringn "\x0701아니, 그런 건 아니야.\n"
.stringn "그… 점점 전쟁이 격렬해져서…\n"
.stringn "얼마 전까지만 해도\n"
.stringn "우리가 이렇게 큰 사건에 말려들게 될 줄은\n"
.stringn "생각도 못했으니까.\n"
.stringn "\x0713그래……\n"
.stringn "아버지가 죽고……\n"
.stringn "상당히 상황이 급박하게 돌아가고 있지.\n"
.stringn "솔직히, 숨 돌릴 틈도 없어.\n"
.stringn "\x0701그러니까…… 괜찮은 거지?\n"
.stringn "아니, 괜찮지는 않겠지만……\n"
.stringn "내가…… 뭔가 할 수 있는 게 없을까?\n"
.stringn "\x0713……고마워.\n"
.stringn "너한테는 계속 고생만\n"
.stringn "시키게 되네.\n"
.stringn "이런 미덥지 못한 단장을\n"
.stringn "지금까지 따라와 준 것만으로도\n"
.stringn "이미 충분해.\n"
.stringn "\x0701아이크……\n"
.stringn "\x0713앞으로도 함께해 줄래?\n"
.stringn "\x0701그래, 물론이지.\n"
.stringn "나는, 그레일 단장님께서 말씀하셨듯이\n"
.stringn "너를 가족이라고 생각하고 있어.\n"
.stringn "용병단은 내가 돌아올 집이나 다름없으니까.\n"
.stringn "\x0713오스카……\n"
.stringn "오랜만에 네가 해 준 밥을 먹고 싶어.\n"
.stringn "나중에 또 미스트랑 같이 만들어 줄래?\n"
.stringn "\x0701그래, 알았어.\n"
.stringn "오늘은 실력 발휘 좀 해 볼까? 기대해 줘."
db 0
.align 4
//MYELL_8_IKE_OSCAR_A

//0x15190
Text_15170:
.stringn "\x05FL|OSCAR|IKE||\x070-\x0703아이크.\n"
.stringn "상태는 괜찮아?\n"
.stringn "\x0711오스카구나.\n"
.stringn "아, 잠시 싸우는 데에\n"
.stringn "고민하고 있는 게 있어서……\n"
.stringn "\x0703나라도 괜찮다면 들어줄까?\n"
.stringn "\x0711별건 아니고, 수아족이나 조익족을 상대로\n"
.stringn "어떻게 싸우면 좋을지\n"
.stringn "생각하고 있던 중이었어.\n"
.stringn "\x0703그렇구나……\n"
.stringn "그건 나도 생각하고 있었어.\n"
.stringn "모습을 바꾸는 순간\n"
.stringn "우리가 상상하는 전투의 범주를\n"
.stringn "아득히 뛰어넘지.\n"
.stringn "\x0711맞아.\n"
.stringn "수아족은 그 발톱으로 일격에\n"
.stringn "바위를 부수는 것도,\n"
.stringn "땅을 가르는 것도 가능해.\n"
.stringn "조익족은 우리의 사각을\n"
.stringn "쉽게 찾아내겠지.\n"
.stringn "게다가 하늘로 도망쳐 버리면\n"
.stringn "내 검술은 아무 의미도 없게 돼…\n"
.stringn "\x0703……역시 가장 좋은 건\n"
.stringn "그들에게 연습 상대를 부탁해 보는 거겠지.\n"
.stringn "어려운 일이지만……\n"
.stringn "\x0711……어렵다고?\n"
.stringn "그래?\n"
.stringn "\x0703아……\n"
.stringn "아니, 응.\n"
.stringn "……아이크는…… 대단하네.\n"
.stringn "\x0711? 오스카한테 대단하다는 소리를\n"
.stringn "들으니 기분이 이상한걸.\n"
.stringn "너는 뭐든지 할 수 있고\n"
.stringn "아는 것도 많잖아.\n"
.stringn "\x0703내가 하는 일들은 노력하면\n"
.stringn "누구나 할 수 있는 것들이야.\n"
.stringn "……너는 역시 단장님의 아들이구나.\n"
.stringn "널 본받고 싶다고 생각하게 돼.\n"
.stringn "\x0711…………"
db 0
.align 4
//MYELL_8_IKE_OSCAR_B

//0x14D24
Text_14D04:
.stringn "\x05FL|IKE|OSCAR||\x0703오스카,\n"
.stringn "훈련하는데 좀 도와줄……\n"
.stringn "?\n"
.stringn "어디 가는 거야?\n"
.stringn "\x0711미안해, 아이크.\n"
.stringn "오늘은 내가 식사 담당이야.\n"
.stringn "\x0703미스트는?\n"
.stringn "\x0711빨래가 아직 안 끝난 것 같아.\n"
.stringn "요리는 오랜만이라서\n"
.stringn "실력이 줄은 게 아닐까 모르겠네.\n"
.stringn "\x0703오스카의 요리는 오랜만인걸.\n"
.stringn "기대돼.\n"
.stringn "\x0711…정말이야?\n"
.stringn "\x0703응. 왜 그래?\n"
.stringn "네 요리는 항상 맛있었어.\n"
.stringn "\x0711내가 느끼기로…\n"
.stringn "항상 반응이 없는 세네리오와\n"
.stringn "원래 내 요리에 익숙한\n"
.stringn "동생 두 명은 제외하고…\n"
.stringn "단장님, 티아마트 부장님, 아이크,\n"
.stringn "가트리는 감사히 먹어 주긴 했지만…\n"
.stringn "먹을 수만 있다면 뭐든 상관없다는 느낌이었거든.\n"
.stringn "매번 맛의 차이를 미세하게 알아채고\n"
.stringn "감상을 말해 준 건…\n"
.stringn "미스트와 시논, 그리고\n"
.stringn "킬로이뿐이었어.\n"
.stringn "\x0703딱히 말을 안 했을 뿐이지,\n"
.stringn "맛은 제대로 느끼고 있다고? 일단은.\n"
.stringn "식사 담당이 오스카에서\n"
.stringn "미스트로 교체됐던 날의 저녁밥은…\n"
.stringn "지금 생각해도 속이 울렁거려.\n"
.stringn "아버지조차도 진땀을 흘리면서\n"
.stringn "먹었던 것 같고.\n"
.stringn "그러고 보니\n"
.stringn "미스트의 요리도 최근에는 괜찮아졌지.\n"
.stringn "\x0711맞아, 네가 검 실력을 연마하는 것처럼\n"
.stringn "뒤에서 열심히 특훈하고 있어.\n"
.stringn "맛있다고 말해 주는 건\n"
.stringn "만드는 사람 입장에서 가장 큰 격려가 되니까.\n"
.stringn "그걸 위해서라도, 알지?\n"
.stringn "\x0703그렇구나……\n"
.stringn "앞으로는 제대로\n"
.stringn "맛있다고 말할게.\n"
.stringn "\x0711하하, 고마워."
db 0
.align 4
//MYELL_8_IKE_OSCAR_C

//0x16288
Text_16268:
.stringn "\x05FL|IKE|RIEUSION||\x0703뤼시온.\n"
.stringn "\x0711……아이크… 알고 있다.\n"
.stringn "자기 몸이니까\n"
.stringn "누구보다도 잘 알고 있다.\n"
.stringn "………하지만, 부디…\n"
.stringn "마지막까지… 함께 하게 해 줘.\n"
.stringn "\x0703…………\n"
.stringn "모든 게 끝나는 순간에\n"
.stringn "네 목숨도 끝나는 게 아니라면 말이지…\n"
.stringn "\x0711……\n"
.stringn "메달리온이 안정되면…\n"
.stringn "내 몸도 원래대로 돌아갈 거다.\n"
.stringn "괜찮다, 내 정신력은 아직…\n"
.stringn "조금도 꺾이지 않았으니까.\n"
.stringn "아슈나드와 만나서…\n"
.stringn "사건의 진상을 밝혀내고야 말겠다.\n"
.stringn "\x0703뤼시온.\n"
.stringn "내가 널 도울게.\n"
.stringn "\x0711나를 특별 취급하지 말라고 했…\n"
.stringn "\x0703그러니까, 너도 날 도와줘.\n"
.stringn "\x0711!\n"
.stringn "\x0703우리가 각자 가지고 있는 힘은\n"
.stringn "전혀 달라.\n"
.stringn "서로 돕는다면…\n"
.stringn "앞으로의 전투에서도 승리할 수 있을 거야.\n"
.stringn "\x0711……그렇…군.\n"
.stringn "알았다. 잘 부탁하지.\n"
.stringn "\x0703이쪽이야말로 마지막까지 잘 부탁해."
db 0
.align 4
//MYELL_8_IKE_RIEUSION_A

//0x15EA0
Text_15E80:
.stringn "\x05FL|IKE|RIEUSION||\x0703뤼시온!\n"
.stringn "\x0717여기다, 아이크.\n"
.stringn "\x0711전투에 관해서 얘기할 게 있나?\n"
.stringn "\x0703그래. 다음 작전에서는\n"
.stringn "네 힘이 승패를 좌우하게 될 거라고\n"
.stringn "얘기하러 왔어. 몸은 괜찮아?\n"
.stringn "\x0711…그래.\n"
.stringn "하늘 높이 올라가 있으면\n"
.stringn "조금은 【부】의 기운으로부터 벗어날 수 있는 것 같다.\n"
.stringn "지금도 바람을 쐬고 오니 꽤 편해졌지.\n"
.stringn "다음 전투까지는 버틸 수 있을 거다.\n"
.stringn "\x0703……네 모습을 보고 있으니\n"
.stringn "어떻게 해서든 널 싸우지 않게 하려던\n"
.stringn "페니키스 왕의 기분을 알 것 같아.\n"
.stringn "무리하게 해서 정말로 미안해.\n"
.stringn "\x0711스스로 원해서 이곳에 있는 나에게…\n"
.stringn "그렇게 말하는 건 모욕이다.\n"
.stringn "\x0703……그랬었지, 미안.\n"
.stringn "네가 이런 배려를 싫어한다는 건\n"
.stringn "알고 있었는데 말이지……\n"
.stringn "\x0711…네가 아니었다면\n"
.stringn "진작에 때려서 입을 다물게 했을지도 모른다.\n"
.stringn "\x0703……백로 민족은 아예 공격을\n"
.stringn "못하는 게 아니었어?\n"
.stringn "\x0711…………\n"
.stringn "때리는 것 정도는 할 수 있다. 다만…\n"
.stringn "\x0703다만?\n"
.stringn "\x0711맞은 상대보다\n"
.stringn "때린 내 주먹이 더 피해가 크다.\n"
.stringn "\x0703예를 들면?\n"
.stringn "\x0711…전에 타나스 공작의 안면을\n"
.stringn "때렸을 때……\n"
.stringn "놈은 코피를 흘릴 뿐이었지만\n"
.stringn "나는 손등뼈에 금이 갔었다…\n"
.stringn "\x0703…………\n"
.stringn "\x0711…………\n"
.stringn "\x0703사나이구만.\n"
.stringn "\x0711뭐, 그렇지."
db 0
.align 4
//MYELL_8_IKE_RIEUSION_B

//0x158B4
Text_15894:
.stringn "\x05FL|IKE|RIEUSION||\x0701뤼시온.\n"
.stringn "\x071-\x0713아이크인가. 무슨 일이지?\n"
.stringn "\x0701상태를 보러 왔을 뿐이야.\n"
.stringn "좀 어때?\n"
.stringn "\x0713괜찮다. 아무런 문제도 없어.\n"
.stringn "\x0701…문제없다고 하기에는\n"
.stringn "설득력이 없는 안색인데.\n"
.stringn "\x0713……우리 백로 민족은 【정】에 가까운 존재.\n"
.stringn "【부】의 기운이 넘치는 전장에서는…\n"
.stringn "상태에 만전을 기할 수 없다.\n"
.stringn "그렇지만 지쳐서 쓰러지지 않도록\n"
.stringn "잘 휴식하고 있으니… 부디 마지막까지\n"
.stringn "함께 싸우게 해 줘. 부탁한다.\n"
.stringn "\x0701본인이 조심하고 있으면\n"
.stringn "나는 불만은 없지만…\n"
.stringn "몸에 맞는 음식이라든지,\n"
.stringn "조금이라도 도움되는 게 있다면\n"
.stringn "어떻게든 준비해 줄 수 있다고?\n"
.stringn "\x0713…그 마음만으로도 충분하다.\n"
.stringn "실은 나도 옛날에… 이 연약한 몸에\n"
.stringn "싫증이 나서……\n"
.stringn "여러 가지를 시도해 봤었다.\n"
.stringn "고기, 생선, 술… 티반이 좋아하는 것들을\n"
.stringn "늘어놓고 하나씩 먹었지.\n"
.stringn "\x0701…결과는 어땠는데?\n"
.stringn "\x071310일 동안 사경을 헤맸다.\n"
.stringn "아무래도 우리 백로 민족은\n"
.stringn "신선한 나무 열매 외에는\n"
.stringn "잘 안 받는 체질인 것 같더군.\n"
.stringn "\x0701…목숨을 건 행위였구나.\n"
.stringn "\x0713티반처럼 되고 싶었다.\n"
.stringn "크고 늠름한 몸과 날개…\n"
.stringn "내가 그것들을 가지고 해 달라고,\n"
.stringn "직접 베그니온에 쳐들어가\n"
.stringn "인간들에게 복수할 수 있게 해 달라고…\n"
.stringn "매일 밤 여신에게 기도하며… 빌었다.\n"
.stringn "하지만……… 이루어지지 않았지.\n"
.stringn "\x0701…왠지 네 그 기분이\n"
.stringn "이해가 가긴 하지만……\n"
.stringn "오히려 잘된 일 아니야?\n"
.stringn "\x0713어째서지?\n"
.stringn "\x0701싸움의 기운만으로도 몸이 망가지는 네가,\n"
.stringn "직접 상대방을 다치게 하는\n"
.stringn "짓을 한다면… 가볍게 끝나지는 않았을 거야.\n"
.stringn "\x0713……그렇군.\n"
.stringn "절망에 지배당했을 때의 나는\n"
.stringn "목숨과 맞바꿔도 상관없다고\n"
.stringn "진지하게 생각했었지.\n"
.stringn "하지만… 지금은 이렇게 살아 있어서 다행이라고 생각한다.\n"
.stringn "살아 있었기에 리아네를 만날 수 있었으니까.\n"
.stringn "\x0701뤼시온… 너,\n"
.stringn "생각했던 것보다 남자다운데.\n"
.stringn "\x0713정신력만큼은\n"
.stringn "남에게 뒤지지 않을 자신이 있다."
db 0
.align 4
//MYELL_8_IKE_RIEUSION_C

//0x170E0
Text_170C0:
.stringn "\x05FL|SENERIO|IKE||\x070-\x0C05\x0713……\n"
.stringn "\x0705……\n"
.stringn "\x0713…지난번 이야기를 듣고,\n"
.stringn "내 나름대로 없는 지혜를 짜서 생각해 봤는데,\n"
.stringn "역시 모르겠어.\n"
.stringn "네가 자신의 존재에 대해\n"
.stringn "뭔가 불만을 가지고 있다는 것 말고는\n"
.stringn "아무것도 알 수가 없었어.\n"
.stringn "그러니까 역시 얘기를 듣고 싶어.\n"
.stringn "\x0C05\x0701……어째서\n"
.stringn "그냥 놔두지 않으시는 건가요?\n"
.stringn "제게는… 당신밖에\n"
.stringn "의지할 상대가 없는데……\n"
.stringn "당신에게까지 미움받으면……\n"
.stringn "더 이상 살아갈 수 없는데……\n"
.stringn "\x0713그래서야.\n"
.stringn "너는 나 말고 누구에게도\n"
.stringn "마음을 열려고 하지 않아.\n"
.stringn "그러니까 내가 어떻게 하지 않으면\n"
.stringn "너는 언제까지나\n"
.stringn "고통을 껴안고 있겠지.\n"
.stringn "\x0701………아이크…\n"
.stringn "저는… 저는……\n"
.stringn "\x0713나를 믿어 줘.\n"
.stringn "네가 어떤 사람이라고 해도,\n"
.stringn "내가 너를 인정해 줄 테니까.\n"
.stringn "\x0701………으……\n"
.stringn "………………………\n"
.stringn "…………네……\n"
.stringn "………………\n"
.stringn "…저는… 아마도……\n"
.stringn "【인붙이】입니다.\n"
.stringn "\x0713【인붙이】…\n"
.stringn "그게 뭔데?\n"
.stringn "\x0701베오크와 라구즈의… 혼혈입니다……\n"
.stringn "여신의 이치를 거스른 이유로…\n"
.stringn "어느 종족에게나…\n"
.stringn "미움을 받는 꺼림칙한 존재죠……\n"
.stringn "\x0713……잘 모르겠지만,\n"
.stringn "어쨌든 너는\n"
.stringn "라구즈의 핏줄을 이어받았다는 거지?\n"
.stringn "\x0701…네.\n"
.stringn "제 이마에 있는 증표가 그 증거입니다…\n"
.stringn "베그니온의 대신전 마나일에서……\n"
.stringn "오래된 책을 조사하다가… 알게 되었어요.\n"
.stringn "그 전까지는…\n"
.stringn "마도사가 더 강한 마력을 얻기 위해\n"
.stringn "새기는 【정령의 부적】이라고 생각했었죠……\n"
.stringn "현자가 그것에 눈을 떴다고\n"
.stringn "자주 말했으니까요………\n"
.stringn "\x0713그래서?\n"
.stringn "\x0701네…? 그래서, 라뇨?\n"
.stringn "\x0713네게 라구즈의 피가 섞여 있고\n"
.stringn "인 뭐시기…라는 건 알겠어.\n"
.stringn "그래서 그게 어쨌다는 거야?\n"
.stringn "\x0701그게 어쨌다니…\n"
.stringn "불쾌하지 않으신가요!?\n"
.stringn "자신의 곁에… 이런\n"
.stringn "어떤 것에도 속하지 않는 존재가 있다는 게…!\n"
.stringn "\x0713………아니.\n"
.stringn "전혀 이상하지 않아.\n"
.stringn "세네리오는 세네리오야.\n"
.stringn "우리 용병단의 유능한 참모지.\n"
.stringn "네가 없으면,\n"
.stringn "금세 단을 이어나갈 수 없게 될 거고.\n"
.stringn "\x0701…………아이크…\n"
.stringn "저는… 그래서 당신을……\n"
.stringn "\x0713응?\n"
.stringn "\x0701갈리아였어요…\n"
.stringn "제가 현자와 살고 있었던 곳은…\n"
.stringn "갈리아에 있는 작은 마을이었습니다.\n"
.stringn "그곳에는 몇몇 베오크가\n"
.stringn "모여서 살고 있었고……\n"
.stringn "\x0713…갈리아?\n"
.stringn "너, 그럼…\n"
.stringn "\x0701현자가 죽고…… 말을 못하는 저는\n"
.stringn "굶어 죽어 가고 있었어요……\n"
.stringn "그런 저에게\n"
.stringn "당신만이 손을 내밀어 주었죠.\n"
.stringn "그래서……\n"
.stringn "당신이 제게 있어\n"
.stringn "특별한 사람이 된 겁니다……"
db 0
.align 4
//MYELL_8_IKE_SENERIO_A

//0x1679C
Text_1677C:
.stringn "\x05FL|SENERIO|IKE||\x0703………\n"
.stringn "\x0711세네리오, 잠시 시간 돼?\n"
.stringn "\x0703네, 네에.\n"
.stringn "무슨 일이신가요, 아이크?\n"
.stringn "\x0711…이제 그만 말해 주면 안 될까?\n"
.stringn "왜 그렇게\n"
.stringn "우울해하고 있는 건지.\n"
.stringn "\x0703아… ………\n"
.stringn "\x0711………\n"
.stringn "\x0703……저기……\n"
.stringn "……………………\n"
.stringn "…아이크는, 자신이 누구인지…\n"
.stringn "고민해 본 적 없나요?\n"
.stringn "\x0711자신이 누구인지…?\n"
.stringn "…글쎄, 딱히 없는데.\n"
.stringn "아버지와 엄마의 아들이고, 그거에\n"
.stringn "불만을 가져 본 적도 없고.\n"
.stringn "\x0703……부모님의 존재는 크죠.\n"
.stringn "자신의 어린 시절을 아는 사람의\n"
.stringn "존재는…\n"
.stringn "유아가 자아를 형성해 가는 과정에\n"
.stringn "꼭 필요하다고 생각합니다.\n"
.stringn "아무것도 모르는 생물이 확신을 가진\n"
.stringn "한 사람이 되기 위해서…그걸 긍정해 주고\n"
.stringn "후원해 주는 어른이 없다면……\n"
.stringn "아이는 자신이 나아가는 길을 알 수 없게 되고…\n"
.stringn "자신이 대체 무엇인지도\n"
.stringn "알 수 없게 될 거예요.\n"
.stringn "\x0711세네리오는 부모에 대한 기억이 없어?\n"
.stringn "\x0703네. 저를 키운 여자는,\n"
.stringn "적어도 저를 낳은 자가 아니에요.\n"
.stringn "그 여자의 말버릇은…\n"
.stringn "『왜 내가?』\n"
.stringn "『세상은 불공평해』\n"
.stringn "『가까이 오지 마』…였거든요.\n"
.stringn "일말의 애정도 없이\n"
.stringn "뭔가의 의무감에 휩싸여서\n"
.stringn "저를 돌보는 것 같았죠.\n"
.stringn "\x0711……\n"
.stringn "\x0703그리고… 네 살 정도 됐을 때,\n"
.stringn "부근에 살고 있던 현자가……\n"
.stringn "저를 데려가겠다고 제안했죠.\n"
.stringn "제게… 보기 드문\n"
.stringn "마도의 재능이 있다고 하면서요…\n"
.stringn "여자는 매우 기뻐하며 현자에게 저를 양보했어요.\n"
.stringn "잘 기억하고 있습니다.\n"
.stringn "제가 그 여자의 웃는 얼굴을 본 건\n"
.stringn "그때뿐이었어요.\n"
.stringn "정말 기쁜 것 같더군요.\n"
.stringn "귀찮은 것을 쫓아낼 뿐만 아니라\n"
.stringn "사례금까지\n"
.stringn "손에 넣을 수 있었으니까요.\n"
.stringn "\x0711……\n"
.stringn "\x0703현자는 죽을 때가 가까워졌고,\n"
.stringn "자신의 지식을 이어받을 사람을 구했습니다.\n"
.stringn "시간이 없다고 들으면서,\n"
.stringn "먹고 자는 시간도 아껴 가며 마도 수행을 끝내면\n"
.stringn "어느새 새벽이 되어 있었습니다.\n"
.stringn "그래도… 제게 있어선\n"
.stringn "그 여자와의 생활보다 훨씬 나았어요.\n"
.stringn "자신이 누구인지\n"
.stringn "돌아볼 여유조차 없었으니까요.\n"
.stringn "2년 후, 현자가 죽었을 때……\n"
.stringn "저는 약간의 마도를 쓸 수 있었어요.\n"
.stringn "현자의 집에 먹을 것이 떨어져서,\n"
.stringn "밖으로 나가 마을로 갔습니다.\n"
.stringn "그리고……\n"
.stringn "저는… 처음으로 깨달았죠.\n"
.stringn "자신이 한 마디도 말할 줄 모른다는 것을.\n"
.stringn "\x0711…세네리오……\n"
.stringn "\x0703읽고 쓸 줄은 알았어요.\n"
.stringn "상대방의 말도 이해할 수 있었죠.\n"
.stringn "하지만… 스스로는 아무 말도 할 줄 몰랐어요.\n"
.stringn "어쩔 수 없었죠.\n"
.stringn "여자도 현자도, 제게 일방적으로\n"
.stringn "말을 던지기만 했을 뿐 거기에 제가\n"
.stringn "대답할 필요는 없다고 생각했으니까요……\n"
.stringn "\x0711…세네리오!!\n"
.stringn "\x0703!\n"
.stringn "…아…\n"
.stringn "죄, 죄송합니다……\n"
.stringn "이런 시시한 이야기를…\n"
.stringn "\x0711시시하지 않아.\n"
.stringn "그게 네가…\n"
.stringn "우울해하고 있었던 이유야?\n"
.stringn "혹시 어렸을 때\n"
.stringn "네가 살았던 곳은\n"
.stringn "베그니온이었어?\n"
.stringn "\x0703…아니에요.\n"
.stringn "……제가 말하고 싶었던 건…\n"
.stringn "………………\n"
.stringn "아뇨, 이제 됐어요.\n"
.stringn "죄송해요, 실례하겠습니다.\n"
.stringn "\x0711잠깐, 세네리오…!\n"
.stringn "…………"
db 0
.align 4
//MYELL_8_IKE_SENERIO_B

//0x1653C
Text_1651C:
.stringn "\x05FL|SENERIO|IKE||\x0C01\x0C13\x0701그래서 이번 지출은…\n"
.stringn "물자도 부족하고……\n"
.stringn "………아이크?\n"
.stringn "제대로 듣고 있는 건가요?\n"
.stringn "\x0713응?\n"
.stringn "아, 못 들었어.\n"
.stringn "미안해.\n"
.stringn "\x0701………\n"
.stringn "\x0713미안하지만 다시 한번\n"
.stringn "처음부터 보고해 줘.\n"
.stringn "\x0701좀 쉬시는 게 어때요?\n"
.stringn "굉장해 피곤해 보여요.\n"
.stringn "\x0713…그래 보여?\n"
.stringn "\x0701네.\n"
.stringn "상태가 안 좋을 때의 아이크는\n"
.stringn "미간의 주름이 깊어지니까요.\n"
.stringn "\x0713…묘한 판단인걸.\n"
.stringn "\x0701아무튼 휴식을 취해 주세요.\n"
.stringn "나머지 일은\n"
.stringn "제가 잘 처리할 테니까요.\n"
.stringn "\x0713그럼, 그렇게 해 줘.\n"
.stringn "\x0701네.\n"
.stringn "\x0713……다른 녀석들한테도\n"
.stringn "이렇게 친절하면\n"
.stringn "좋을 텐데……\n"
.stringn "\x0701네? 뭐라고 하셨나요?\n"
.stringn "\x0713아무것도 아니야.\n"
.stringn "그럼, 부탁해.\n"
.stringn "\x0701…네."
db 0
.align 4
//MYELL_8_IKE_SENERIO_C

//0x17FF4
Text_17FD4:
.stringn "\x05FL|IKE|TIAMAT||\x0C01\x0C13\x0701저기, 티아마트……\n"
.stringn "고마워.\n"
.stringn "\x0713? ……왜 그래? 아이크.\n"
.stringn "새삼스럽게……\n"
.stringn "\x0701내일 얘기할 수 있을진 장담 못 하니까.\n"
.stringn "생각이 났을 때 전해 두고 싶었어.\n"
.stringn "……들어 줄래?\n"
.stringn "\x0713어, 으응…… 상관없어……\n"
.stringn "그런데 갑자기 왜 그래?\n"
.stringn "내가 너한테 감사받을 만한 일을\n"
.stringn "한 적이 있었나……?\n"
.stringn "\x0701그래.\n"
.stringn "너는…… 갈리아에서 엄마를 잃고\n"
.stringn "어린 나와 미스트를 키워야 하는 아버지를\n"
.stringn "도와, 용병단을 만들어 주었어.\n"
.stringn "그 일에 대해…… 감사를 전하고 싶었어.\n"
.stringn "\x0713…………\n"
.stringn "\x0701지금까지 아무것도 모르고 지내서 미안해.\n"
.stringn "네가 지켜 주었기에\n"
.stringn "존재하는 것들을 당연하다는 듯이\n"
.stringn "누리고 있었어.\n"
.stringn "\x0713……아니야, 아이크.\n"
.stringn "나는 자신을 위해서……\n"
.stringn "\x0701알고 있어.\n"
.stringn "아버지를…… 사랑하고 있었던 거지?\n"
.stringn "\x0713……!!\n"
.stringn "\x0701만약 그게 아니라\n"
.stringn "다른 생각이 있었다고 해도\n"
.stringn "지금 나는 이렇게 살아 있어.\n"
.stringn "그 사실에\n"
.stringn "감사하는 마음은 변하지 않아.\n"
.stringn "아버지가 강했어도, 네가 도와주지 않았다면\n"
.stringn "어쩌면 우리와 함께\n"
.stringn "죽었을지도 몰라.\n"
.stringn "아버지의 목숨을, 그때 그곳에서\n"
.stringn "칠흑의 기사에게 쓰러질 때까지……\n"
.stringn "지켜 주고 있었던 거구나.\n"
.stringn "………정말로, 고마워.\n"
.stringn "\x0713…… …… ……\n"
.stringn "흐, 흑……… 흐윽…\n"
.stringn "\x0701아버지와는 달리 나에겐 아직 경험도 힘도\n"
.stringn "없지만…… 괜찮다면 앞으로도\n"
.stringn "우리를 이끌고, 지지해 줄 수 있을까?\n"
.stringn "……부탁해.\n"
.stringn "\x0713응……\n"
.stringn "그래, 물론이지…… 아이크……"
db 0
.align 4
//MYELL_8_IKE_TIAMAT_A

//0x17B5C
Text_17B3C:
.stringn "\x05FL|IKE|TIAMAT||\x0703티아마트. 잠깐 괜찮을까?\n"
.stringn "\x0711아이크?\n"
.stringn "나한테 볼일이 있는 거야?\n"
.stringn "\x0703잊어버렸어?\n"
.stringn "저번에 얘기했었잖아.\n"
.stringn "너와 아버지는\n"
.stringn "언제부터 서로 알게 된 거냐고.\n"
.stringn "\x0711아, 그래……\n"
.stringn "그러고 보니 말해 주기로 했었지……\n"
.stringn "\x0703……말하기 싫다면\n"
.stringn "억지로 물어보진 않겠지만……\n"
.stringn "\x0711싫다, 기보다는……\n"
.stringn "자신의 과거를 말하는 게 어색해서 그래.\n"
.stringn "……그래도……\n"
.stringn "그 사람에 대해 네가 조금이라도 더\n"
.stringn "많이 알고 있었으면 하니까……\n"
.stringn "얘기해 줄게.\n"
.stringn "\x0703그래, 부탁해.\n"
.stringn "\x0711내가 아직 크리미아 기사였을 때……\n"
.stringn "크리미아와 갈리아의 교환 무관에 지원해서,\n"
.stringn "갈리아에 머무는 동안에 만났어.\n"
.stringn "왕궁에서 열린 합동 투기로\n"
.stringn "그 사람의 강함을 목격하게 되었지.\n"
.stringn "덮쳐 오는 여러 강호들을 마치\n"
.stringn "어린아이 다루듯이 쓰러뜨려 갔어.\n"
.stringn "상대는 도대체 자신이 왜 쓰러져 있는지도\n"
.stringn "모를 정도로…… 훌륭한 검술이었지.\n"
.stringn "일기당천이란 건 이런 거구나 하고……\n"
.stringn "몸이 떨렸어.\n"
.stringn "\x0703…………\n"
.stringn "\x0711나도 검을 맞댔었지만……\n"
.stringn "도저히 당해낼 수가 없었지.\n"
.stringn "하지만 그 후에도 시간이 있을 때\n"
.stringn "상대를 해 주셨거든.\n"
.stringn "그렇게 친해지고……\n"
.stringn "그 사람의 집에 초대받았을 때,\n"
.stringn "네가 있었어.\n"
.stringn "\x0703내가?\n"
.stringn "\x0711그래. 미소 지은 에르나에게 안겨서\n"
.stringn "자고 있었는데…… 귀여웠지.\n"
.stringn "그 사람이 너를 보고 있을 때의 눈은\n"
.stringn "무척 상냥해서……\n"
.stringn "검을 겨눌 때하곤 완전히 다른 사람 같았어.\n"
.stringn "\x0703…………그랬구나……"
db 0
.align 4
//MYELL_8_IKE_TIAMAT_B

//0x1787C
Text_1785C:
.stringn "\x05FL|TIAMAT|IKE||\x070-\x0701어머, 아이크.\n"
.stringn "너도 훈련하려고?\n"
.stringn "\x0713티아마트구나.\n"
.stringn "그럼, 상대를 부탁해도 될까?\n"
.stringn "네가 상대라면 배울 게 많아서 좋거든.\n"
.stringn "\x0701그래? 다행이네.\n"
.stringn "이제 네게 내 지도는\n"
.stringn "필요 없을 줄 알았어.\n"
.stringn "\x0713무슨 소리야.\n"
.stringn "아버지한테서 물려받은 검술을\n"
.stringn "쓸 만하게 다듬어 준 건\n"
.stringn "너라고 생각하는데.\n"
.stringn "\x0701후후, 그렇게 말해 주니 영광이야.\n"
.stringn "……저기, 아이크.\n"
.stringn "\x0713왜?\n"
.stringn "\x0701네가 그레일 단장님께\n"
.stringn "물려받은 검술은……\n"
.stringn "이 세상에서 유일한 거야.\n"
.stringn "소중히 해 줘.\n"
.stringn "\x0713…………\n"
.stringn "저기, 티아마트.\n"
.stringn "갑자기 궁금해서 그런데……\n"
.stringn "너는 언제부터 아버지와 함께 있었어?\n"
.stringn "티아마트는 크리미아 기사였지?\n"
.stringn "\x0701……맞아.\n"
.stringn "하지만 그 얘기는 다음에 할게.\n"
.stringn "마음의 준비를 하고 싶어.\n"
.stringn "지금은 다음 싸움에만 전념하자.\n"
.stringn "\x0713……알았어."
db 0
.align 4
//MYELL_8_IKE_TIAMAT_C

//0x18C40
Text_18C20:
.stringn "\x05FL|JANAFF|LUCHINO||\x0C01\x071-\x0713베오크도 라구즈도\n"
.stringn "서로 차별하지 않고,\n"
.stringn "나라와 종족을 넘어선 우호……\n"
.stringn "우리 크리미아의 이상은\n"
.stringn "모든 사람들의 평화입니다.\n"
.stringn "\x0701종족을 넘어서……인가.\n"
.stringn "크리미아는 별난 나라네.\n"
.stringn "라구즈를 자기 나라 안에서\n"
.stringn "살게 해 준다며?\n"
.stringn "\x0713네, 카이네기스 왕과의\n"
.stringn "동맹에 의한 것입니다.\n"
.stringn "엘린시아 공주님께서는 언젠가\n"
.stringn "갈리아뿐만 아니라, 다른\n"
.stringn "라구즈 국가들과도 그렇게 되길 원하십니다…\n"
.stringn "\x0701……좋은 이야기라고 생각해.\n"
.stringn "그래도 종족이나 나라를\n"
.stringn "초월한 우호라니,\n"
.stringn "그렇게 잘 될까?\n"
.stringn "\x0713……라고 말씀하신다면?\n"
.stringn "\x0701예를 들어 보자고.\n"
.stringn "우리 페니키스와\n"
.stringn "베그니온이 대립했던 건\n"
.stringn "당연히 알고 있지?\n"
.stringn "\x0713네……\n"
.stringn "\x0701신사는 셀리노스에게 사죄하긴 했지만\n"
.stringn "그렇다고 그 사실이\n"
.stringn "나라 전체에 영향을 끼치진 못했어.\n"
.stringn "언제 무슨 일로 다시 대립하고,\n"
.stringn "전쟁이 일어날지도 몰라.\n"
.stringn "그렇게 된다면 너는 어디에 붙을 거야?\n"
.stringn "\x0713그건……\n"
.stringn "\x0701베그니온이겠지. 아니야?\n"
.stringn "우리 페니키스 입장에서 보면,\n"
.stringn "크리미아는 베그니온의 속국,\n"
.stringn "베그니온의 부하라고 할 수 있지.\n"
.stringn "그렇다면 나는 너를 상대로\n"
.stringn "싸우게 될 거고.\n"
.stringn "\x0713……엘린시아 공주님께서는 결코\n"
.stringn "그런 사태를 바라지 않으십니다.\n"
.stringn "온갖 방법을 써서\n"
.stringn "전쟁을 피하려고 하시겠지요.\n"
.stringn "……하지만, 저는 엘린시아 공주님의 신하.\n"
.stringn "만일 싸워야만 한다면……\n"
.stringn "그때는 망설이지 않을 겁니다.\n"
.stringn "\x0701나도 마찬가지야.\n"
.stringn "왕의 아군은 나의 아군.\n"
.stringn "왕의 적은 나의 적이니까.\n"
.stringn "그래도 가능하다면\n"
.stringn "너하고 싸우고 싶지는 않은걸.\n"
.stringn "너같이 괜찮은 여자하고는 싸우는 것보다\n"
.stringn "마시면서 얘기하고 싶으니까.\n"
.stringn "\x0713네…… 저도 동감입니다.\n"
.stringn "이 전쟁이 끝나고 나면,\n"
.stringn "크리미아의 부흥을 이루고 나면……\n"
.stringn "또 뵙도록 해요.\n"
.stringn "적이 아니라, 친구로서.\n"
.stringn "\x0701그 무렵에는 너도 술을 마실 수 있는\n"
.stringn "나이가 되어 달라고. 부탁한다?\n"
.stringn "\x0713네……네에……\n"
.stringn "…………?"
db 0
.align 4
//MYELL_8_JANAFF_LUCHINO_A

//0x187F4
Text_187D4:
.stringn "\x05FL|JANAFF|LUCHINO||\x070-\x0C01\x071-\x0C13\x0701우리 페니키스는 남해에 있어.\n"
.stringn "따뜻하고 살기 좋은 곳이지.\n"
.stringn "인구는 적지만\n"
.stringn "우리들은 동족끼리 다투거나 하지 않아.\n"
.stringn "나는 이 눈으로 여러 나라들을 봐 왔지만,\n"
.stringn "틀림없이 우리 나라만큼 좋은 곳은 없었어.\n"
.stringn "\x0713타국과의 국교는\n"
.stringn "갖고 계셨나요?\n"
.stringn "\x0701아니, 우린 타국과 어울리지 않아.\n"
.stringn "친분을 가지고 있던 셀리노스는\n"
.stringn "베오크 놈들에게 멸망당했고……\n"
.stringn "그 네사라 왕이 있는 키르바스는\n"
.stringn "신용할 수가 없으니까.\n"
.stringn "\x0713베오크 국가들과는 어땠나요?\n"
.stringn "\x0701그건 더욱 있을 수 없는 얘기지.\n"
.stringn "셀리노스 학살 이후로 우리에게\n"
.stringn "베오크는 적이었으니까.\n"
.stringn "\x0713그렇군요……\n"
.stringn "하지만 앞서 말씀드렸다시피 우리 크리미아는\n"
.stringn "여러분들과의 국교를 희망합니다.\n"
.stringn "돌아가신 폐하께서는 라구즈와 우호를\n"
.stringn "다지는 데 힘쓰셨고, 갈리아의 카이네기스 왕과도\n"
.stringn "친밀한 관계에 있었어요.\n"
.stringn "\x0701그래, 그렇다며.\n"
.stringn "우리 페니키스는\n"
.stringn "타국과 손을 잡지 않아도 잘 살 수 있지…\n"
.stringn "만, 우리 왕께서\n"
.stringn "그렇게 결단하신다면\n"
.stringn "크리미아와의 우호도 생길 수 있겠지.\n"
.stringn "\x0713야나프님께서는 어떻게 생각하시나요?\n"
.stringn "\x0701나는…… 그렇지.\n"
.stringn "전에는 베오크라는 이유 하나로\n"
.stringn "싫어했었지만……\n"
.stringn "지금은 우호를 쌓는 것도 나쁘지 않다고 생각해.\n"
.stringn "이것도 저것도……\n"
.stringn "다 너와 만난 덕분이야……\n"
.stringn "\x0713네……네에……\n"
.stringn "황송합니다…………"
db 0
.align 4
//MYELL_8_JANAFF_LUCHINO_B

//0x18478
Text_18458:
.stringn "\x05FL|JANAFF|LUCHINO||\x0C01\x0713페니키스의 기사님이시군요.\n"
.stringn "\x0701응?\n"
.stringn "\x0713처음 뵙겠습니다.\n"
.stringn "저는 크리미아 왕국의 루키노,\n"
.stringn "엘린시아 공주님의 신하입니다.\n"
.stringn "이번 귀국의 조력에,\n"
.stringn "진심으로 감사를 표합니다.\n"
.stringn "\x0701흐음……\n"
.stringn "\x0713?\n"
.stringn "\x0701아니아니, 친절하네.\n"
.stringn "나는 야나프.\n"
.stringn "우리 왕의 명령으로 여기에 있어.\n"
.stringn "그러니까 감사는\n"
.stringn "내가 아니라 왕께 해 줘.\n"
.stringn "\x0713네.\n"
.stringn "가능하면 직접 뵈어\n"
.stringn "전하고 싶습니다만……\n"
.stringn "상황이 상황이니까요.\n"
.stringn "티반 왕께는\n"
.stringn "부디 안부 전해 주시면 감사하겠습니다.\n"
.stringn "\x0701……흐~음.\n"
.stringn "\x0713무, 무슨 일이라도?\n"
.stringn "\x0701아니 그게, 앞으로는 너하고\n"
.stringn "이 군에 싸우는 거지?\n"
.stringn "그렇다면 우호의 의미를 겸해서\n"
.stringn "같이 술이라도 마실래?\n"
.stringn "\x0713아뇨, 그럴 수는 없습니다.\n"
.stringn "여러분의 관습이 어떤지는 모르지만……\n"
.stringn "우리 나라에서는 아직 술에 흥미를\n"
.stringn "가져선 안 되는 나이인지라……\n"
.stringn "\x0701흐~음……\n"
.stringn "뭐, 그렇다면 어쩔 수 없지.\n"
.stringn "그나저나 너 외견은 괜찮은 여자인 것 같은데\n"
.stringn "나이는 아직 어린가 봐?\n"
.stringn "베오크의 나이는 알 수가 없다니까.\n"
.stringn "\x0713……?"
db 0
.align 4
//MYELL_8_JANAFF_LUCHINO_C

//0x1973C
Text_1971C:
.stringn "\x05FL|OSCAR|JANAFF||\x0703저기……\n"
.stringn "\x0711응?\n"
.stringn "…흥, 또 너냐.\n"
.stringn "\x0703지난번에는 정말로\n"
.stringn "죄송했습니다.\n"
.stringn "여러분 조익족에 대한\n"
.stringn "제 공부가 소홀했던 점을 부디 용서해 주십시오.\n"
.stringn "\x0711……호오.\n"
.stringn "뭐어…… 알았으면 됐어.\n"
.stringn "근데 넌 몇 살이냐?\n"
.stringn "베오크의 나이는 알 수가 없다니까.\n"
.stringn "\x0703저는 이제 24살입니다.\n"
.stringn "\x071124!?\n"
.stringn "24살이라니…… 이봐 이봐,\n"
.stringn "아직 깃털도 안 난\n"
.stringn "어린애잖아!\n"
.stringn "베오크는 아기를 전장에 내보내는 거냐!?\n"
.stringn "나 참… 피도 눈물도 없는 녀석들이구만.\n"
.stringn "\x0703하…하하……\n"
.stringn "\x0711……꼬맹이, 네 이름은?\n"
.stringn "\x0703오, 오스카입니다.\n"
.stringn "\x0711나는 야나프다.\n"
.stringn "……정말 예의도 모르는 놈인 줄\n"
.stringn "녀석인가 싶었다고……\n"
.stringn "어린애였다면 어쩔 수 없지.\n"
.stringn "\x0703………………\n"
.stringn "\x0711뭐, 세상물정 모르는 아이를\n"
.stringn "날 수 있게 될 때까지 이끌어 주는 게\n"
.stringn "연장자의 의무 아니겠어.\n"
.stringn "여태까지의 무례는 용서해 줄게.\n"
.stringn "무슨 일이 있으면 나를 의지하라고.\n"
.stringn "알겠지?\n"
.stringn "\x0703네……넵.\n"
.stringn "감사합니다."
db 0
.align 4
//MYELL_8_JANAFF_OSCAR_A

//0x19404
Text_193E4:
.stringn "\x05FL|OSCAR|JANAFF||\x070-\x0703얘, 안녕.\n"
.stringn "\x0711응?\n"
.stringn "\x0703또 만났네.\n"
.stringn "저번에는 미안했어.\n"
.stringn "난 너희들과 얘기했던 경험이\n"
.stringn "별로 없어서……\n"
.stringn "그렇지. 뭔가 이 군에 대해서\n"
.stringn "모르는 게 있으면 물어봐도 돼!\n"
.stringn "\x0711아니, 딱히 없어.\n"
.stringn "왜 갑자기?\n"
.stringn "\x0703나한테는 딱 너만한 동생이 있거든.\n"
.stringn "그러니까 왠지 내버려 둘 수 없어서.\n"
.stringn "그나저나 라구즈는 대단하구나.\n"
.stringn "너처럼 아직 어린애까지\n"
.stringn "뛰어난 전사이고……\n"
.stringn "\x0711야, 잠깐 기다려……\n"
.stringn "어린애…… 어린애라고!?\n"
.stringn "\x0703왜, 왜 그래?\n"
.stringn "\x0711알겠냐, 잘 들어!\n"
.stringn "나는 꼬맹이가 아냐!\n"
.stringn "벌써 100년은 넘게 살았거든!\n"
.stringn "\x0703응?\n"
.stringn "100년……?\n"
.stringn "\x0711네가 몇 살인지는 모르겠지만\n"
.stringn "내 얼굴을 좀 본 다음에 말해라!\n"
.stringn "애 취급 받는 건 못 참는다고!\n"
.stringn "다시는 착각하지 마!\n"
.stringn "알겠지!\n"
.stringn "\x0703아, 잠깐……!\n"
.stringn "\x0C11\x0C03실수했다……\n"
.stringn "많이 화나게 해 버린 것 같은데……\n"
.stringn "겉모습으로만 판단해선 안 된다는 건가.\n"
.stringn "나중에 날을 잡아서 사과하러 가야겠네……"
db 0
.align 4
//MYELL_8_JANAFF_OSCAR_B

//0x19270
Text_19250:
.stringn "\x05FL|OSCAR|JANAFF||\x0701너는……\n"
.stringn "\x0713응?\n"
.stringn "\x0701안녕.\n"
.stringn "………………\n"
.stringn "\x0713?\n"
.stringn "나한테 볼일 있어?\n"
.stringn "\x0701아니, 별로 볼일이 있는 건\n"
.stringn "아니지만……\n"
.stringn "\x0713뭐야? 이상한 녀석이네.\n"
.stringn "볼일 없는 거지?\n"
.stringn "그럼 간다.\n"
.stringn "……베오크는 잘 모르겠다니까.\n"
.stringn "\x0701곤란한걸……\n"
.stringn "어떻게 말을 걸면 좋을까……\n"
.stringn "여태까지 조익족이랑 어울렸던 적은\n"
.stringn "없었는데……\n"
.stringn "하지만 동료끼리\n"
.stringn "교류를 가지지 않는 건 이상하고…\n"
.stringn "다음엔 좀 더 제대로 얘기해 보자……"
db 0
.align 4
//MYELL_8_JANAFF_OSCAR_C

//0x1A79C
Text_1A77C:
.stringn "\x05FL|RETHE|JILL||\x0701……\n"
.stringn "\x0713! 레테…\n"
.stringn "\x0701……어째서냐?\n"
.stringn "달레카에서 싸운 용 기사는……\n"
.stringn "네 아버지였다고 들었다.\n"
.stringn "…어째서, 그렇게까지 해서\n"
.stringn "이쪽에 남을 결심을 한 거지?\n"
.stringn "\x0713………\n"
.stringn "운명이란 건 신기하지.\n"
.stringn "만약, 이 군을…\n"
.stringn "아이크님이나 용병단…\n"
.stringn "그리고 무엇보다……\n"
.stringn "레테와 라구즈들을 몰랐다면……\n"
.stringn "난 지금도 분명 데인군에 있었을 거야.\n"
.stringn "데인 왕국 군인으로서의 자부심에 불타\n"
.stringn "아슈나드를 위해서\n"
.stringn "기꺼이 목숨을 바쳤겠지.\n"
.stringn "너희를 쓰러뜨리는 걸\n"
.stringn "주저하지 않았을 거야.\n"
.stringn "……그렇지만, 알아 버렸어.\n"
.stringn "\x0701……\n"
.stringn "\x0713공을 세우기 위해 항구 마을 토하에서\n"
.stringn "너희들의 배를 쫓았을 때와는 달라.\n"
.stringn "나는 처음으로… 스스로 생각하고 행동했어.\n"
.stringn "내가…\n"
.stringn "더 옳다고 생각하는 길을 선택하기 위해서.\n"
.stringn "그것이 비록… 친아버지를\n"
.stringn "상대하는 것이었다고 해도.\n"
.stringn "이젠, 몰랐던 시절로 돌아갈 수 없어.\n"
.stringn "그래서… 나는 여기에 있어.\n"
.stringn "\x0701………질.\n"
.stringn "내 손을 잡아 주지 않겠나?\n"
.stringn "\x0713어…?\n"
.stringn "\x0701우애의 마음을 표시할 때…\n"
.stringn "서로의 손을 잡는 것이\n"
.stringn "베오크의 관례라고 들었다.\n"
.stringn "나는 너의 강함에…\n"
.stringn "너의 삶의 방식에 경의를 표하지.\n"
.stringn "\x0713레테…\n"
.stringn "아…… 응. …고마워.\n"
.stringn "\x0701…베오크와 라구즈는\n"
.stringn "이해할 수 있다.\n"
.stringn "서로를 이해하려는 계기와…\n"
.stringn "양보하려는 마음이 있다면, 반드시."
db 0
.align 4
//MYELL_8_JILL_LETHE_A

//0x19D6C
Text_19D4C:
.stringn "\x05FL|JILL|RETHE||\x0701레… 레테?\n"
.stringn "\x0713…누군가 했더니, 또 너인가.\n"
.stringn "\x0701나는 질이야.\n"
.stringn "너가… 아니라.\n"
.stringn "\x0713그럼 질.\n"
.stringn "오늘은 무슨 용무지?\n"
.stringn "또 쓸데없는 질문인가?\n"
.stringn "\x0701…쭉, 알 수 없었어.\n"
.stringn "데인에서는…\n"
.stringn "너희들이 맹수나 다름없다고,\n"
.stringn "인간을 습격하는 적이라고…\n"
.stringn "그렇게 가르쳐 왔으니까.\n"
.stringn "\x0713하, 우리가 베오크를\n"
.stringn "무차별적으로 습격한다고?\n"
.stringn "설령 그렇게 부탁받았다 해도\n"
.stringn "관여조차 안 하고 싶다만?\n"
.stringn "\x0701……하지만, 데인에서는\n"
.stringn "주위의 누구나 그렇게 믿고 있었어.\n"
.stringn "그러니까… 그럴 거라고\n"
.stringn "의심하지도 않고 살아 왔지……\n"
.stringn "하지만… 남쪽 바다에서……\n"
.stringn "아이크네와 함께 싸우는\n"
.stringn "레테의 모습에… 위화감을 느꼈어.\n"
.stringn "어째서 이렇게\n"
.stringn "상상했던 것과 다른 걸까.\n"
.stringn "어렸을 때부터 들어 왔던\n"
.stringn "괴물 같은 짐승이 아니었어.\n"
.stringn "그리고 화신을 푼 너는……\n"
.stringn "짐승이 아니라… 오히려 우리와 가까웠지.\n"
.stringn "\x0713………\n"
.stringn "\x0701애초에…\n"
.stringn "베오크와 라구즈가 싸우기 시작한 건\n"
.stringn "언제부터였을까?\n"
.stringn "뭔가 계기가 있었던 걸까?\n"
.stringn "\x0713…그건 나도 모른다.\n"
.stringn "처음부터… 여신이 그렇게\n"
.stringn "만들어 냈기 때문인지,\n"
.stringn "근본적으로 그런 것인지.\n"
.stringn "다만… 고르드아를 제외한\n"
.stringn "갈리아, 페니키스, 키르바스…\n"
.stringn "이 나라들에 한해서\n"
.stringn "베오크가 증오받는 이유는 명확하다.\n"
.stringn "\x0701무, 무슨 이유인데?\n"
.stringn "\x0713……그 반응을 보니,\n"
.stringn "베오크는 후세에게… 정확한 역사를\n"
.stringn "전하지 않고 있는 것 같군.\n"
.stringn "………후우…\n"
.stringn "…잘 들어라. 베그니온이 아직\n"
.stringn "제국이 아닌 왕국이었던 때…\n"
.stringn "테리우스에는 베그니온과\n"
.stringn "고르드아 두 나라만이 존재했다.\n"
.stringn "고르드아는 지금과 다름없이\n"
.stringn "용린족들뿐인 폐쇄적인 나라였고…\n"
.stringn "다른 라구즈… 수아족, 조익족은\n"
.stringn "베그니온에서\n"
.stringn "베오크와 함께 살고 있었지.\n"
.stringn "\x0701과거의 베그니온에서는…\n"
.stringn "인간과 라구즈가 공존하고 있었다고…?\n"
.stringn "그, 그런 이야기는…\n"
.stringn "들어본 적도 없어.\n"
.stringn "\x0713나라의 왕으로는… 초대엔\n"
.stringn "베오크가 뽑혔다는 것 같지만\n"
.stringn "그 뒤로는… 완력이 뛰어난 라구즈가\n"
.stringn "왕위에 오르는 경우도 많았다고 한다.\n"
.stringn "그러나 그에 불복한 원로원이\n"
.stringn "【신사】의 이름 아래\n"
.stringn "베오크야말로 베그니온의\n"
.stringn "지배자라며 크게 내란을 일으켰지.\n"
.stringn "결국 오합지졸에 불과했던\n"
.stringn "라구즈의 왕들은…\n"
.stringn "개량을 거듭해 진화를 이룬\n"
.stringn "무기와 마도 앞에서 무릎을 꿇고 말았다.\n"
.stringn "………………\n"
.stringn "…그리고… 길고 긴……\n"
.stringn "라구즈의 노예 시대가 시작됐지.\n"
.stringn "\x0701……\n"
.stringn "\x0713200년에 이르는 시간을 거쳐\n"
.stringn "베오크의 손아귀에서 벗어나기 위해\n"
.stringn "베그니온 탈출에 성공한 라구즈들이 있었다.\n"
.stringn "수아족은 험준한 산악을 목숨을 걸고\n"
.stringn "돌파해 미개척된 대삼림 지대로…\n"
.stringn "조익족은 남쪽 섬으로 각자 빠져나갔지.\n"
.stringn "그것이 우리 라구즈 왕국의 시작이다.\n"
.stringn "그로부터 정식 국가로 인정받기까지는\n"
.stringn "80년의 시간을 거치며 많은\n"
.stringn "동포들의 피가 흘렀다.\n"
.stringn "싸움의 이유는 있었다.\n"
.stringn "베오크들은 한 번은 굴복했던 노예들이\n"
.stringn "나라를 세우고 자신들과 대등해지는 것을 싫어했지.\n"
.stringn "라구즈들은 과거의 굴욕을 안고\n"
.stringn "지금도 자유를 찾아 쟁취하려 하고 있다.\n"
.stringn "이것이 너희 베오크가 후세에 전하지 않고\n"
.stringn "어둠 속에 묻으려고 하는 역사의 진실이다.\n"
.stringn "\x0701…………\n"
.stringn "\x0713흥, 할 말이 없나 보군.\n"
.stringn "잘… 생각해 봐라.\n"
.stringn "자신의 눈으로 본 것을…\n"
.stringn "그 귀로 들은 것을 생각해 봐라.\n"
.stringn "그것조차도 할 수 없다면,\n"
.stringn "두 번 다시 내 앞에 모습을 드러내지 마라.\n"
.stringn "\x0701………………"
db 0
.align 4
//MYELL_8_JILL_LETHE_B

//0x19A5C
Text_19A3C:
.stringn "\x05FL|RETHE|JILL||\x0C01\x0713아…\n"
.stringn "\x0701?\n"
.stringn "나한테 볼일이라도 있나?\n"
.stringn "\x0713지, 질문이 있는데\n"
.stringn "물어봐도 괜찮을까?\n"
.stringn "\x0701…내용에 따라서.\n"
.stringn "\x0713…………그…\n"
.stringn "왜 반수… 아니\n"
.stringn "라구즈…는,\n"
.stringn "전투에 무기를 사용하지 않는 거야?\n"
.stringn "\x0701………\n"
.stringn "라구즈에게는 선천적으로\n"
.stringn "전투술이 몸에 배어 있다.\n"
.stringn "무기는 힘을 가질 수 없는\n"
.stringn "너희들 베오크가…\n"
.stringn "우리의 손톱과 이빨에 대항하여\n"
.stringn "만들어낸 것.\n"
.stringn "쓸 필요가 없다.\n"
.stringn "\x0713그, 그렇구나…\n"
.stringn "\x0701그것뿐인가?\n"
.stringn "\x0713어… 아, 아니.\n"
.stringn "또 있어.\n"
.stringn "너희들은 어째서\n"
.stringn "우리들… 그, 인간을\n"
.stringn "증오하는 거야?\n"
.stringn "\x0701……그 질문이라면\n"
.stringn "오히려 이쪽이 먼저\n"
.stringn "네 대답을 듣고 싶군.\n"
.stringn "왜 베오크는 라구즈를 증오하지?\n"
.stringn "나는… 그 이유를 알고 싶다.\n"
.stringn "\x0713그건…\n"
.stringn "반수… 라구즈가 적이니까.\n"
.stringn "\x0701적인가…\n"
.stringn "그렇다면 이쪽도\n"
.stringn "적이니까 베오크를 증오하는 것이라고\n"
.stringn "대답할 수밖에 없다.\n"
.stringn "……그럼, 이만 가지.\n"
.stringn "이 이상 시간을 낭비하고 싶지 않아.\n"
.stringn "\x0713………"
db 0
.align 4
//MYELL_8_JILL_LETHE_C

//0x1AF64
Text_1AF44:
.stringn "\x05FL|JILL|MIST||\x0C01\x0C13\x0701미스트, 잠깐 괜찮을까?\n"
.stringn "\x0713아, 질.\n"
.stringn "\x0701…딱히 뭔가 중요한 볼일이\n"
.stringn "있는 건 아니야…\n"
.stringn "미스트랑 같이 있고 싶어서.\n"
.stringn "방해된다면 말해 줘?\n"
.stringn "\x0713아냐.\n"
.stringn "나도 마침 질이랑\n"
.stringn "만나고 싶다고 생각했어.\n"
.stringn "와 줘서 기뻐.\n"
.stringn "\x0701다행이다.\n"
.stringn "\x0713헤헤\n"
.stringn "\x0701………\n"
.stringn "\x0713………\n"
.stringn "\x0701…………\n"
.stringn "\x0713……대단했지.\n"
.stringn "\x0701…?\n"
.stringn "\x0713셀리노스의 숲.\n"
.stringn "뤼시온씨와 리아네씨의 노랫소리가…\n"
.stringn "눈부신 빛으로 바뀌어서……\n"
.stringn "숲이… 숲이 살아났잖아.\n"
.stringn "\x0701……그…랬지.\n"
.stringn "…………\n"
.stringn "\x0713질?\n"
.stringn "…왜 울어?\n"
.stringn "\x0701그걸 보고… 깨달았어……\n"
.stringn "라구즈는… 악한 존재가 아니야.\n"
.stringn "틀린 건… 나였어……\n"
.stringn "……내가 믿어 온… 것들은……\n"
.stringn "\x0713………질……\n"
.stringn "\x0701…아버님은… 어째서…\n"
.stringn "내게 거짓말을……?\n"
.stringn "이렇게 괴로워질 줄 알았다면…\n"
.stringn "처음부터 진실을 아는 게 나았을 텐데……\n"
.stringn "설마… 데인이 쓰기 편한 군인으로\n"
.stringn "만들기 위해서……?\n"
.stringn "\x0713그럴 리가 없어!\n"
.stringn "\x0701!?\n"
.stringn "\x0713아빠는 절대…\n"
.stringn "자기 아이를……\n"
.stringn "그런… 도구처럼 생각하지 않아!\n"
.stringn "만약… 거짓말을 했다면,\n"
.stringn "분명 그건 자식을 위해서\n"
.stringn "한 걸 거야… 그러니까……\n"
.stringn "\x0701미스트…\n"
.stringn "\x0713질은 바보야!\n"
.stringn "아무리 풀이 죽어도 그렇지\n"
.stringn "아빠의 애정까지 의심하다니…\n"
.stringn "완전 바보라고!\n"
.stringn "그야, 아빠는…\n"
.stringn "아빠는………\n"
.stringn "\x0701미스트…!\n"
.stringn "알았어… 이제 알았으니까…\n"
.stringn "\x0713아빠…\n"
.stringn "아…빠……\n"
.stringn "………………\n"
.stringn "\x0701……………………\n"
.stringn "……미스트…\n"
.stringn "울지 마…………\n"
.stringn "………미스트…?\n"
.stringn "\x0713……응… 미…안…\n"
.stringn "\x0701……미스트, 고마워.\n"
.stringn "내 아버지에 대해…\n"
.stringn "그렇게 말해 줘서\n"
.stringn "고마워……\n"
.stringn "\x0713…질…\n"
.stringn "\x0701난… 정말 바보인가 봐.\n"
.stringn "그렇게나… 나를\n"
.stringn "소중하게 키워 준 사람을\n"
.stringn "한순간 의심하다니……\n"
.stringn "어떻게 됐나 보네……\n"
.stringn "……나, 정했어.\n"
.stringn "자신이 믿는 길을 고를 거야.\n"
.stringn "아버님께선… 분명 이해해 주시겠지.\n"
.stringn "\x0713질… 그래.\n"
.stringn "……그럴 거야!"
db 0
.align 4
//MYELL_8_JILL_MIST_A_a

//0x1B5B0
Text_1B590:
.stringn "\x05FL|JILL|MIST||\x0C01\x0C13\x0701미스트, 잠깐 괜찮을까?\n"
.stringn "\x0713아, 질.\n"
.stringn "\x0701…딱히 뭔가 중요한 볼일이\n"
.stringn "있는 건 아니야…\n"
.stringn "미스트랑 같이 있고 싶어서.\n"
.stringn "방해된다면 말해 줘?\n"
.stringn "\x0713아냐.\n"
.stringn "나도 마침 질이랑\n"
.stringn "만나고 싶다고 생각했어.\n"
.stringn "와 줘서 기뻐.\n"
.stringn "\x0701다행이다.\n"
.stringn "\x0713헤헤\n"
.stringn "\x0701………\n"
.stringn "\x0713………\n"
.stringn "\x0701…………\n"
.stringn "\x0713……대단했지.\n"
.stringn "\x0701…?\n"
.stringn "\x0713셀리노스의 숲.\n"
.stringn "뤼시온씨와 리아네씨의 노랫소리가…\n"
.stringn "눈부신 빛으로 바뀌어서……\n"
.stringn "숲이… 숲이 살아났잖아.\n"
.stringn "\x0701……그…랬지.\n"
.stringn "…………\n"
.stringn "\x0713질?\n"
.stringn "…왜 우는 거야?\n"
.stringn "\x0701그걸 보고… 깨달았어……\n"
.stringn "라구즈는… 악한 존재가 아니야.\n"
.stringn "틀린 건… 나였어……\n"
.stringn "……내가 믿어 온… 것들은……\n"
.stringn "\x0713………질……\n"
.stringn "그걸… 알았으니까,\n"
.stringn "질은 여기에 남아 준 거잖아.\n"
.stringn "아빠가 있는 데인군으로 돌아가지 않고…\n"
.stringn "\x0701알아 버렸다면…\n"
.stringn "돌아갈 수 있을 리가… 없어……\n"
.stringn "아버님은… 내게 실망하셨겠지……\n"
.stringn "쓸모없는… 배신자라면서……\n"
.stringn "\x0713그렇지 않아!\n"
.stringn "\x0701!?\n"
.stringn "\x0713아빠는 절대…\n"
.stringn "자기 아이에 대해서……\n"
.stringn "그런 식으로 말하지 않아!\n"
.stringn "아무리 실패해도…\n"
.stringn "마지막에는 웃으면서\n"
.stringn "어쩔 수 없는 애라면서… 용서해 줘.\n"
.stringn "하물며… 아이가\n"
.stringn "자신이 믿는 길을 선택했다면\n"
.stringn "틀림없이 기뻐하셨을 거야.\n"
.stringn "그야, 아빠는…\n"
.stringn "아빠는………\n"
.stringn "\x0701미스트…!\n"
.stringn "알았어… 이제 알았으니까…\n"
.stringn "\x0713아빠…\n"
.stringn "아…빠……\n"
.stringn "………………\n"
.stringn "\x0701……………………\n"
.stringn "……미스트…\n"
.stringn "울지 마…………\n"
.stringn "………미스트…?\n"
.stringn "\x0713……응… 미…안…\n"
.stringn "\x0701……미스트.\n"
.stringn "나는… 미스트 옆에 있으면……\n"
.stringn "…마음이 좀 가벼워져.\n"
.stringn "\x0713질…\n"
.stringn "\x0701사는 건 힘들지만…\n"
.stringn "그래도, 계속 살고 싶다고\n"
.stringn "생각할 수 있어. 고마워.\n"
.stringn "\x0713질… …\n"
.stringn "\x0701울지 말라니까…\n"
.stringn "정말… 어쩔 수 없네……"
db 0
