//MYELL_8_JILL_MIST_A_b

//0x1AD44
Text_1AD24:
.stringn "\x05FL|MIST|JILL||\x0C01\x0C13\x0701질, 그거…\n"
.stringn "맛없어?\n"
.stringn "\x0713…그렇진 않은데.\n"
.stringn "왜?\n"
.stringn "\x0701다행이다.\n"
.stringn "그거, 내가 만든 거야.\n"
.stringn "\x0713미스트가?\n"
.stringn "\x0701응. 그건 말이지,\n"
.stringn "사실 아플 때 먹는\n"
.stringn "영양분이 가득한 수프거든.\n"
.stringn "질이 기운도 없고 밥도 잘 안 먹으니까…\n"
.stringn "이거라면 괜찮을까 해서.\n"
.stringn "\x0713…나는 미스트가 신경 쓰게 해 버렸구나.\n"
.stringn "왜 그렇게\n"
.stringn "나한테 잘해 주는 거야…?\n"
.stringn "나는 데인의…\n"
.stringn "\x0701이제, 그만하자… 그런 거.\n"
.stringn "\x0713뭐…?\n"
.stringn "\x0701데인병이니까\n"
.stringn "함께 있으면\n"
.stringn "안 되는 게 당연하다니… 그런 건 싫어.\n"
.stringn "내 눈앞에 있는 질은\n"
.stringn "전혀 나쁜 애도 아니고.\n"
.stringn "난… 너랑 친해지고 싶은걸?\n"
.stringn "\x0713미스트…"
db 0
.align 4
//MYELL_8_JILL_MIST_B

//0x1ABC8
Text_1ABA8:
.stringn "\x05FL|JILL|MIST||\x0C01\x071-\x0713아, 있다.\n"
.stringn "\x0701……미스트, 또 온 거야?\n"
.stringn "\x0713응. 그야 질이\n"
.stringn "또 밥 먹으러 안 왔으니까.\n"
.stringn "\x0701데인 사람이 모두와 같은 장소에\n"
.stringn "있을 수는 없잖아.\n"
.stringn "모처럼의 식사가 맛없어질 거야.\n"
.stringn "\x0713오빠는 상관없다고\n"
.stringn "말했었는데?\n"
.stringn "\x0701……\n"
.stringn "\x0713나도 또래\n"
.stringn "여자애가 있으면 기쁘기도 하고.\n"
.stringn "\x0701……\n"
.stringn "미안.\n"
.stringn "\x0713그래. 그럼 어쩔 수 없지.\n"
.stringn "\x0701………"
db 0
.align 4
//MYELL_8_JILL_MIST_C

//0x1C2E4
Text_1C2C4:
.stringn "\x05FL|KILROY|KEVIN||\x0703케빈씨.\n"
.stringn "……또 훈련 중이세요?\n"
.stringn "\x071-\x0711오오, 킬로이!\n"
.stringn "저번에는 고마웠다.\n"
.stringn "내 도끼가 머리에 수직으로 떨어졌을 때는\n"
.stringn "정말 어떻게 되는 줄 알았다.\n"
.stringn "\x0703그렇다면 좀 더……\n"
.stringn "자신의 안전을 생각하는 건\n"
.stringn "어떨까요……?\n"
.stringn "\x0711안전? 핫핫하!\n"
.stringn "난 그런 겁쟁이가 아니다!\n"
.stringn "기사에게 두려움 따위는 없다! 절대로!\n"
.stringn "\x0703그, 그치만……\n"
.stringn "하지만 만에 하나라는 게 있으니까,\n"
.stringn "케빈씨의 명예에 흠집이 날 수도 있는걸요?\n"
.stringn "\x0711내 명예에?\n"
.stringn "\x0703예를 들면……\n"
.stringn "『기사 케빈, 훈련 도중 어째서인지 대출혈.\n"
.stringn "수수께끼의 죽음을 맞이하다』……\n"
.stringn "후세에 그렇게 기록될지도 몰라요.\n"
.stringn "그래도 괜찮으신가요?\n"
.stringn "\x0711큭!\n"
.stringn "화, 확실히 그건\n"
.stringn "싫군……\n"
.stringn "\x0703그럼 약속해 주세요.\n"
.stringn "이제 위험한 훈련은 하지 않기로.\n"
.stringn "\x0711큭! 어쩔 수 없는 건가!?\n"
.stringn "전장에 나가기도 전에 혼자서 멋대로 죽다니,\n"
.stringn "후세에도 치욕으로 남을 텐데.\n"
.stringn "하, 하지만……\n"
.stringn "\x0703…………\n"
.stringn "케, 케빈씨, 당신을 잃으면\n"
.stringn "저희가 곤란해져요!\n"
.stringn "으~음…… 그렇지, 우리 군에서\n"
.stringn "가장 든든한 케빈씨를 잃게 된다면\n"
.stringn "승리란 있을 수 없겠죠……\n"
.stringn "\x0711……그런가… 그렇군!\n"
.stringn "그 말대로다!\n"
.stringn "우리 군 최고의 전력인 내가\n"
.stringn "무모한 짓을 할 수는 없지!\n"
.stringn "알았다.\n"
.stringn "아직 부족하지만 자중하도록 하지!\n"
.stringn "\x0703휴우…… 알아 주셔서\n"
.stringn "다행이에요……\n"
.stringn "앞으로도 가끔씩 보러 올 테니까\n"
.stringn "아무쪼록 무리한 짓은 하지 말아 주세요?\n"
.stringn "\x0711그래, 알겠다!"
db 0
.align 4
//MYELL_8_KEVIN_KILROY_A

//0x1BF8C
Text_1BF6C:
.stringn "\x05FL|KILROY|KEVIN||\x070-\x0701케빈씨,\n"
.stringn "여기 계셨군요.\n"
.stringn "\x071-\x0713오오, 킬로이 아닌가!\n"
.stringn "무슨 일이지?\n"
.stringn "\x0701케빈씨가 훈련하는 모습을\n"
.stringn "구경해도 될까요?\n"
.stringn "또 지난번과 같은 사고가\n"
.stringn "일어날 수 있으니, 지팡이를 사용할 줄 아는\n"
.stringn "사람이 옆에 있는 편이 좋을 것 같아서요.\n"
.stringn "\x0713하하하, 킬로이는 걱정이 많군.\n"
.stringn "하지만 다른 이에게 보여 주는 것은 좋지!\n"
.stringn "평소보다 한층 더 훈련에\n"
.stringn "열중할 수 있겠어!\n"
.stringn "흡! 하앗!\n"
.stringn "\x0701저기, 부디\n"
.stringn "저는 신경 쓰지 마시고……\n"
.stringn "\x0713좋아, 기술을 하나 보여 주마.\n"
.stringn "……봐라! 내 도끼 실력을!\n"
.stringn "너희 용병단원들은\n"
.stringn "도저히 따라할 수 없겠지!!\n"
.stringn "\x0701아뇨, 저기,\n"
.stringn "저는 다치지 않게 하려고\n"
.stringn "보고 있는 것뿐이니까……\n"
.stringn "너무 지나치게 힘을 쓰지 않는 편이……\n"
.stringn "\x0713보아라, 이것이야말로\n"
.stringn "크리미아 기사 케빈의 오의.\n"
.stringn "그 이름하여――\n"
.stringn "……크옷! 방심했다!\n"
.stringn "\x0701잠깐…… 케빈씨!?\n"
.stringn "……아아…… 역효과였나 보네……\n"
.stringn "케빈씨, 가만히 계세요.\n"
.stringn "지금 치료할 테니까……\n"
.stringn "\x0718미안하다……"
db 0
.align 4
//MYELL_8_KEVIN_KILROY_B

//0x1BB8C
Text_1BB6C:
.stringn "\x05FL|KEVIN|KILROY||\x070-\x0701여어, 킬로이!\n"
.stringn "\x071-\x0713앗, 케빈씨……\n"
.stringn "!?\n"
.stringn "무, 무슨 일이 있었던 거예요?\n"
.stringn "\x0701무슨 말이지?\n"
.stringn "\x0713피, 피가……\n"
.stringn "머리 쪽에서 피가 흐르고 있다고요!?\n"
.stringn "\x0701음?\n"
.stringn "아아 그렇군! 깜빡하고 있었다.\n"
.stringn "\x0713까, 깜빡했다고요……?\n"
.stringn "어, 어쨌든\n"
.stringn "그 자리에서 움직이지 마세요.\n"
.stringn "지금 라이브 지팡이를 사용할 테니까……\n"
.stringn "\x0701괜찮다,\n"
.stringn "이 정도는 놔두면 나으니까!\n"
.stringn "\x0713나, 나을 리가 없잖아요!\n"
.stringn "가만히 있어 주세요……\n"
.stringn "…………휴우……\n"
.stringn "이걸로 일단 괜찮으려나.\n"
.stringn "그나저나…… 어쩌다가 다치신 거예요?\n"
.stringn "\x0701뭐, 별건 아니고\n"
.stringn "훈련에 너무 열중했을 뿐이다.\n"
.stringn "\x0713훈련? 누구랑\n"
.stringn "겨루시기라도 한 건가요?\n"
.stringn "\x0701아니, 그냥 무기를 휘두르고 있었다.\n"
.stringn "\x0713대, 대체 뭘 어떻게\n"
.stringn "휘둘렀길래 피가……?\n"
.stringn "\x0701나는 크리미아 기사니까 말이다!\n"
.stringn "꽤 자주 있는 일이지,\n"
.stringn "신경 쓸 필요는 없다!\n"
.stringn "\x0C13\x0C01……응? 왜 그러지 킬로이?\n"
.stringn "\x0713죄, 죄송해요……\n"
.stringn "조금 현기증이……\n"
.stringn "어, 언제나 그렇게\n"
.stringn "혹독한 훈련을 하고 계신 건가요?\n"
.stringn "\x0701물론이다.\n"
.stringn "나는 크리미아 기사니까 말이지!\n"
.stringn "비록 훈련이더라도\n"
.stringn "하려면 제대로 해야 하는 법!\n"
.stringn "언제 어떤 장소든지 간에\n"
.stringn "전력을 다해 단련할 뿐이다!\n"
.stringn "\x0713그 마음가짐은\n"
.stringn "대단히 훌륭하다고 생각하지만……\n"
.stringn "……불안한데……"
db 0
.align 4
//MYELL_8_KEVIN_KILROY_C

//0x1D024
Text_1D004:
.stringn "\x05FL|MARCIA|KEVIN||\x070-\x0701케빈씨!\n"
.stringn "\x071-\x0713음, 마샤 공인가!\n"
.stringn "\x0701케빈씨의 말,\n"
.stringn "건강해진 것 같네요.\n"
.stringn "다행이다.\n"
.stringn "\x0713그래, 마샤 공 덕분이다.\n"
.stringn "다시 한번 예를……\n"
.stringn "\x0701그 얘기는 이제 됐다고 했잖아요.\n"
.stringn "그것보다, 지금\n"
.stringn "어디 외출하시려고요?\n"
.stringn "\x0713아니, 오랜만에\n"
.stringn "말의 몸을 씻겨 주려고 한다.\n"
.stringn "항상 고생을 하고 있으니\n"
.stringn "전쟁 중간에\n"
.stringn "가능한 만큼 보살펴 주고 싶군.\n"
.stringn "\x0701……멋지네요.\n"
.stringn "\x0713뭐가 말이냐?\n"
.stringn "\x0701저번에도 생각했지만,\n"
.stringn "케빈씨, 말을 무척이나\n"
.stringn "신경 써 주시잖아요……\n"
.stringn "\x0713물론이다! 내게 있어서는\n"
.stringn "소중한 전우니까.\n"
.stringn "기사 동료들 중에는 『그래 봤자 탈것』이라는\n"
.stringn "녀석들도 있지만, 내 생각은 다르다.\n"
.stringn "말뿐만이 아니다,\n"
.stringn "갑옷도 도끼도, 함께 싸우는 것들 전부\n"
.stringn "내게 있어서는 소중한 전우다!\n"
.stringn "\x0701훌륭하시네요.\n"
.stringn "\x0713훌륭하다고?\n"
.stringn "당연한 이야기를 한 것뿐이다.\n"
.stringn "\x0701당연하지 않은걸요.\n"
.stringn "다른 건 자주 잊어버리거나\n"
.stringn "깜빡하고 그러시면서……\n"
.stringn "우후후\n"
.stringn "\x0713그런가?\n"
.stringn "조금 납득이 안 간다만…\n"
.stringn "\x0701후후"
db 0
.align 4
//MYELL_8_KEVIN_MARCIA_A

//0x1CBCC
Text_1CBAC:
.stringn "\x05FL|KEVIN|MARCIA||\x0701마샤 공!\n"
.stringn "\x071-\x0713아, 케빈씨.\n"
.stringn "…말의 상태는 좋아졌나요?\n"
.stringn "\x0701그래, 상당히 괜찮아졌다!\n"
.stringn "마샤 공 덕분이야.\n"
.stringn "처음에 상태가 이상할 때는\n"
.stringn "어쩌나 했는데……\n"
.stringn "마샤 공의 응급 처치 덕분에 산 것 같군!\n"
.stringn "\x0713행군하면서 피로가 쌓였었나 봐요.\n"
.stringn "그만큼 오랫동안 이동하면서 싸웠으니까\n"
.stringn "어쩔 수 없죠.\n"
.stringn "토지의 변화에 적응할 때까지\n"
.stringn "잠시 쉬게 하면 다시 건강해질 거예요.\n"
.stringn "\x0701나는 크리미아 국내에서만\n"
.stringn "싸웠기 때문에\n"
.stringn "그런 지식은 없었다.\n"
.stringn "정말로, 마음 깊이 감사를 표하지!\n"
.stringn "\x0713에이, 됐어요!\n"
.stringn "저도 용병이 되고 나서\n"
.stringn "여기저기 다니다 보니까\n"
.stringn "우연히 알게 된 것뿐이니까요.\n"
.stringn "\x0701이 은혜는, 무슨 일이 있더라도…\n"
.stringn "\x0713그러니까 괜찮다니까요.\n"
.stringn "앞으로의 전투에서\n"
.stringn "케빈씨는 알고 계시지만\n"
.stringn "저는 모르는 것들이 많을 거라 생각해요.\n"
.stringn "그때 힘이 되어 주신다면\n"
.stringn "그걸로 충분합니다.\n"
.stringn "\x0701알았다!\n"
.stringn "그때는, 내 목숨과 맞바꿔서…\n"
.stringn "\x0713죽을 것까지는 없다구요!\n"
.stringn "……그러고 보니 케빈씨,\n"
.stringn "전에 저한테 무슨 볼일이\n"
.stringn "있던 게 아니었나요?\n"
.stringn "\x0701그건…… 애마의 상태 건도 있고 하니\n"
.stringn "완전히 잊어버리고 말았군……\n"
.stringn "언젠가 꼭 떠올리겠다고 이 도끼에 맹세를…\n"
.stringn "\x0713맹세하지 않아도 된다고요~!\n"
.stringn "정말, 왜\n"
.stringn "그렇게 되는 거냐구요~"
db 0
.align 4
//MYELL_8_KEVIN_MARCIA_B

//0x1C7A0
Text_1C780:
.stringn "\x05FL|KEVIN|MARCIA||\x0703으음, 능력 향상을 위해\n"
.stringn "한번 천마 기사와\n"
.stringn "겨뤄 보고 싶은데……\n"
.stringn "오, 있다 있다, 마샤 공!\n"
.stringn "\x0711네?\n"
.stringn "\x0703크흠, 어, 한번 귀공과…\n"
.stringn "이런, 그 전에 이름을 대야지.\n"
.stringn "내 이름은……\n"
.stringn "\x0711알고 있습니다.\n"
.stringn "크리미아 왕국 왕궁 기사,\n"
.stringn "5번 소대 대장 케빈씨 맞죠?\n"
.stringn "\x0703엇!? 어떻게 내 이름을?\n"
.stringn "게다가 소속까지…\n"
.stringn "설마, 내가 지난번 전투에서\n"
.stringn "자신도 모르게 공을 세웠던 것인가?\n"
.stringn "…하지만, 짚이는 구석이 없는데.\n"
.stringn "\x0711……저기~\n"
.stringn "\x0703혹시, 그럴 리 없지만\n"
.stringn "이 내가 엄청난 실수를 했다든가?\n"
.stringn "아냐, 그런 기억도 없어.\n"
.stringn "\x0711저기~……\n"
.stringn "\x0703그것도 아니라면, 나의 무용이\n"
.stringn "타국에까지 울려 퍼진 것인가?\n"
.stringn "…아니아니, 아무리 그래도 그건.\n"
.stringn "허나, 있을 수 없는 이야기는 아니군.\n"
.stringn "다른 가능성으로는…\n"
.stringn "\x0711저기요~!!\n"
.stringn "\x0703뭐, 뭐냐.\n"
.stringn "갑자기 놀래키다니!\n"
.stringn "\x0711케빈씨 이름이라면 다 알죠.\n"
.stringn "그야 싸우기 전에,\n"
.stringn "항상 이렇게 이름을 대잖아요.\n"
.stringn "『나는 크리미아 왕국 왕궁 기사,\n"
.stringn "5번 소대 대장 케빈이다』라고.\n"
.stringn "\x0703과연, 그런 것이었군!\n"
.stringn "\x0711그래서, 용건이 뭔가요?\n"
.stringn "\x0703어?\n"
.stringn "\x0711제게 볼일이\n"
.stringn "있는 게 아니셨나요?\n"
.stringn "\x0703아, 그랬지.\n"
.stringn "그러니까… 응? 뭐였더라?\n"
.stringn "\x0711……생각나면 말씀해 주세요."
db 0
.align 4
//MYELL_8_KEVIN_MARCIA_C

//0x1DA94
Text_1DA74:
.stringn "\x05FL|KEVIN|OSCAR||\x0701오스카!!\n"
.stringn "\x071-\x0713안녕, 또 기사단으로 돌아오라는 얘기야?\n"
.stringn "\x0701그 말대로다!\n"
.stringn "나는 크리미아 기사지.\n"
.stringn "그리고 난 그걸 자랑스럽게 생각한다!\n"
.stringn "전장에서 화려하게 공을 세워\n"
.stringn "사람들의 찬사를 받아 승리해 나가고\n"
.stringn "주군께서는 칭송을 내리신다.\n"
.stringn "기사로서 이름을 날린다면\n"
.stringn "온 세상에 널리 퍼지게 되고\n"
.stringn "나아가 영지를 하사받을 수도 있다.\n"
.stringn "무엇보다 사랑하는 크리미아와 그 백성들을\n"
.stringn "이 손으로 지킬 수 있는 것이다!!\n"
.stringn "\x0713그렇지.\n"
.stringn "\x0701무법자들의 무리에 섞여\n"
.stringn "한 치 앞도 모르는 싸움에 뛰어드는\n"
.stringn "용병 따위보다 훨씬 나을 거다.\n"
.stringn "그런데 어째서지?\n"
.stringn "난 도저히 이해할 수가 없다!\n"
.stringn "\x0713…………\n"
.stringn "\x0701네놈의 실력은\n"
.stringn "내가 제일 잘 알고 있다.\n"
.stringn "어찌 됐든 내 영원한 호적수니까.\n"
.stringn "네놈에게 돌아올 의지가 있다면\n"
.stringn "기사단으로 복귀할 수 있도록\n"
.stringn "내가 전력을 다해 추진하도록 하지!\n"
.stringn "\x0713고마워.\n"
.stringn "하지만 돌아갈 마음은 전혀 없어.\n"
.stringn "……용병단에 들어가\n"
.stringn "여러 일들을 하면서……\n"
.stringn "나는 백성들이 겪는 슬픔을 알게 됐어.\n"
.stringn "아무도 모르게 죽어 가는 사람들이 있고\n"
.stringn "나라조차 구할 수 없는 사람들이 있어.\n"
.stringn "그렇다면 그들을 구할 수 있는 건\n"
.stringn "우리 같은 민간인이라고 생각해.\n"
.stringn "그리고 나는 명예 같은 건 필요 없어.\n"
.stringn "용병단이라는 내 가족을 지킬 수만 있다면\n"
.stringn "그걸로 충분해.\n"
.stringn "\x0701제……젠자앙!\n"
.stringn "네놈, 뭔지 모르겠지만 눈부시다!\n"
.stringn "어째서냐…… 또다시\n"
.stringn "네놈에게 진 기분이다……!\n"
.stringn "\x0713그렇지 않아.\n"
.stringn "너 같은 기사가 아니라면\n"
.stringn "못하는 일도 많은걸.\n"
.stringn "그러니까 서로 힘내자.\n"
.stringn "입장은 다르지만,\n"
.stringn "목표로 하는 이상은 같으니까.\n"
.stringn "\x0701…………그런가.\n"
.stringn "그렇다면 아무 말 않겠다!!\n"
.stringn "크리미아 부흥이 이루어진 새벽,\n"
.stringn "나는 반드시 대륙 전체에\n"
.stringn "울려퍼질 만한 활약을 하고야 말 것이다!\n"
.stringn "네놈이 어디에 있든,\n"
.stringn "내 활약이 전해지도록 말이다!\n"
.stringn "\x0713그래, 너라면 반드시 할 수 있어.\n"
.stringn "이 대륙 어딘가에서\n"
.stringn "무운을 빌고 있을게."
db 0
.align 4
//MYELL_8_KEVIN_OSCAR_A

//0x1D6A4
Text_1D684:
.stringn "\x05FL|KEVIN|OSCAR||\x0701오스카!!\n"
.stringn "\x071-\x0713안녕, 여전히 기운이 넘치는구나.\n"
.stringn "\x0701크리미아 기사단으로 돌아와라!\n"
.stringn "\x0713그리고 여전히 뜬금없네.\n"
.stringn "\x0701전 크리미아 기사로서\n"
.stringn "주군을 향한 충성심을 가지란 말이다!\n"
.stringn "지금은 조국의 위기!\n"
.stringn "크리미아 기사였던 자라면\n"
.stringn "곧바로 이 위기에 나서야 할 때가 아닌가!\n"
.stringn "\x0713그렇지.\n"
.stringn "지금은 용병이지만\n"
.stringn "조국 부흥에 도움이 되어서 기뻐.\n"
.stringn "\x0701기뻐, 좋아하시네!\n"
.stringn "난 네놈에게 다시 기사가 되라고 말하는 거다!\n"
.stringn "용병으로서는 조국에 대한\n"
.stringn "충성심을 다할 수 없지!\n"
.stringn "그래도 괜찮은 거냐!\n"
.stringn "\x0713그래, 괜찮아.\n"
.stringn "나는 그레일 용병단의 단원으로서\n"
.stringn "언제까지나 아이크와 모두랑\n"
.stringn "함께 지내고 싶어.\n"
.stringn "\x0701큭…… 어째서냐!\n"
.stringn "무엇이 네놈을 그렇게까지 끌어당기지…\n"
.stringn "위대한 조국 크리미아를 향한\n"
.stringn "충성과도 맞바꿀\n"
.stringn "용병단이라니 대체……!?\n"
.stringn "하! 그렇다면 높은 급료인가!?\n"
.stringn "그렇겠지! 네놈은 가족을 위해서\n"
.stringn "돈이 필요하다고 했으니까!\n"
.stringn "\x0713돈이 문제였다면 그대로\n"
.stringn "크리미아 기사단에 남았겠지.\n"
.stringn "지금 받는 보수는 그때의 절반도 안 되고.\n"
.stringn "\x0701뭐라고!?\n"
.stringn "정신 차려라!\n"
.stringn "네놈은 속고 있는 거다!!\n"
.stringn "\x0713아냐 아냐.\n"
.stringn "\x0701에에잇…!\n"
.stringn "정말이지 완고한 녀석이군!\n"
.stringn "\x0713……네가 말이지."
db 0
.align 4
//MYELL_8_KEVIN_OSCAR_B

//0x1D3B8
Text_1D398:
.stringn "\x05FL|OSCAR|KEVIN||\x070-\x0701안녕 케빈.\n"
.stringn "요즘 잘 지내?\n"
.stringn "\x0713오스카 네놈!\n"
.stringn "뻔뻔하게 인사하지 마랏!\n"
.stringn "\x0701…오늘은 내 어떤 점에\n"
.stringn "화난 거야?\n"
.stringn "\x0713잊을 리가 없지. 입대 2년 차 때,\n"
.stringn "우리는 승마로 경주를 했다!\n"
.stringn "나와 애마는 훌륭히 달렸지만,\n"
.stringn "근소한 차이로\n"
.stringn "네놈에게 패배했지…… 큭!\n"
.stringn "\x0701음… 아, 그때.\n"
.stringn "내 기억으로는\n"
.stringn "근소한 차이가 아니라 한\n"
.stringn "3마신 정도는 떨어져 있었던 것 같은데.\n"
.stringn "\x0713그 순간부터\n"
.stringn "네놈과 나는 영원한 호적수로\n"
.stringn "정해진 것을 몰랐나!?\n"
.stringn "\x0701……모르고 있었어.\n"
.stringn "\x0713그랬던 네놈이 대체 왜!\n"
.stringn "이 내게 한 마디도 없이!\n"
.stringn "기사단을 그만둔 거냐!?\n"
.stringn "난 설욕을 위해\n"
.stringn "애마와 함께 훈련에 몰두했다…\n"
.stringn "……너무 몰두한 탓에,\n"
.stringn "네놈이 없어진 걸 깨달았을 때는\n"
.stringn "이미 반년이 지나 있었지!\n"
.stringn "\x0701잠깐 케빈…\n"
.stringn "그거… 내 탓이야?"
db 0
.align 4
//MYELL_8_KEVIN_OSCAR_C

//0x1E944
Text_1E924:
.stringn "\x05FL|LOFA|KILROY||\x0701킬로이씨?\n"
.stringn "\x071-\x0713요파? 왜 그래?\n"
.stringn "\x0701아……\n"
.stringn "오늘은 아프지 않나 보네.\n"
.stringn "다행이다.\n"
.stringn "\x0713……미안해.\n"
.stringn "계속 요파에게 걱정만 끼치고…\n"
.stringn "이럴 바에는 내가 용병단을\n"
.stringn "나가는 편이 좋을지도 모르겠어…\n"
.stringn "\x0701!? 안 돼!\n"
.stringn "그런 뜻으로 말한 게 아니야!\n"
.stringn "\x0713응, 알고 있어.\n"
.stringn "그치만…… 내가 괴로워.\n"
.stringn "싸우는 것만으로도 힘들 텐데,\n"
.stringn "괜한 걱정까지 시키고……\n"
.stringn "아이크나 티아마트씨에게도 폐를 끼치고 있어.\n"
.stringn "그러니까… 모두와 헤어지고 싶지 않지만……\n"
.stringn "\x0701싫어!!\n"
.stringn "킬로이씨가 없어지다니\n"
.stringn "싫다고!\n"
.stringn "미안해, 나……\n"
.stringn "킬로이씨를 탓한 건 아니야……\n"
.stringn "그야 병에 걸린 건 킬로이씨의\n"
.stringn "잘못이 아니니까……\n"
.stringn "\x0713…………요파……\n"
.stringn "\x0701……나는 그냥 킬로이씨가 제대로\n"
.stringn "나를 의지해 주길 바랐을 뿐이었어.\n"
.stringn "\x0713뭐?\n"
.stringn "\x0701싸운다는 건…… 사람을, 쓰러뜨리는… 거잖아.\n"
.stringn "정말로 무섭고 떨리지만……\n"
.stringn "그래도 난 용병단의 모두가 죽지 않았으면 좋겠어.\n"
.stringn "전에는 아무것도 못하고 기도할 수밖에 없었지만…\n"
.stringn "지금은 싸워서 모두를 지킬 수 있어.\n"
.stringn "그러니까 다행이라고 생각했어.\n"
.stringn "이렇게 모두와 같이 싸울 수 있게\n"
.stringn "된 건 잘된 일이라고……\n"
.stringn "생각해서……\n"
.stringn "\x0713…………\n"
.stringn "\x0701그러니까 꼭 지키고 싶어.\n"
.stringn "킬로이씨를.\n"
.stringn "지키기 위해 싸운다고 생각하면\n"
.stringn "떨리지 않아.\n"
.stringn "나 노력할 테니까… 강해질 테니까……\n"
.stringn "그러니까 나간다고 하지 마……\n"
.stringn "\x0713요파…… 너…………\n"
.stringn "……………………\n"
.stringn "강해졌구나, 요파……\n"
.stringn "앞으로는 무슨 일이 있으면 제대로\n"
.stringn "말하도록 할게.\n"
.stringn "그리고 의지도 할 테니까……\n"
.stringn "…………고마워.\n"
.stringn "\x0701……응!"
db 0
.align 4
//MYELL_8_KILROY_LOFA_A

//0x1E570
Text_1E550:
.stringn "\x05FL|LOFA|KILROY||\x070-\x0703아, 킬로이씨!\n"
.stringn "\x071-\x0711……응?\n"
.stringn "요파, 무슨 일 있어?\n"
.stringn "\x0703아…… 오늘도 어디 아픈 거지?\n"
.stringn "\x0711아냐, 난 괜찮아.\n"
.stringn "왜 그래?\n"
.stringn "\x0703거짓말하면 안 돼!\n"
.stringn "난 알 수 있거든!\n"
.stringn "킬로이씨는 힘들 때\n"
.stringn "얼굴이 새파래지는걸!\n"
.stringn "……손, 이리 줘 봐!\n"
.stringn "\x0C02\x0711아……\n"
.stringn "\x0702봐봐, 완전 차갑네!\n"
.stringn "……힘들 때는 제대로 나한테 알려 달라고\n"
.stringn "말했었는데……\n"
.stringn "\x0711미안해, 요파.\n"
.stringn "그래도 제대로 전장에 설 수 있을 정도는\n"
.stringn "되니까, 괜찮아……\n"
.stringn "\x0C02\x0703괜찮긴 뭐가 괜찮아!\n"
.stringn "여긴 전장이야,\n"
.stringn "요새 안이 아니라고!\n"
.stringn "몸이 안 좋은데 자꾸 숨기면……\n"
.stringn "자꾸 그러면……\n"
.stringn "킬로이씨 언젠가 죽을지도 몰라…\n"
.stringn "\x0711……요파…………\n"
.stringn "미, 미안해……\n"
.stringn "\x0703……………………\n"
.stringn "\x0711……정말로 미안해, 요파.\n"
.stringn "요파가…… 나보다도 훨씬\n"
.stringn "잘 알고 있었구나……\n"
.stringn "\x0703…………지팡이로 병도……\n"
.stringn "고칠 수 있으면 좋을 텐데……\n"
.stringn "\x0711……그러게.\n"
.stringn "병이 나으면…… 이런 걱정은 하지 않아도\n"
.stringn "될 텐데 말이야…… ……\n"
.stringn "\x0C03\x0C11\x0C03\x0704아이크씨한테 부탁해 볼게.\n"
.stringn "나랑 킬로이씨가 전투에 나갈 때\n"
.stringn "같이 있을 수 있게 해 달라고.\n"
.stringn "\x0711고마워, 요파……"
db 0
.align 4
//MYELL_8_KILROY_LOFA_B

//0x1E08C
Text_1E06C:
.stringn "\x05FL|LOFA|KILROY||\x070-\x0701킬로이씨!\n"
.stringn "\x071-\x0713안녕 요파.\n"
.stringn "그렇게 급하게 달려오고… 무슨 일 있어?\n"
.stringn "\x0701아니, 킬로이씨가 보이길래\n"
.stringn "그냥 달려 온 것뿐이야.\n"
.stringn "있지, 몸은 괜찮아?\n"
.stringn "\x0713고마워. 오늘은 괜찮아.\n"
.stringn "아침에도 가볍게 운동을 했고,\n"
.stringn "식사도 모두랑 같이 잘 먹었어.\n"
.stringn "\x0701그래? 다행이다!\n"
.stringn "힘들 때는 꼭 나한테 말해 줘!\n"
.stringn "킬로이씨, 모두하고 용병단 요새에\n"
.stringn "있었을 때에는 자주 몸이 아파서\n"
.stringn "누워 있었는데……\n"
.stringn "계속 싸우고 있잖아.\n"
.stringn "\x0713응…… 하지만 모두와 함께\n"
.stringn "있을 수 있어서 기뻐.\n"
.stringn "\x0701나도!\n"
.stringn "미스트랑 킬로이씨랑 나는\n"
.stringn "요새에서 기다리기만 했으니까.\n"
.stringn "혼자 남겨져서 외롭고\n"
.stringn "엄청 무서웠었어……\n"
.stringn "\x0713그랬지……\n"
.stringn "다음 임무는 위험하다고\n"
.stringn "우연히 작전실 앞을\n"
.stringn "지나가다가 들어 버렸을 때…\n"
.stringn "셋이서 열심히\n"
.stringn "무사하기를 빌었던 적도 있었고.\n"
.stringn "고작 2일 동안이었지만……\n"
.stringn "너무나도 길게 느껴졌었어……\n"
.stringn "\x0701그래서 싸우는 건 무서울 때도 있지만…\n"
.stringn "항상 모두의 곁에 있을 수 있게 된 건\n"
.stringn "다행일지도 모른다고 생각해.\n"
.stringn "\x0713…………조금 생각이 복잡하지만……\n"
.stringn "나도 잘됐다고 여기는 게 맞다고 봐.\n"
.stringn "나쁘다고 생각해 봤자 좋을 것도 없고.\n"
.stringn "긍정적으로 생각하도록 노력해야겠어.\n"
.stringn "\x0701그렇지!\n"
.stringn "긍정적으로 생각해야 돼.\n"
.stringn "그렇지 않으면, 나는……\n"
.stringn "\x0713……요파?\n"
.stringn "\x0701아무것도 아냐!\n"
.stringn "나, 미스트한테도 볼일이 있으니까……\n"
.stringn "나중에 봐, 킬로이씨!\n"
.stringn "\x0713………………"
db 0
.align 4
//MYELL_8_KILROY_LOFA_C

//0x1FA88
Text_1FA68:
.stringn "\x05FL|KILROY|TIAMAT||\x070-\x0701티아마트씨.\n"
.stringn "오늘도 잠깐이지만\n"
.stringn "훈련에 동참할 수 있을까요?\n"
.stringn "\x071-\x0713그래, 물론이야.\n"
.stringn "너 제법 체력이 붙지 않았어?\n"
.stringn "예전보다 안색도 좋은 것 같고.\n"
.stringn "\x0701네,\n"
.stringn "티아마트씨 덕분이에요.\n"
.stringn "\x0713후후…… 그렇다면 다행인걸.\n"
.stringn "……저기, 킬로이.\n"
.stringn "너는 아이크를 어떻게 생각해?\n"
.stringn "\x0701아이크 말인가요?\n"
.stringn "전투 능력 같은 건\n"
.stringn "잘 모르겠지만……\n"
.stringn "아이크는 그래 보여도\n"
.stringn "세심한 배려가 있는 사람이고,\n"
.stringn "무엇보다 흔들림 없는 의지와\n"
.stringn "이상을 현실로 이끌 만한 힘을 가지고 있죠.\n"
.stringn "그레일 용병단의 단장에\n"
.stringn "걸맞은 인물이라고 생각해요.\n"
.stringn "\x0713그래. 나도 그렇게 생각해.\n"
.stringn "그렇지만…… 아이크는 아직 젊어.\n"
.stringn "앞으로 겪게 될 일들이\n"
.stringn "그 애를 어느 쪽으로 이끌지……\n"
.stringn "조금 걱정돼.\n"
.stringn "\x0701어째선가요?\n"
.stringn "\x0713앞으로 용병단이 커지면서\n"
.stringn "여러 가지 유혹이 늘어날 거라고 생각해.\n"
.stringn "돈은 벌 수 있지만 어디의 누군가는\n"
.stringn "상처받고, 눈물을 흘리는……\n"
.stringn "그런 의뢰도 들어오겠지.\n"
.stringn "하지만, 단원들을 부양하고 용병단을 존속시키려면\n"
.stringn "돈이 되는 일을 선택해야 쉽게 살아갈 수 있어.\n"
.stringn "\x0701하지만\n"
.stringn "그레일 단장님은 달랐어요.\n"
.stringn "\x0713그래……\n"
.stringn "우리 그레일 용병단은\n"
.stringn "용병단답지 않기로 유명했지.\n"
.stringn "때로는 무상으로 일을 맡고……\n"
.stringn "사람들을 많이 구해 왔어.\n"
.stringn "\x0701아이크도 마찬가지예요.\n"
.stringn "분명 그레일 단장님과\n"
.stringn "같은 이상을 가지고 있을 거라고 생각해요.\n"
.stringn "\x0713……그렇지, 분명……\n"
.stringn "나 같은 사람이 말해 주지 않아도,\n"
.stringn "우리가 싸우는 이유를, 살아가는 의미를…\n"
.stringn "아이크라면 반드시 올바른 길로 이끌어 줄 거야.\n"
.stringn "우리는 그저 아이크를 믿고\n"
.stringn "함께 따라가 주면 돼……\n"
.stringn "\x0701……네."
db 0
.align 4
//MYELL_8_KILROY_TIAMAT_A

//0x1F478
Text_1F458:
.stringn "\x05FL|KILROY|TIAMAT||\x070-\x0701티아마트씨,\n"
.stringn "오늘도 훈련하세요?\n"
.stringn "\x071-\x0713그래, 몸을 움직이지 않으면\n"
.stringn "뭔가 심란해서.\n"
.stringn "\x0701잠깐 같이 해도\n"
.stringn "괜찮을까요?\n"
.stringn "\x0713어, 물론 상관없어.\n"
.stringn "근데 갑자기 왜?\n"
.stringn "\x0701적어도 제 몸만큼은 지킬 수 있도록\n"
.stringn "뭔가 할 수 있는 일이 없을까 해서요……\n"
.stringn "모두의 발목을\n"
.stringn "잡는 건 싫어서……\n"
.stringn "\x0713그래도 그건 어쩔 수 없잖아?\n"
.stringn "킬로이는 이곳에 들어올 때까지\n"
.stringn "싸움 같은 건 해본 적이 없었으니까.\n"
.stringn "그리고 지금은 용병단의 일원……\n"
.stringn "…………\n"
.stringn "\x0701티아마트씨?\n"
.stringn "\x0713……사실, 나를 구해 주지 않았던 편이\n"
.stringn "킬로이한테는 더 행복했을지도 몰라.\n"
.stringn "부모님과 평온한 삶을 보내는 게\n"
.stringn "킬로이한테는 더 맞는 일일텐데.\n"
.stringn "\x0701하지만 부모님께서 벌어 오시는 돈만으로는\n"
.stringn "먹고 살기 힘들었어요.\n"
.stringn "저처럼 몸이 약한 사람을\n"
.stringn "고용해 주는 일은\n"
.stringn "그 작은 마을엔 아무것도 없었거든요.\n"
.stringn "부모님께서도 몸이 약한 걸 걱정하셔서\n"
.stringn "제게 마을에 머무르라고 하셨지만……\n"
.stringn "티아마트씨 같은 사람이 있는 용병단이라면\n"
.stringn "안심이라고 바래다 주셨어요.\n"
.stringn "\x0713……그래도 분명 다른 곳에 더\n"
.stringn "안전한 일이 있을지도 모르는데……\n"
.stringn "\x0701티아마트씨.\n"
.stringn "저는 계속 동경하고 있었어요.\n"
.stringn "어렸을 때는 이불에 누워 있던 적이 많아서……\n"
.stringn "사이좋게 밖에서 노는 아이들의 목소리를\n"
.stringn "부러워하면서 듣고 있었죠.\n"
.stringn "그런 저를 귀여워해 주셨던 숙부님은\n"
.stringn "용병이셨는데…… 여러 곳의 다양한 이야기를\n"
.stringn "잔뜩 들려주셨어요.\n"
.stringn "그래서 저는 언젠가 반드시\n"
.stringn "용병이 되겠다고 생각했었답니다.\n"
.stringn "\x0713그랬던 거야? 의외인걸.\n"
.stringn "\x0701그렇죠.\n"
.stringn "그러니까, 지금 이렇게 싸워 나가고 있는 걸…\n"
.stringn "말하긴 좀 그렇지만, 꿈이 이루어진 것 같아서\n"
.stringn "기쁘다는 생각이 들 때도 있어요.\n"
.stringn "\x0713……그렇구나.\n"
.stringn "우리에게 네 존재는 정말로\n"
.stringn "크니까…… 그렇게 생각해 준다고 하니\n"
.stringn "기쁘네……"
db 0
.align 4
//MYELL_8_KILROY_TIAMAT_B

//0x1EEE4
Text_1EEC4:
.stringn "\x05FL|TIAMAT|KILROY||\x070-\x0701킬로이, 몸은 좀 괜찮아?\n"
.stringn "\x071-\x0713네.\n"
.stringn "오늘은 열도 없고\n"
.stringn "기분도 좋아요.\n"
.stringn "항상 신경 써 주셔서\n"
.stringn "감사합니다.\n"
.stringn "\x0701그러고 보니……\n"
.stringn "벌써 1년이 다 되어 가네.\n"
.stringn "너와 처음 만난 지……\n"
.stringn "\x0713그렇네요.\n"
.stringn "\x0701그렇다고는 해도,\n"
.stringn "나는 며칠 동안 의식이 없었으니까\n"
.stringn "잘 기억이 안 나지만.\n"
.stringn "내가 임무에서 중상을 입고……\n"
.stringn "그 당시에는 지팡이 사용자도 없어서,\n"
.stringn "그때 치료를 해 준 게\n"
.stringn "우연히 거기 있었던 너였지.\n"
.stringn "\x0713마침 약초를 캐러 나가는 중이어서\n"
.stringn "발견할 수 있었습니다만……그런 숲속에서는\n"
.stringn "정말로 위험했어요……\n"
.stringn "\x0701맞아. 상대는 오래 전부터\n"
.stringn "네가 살던 마을 근처에서\n"
.stringn "세력을 떨치던 산적단이었고,\n"
.stringn "생각보다 애먹었어.\n"
.stringn "놓친 한 명이 숲으로 도망쳤는데……\n"
.stringn "그걸 뒤쫓아갔던 게 패인이었지.\n"
.stringn "숲속에서는 말의 움직임이 자유롭지 못하니까…\n"
.stringn "시논이 달려와 주지 않았다면\n"
.stringn "어떻게 됐을지…\n"
.stringn "\x0713가트리씨도 시논씨도 저희 집으로\n"
.stringn "티아마트씨를 옮기는 동안 정말로\n"
.stringn "걱정하는 것 같았어요.\n"
.stringn "\x0701어머, 그랬었어? …후후\n"
.stringn "그래서… 내 상처가 나을 때까지\n"
.stringn "간병을 계속해 줬고……\n"
.stringn "그때 네가 도와주지 않았다면\n"
.stringn "나는 두 번 다시 도끼를\n"
.stringn "휘두르지 못했을 거야.\n"
.stringn "정말로 감사하고 있어.\n"
.stringn "\x0713아뇨, 저야말로 감사하죠.\n"
.stringn "지금 이렇게 용병단에\n"
.stringn "고용되어 있는 덕분에 고향에 계신 부모님께\n"
.stringn "생활비를 보내드릴 수 있으니까요.\n"
.stringn "두 분 다 다리가 안 좋으셔서 저밖에\n"
.stringn "변변한 일꾼이 없거든요.\n"
.stringn "\x0701그래…… 그때는 부모님께도\n"
.stringn "정말로 신세 많이 졌어.\n"
.stringn "그 은혜에 보답하기 위해서라도\n"
.stringn "넌 내가 꼭 지켜 줄게.\n"
.stringn "\x0713감사합니다, 티아마트씨."
db 0
.align 4
//MYELL_8_KILROY_TIAMAT_C

//0x20648
Text_20628:
.stringn "\x05FL|VULCI|KILROY||\x0C01\x071-\x0713우르키씨!\n"
.stringn "다음이 기대되네요!\n"
.stringn "아니 그, 싸우는 건 무섭고\n"
.stringn "피해야 한다고 생각하지만……\n"
.stringn "아 그래도, 네!\n"
.stringn "엄청 도움이 될 거라고 생각해요!\n"
.stringn "\x0701…………그렇다면 다행이군.\n"
.stringn "\x0713하지만 우르키씨의 등 뒤에서\n"
.stringn "떨어지지 않게 조심해야겠어요……\n"
.stringn "아, 한 번 더 연습해도\n"
.stringn "괜찮을까요?\n"
.stringn "\x0701……아니…………\n"
.stringn "다음 전투 전까지 이 이상\n"
.stringn "체력을 소모할 순 없다……\n"
.stringn "\x0713그, 그렇군요……\n"
.stringn "죄송합니다……\n"
.stringn "…………혹시……\n"
.stringn "화신하는 건\n"
.stringn "체력이 소모되나요……?\n"
.stringn "\x0701………………그래.\n"
.stringn "\x0713네!? 그랬어요!?\n"
.stringn "그런데도 며칠 동안 그것도 몇 번씩이나\n"
.stringn "연습시켜 주신 겁니까!?\n"
.stringn "\x0701………………괜찮다.\n"
.stringn "말 안하고 있던 내 잘못이니.\n"
.stringn "네가 그렇게 기뻐하니\n"
.stringn "그만…… 말하는 것도 잊었었군.\n"
.stringn "\x0713……지금……\n"
.stringn "안색이 안 좋아 보이는데요?\n"
.stringn "……………………\n"
.stringn "죄송합니다……\n"
.stringn "방금 이야기는 없었던 걸로 해요.……\n"
.stringn "\x0701……그러는 편이 좋겠군.\n"
.stringn "체력이 소모된 상태에서 전장에 나가는 건\n"
.stringn "위험할 테니.\n"
.stringn "\x0713………………네……\n"
.stringn "\x0701…………하지만……\n"
.stringn "또 시간이 된다면……\n"
.stringn "전장이 아닌 곳에서\n"
.stringn "다시 태워 주도록 하지……\n"
.stringn "\x0713!!\n"
.stringn "네, 네에!\n"
.stringn "감사합니다, 우르키씨!!"
db 0
.align 4
//MYELL_8_KILROY_VULCI_A

//0x2032C
Text_2030C:
.stringn "\x05FL|KILROY|VULCI||\x070-\x0701우르키씨!\n"
.stringn "\x0713……킬로이인가.\n"
.stringn "\x0701저기, 전에 우르키씨가 싸우는 모습을\n"
.stringn "봤습니다만……\n"
.stringn "공중에서 빙글 한 바퀴 돌았었죠?\n"
.stringn "\x0713그랬……던가?\n"
.stringn "\x0701그 뒤로도 몇 번이고 돌면서\n"
.stringn "재빠르게 오른쪽 왼쪽……\n"
.stringn "정말 대단해요!\n"
.stringn "\x0713……아니…………\n"
.stringn "\x0701아아…… 저도 그렇게\n"
.stringn "하늘을 날 수 있다면……\n"
.stringn "\x0713…………\n"
.stringn "\x0701날씨가 좋은 날에는 하늘로 올라가\n"
.stringn "높은 산 위에 내려서서……\n"
.stringn "아래에 보이는 마을이나 상가를 바라보겠죠……\n"
.stringn "아아…… 생각만 해도 즐거워……\n"
.stringn "\x0713……………………\n"
.stringn "네가…… 날 수 있다면……\n"
.stringn "다친 사람을… 더 빨리 치료할 수 있을지도…\n"
.stringn "\x0701아, 그것도 굉장하네요!\n"
.stringn "다친 사람이 아무리 멀리 있더라도\n"
.stringn "치료하러 갈 수 있고요!\n"
.stringn "할 수만 있다면 해 보고 싶네요, 그거!\n"
.stringn "\x0713……………………\n"
.stringn "…………………………\n"
.stringn "………해…… 보겠나?\n"
.stringn "\x0701네!?\n"
.stringn "어, 어떻게요!?\n"
.stringn "전 날개가 없는데……\n"
.stringn "\x0713……………………"
db 0
.align 4
//MYELL_8_KILROY_VULCI_B

//0x20004
Text_1FFE4:
.stringn "\x05FL|VULCI|KILROY||\x0C01\x0713아……안녕하세요.\n"
.stringn "\x0701……\n"
.stringn "\x0713저, 저기…… 죄, 죄송합니다.\n"
.stringn "화나게 할 생각은 없었어요.\n"
.stringn "저는 단지 당신과 이야기를……\n"
.stringn "\x0701아니. 화나지 않았다.\n"
.stringn "뭔가 볼일이 있나.\n"
.stringn "\x0713그, 그렇군요…… 다행이다.\n"
.stringn "저는 킬로이예요!\n"
.stringn "자, 잘 부탁드립니다!\n"
.stringn "\x0701……그래.\n"
.stringn "나는 우르키다. 잘 부탁하지.\n"
.stringn "\x0713저기, 으음…… 우르키씨는\n"
.stringn "그 날개로 하늘을 날잖아요.\n"
.stringn "매의 모습이 되었을 때도 봤는데……\n"
.stringn "부럽네요…… 대단합니다……\n"
.stringn "\x0701?\n"
.stringn "\x0713아, 죄송해요……\n"
.stringn "저는 어렸을 때부터 병약해서\n"
.stringn "침대에서 하루를 보낼 때가 많았거든요.\n"
.stringn "그래서…… 자주 창밖을 내다보며\n"
.stringn "하늘을 나는 작은 새들을 보고 있었습니다.\n"
.stringn "자유롭게 어디든 날아갈 수 있다는 것은…\n"
.stringn "참 근사한 일이네요……\n"
.stringn "\x0701……\n"
.stringn "근사하다……라.\n"
.stringn "그런 식으로\n"
.stringn "생각해 본 적은 없군.\n"
.stringn "\x0713그건 그렇겠죠.\n"
.stringn "태어날 때부터 날 수 있으니까요.\n"
.stringn "그치만…… 부럽네요……\n"
.stringn "\x0701…………"
db 0
.align 4
//MYELL_8_KILROY_VULCI_C

//0x211DC
Text_211BC:
.stringn "\x05FL|WAYU|KILROY||\x0701으~음……\n"
.stringn "정말 미안.\n"
.stringn "무리를 시켜 버린 것 같네……\n"
.stringn "\x071-\x0713아냐…… 나도 검사를\n"
.stringn "동경했던 적이 있으니까……\n"
.stringn "그래도 조금 즐거웠어.\n"
.stringn "\x0701그치만 요즘 계속\n"
.stringn "열 나잖아?\n"
.stringn "그런 몸으로 전장에 나가도 괜찮은 거야?\n"
.stringn "\x0713익숙하니까 괜찮아.\n"
.stringn "무리할 생각은 없고,\n"
.stringn "후위에 있는 게 기본이니까 문제없어.\n"
.stringn "그리고 와유도 곁에 있어 주는걸.\n"
.stringn "\x0701그야 나도 책임감을 느끼니까…\n"
.stringn "항상 『괜찮으려나~ 어떠려나~』 하면서\n"
.stringn "킬로이씨 생각만 나고.\n"
.stringn "최근 킬로이씨 생각밖에 안 한다고.\n"
.stringn "하아~……\n"
.stringn "이제부터 점 같은 건 안 믿을 거야.\n"
.stringn "\x0713아니…… 믿었다기보다는\n"
.stringn "도중에 의미가 완전히\n"
.stringn "바뀐 것 같은데……?\n"
.stringn "\x0701사소한 건 신경 쓰지 마!\n"
.stringn "……아니, 근데 잠깐.\n"
.stringn "백마를 타고 찾아오는\n"
.stringn "숙명의 라이벌……\n"
.stringn "………혹시 검사가 아니라\n"
.stringn "기병인가………\n"
.stringn "\x0713……응?\n"
.stringn "\x0701킬로이씨한테 딱 맞는 직업.\n"
.stringn "그렇구나, 그럴지도 몰라!\n"
.stringn "말에 타면 행군도 편하고\n"
.stringn "몸에도 좋잖아?\n"
.stringn "\x0713뭐어!? 마, 말!?\n"
.stringn "\x0701그래! 말 탄 기사 킬로이씨!\n"
.stringn "옷도 하얗고, 꽤 멋질 거 같지 않아!?\n"
.stringn "킬로이씨가 말 위에서 지팡이를 쓰고,\n"
.stringn "나는 그 옆에서 화려하게 싸우는 거지!\n"
.stringn "\x0713자, 잠깐 와유……\n"
.stringn "\x0701좋아, 그거였어!\n"
.stringn "다음엔 그걸로 가 보자!\n"
.stringn "\x0713잠깐 기다려 봐, 와유.\n"
.stringn "애초에 내가 아니라\n"
.stringn "다른 사람이 너의……\n"
.stringn "\x0701그건 싫어.\n"
.stringn "\x0713싫다고?\n"
.stringn "\x0701응. 이제 킬로이씨 말고는\n"
.stringn "생각할 수 없다구? 내 운명의 상대!\n"
.stringn "\x0713우, 운명……!? 숙명의 라이벌이 아니라……\n"
.stringn "\x0701사소한 건 신경 쓰지 마~!\n"
.stringn "그럼 앞으로도 잘 부탁해, 킬로이씨!"
db 0
.align 4
//MYELL_8_KILROY_WAYU_A

//0x20DD4
Text_20DB4:
.stringn "\x05FL|KILROY|WAYU||\x070-\x0C01\x0C13\x0701와유.\n"
.stringn "또 훈련 중이야?\n"
.stringn "\x0713어라, 킬로이씨?\n"
.stringn "또 『누군가 와 줘~』라고 생각했더니\n"
.stringn "처음으로 만나 버렸어……\n"
.stringn "\x0701아, 그 점 얘기구나.\n"
.stringn "미안, 까맣게 잊고 있었어.\n"
.stringn "방해할 생각은 없었는데……\n"
.stringn "\x0713아냐. 역시 점은\n"
.stringn "믿는 게 아닌가 봐~\n"
.stringn "완전 잘 들어맞는다고 소문난\n"
.stringn "점술가였는데……\n"
.stringn "…………아니, 설마……\n"
.stringn "\x0701?\n"
.stringn "\x0713킬로이씨, 나랑 승부하지 않을래?\n"
.stringn "\x0701뭐어!?\n"
.stringn "\x0713아~ 왜 몰랐을까?\n"
.stringn "킬로이씨는 검사나 전사에\n"
.stringn "소질이 있다구!\n"
.stringn "지금은 아직 눈치채지 못했을 뿐이고\n"
.stringn "킬로이씨에게는 굉장한 재능이 잠들어 있는 거야.\n"
.stringn "그러니까 검사로서 눈을 뜬 다음에\n"
.stringn "나랑 숙명의 대결이라든가\n"
.stringn "할 수 있을지도 몰라, 확실해!\n"
.stringn "\x0701그, 그건 말도 안 돼, 와유.\n"
.stringn "그야 나는 어렸을 때\n"
.stringn "몸이 약했으니까……\n"
.stringn "강한 용병이 되고 싶다고\n"
.stringn "생각한 적도 있었지만……\n"
.stringn "\x0713봐봐! 역시나!\n"
.stringn "몸이 약하다고 포기해 버리면\n"
.stringn "안 되지~ 아깝잖아!\n"
.stringn "자 자, 한번 속는 셈 치고\n"
.stringn "해 보자.\n"
.stringn "제대로 기본부터 가르쳐 줄 테니까!\n"
.stringn "\x0701그, 그럴까……?\n"
.stringn "\x0713사소한 건 신경 쓰지 말고!\n"
.stringn "자, 가 보자구~우!"
db 0
.align 4
//MYELL_8_KILROY_WAYU_B

//0x20A78
Text_20A58:
.stringn "\x05FL|WAYU|KILROY||\x070-\x0C01\x0C13\x0701아…… 킬로이씨!\n"
.stringn "자, 이거 받아!\n"
.stringn "\x0713이건…… 검?\n"
.stringn "\x0701그래! 근데 설마\n"
.stringn "킬로이씨였을 줄이야~\n"
.stringn "여튼 이렇게 됐으니까, 승부하자!\n"
.stringn "\x0713그, 그렇게 말해도\n"
.stringn "잘 모르겠는데……\n"
.stringn "그리고 나는 무기를 못 다뤄.\n"
.stringn "\x0701뭐어!?\n"
.stringn "그래도 조금 정도는\n"
.stringn "할 수 있지 않아?\n"
.stringn "\x0713아니, 지금까지 잡아 본 적도 없는데…\n"
.stringn "이걸 쥐고 서 있기만 해도 된다면\n"
.stringn "그렇게 해 줄게.\n"
.stringn "\x0701뭐야, 실망인걸.\n"
.stringn "전에 점술가가 점을 봐 줬는데,\n"
.stringn "난 이제 곧 운명의 상대를 만난다는\n"
.stringn "말을 들었어.\n"
.stringn "백마를 타고 찾아오는\n"
.stringn "내 숙명의 라이벌……\n"
.stringn "기대하고 있었는데.\n"
.stringn "\x0713그건 내가 잘못했네.\n"
.stringn "미안해.\n"
.stringn "\x0701아냐, 킬로이씨가\n"
.stringn "잘못한 건 없는걸.\n"
.stringn "그냥 잠깐 『누군가 와 줘~』라고\n"
.stringn "생각했더니 이곳에 누가 있길래\n"
.stringn "혹시나 했을 뿐이야.\n"
.stringn "\x0713그럼…… 쥐고 있을 뿐이지만\n"
.stringn "상대해 줄까?\n"
.stringn "\x0701괜찮아 괜찮아. 다칠 수도 있고.\n"
.stringn "오늘은 포기할까…… 아~아."
db 0
.align 4
//MYELL_8_KILROY_WAYU_C

//0x21DA0
Text_21D80:
.stringn "\x05FL|LARGO|MWARIM||\x070-\x0703오오, 무와림!\n"
.stringn "지난번에는 즐거웠어!\n"
.stringn "\x071-\x0711그래, 나도다.\n"
.stringn "\x0703모두의 짐을 얼마나 들 수 있나\n"
.stringn "힘겨루기를 하고 있는데,\n"
.stringn "다들 재밌다고 아무거나\n"
.stringn "쌓아 올리고 앉았었다니까.\n"
.stringn "\x0711그래. 물건뿐만 아니라\n"
.stringn "사람까지 위로\n"
.stringn "올라타길래 곤란했었지.\n"
.stringn "\x0703그래, 마지막까지\n"
.stringn "결국 엇비슷했어.\n"
.stringn "가장 마지막에 올린 게,\n"
.stringn "나는 큰 무쇠솥 하나,\n"
.stringn "네가 그 작은 여자아이……\n"
.stringn "이름이 뭐였더라.\n"
.stringn "\x0711미스트다.\n"
.stringn "\x0703그래, 그 아이.\n"
.stringn "그 아이랑 무쇠솥 중에\n"
.stringn "어느 쪽이 더 무거웠는지 알았다면\n"
.stringn "결판이 났을 텐데.\n"
.stringn "\x0711……너는 굉장하군.\n"
.stringn "\x0703음? 뭐가?\n"
.stringn "너도 굉장했잖아.\n"
.stringn "\x0711그런 뜻이 아니다.\n"
.stringn "긴장되는 행군 분위기를\n"
.stringn "역으로 순식간에\n"
.stringn "바꿔 버렸지.\n"
.stringn "숨통이 트였다, 재밌었다며\n"
.stringn "모두가 고마워했다.\n"
.stringn "\x0703뭐, 난 단순히 긴장하고 있는 게\n"
.stringn "싫었던 것뿐이야.\n"
.stringn "딱딱하게 굳어 있으면 전력으로 못 싸우잖아?\n"
.stringn "\x0711게다가, 너는 나를 대하든\n"
.stringn "누구를 대하든 태도가 변하지 않는다.\n"
.stringn "그게 굉장하다고 생각한다.\n"
.stringn "\x0703와하하하! 잘은 모르겠지만\n"
.stringn "그렇게 칭찬하지 마!\n"
.stringn "뭐어, 사소한 건 됐으니까.\n"
.stringn "승부는 무승부였지, 다음은……\n"
.stringn "그래, 팔씨름 같은 건 어때!\n"
.stringn "나 팔씨름에는 자신이 있다고!\n"
.stringn "\x0711…………그래, 좋다.\n"
.stringn "다음 기회를 기대하도록 하지."
db 0
.align 4
//MYELL_8_LARGO_MWARIM_A

//0x219EC
Text_219CC:
.stringn "\x05FL|LARGO|MWARIM||\x070-\x0C01\x0C13\x0701오오, 무와림이잖아.\n"
.stringn "상태는 어때?\n"
.stringn "\x0713……아, 라르고인가.\n"
.stringn "전에는…… 고마웠다.\n"
.stringn "\x0701와하하하하! 별거 아니야!\n"
.stringn "근데 넌 대단하구만.\n"
.stringn "여러 곳을 여행해 봤지만,\n"
.stringn "나 정도로 힘이 센 남자는\n"
.stringn "본 적이 없었는데.\n"
.stringn "아무리 나라도 네게는\n"
.stringn "질지도 모르겠어.\n"
.stringn "저기, 나하고 너,\n"
.stringn "누가 더 힘이 셀까?\n"
.stringn "\x0713……글쎄.\n"
.stringn "\x0701나는…… 그래.\n"
.stringn "제일 무거웠던 건 그거야.\n"
.stringn "옛날에 수명이 몇백 년 됐다던\n"
.stringn "직경이 내 키의 3배인 거목을\n"
.stringn "메고 날랐던 적이 있었지.\n"
.stringn "넌 어때?\n"
.stringn "\x0713……그렇군.\n"
.stringn "성벽을 복원하는 데 사용할 바위를\n"
.stringn "바위산에서 깎아\n"
.stringn "쌓아 올렸던 적이 있었다.\n"
.stringn "\x0701호오, 얼마나 큰 바위였는데?\n"
.stringn "\x0713내 키의 3배 정도였나.\n"
.stringn "\x0701오오, 역시 넌 대단해!\n"
.stringn "왠지 기쁜걸!\n"
.stringn "어때, 다음에 힘겨루기를 해 보지 않을래?\n"
.stringn "나하고 너라면\n"
.stringn "좋은 승부를 할 수 있을 것 같아!\n"
.stringn "\x0713아니, 나는……\n"
.stringn "\x0701쩨쩨하게 그러지 말고!\n"
.stringn "닳는 것도 아니잖아, 괜찮지?\n"
.stringn "\x0713………………후우……\n"
.stringn "어쩔 수 없군……\n"
.stringn "알았다. 한 번만이야."
db 0
.align 4
//MYELL_8_LARGO_MWARIM_B

//0x21790
Text_21770:
.stringn "\x05FL|LARGO|MWARIM||\x070-\x0703오?\n"
.stringn "너, 제법 몸이 좋잖아.\n"
.stringn "잠깐 팔 좀 보여 줘 봐.\n"
.stringn "\x0711……?\n"
.stringn "\x0703오오, 대단한데.\n"
.stringn "나도 팔뚝 굵기에는 자신이 있지만\n"
.stringn "너는 엄청나구만.\n"
.stringn "\x0711…………너도 엄청나다고 생각한다.\n"
.stringn "\x0703와하하하하! 난\n"
.stringn "이 괴력이 유일한 장점이니까!\n"
.stringn "그런데 그건 어디로 옮기는 거야?\n"
.stringn "\x0711아, 이것 말이지.\n"
.stringn "이 물독에 물을 떠 가는 중이다.\n"
.stringn "\x0703그런 큰 독에 물을?\n"
.stringn "그것참 힘들겠구만.\n"
.stringn "하나 둘 셋,\n"
.stringn "수도 제법 많네.\n"
.stringn "좋아, 나도 도와줄게.\n"
.stringn "\x0711아니, 그럴 필요는 없다.\n"
.stringn "\x0703오, 여유롭네 이거! 가볍구만!\n"
.stringn "난 팔 힘밖에\n"
.stringn "가진 게 없으니까! 자, 가자고!\n"
.stringn "\x0711………………"
db 0
.align 4
//MYELL_8_LARGO_MWARIM_C

//0x229EC
Text_229CC:
.stringn "\x05FL|LARGO|TAURONEO||\x070-\x0701으~음……\n"
.stringn "으~~음……\n"
.stringn "\x0713또 가게 일로\n"
.stringn "고민하고 있는 건가?\n"
.stringn "\x0701아, 당신이구만.\n"
.stringn "또 뭔가 좋은 지혜를 빌려줄 수 있을까?\n"
.stringn "\x0713그러지.\n"
.stringn "\x0701내 가게 이름을 생각 중이었어.\n"
.stringn "머리를 쥐어짜서 여러 가지를 생각해 봤지.\n"
.stringn "\x0713호오. 예를 들면?\n"
.stringn "\x0701『내 가게』라는 이름은 어때?\n"
.stringn "\x0713흠. 좀 단순하군.\n"
.stringn "\x0701그럼…… 좀 더 쥐어짜 볼까.\n"
.stringn "나는 베오크든 라구즈든 누구든\n"
.stringn "부담 없이 와서, 잔뜩 마시고 얘기하면서\n"
.stringn "행복해지는 술집이 되도록 하고 싶어.\n"
.stringn "그러니까 『베오크든 라구즈든 누구든\n"
.stringn "부담없이 와서, 잔뜩 마시고 얘기하면서\n"
.stringn "행복해지는 가게』는 어때!?\n"
.stringn "\x0713흠. 좀 길군.\n"
.stringn "\x0701아, 역시 안 되겠다.\n"
.stringn "곤란하게 됐다구,\n"
.stringn "나 이런 거\n"
.stringn "전혀 생각 못 하겠어.\n"
.stringn "\x0713굳이 어렵게 생각할 필요는 없다.\n"
.stringn "제일 아끼는 사람의 이름은 어떤가?\n"
.stringn "\x0701그럼 카릴이지.\n"
.stringn "나한텐 언제나 카릴이 첫 번째니까…\n"
.stringn "\x0713반한 여자의 이름인가.\n"
.stringn "그렇다면 그걸로 충분하겠지.\n"
.stringn "가게가 문을 열면\n"
.stringn "나도 들러도 되겠나?\n"
.stringn "\x0701그래, 당신한테는\n"
.stringn "잔뜩 신세를 졌으니까.\n"
.stringn "당신이 좋아하는 술은……\n"
.stringn "분명 어딘가에 적어 놨었는데…… 어디지?\n"
.stringn "오오, 찾았다. 독한 술 맞지?\n"
.stringn "\x0713그렇다.\n"
.stringn "\x0701와하하하하! 맡겨 둬!\n"
.stringn "불이라도 뿜을 만한\n"
.stringn "독한 술을 준비해 놓고 있을게!"
db 0
.align 4
//MYELL_8_LARGO_TAURONEO_A

//0x22590
Text_22570:
.stringn "\x05FL|LARGO|TAURONEO||\x0C05\x0C13\x0705으~~음.\n"
.stringn "\x0713……\n"
.stringn "\x0705으~~음.\n"
.stringn "\x0713……또 무슨 일이 있나?\n"
.stringn "\x0C05\x0701응?\n"
.stringn "오오, 당신이었구만.\n"
.stringn "\x0713방금 전부터 끙끙거리면서 서 있더군.\n"
.stringn "하늘만 바라보고 있던데.\n"
.stringn "자군의 진영 내라고는 해도, 방심하면\n"
.stringn "목숨을 잃게 될 거다.\n"
.stringn "\x0701아, 확실히 그렇지.\n"
.stringn "안 되겠다 안 되겠어.\n"
.stringn "난 머리가 나쁘니까 두 가지 일을\n"
.stringn "한꺼번에 생각할 수가 없다고.\n"
.stringn "\x0713뭔가 고민이라도 있나?\n"
.stringn "\x0701그래, 들어줄래?\n"
.stringn "난 언젠가 가게를 열려고 하거든.\n"
.stringn "여기서 돈도 잔뜩 모았고,\n"
.stringn "술집 같은 걸 차려 보려고 하는데.\n"
.stringn "\x0713호오.\n"
.stringn "\x0701나는 손님을 소중하게 생각하고 싶어.\n"
.stringn "와 주는 손님들을\n"
.stringn "모두 행복하게 만들고 싶어.\n"
.stringn "그래서 여러 사람이 모이는 이곳에서\n"
.stringn "여러 가지를 공부하고 있지.\n"
.stringn "사람 수만큼 취향도 다양한 법이니까.\n"
.stringn "\x0713그거 훌륭한 이상이로군.\n"
.stringn "그런데 그 가게는 어디에 차릴 셈이지?\n"
.stringn "\x0701으~~~음……\n"
.stringn "이래 봬도\n"
.stringn "베그니온 출신이라서 말이지.\n"
.stringn "역시 고향인 베그니온이 좋을까.\n"
.stringn "그치만 다른 사람의 얘기도 들어보니까,\n"
.stringn "크리미아나 데인도 좋은 것 같고…\n"
.stringn "아아, 이거 큰일이네.\n"
.stringn "내가 머리가 나빠서……\n"
.stringn "\x0713………………\n"
.stringn "나라도 괜찮다면 상담을 해 줘도 되겠나?\n"
.stringn "\x0701오오, 그거 고맙겠어.\n"
.stringn "두 명이라면 두 가지를 생각할 수 있겠지.\n"
.stringn "그리고 가게 메뉴랑,\n"
.stringn "으음…… 뭐였더라……"
db 0
.align 4
//MYELL_8_LARGO_TAURONEO_B

//0x22250
Text_22230:
.stringn "\x05FL|LARGO|TAURONEO||\x0701으~~음…… 으~~음……\n"
.stringn "\x0716……\n"
.stringn "\x0701오?\n"
.stringn "저기, 거기 당신.\n"
.stringn "\x0C16\x0713음?\n"
.stringn "\x0701이 군, 상당히 별난 곳이라고\n"
.stringn "생각하지 않아?\n"
.stringn "이렇게 다양한 나라 사람들이\n"
.stringn "섞여 있는 건 드문 일이라고.\n"
.stringn "나 이쪽저쪽으로 여행을 다녔는데,\n"
.stringn "이 정도로 뒤죽박죽인 건\n"
.stringn "처음이야 처음.\n"
.stringn "\x0713……그럴지도 모르겠군.\n"
.stringn "무엇보다 적이었던 전 데인병도\n"
.stringn "섞여 있을 정도니까.\n"
.stringn "국가의 다양함에는 부족함이 없겠지.\n"
.stringn "\x0701맞아, 그래서 여러 인종이\n"
.stringn "다양하게 있어서\n"
.stringn "희귀한 요리도 나오잖아.\n"
.stringn "\x0713……그 손에 있는 것은 뭐지?\n"
.stringn "\x0701응? 아아, 생각해 두었던 걸\n"
.stringn "잊어버리지 않도록 기록하는 거야.\n"
.stringn "난 머리가 나빠서 금방 잊어버리거든.\n"
.stringn "라구즈들은 진한 양념을 좋아하는 거 같고,\n"
.stringn "게다가 우리랑 같이 술도 마셔 준다고!\n"
.stringn "정말 최고야 최고!\n"
.stringn "저기, 당신은 어떤 술이 좋아?\n"
.stringn "\x0713……술 말인가.\n"
.stringn "독한 술을 좋아하지.\n"
.stringn "\x0701맛은?\n"
.stringn "\x0713맛은 상관없다.\n"
.stringn "\x0701와하하하! 좋네, 사나이답구만!\n"
.stringn "좋아, 그것도 잊어버리지 않게 써 둬야지."
db 0
.align 4
//MYELL_8_LARGO_TAURONEO_C

//0x23554
Text_23534:
.stringn "\x05FL|WAYU|LARGO||\x0C03\x0C11\x0703봐준 거야?\n"
.stringn "\x0711아니.\n"
.stringn "\x0703……정말로?\n"
.stringn "\x0711정말이야.\n"
.stringn "\x0703정말 정말로?\n"
.stringn "\x0711정말 정말로.\n"
.stringn "보기 좋게 당해 버렸구만.\n"
.stringn "졌다 졌어.\n"
.stringn "네 성장은 대단한걸.\n"
.stringn "\x0703…………\n"
.stringn "하~~~…… 지쳤어.\n"
.stringn "그럼, 오늘은 정말 내 승리인 거다!\n"
.stringn "일단 잠깐 한숨 자고 올까……\n"
.stringn "\x0711그래, 그 전에 네가\n"
.stringn "지쳤다는 건 알고 있지만……\n"
.stringn "하나 물어봐도 되냐?\n"
.stringn "\x0703응?\n"
.stringn "\x0711너,\n"
.stringn "왜 그렇게 고집을 부리는 거야?\n"
.stringn "내가 전에 한 말……\n"
.stringn "너는 나 이상으로\n"
.stringn "뼈저리게 알고 있을 거 아냐.\n"
.stringn "그런데 어째서\n"
.stringn "그렇게까지 열심히 하는 거야?\n"
.stringn "\x0703난 질 수 없어.\n"
.stringn "여자니까, 여자한테 맞는 일이 아니야.\n"
.stringn "지금까지 몇 번이나 그런 말을 들었으니까.\n"
.stringn "그래서 질 수 없어.\n"
.stringn "\x0711……\n"
.stringn "\x0703약해서 지는 건 납득할 수 있어.\n"
.stringn "기술이 부족하면 갈고닦으면 돼.\n"
.stringn "경험이 부족하면 더 싸우면 돼.\n"
.stringn "하지만 여자라서 진다는 건\n"
.stringn "스스로 용서가 안 돼.\n"
.stringn "아저씨한테 진 건,\n"
.stringn "내가 여자라서가 아니야.\n"
.stringn "그런 이유로 도망치고 싶지 않아.\n"
.stringn "내가 미숙해서 진 거라고.\n"
.stringn "그렇다면 수행하면 돼.\n"
.stringn "검 솜씨를 갈고닦으면, 언젠가는 이길 테니까.\n"
.stringn "\x0711……그렇구만.\n"
.stringn "대단한걸.\n"
.stringn "이러니 내가 지는 것도 당연하지.\n"
.stringn "나도 지지 않을 거다,\n"
.stringn "너의 그 의지를 본받아야겠어.\n"
.stringn "\x0703그럼, 언제 할래?\n"
.stringn "\x0711응?\n"
.stringn "\x0703다음 승부 말이야.\n"
.stringn "아저씨도\n"
.stringn "진 채로 끝내기는 싫지?\n"
.stringn "\x0711와하하하하! 역시 너다워.\n"
.stringn "그야 물론이지.\n"
.stringn "이길 때까지 몇 번이라도 해 주마!\n"
.stringn "\x0703바라던 바야!"
db 0
.align 4
//MYELL_8_LARGO_WAYU_A

//0x230E4
Text_230C4:
.stringn "\x05FL|WAYU|LARGO||\x0C03\x0C11\x0703아저씨!\n"
.stringn "\x0711오오, 너구나.\n"
.stringn "저번에 그, 뭐냐.\n"
.stringn "무시하는 듯이 말해서 미안했다.\n"
.stringn "\x0703그런 건 아무렇지도 않아.\n"
.stringn "그것보다 아저씨,\n"
.stringn "알고 있겠지!\n"
.stringn "\x0711음?\n"
.stringn "뭔데?\n"
.stringn "\x0703지난번의 빛을 갚으러\n"
.stringn "온 게 당연하잖아!\n"
.stringn "그때는 확실히 져 버렸지!\n"
.stringn "하지만 지금의 나를 전과 같다고\n"
.stringn "생각하면 곤란해!\n"
.stringn "\x0711아직도 하는 거야?\n"
.stringn "기분은 알겠지만……\n"
.stringn "그만두는 편이 좋아,\n"
.stringn "여자애의 힘으론\n"
.stringn "나를 이길 수 없을 테니까.\n"
.stringn "\x0703!\n"
.stringn "또 여자라고 무시하고 있어!\n"
.stringn "\x0711난감하구만……\n"
.stringn "있잖아.\n"
.stringn "이건 너를\n"
.stringn "무시하는 게 아니야.\n"
.stringn "남자와 여자는 뼈와 살이 붙은 구조가 다르다고.\n"
.stringn "싸움에서는 어떻게 해도\n"
.stringn "불리해져 버릴걸.\n"
.stringn "\x0703그런 건 알고 있어!\n"
.stringn "하지만 나는 지지 않을 거야.\n"
.stringn "질 수 없어, 절대로.\n"
.stringn "오늘 지면 수행해서 내일 이길 거야.\n"
.stringn "내일 지면 수행해서 그 다음 날에도……\n"
.stringn "\x0711이, 이봐……\n"
.stringn "너 잘 보니까\n"
.stringn "휘청거리고 있잖아.\n"
.stringn "그런 상태로 싸우는 건\n"
.stringn "애초에 무리라고.\n"
.stringn "오늘은 좀 쉬어……\n"
.stringn "\x0703신경 쓸 필요 없어!\n"
.stringn "좀 휘청거리는 건\n"
.stringn "오늘 아저씨를 이기기 위해\n"
.stringn "훈련하고 와서 그런 거야.\n"
.stringn "그러니까 오늘\n"
.stringn "아저씨랑 싸우지 않으면 의미가 없어.\n"
.stringn "\x0711……\n"
.stringn "알았다.\n"
.stringn "네가 그렇게까지 말한다면……\n"
.stringn "나도 사나이야. 받아 줄게.\n"
.stringn "\x0703간다!"
db 0
.align 4
//MYELL_8_LARGO_WAYU_B

//0x22E50
Text_22E30:
.stringn "\x05FL|WAYU|LARGO||\x070-\x0C03\x0C11\x0703흐음.\n"
.stringn "아저씨, 몸이 좋은걸.\n"
.stringn "\x0711음? 뭐야, 넌.\n"
.stringn "\x0703나는 와유!\n"
.stringn "수행 중인 검사야.\n"
.stringn "한 판 승부하지 않을래?\n"
.stringn "\x0711승부라고?\n"
.stringn "으~음…… 곤란하구만.\n"
.stringn "\x0703왜?\n"
.stringn "\x0711너는 여자잖아.\n"
.stringn "여자애를 상대로 승부하는 건\n"
.stringn "조금 그런데……\n"
.stringn "\x0703!\n"
.stringn "\x0711너도 그 뭐냐,\n"
.stringn "검을 가지고 싸우는 것보다……\n"
.stringn "좀 더 뭐랄까\n"
.stringn "가정적인 일을 하는 게 낫지 않아?\n"
.stringn "잘 모르지만 예를 들자면\n"
.stringn "뜨개질이라든지 요리라든지……\n"
.stringn "적어도 마도 사용자가 된다든지……\n"
.stringn "\x0703무슨 소리야!\n"
.stringn "여자는 싸울 수 없다는 거야?\n"
.stringn "\x0711으~음……\n"
.stringn "미안.\n"
.stringn "\x0703알았으면\n"
.stringn "빨리 빨리! 자세 잡아!\n"
.stringn "\x0711으~음…… 큰일났구만.\n"
.stringn "저기, 이건 어때?\n"
.stringn "뜨개질로 승부를 낸다든지……\n"
.stringn "\x0703문답무용!"
db 0
.align 4
//MYELL_8_LARGO_WAYU_C

//0x242A8
Text_24288:
.stringn "\x05FL|RETHE|LAY||\x0C01\x0713레테, 전에 했던 이야기 말인데.\n"
.stringn "부대장급의 지원자를 몇 명 정도\n"
.stringn "파견지에서 갈리아로 귀환시키자는 의견이 나왔어.\n"
.stringn "아직 정식으로 결정된 건 아니지만……\n"
.stringn "만약 그렇게 된다면 넌 어떡할 거야?\n"
.stringn "갈리아로 돌아가고 싶다면 그렇게 전해 둘게.\n"
.stringn "\x0701나는……\n"
.stringn "여기에 남겠다.\n"
.stringn "\x0713뭐?\n"
.stringn "괜찮겠어?\n"
.stringn "\x0701……내가 없어지자마자\n"
.stringn "아이크 일행에게 무슨 일이 생기면 곤란하니까.\n"
.stringn "그러니, 여기에 남겠다.\n"
.stringn "\x0713호오……\n"
.stringn "\x0701뭐, 뭐냐\n"
.stringn "그 의미심장한 미소는.\n"
.stringn "\x0713아냐, 아무것도.\n"
.stringn "『인간 놈들이!』라고 말하던\n"
.stringn "네가 그러니까 뭔가……\n"
.stringn "\x0701나, 나는 딱히……\n"
.stringn "\x0713넌 동요하면 꼬리에서 다 들어나니까\n"
.stringn "금방 알 수 있다고.\n"
.stringn "그래그래, 역시 그런 거였어.\n"
.stringn "\x0701……단련 중이었다.\n"
.stringn "이야기가 끝났다면 가 보지.\n"
.stringn "\x0713아, 미안.\n"
.stringn "너무 놀렸나.\n"
.stringn "\x0700…………\n"
.stringn "라이.\n"
.stringn "\x0713응?\n"
.stringn "\x0700……내 생각이\n"
.stringn "이전과 달라진 것은 인정하겠다.\n"
.stringn "\x0713……그래?\n"
.stringn "\x0700그동안 쭉…… 네 생각에는\n"
.stringn "동의할 수 없었다만……\n"
.stringn "이제는 네 기분을 알 것 같다.\n"
.stringn "함께 싸우는 그들은 소중한 동료다.\n"
.stringn "저주받은 【부】의 기운이 소용돌이치는 땅으로\n"
.stringn "향하는 동료들을 내버려 둘 수는 없지.\n"
.stringn "그러니, 나는 아이크와 함께 가겠다.\n"
.stringn "\x0713그렇구나……\n"
.stringn "좋아, 이긴다면 아이크네랑\n"
.stringn "다 같이 신나게 놀아 보자구.\n"
.stringn "\x0700지금은 아직 방심할 때가 아니다.\n"
.stringn "하지만…… 그렇군.\n"
.stringn "언젠가…… 그렇게 되면 좋겠어."
db 0
.align 4
//MYELL_8_LAY_LETHE_A

//0x23E4C
Text_23E2C:
.stringn "\x05FL|LAY|RETHE||\x070-\x0C01\x0713라이, 갈리아에 있는\n"
.stringn "내 부하들은 단련을 계속하고 있나?\n"
.stringn "\x0701그래, 물론이지.\n"
.stringn "그놈들도 갈리아의 전사야.\n"
.stringn "나라의 수비는\n"
.stringn "녀석들에게 맡겨도 괜찮겠지.\n"
.stringn "\x0713하지만 아무래도 걱정이군.\n"
.stringn "열심히 단련하는 건 좋다만,\n"
.stringn "겨루는 도중에 진심이 되어서\n"
.stringn "피가 끓어올라 싸움이 벌어질 때가 자주 있었다.\n"
.stringn "\x0701뭐, 혈기 왕성한 녀석들이\n"
.stringn "잔뜩 있으니까 말이지……\n"
.stringn "그래도 어떻게든 될 거야.\n"
.stringn "\x0713너, 그렇게 태평하게 넘기……\n"
.stringn "\x0701너 말야,\n"
.stringn "그렇게 온종일 긴장하고 있지 말고\n"
.stringn "가끔은 어깨에서 힘 좀 빼지 그래?\n"
.stringn "물론 그렇다고 네 여동생처럼\n"
.stringn "전장에서 틈만 나면 털을 갈거나,\n"
.stringn "발톱을 다듬거나 하는 건 곤란하지만.\n"
.stringn "\x0713…리레는 지금 네 부대에 있나?\n"
.stringn "\x0701그래. 키사랑 같이 날 애먹이고 있어.\n"
.stringn "\x0713키사도 덩치는 큰 주제에\n"
.stringn "너를 잘 따르니까 말이다.\n"
.stringn "힘들겠지만… 잘 부탁한다.\n"
.stringn "\x0701리레랑 안 본 지 오래됐다면서?\n"
.stringn "\x0713……\n"
.stringn "\x0701말 안 하는 거구나. 뭐, 딱히 상관없지만.\n"
.stringn "빨리 화해하도록 해.\n"
.stringn "서로 하나뿐인 자매니까.\n"
.stringn "\x0713너하고는 관계없다.\n"
.stringn "\x0701네네.\n"
.stringn "\x0713여동생 일은 둘째 치고……\n"
.stringn "본국의 부대가 꽤나 걱정되는군.\n"
.stringn "너와 우리가 여기에 파견되어 있으니,\n"
.stringn "나라의 수비가 느슨해지고 있을 거다.\n"
.stringn "\x0701그렇긴 하지……\n"
.stringn "나도 좀 위하고 상의해 봐야겠어."
db 0
.align 4
//MYELL_8_LAY_LETHE_B

//0x23A74
Text_23A54:
.stringn "\x05FL|LAY|RETHE||\x070-\x0C03\x0C11\x0703잘 지냈어? 레테.\n"
.stringn "\x0711라이인가. 드디어 참전하는군.\n"
.stringn "\x0703그래, 드디어\n"
.stringn "형세가 역전되었으니까.\n"
.stringn "그것보다 상태는 어때, 레테?\n"
.stringn "여태까지는 너나 모우디한테만\n"
.stringn "맡겼잖아.\n"
.stringn "사실은 나도 함께하려고 했는데\n"
.stringn "미안하게 됐어.\n"
.stringn "\x0711사과 같은 건 의미가 없다.\n"
.stringn "행동으로 갚아.\n"
.stringn "\x0703변함없이 딱딱하다니까~ 너는.\n"
.stringn "그건 그렇고, 어때?\n"
.stringn "용병단 녀석들하고는 친해진 것 같아?\n"
.stringn "\x0711…………나름대로, 는.\n"
.stringn "하지만 여전히 불만은 있다.\n"
.stringn "어쩔 수 없겠지만 갑옷이 문제야.\n"
.stringn "아군까지 쇠 냄새를 풍기고 있으니,\n"
.stringn "내가 적을 감지할 수가 없어.\n"
.stringn "\x0703뭐어, 그건 그렇겠지~…\n"
.stringn "아무리 그래도 아이크네에게 전원 맨몸으로\n"
.stringn "싸워 달라고도 할 수 없는 노릇이고.\n"
.stringn "\x0711그리고, 베오크의 눈은 좀 어떻게 안 되는 건가?\n"
.stringn "어둠 속에서 보지 못하는 건 치명적이다.\n"
.stringn "조익족은 불가능하겠지만,\n"
.stringn "조금이라도 앞이 보인다면 기합으로 어떻게든……\n"
.stringn "\x0703아니 말도 안 되지, 그건……\n"
.stringn "\x0711다만……\n"
.stringn "여기 있는 건 생각보다 할 만하다.\n"
.stringn "\x0703그렇구나, 다행이네.\n"
.stringn "처음에 아이크네랑 같이 가게\n"
.stringn "되었을 때 네 비장한 얼굴이 마치……\n"
.stringn "\x0711시, 시끄러워!"
db 0
.align 4
//MYELL_8_LAY_LETHE_C

//0x24DD0
Text_24DB0:
.stringn "\x05FL|LAY|MORDY||\x0C03\x0711미안하다, 라이.\n"
.stringn "\x0703왜 그래, 모우디?\n"
.stringn "\x0711라이한테 듣고 나서, 생각해 봤다.\n"
.stringn "하지만, 아무리 그래도 모우디는\n"
.stringn "싸우는 게 싫다.\n"
.stringn "\x0703아아… 그건\n"
.stringn "이해한다고 말했잖아?\n"
.stringn "\x0711모우디는 전사니까, 싸운다.\n"
.stringn "동료를 지키기 위해, 싸운다.\n"
.stringn "그런데도…… 모우디는,\n"
.stringn "지금까지처럼 싸울 수밖에 없다.\n"
.stringn "\x0703……모우디.\n"
.stringn "그래…… 너는\n"
.stringn "옛날부터 그랬지.\n"
.stringn "숲에서 다람쥐랑 낮잠 자는 게 취미인…\n"
.stringn "쾌활하면서도 느긋한 녀석이었어.\n"
.stringn "\x0711으으…… 미안.\n"
.stringn "\x0703아니, 신경 쓰지 말라니까.\n"
.stringn "\x0711……혹시\n"
.stringn "모우디는… 좋아하는 아이크와 모두에게\n"
.stringn "민폐일지도 모른다……\n"
.stringn "그렇게 생각하니 무척 괴로웠다………\n"
.stringn "\x0703그럼, 빨리 전쟁을 끝내자.\n"
.stringn "그러면 이렇게 고민하지 않아도 되잖아?\n"
.stringn "\x0711그렇다! 그러면 되겠다!\n"
.stringn "\x0703그럼 평소보다 더 기합을 넣고 가 볼까?\n"
.stringn "같이 어울려 줘.\n"
.stringn "다음을 대비해서 몸을 움직여 두자구.\n"
.stringn "\x0711그래!!"
db 0
.align 4
//MYELL_8_LAY_MORDY_A

//0x24A30
Text_24A10:
.stringn "\x05FL|MORDY|LAY||\x0707쿨……쿨……\n"
.stringn "\x071-\x0713어~이 모우디.\n"
.stringn "뭐지? 자는 건가?\n"
.stringn "\x0C07\x0701으으으으음…… 라이?\n"
.stringn "\x0713오! 일어났구나.\n"
.stringn "잘도 이런 곳에서 자네.\n"
.stringn "너도 무신경한 건\n"
.stringn "아이크랑 맞먹는단 말이지.\n"
.stringn "\x0701모우디는 아이크와 모두를\n"
.stringn "신뢰하고 있다.\n"
.stringn "모두가 있다고 생각하면, 안심이 된다.\n"
.stringn "\x0713하하, 그러냐.\n"
.stringn "……그러고 보니 모우디.\n"
.stringn "이전에 네가 싸우는 걸 보다가\n"
.stringn "눈치챘는데.\n"
.stringn "너, 적을 공격할 때\n"
.stringn "가끔씩 눈을 감고 있더라?\n"
.stringn "\x0701……그렇다.\n"
.stringn "라이가 잘 봤다.\n"
.stringn "\x0713왜 그러는 거야?\n"
.stringn "\x0701아파하는 적을 보면, 모우디도 아프다.\n"
.stringn "그래도, 싸움이다.\n"
.stringn "싸움에 자비는 없다.\n"
.stringn "열심히 싸워야 한다.\n"
.stringn "그래서 눈을 조금 감는다.\n"
.stringn "\x0713가끔 부자연스럽게\n"
.stringn "움직임이 둔해지는 것도 그 때문이었구나…\n"
.stringn "\x0701맞다… 라이는 잘 보고 있다.\n"
.stringn "\x0713뭐 그렇지…\n"
.stringn "그나저나 아까운걸.\n"
.stringn "그 상냥한 마음이 없었다면\n"
.stringn "너는 더 강한 전사가 됐겠지.\n"
.stringn "\x0701으으…… 미안하다……\n"
.stringn "\x0713딱히 사과할 필요는 없어.\n"
.stringn "네 성격은 잘 이해하고 있으니까.\n"
.stringn "\x0701응……"
db 0
.align 4
//MYELL_8_LAY_MORDY_B

//0x24720
Text_24700:
.stringn "\x05FL|MORDY|LAY||\x070-\x0C01\x071-\x0713안녕, 모우디.\n"
.stringn "\x0701라이.\n"
.stringn "이렇게 얘기하는 거 오랜만이다.\n"
.stringn "\x0713그래, 여태까지 수고 많았어.\n"
.stringn "다 들었어, 용병단 내에서도\n"
.stringn "맹활약했다면서?\n"
.stringn "\x0701그런가?\n"
.stringn "도움이 되어서 다행이다.\n"
.stringn "아이크는 좋은 베오크니까\n"
.stringn "모우디는 힘냈다.\n"
.stringn "\x0713이제 용병단 동료들과도\n"
.stringn "잘 지내는 거야?\n"
.stringn "\x0701글쎄?\n"
.stringn "아마, 잘 지내는 것 같다.\n"
.stringn "근데 라이,\n"
.stringn "모우디가 말하는 거, 이상한가?\n"
.stringn "\x0713아니, 하나도 안 이상해.\n"
.stringn "조금 딱딱하긴 하지만.\n"
.stringn "\x0701말은 어렵다.\n"
.stringn "우리들은 화신하면\n"
.stringn "어려운 말은 할 필요가 없다.\n"
.stringn "숲속의 동료들과도 한 번에\n"
.stringn "의사를 주고받을 수 있다.\n"
.stringn "\x0713뭐 그렇지.\n"
.stringn "하지만 우리가 짖어도\n"
.stringn "베오크들은 모를걸.\n"
.stringn "마구 짖어 댔다가\n"
.stringn "모두를 겁주게 되면 큰일이고.\n"
.stringn "\x0701그렇다. 라이 말이 맞다.\n"
.stringn "여기 있는 건\n"
.stringn "좋은 베오크들뿐이다.\n"
.stringn "무섭게 하면 안 된다."
db 0
.align 4
//MYELL_8_LAY_MORDY_C

//0x25844
Text_25824:
.stringn "\x05FL|MWARIM|RETHE||\x0C01\x0C13\x0701레테.\n"
.stringn "\x0713……무슨 일이지?\n"
.stringn "\x0701불쾌하게 해서 미안했다.\n"
.stringn "포기하고 있었던 주제에……\n"
.stringn "나는 네가\n"
.stringn "부러웠던 모양이야.\n"
.stringn "\x0713그래……?\n"
.stringn "\x0701베오크에게 꺾이지 않고\n"
.stringn "대등하게 대할 수 있다.\n"
.stringn "네 입장에서는 당연한 일이겠지만,\n"
.stringn "나는 그런 일을 생각해 본 적도 없었다.\n"
.stringn "\x0713…………그렇다면……\n"
.stringn "생각만이라도 해 본다면 가능하게\n"
.stringn "될 일이 아닌가?\n"
.stringn "\x0701……그래, 그럴지도 모르지.\n"
.stringn "아니…… 그렇게 해야만 하는 걸지도 몰라.\n"
.stringn "\x0713의무는 아니라고 생각하지만……\n"
.stringn "그렇게 하는 편이 분명 네가\n"
.stringn "편해질 거라고 생각한다.\n"
.stringn "네가 편안한 얼굴을 하고 있는 걸\n"
.stringn "나는 본 적이 없어.\n"
.stringn "그게 신경 쓰여서…… 괴롭다.\n"
.stringn "\x0701…………그런가……\n"
.stringn "\x0713……그, 괴로울지도 모르지만……\n"
.stringn "네가 어떤 식으로 살아왔는지\n"
.stringn "들려주지 않겠나?\n"
.stringn "……조금이라도, 네 기분을\n"
.stringn "알게 될지도 모른다.\n"
.stringn "\x0701…………레테……"
db 0
.align 4
//MYELL_8_LETHE_MWARIM_A

//0x2544C
Text_2542C:
.stringn "\x05FL|MWARIM|RETHE||\x0C01\x0713무와림.\n"
.stringn "……요즘은 잘 지내나?\n"
.stringn "\x0701그래, 이 군에도 꽤\n"
.stringn "적응했다.\n"
.stringn "다른 라구즈들의 시선에도…\n"
.stringn "제법 익숙해졌고.\n"
.stringn "\x0713? 라구즈의……?\n"
.stringn "그나저나 너…… 또 짐을 옮기는 거냐?\n"
.stringn "그런 물자를 나르는 일 따윈\n"
.stringn "다른 병사들에게 맡겨 두면 될 텐데.\n"
.stringn "\x0701신경이 쓰여서 말이지.\n"
.stringn "그대로 지나치기에는\n"
.stringn "공포심마저 느끼게 된다.\n"
.stringn "\x0713공포……?\n"
.stringn "\x0701태어날 때부터 그런 환경에서 자라면\n"
.stringn "뼛속까지 새겨지는 법이지.\n"
.stringn "\x0713…………그렇군.\n"
.stringn "\x0701너는 화내지 않는 건가?\n"
.stringn "라구즈로서의 긍지는 어쨌냐고.\n"
.stringn "\x0713…………아니……\n"
.stringn "옛날의 나라면 그렇게 말했을지도 모른다.\n"
.stringn "하지만 지금은…… 아이크 곁에서\n"
.stringn "싸우면서……\n"
.stringn "라구즈와 베오크의 관계에 대해\n"
.stringn "여러 가지를 생각하게 된단 말이지……\n"
.stringn "\x0701…………\n"
.stringn "\x0713무엇보다, 이미 체념하고 있는 네게\n"
.stringn "할 말은 아무것도 없다.\n"
.stringn "\x0701!\n"
.stringn "\x0713그게 나쁘다고는 할 수 없어.\n"
.stringn "나로서는 이해할 수 없는 삶을……\n"
.stringn "너는 살아온 거지?\n"
.stringn "다만…… 하나만 부탁하지.\n"
.stringn "네가 모든 걸 받아들이고 포기했다면\n"
.stringn "그렇게 비굴한 태도로 지내진 말아 줘.\n"
.stringn "……신경이 쓰여서 견딜 수가 없다.\n"
.stringn "\x0701…………"
db 0
.align 4
//MYELL_8_LETHE_MWARIM_B

//0x25100
Text_250E0:
.stringn "\x05FL|RETHE|MWARIM||\x0C01\x0C13\x0701무와림.\n"
.stringn "\x0713……레테인가.\n"
.stringn "\x0701상태는 어떻지?\n"
.stringn "이런 식으로 군대에서 싸우는 건 처음일 텐데.\n"
.stringn "\x0713그래, 맞다.\n"
.stringn "모르는 것이 많아서 당혹스러운 점도 있지.\n"
.stringn "\x0701뭐든지 물어봐라.\n"
.stringn "나는 갈리아에서 부대를 이끌고 있었으니까.\n"
.stringn "전투 지식이라면 풍부하게 가지고 있다.\n"
.stringn "\x0713……여자의 몸으로 말인가.\n"
.stringn "레테는 대단하군.\n"
.stringn "\x0701………………\n"
.stringn "그런가…… 너는 베그니온에서\n"
.stringn "태어나 자랐다고 했었지……\n"
.stringn "갈리아에선 남자든 여자든 관계없다.\n"
.stringn "보다 우수한 전사라면 그걸로 된다.\n"
.stringn "신체 구조의 문제로 남자보다\n"
.stringn "여자 쪽이 아무래도 뒤떨어지는 부분은 있다만…\n"
.stringn "노력으로 보완하면 어떻게든 된다.\n"
.stringn "\x0713훌륭하군.\n"
.stringn "\x0701……너, 그렇게 남의 일인 것마냥\n"
.stringn "듣고만 있지 마라.\n"
.stringn "베그니온에서 노예로 살았다고 했지만……\n"
.stringn "베오크 따위, 네가 진심으로 상대하면…\n"
.stringn "\x0713……넌 모르겠지.\n"
.stringn "태어날 때부터 위대한 갈리아 왕에게 보호받으며,\n"
.stringn "라구즈로서의 자부심을 안고 살아왔다.\n"
.stringn "그런 너로서는 이해할 수 없는 일이야.\n"
.stringn "\x0701…………"
db 0
.align 4
//MYELL_8_LETHE_MWARIM_C

//0x26228
Text_26208:
.stringn "\x05FL|LOFA|MARCIA||\x0C01\x071-\x0713굉장해~!\n"
.stringn "요파, 전부 적중시켰네.\n"
.stringn "\x0701응.\n"
.stringn "그래도 더 열심히 해야지.\n"
.stringn "게다가 맞히기만 하는 걸로는 안 돼.\n"
.stringn "나한테 활을 가르쳐 준 사람은\n"
.stringn "확실하게 갑옷 틈새만 노려서 맞히니까.\n"
.stringn "\x0713굉장하네……\n"
.stringn "요파도 그렇게 되려나……\n"
.stringn "…………어라?\n"
.stringn "자, 잠깐 요파,\n"
.stringn "손 보여 줘 봐!\n"
.stringn "\x0701손……?\n"
.stringn "\x0713역시나……\n"
.stringn "물집이 뭉개져서 피가 나잖아.\n"
.stringn "정말, 뭐 하는 거야!\n"
.stringn "왜 이렇게 될 때까지 놔뒀어!?\n"
.stringn "\x0701정말이네……\n"
.stringn "아프다고 생각은 했었는데……\n"
.stringn "도중에 안 아프게 돼서\n"
.stringn "그대로 계속 있었어.\n"
.stringn "\x0713요파……\n"
.stringn "요파는 정말 강하구나……\n"
.stringn "잠깐만, 상처약이……\n"
.stringn "아, 여기 있다.\n"
.stringn "가만히 있어. 조금 따끔할 거야.\n"
.stringn "\x0701……고마워.\n"
.stringn "\x0713요파는 크면\n"
.stringn "더 강해질 거야.\n"
.stringn "지금도 이렇게 강하니까……\n"
.stringn "\x0701그래?\n"
.stringn "\x0713응. 실력도 실력이지만 마음가짐이 훌륭한걸.\n"
.stringn "아픈 걸 잊어버릴 정도로\n"
.stringn "집중할 수 있잖아.\n"
.stringn "쉽게 할 수 있는 일이 아니야.\n"
.stringn "\x0701그럼…… 나는 제대로\n"
.stringn "모두를 지킬 수 있을까?\n"
.stringn "위험할 때, 제대로 도움이 될 수 있을까?\n"
.stringn "\x0713물론이지!\n"
.stringn "소중한 사람들을 분명 지킬 수 있을 거야.\n"
.stringn "제멋대로지만 내가 보증할게!\n"
.stringn "\x0701……고마워, 마샤씨.\n"
.stringn "제대로 마샤씨도 지켜 줄게.\n"
.stringn "항상 곁에 있어 줘서, 고마워.\n"
.stringn "\x0713요파…………\n"
.stringn "…………나도… 나도, 요파를 지켜 줄게.\n"
.stringn "요파는 아직 어린데……\n"
.stringn "어째서 어른스럽게\n"
.stringn "되어야 하는 걸까…………"
db 0
.align 4
//MYELL_8_LOFA_MARCIA_A

//0x25EDC
Text_25EBC:
.stringn "\x05FL|LOFA|MARCIA||\x0C03\x071-\x0714와, 굉장하다!\n"
.stringn "23번 연속으로 과녁을 맞혔잖아!\n"
.stringn "\x0703으~음…… 사실은 30번 연속으로\n"
.stringn "맞히고 싶었는데……\n"
.stringn "\x0C14\x0C14\x0711그래도 절반 이상은 맞혔다는 거 아냐?\n"
.stringn "잘한다, 요파!\n"
.stringn "\x0703그치만 전장에서는 모두 적중시켜야 한다고\n"
.stringn "나한테 활을 가르쳐 준 사람이 말했어.\n"
.stringn "23번으로 만족하면 안 돼.\n"
.stringn "훈련용이라 거리도 짧고.\n"
.stringn "\x0711그렇구나…… 장하네, 요파는.\n"
.stringn "자신에게 엄격하구나.\n"
.stringn "\x0703마샤는 자신에게 상냥해?\n"
.stringn "\x0711응? 그런 건 아니야.\n"
.stringn "자신에게 엄격하게, 타인에게도 엄격하게!\n"
.stringn "가 예전에 소속되어 있던 군의\n"
.stringn "부대장이 하던 말이었으니까.\n"
.stringn "그래도, 요파는 아직……\n"
.stringn "\x0703어린애가 아니야.\n"
.stringn "……나도 적을 쓰러뜨리고 있어.\n"
.stringn "\x0711……응, 그렇지.\n"
.stringn "\x0703마샤씨는 내가 어린애니까\n"
.stringn "걱정해 주고 있는 거야?\n"
.stringn "\x0711응……\n"
.stringn "\x0703그럼 이제 걱정 안 해 줘도 돼.\n"
.stringn "난 그렇게 약하지 않으니까.\n"
.stringn "\x0711그렇구나…… 미안해."
db 0
.align 4
//MYELL_8_LOFA_MARCIA_B

//0x25B6C
Text_25B4C:
.stringn "\x05FL|LOFA|MARCIA||\x0703영차…… 휴우.\n"
.stringn "\x0711어라? 너는……\n"
.stringn "분명 요파라 했었지.\n"
.stringn "혼자서 뭐 하고 있었니?\n"
.stringn "\x0703활 훈련이야.\n"
.stringn "여기에 이렇게 나무를 세우고,\n"
.stringn "적중시킬 장소를 정한 다음에\n"
.stringn "그곳을 노리는 거지.\n"
.stringn "다른 곳에 맞히면 위험하니까\n"
.stringn "화살 끝에는 천을 달아 놨어.\n"
.stringn "게다가 과녁과의 거리도 짧게 잡아서\n"
.stringn "제대로 훈련이 되지는 않지만.\n"
.stringn "\x0711우와, 대단하네.\n"
.stringn "어린데도 열심히 하는구나.\n"
.stringn "\x0703어리다고 하지 마.\n"
.stringn "나도 어엿한 용병인걸?\n"
.stringn "\x0711알아 알아.\n"
.stringn "그럼 내가\n"
.stringn "훈련하는 거 도와줄까?\n"
.stringn "\x0703어……? 괜찮아.\n"
.stringn "혼자서 할 수 있어.\n"
.stringn "\x0711사양하지 말고.\n"
.stringn "난 말이지, 세상에서 제일 큰 나라의\n"
.stringn "기사였다니까.\n"
.stringn "게다가 궁병에 대한 지식은 풍부한걸?\n"
.stringn "천마 기사에게 궁병은 강적이거든.\n"
.stringn "\x0703난 기사가 아니거든.\n"
.stringn "상관없어.\n"
.stringn "\x0711아, 잠깐 요파.\n"
.stringn "이런 데서 활을 쏠 때는\n"
.stringn "주변에 사람이 있는지\n"
.stringn "확인해야 돼.\n"
.stringn "\x0703나 참, 그런 건 알고 있다구.\n"
.stringn "\x0711그렇구나, 미안 미안!"
db 0
.align 4
//MYELL_8_LOFA_MARCIA_C

//0x26E98
Text_26E78:
.stringn "\x05FL|MIST|LOFA||\x0C01\x0C13\x0701저기, 요파.\n"
.stringn "\x0713……\n"
.stringn "\x0701무시하지 마.\n"
.stringn "제대로 얘기하자.\n"
.stringn "\x0713………\n"
.stringn "\x0701요파를 탓할 생각은 없어.\n"
.stringn "단지 용병단 때처럼\n"
.stringn "산적 퇴치라든가… 그런 식으로\n"
.stringn "상대를 그저 나쁜 사람들로만 보면 안 된다는 걸…\n"
.stringn "알아 줬으면 했어.\n"
.stringn "\x0713…내가 아무런 생각도 없이\n"
.stringn "그러는 줄 알았어?\n"
.stringn "\x0701…뭐?\n"
.stringn "\x0713상대는 과녁이 아니야…\n"
.stringn "과녁은 움직이지도 않고, 비명도 지르지 않아…\n"
.stringn "피를 흘리지도 않지……\n"
.stringn "그런 것쯤은 알고 있었어.\n"
.stringn "처음으로 적을 쓰러뜨린… 그때부터……\n"
.stringn "적도…\n"
.stringn "우리처럼 동료나 가족들을\n"
.stringn "지키기 위해서 싸우는 인간이라는 걸…\n"
.stringn "\x0701요파…\n"
.stringn "\x0713그래도 나쁜 놈들이야.\n"
.stringn "나한테는…\n"
.stringn "소중한 사람들을 상처 입힌다면\n"
.stringn "적이고, 나쁜 놈들이야.\n"
.stringn "그러니까 쓰러뜨리겠어.\n"
.stringn "그야 녀석들을 살려 뒀다간\n"
.stringn "다음엔 아군 중 누군가가 죽을 테니까!\n"
.stringn "난… 그게 무서워.\n"
.stringn "전쟁이 끝나지 않으면\n"
.stringn "언제까지고… 계속될 거야!\n"
.stringn "그러니까…\n"
.stringn "빨리 싸움을 끝내고 싶으니까…\n"
.stringn "\x0C01\x0701요파…!\n"
.stringn "\x0713미스트가…\n"
.stringn "죽는 건, 싫어.\n"
.stringn "난 이제…\n"
.stringn "아무도… 잃고 싶지 않아……\n"
.stringn "… … …\n"
.stringn "\x0701요파, 미안해!\n"
.stringn "미안해…\n"
.stringn "\x0713…흑 … …\n"
.stringn "\x0701요파가… 바뀐 줄 알았어.\n"
.stringn "상냥한 아이였는데,\n"
.stringn "사람의 죽음을… 아무렇지도 않게… 넘기면서\n"
.stringn "싸우는 줄 알았어……\n"
.stringn "미안해… 내가\n"
.stringn "요파의 마음을…\n"
.stringn "이해해 주지 못해서… 미안해…\n"
.stringn "싸우기 위해서 필사적이었구나…\n"
.stringn "발버둥치고 있었구나……\n"
.stringn "\x0713……나… 싸울 거야…\n"
.stringn "다시 한번… 모두와 함께\n"
.stringn "평화롭게 살기 위해서…\n"
.stringn "………싸울 거야……\n"
.stringn "\x0701응…\n"
.stringn "나도 싸울게…\n"
.stringn "둘이서… 같이……\n"
.stringn "힘…내자."
db 0
.align 4
//MYELL_8_LOFA_MIST_A

//0x26A60
Text_26A40:
.stringn "\x05FL|LOFA|MIST||\x0703……어디 보자.\n"
.stringn "\x0714…요파, 잠깐 괜찮아?\n"
.stringn "\x0703아, 응.\n"
.stringn "잠깐만, 활시위 좀\n"
.stringn "고쳐야 돼서.\n"
.stringn "안 하면 여차할 때 곤란하니까.\n"
.stringn "\x0714……\n"
.stringn "\x0C03\x0C03\x0701기다렸지!\n"
.stringn "무슨 일이야? 미스트.\n"
.stringn "\x0714요파, 이제\n"
.stringn "전장에 나가는 거 그만두지 않을래?\n"
.stringn "역시, 우리 같은\n"
.stringn "어린애가 싸우는 건… 좋지 않아.\n"
.stringn "\x0701…뭐…?\n"
.stringn "왜 갑자기 그런 말을 하는 거야?\n"
.stringn "\x0714제발!\n"
.stringn "오빠한테는 내가 말해 둘 테니까…\n"
.stringn "그러니까, 예전처럼\n"
.stringn "둘이서 다른 일을 도와…\n"
.stringn "\x0701…그렇구나,\n"
.stringn "미스트는 싸우는 게 무섭다고\n"
.stringn "했었지…\n"
.stringn "응, 전장에 나가지 않는 편이 좋겠어.\n"
.stringn "걱정하지 마!\n"
.stringn "미스트의 몫까지, 내가 싸울게.\n"
.stringn "\x0714아니야!\n"
.stringn "요파가 그만두지 않으면 의미가 없다고!!\n"
.stringn "\x0701그건 안 돼!\n"
.stringn "나는 남자니까…\n"
.stringn "적을 쓰러뜨리고, 모두를 지켜야 해…\n"
.stringn "\x0714쓰러뜨린다니… 그렇게 쉽게 말하지 마!\n"
.stringn "적도 한 명의 인간이라구!?\n"
.stringn "\x0701!!\n"
.stringn "\x0714요파, 알겠어?\n"
.stringn "적도… 우리와 같은 인간이야…\n"
.stringn "연습용 과녁 같은 게 아니라고……\n"
.stringn "\x0701………………알 게 뭐야…\n"
.stringn "\x0714요파!\n"
.stringn "\x0701알 게 뭐냐고! …난\n"
.stringn "그런 거 몰라!!\n"
.stringn "적은 우리를 상처 입히는 놈들이잖아!\n"
.stringn "난 그것들을 쓰러뜨리고 있을 뿐이야!\n"
.stringn "모두를 지키고 있을 뿐이라고!!\n"
.stringn "\x0714기다려, 요파!\n"
.stringn "……안 돼… 이대로는……"
db 0
.align 4
//MYELL_8_LOFA_MIST_B

//0x26750
Text_26730:
.stringn "\x05FL|MIST|LOFA||\x070-\x0C01\x0C13\x0701요파!\n"
.stringn "여기 있었구나?\n"
.stringn "\x0713미스트,\n"
.stringn "무슨 일이야?\n"
.stringn "날 찾고 있었어?\n"
.stringn "\x0701응.\n"
.stringn "요파랑 얘기하고 싶어서.\n"
.stringn "그때…\n"
.stringn "처음으로 전장에 나가서 싸운 이후로\n"
.stringn "요파랑 얘기할 기회가 없었으니까.\n"
.stringn "\x0713…무사해서 다행이야.\n"
.stringn "우리 둘 다…… 잘 살아 있네.\n"
.stringn "\x0701응…… 정말 다행이야…\n"
.stringn "\x0713나 있지, 무척 가슴이 두근거리고\n"
.stringn "손이 떨렸어.\n"
.stringn "\x0701나도……\n"
.stringn "주위에서 굉장한 소리가 나더니,\n"
.stringn "눈앞이 어지러워서……\n"
.stringn "……정말…… 무서웠어.\n"
.stringn "\x0713미스트는\n"
.stringn "역시 여자애구나.\n"
.stringn "나는 전혀 무섭지 않았는데.\n"
.stringn "긴장해서… 처음에는\n"
.stringn "잘 못 쐈지만\n"
.stringn "나중에는 제대로 적에게 맞혔다고!\n"
.stringn "\x0701어…?\n"
.stringn "\x0713다음 전투가 기다려져.\n"
.stringn "다음번에는 더 잘 싸울 수 있을 거야.\n"
.stringn "더 많이\n"
.stringn "적을 쓰러뜨려야지!\n"
.stringn "자, 좀 더 연습해야 돼.\n"
.stringn "다음에 보자, 미스트.\n"
.stringn "\x0701아, 요파!\n"
.stringn "………요파…"
db 0
.align 4
//MYELL_8_LOFA_MIST_C

//0x27BBC
Text_27B9C:
.stringn "\x05FL|LOFA|TAURONEO||\x0C01\x0713……역시, 나는……\n"
.stringn "착각하고 있었다.\n"
.stringn "할 수 있다면 가족에게……\n"
.stringn "한 마디로라도 사과하고 싶구나.\n"
.stringn "\x0701……있죠, 아저씨.\n"
.stringn "아저씨네 가족은\n"
.stringn "정말 어디 있는지 모르는 거예요?\n"
.stringn "아무런 단서도 없어요?\n"
.stringn "\x0713…………\n"
.stringn "……아내는 데인을 떠나\n"
.stringn "크리미아에 있는 친척에게로 갔단다.\n"
.stringn "아마도 크리미아 땅에서\n"
.stringn "살고 있겠지……\n"
.stringn "\x0701그렇구나! 그럼\n"
.stringn "만나러 가면……\n"
.stringn "\x0713……그럴 순 없다.\n"
.stringn "내가 이제 와서…… 무슨 낯으로\n"
.stringn "아이들을 만나러 갈 수 있겠느냐.\n"
.stringn "이제 와서 모습을 드러내 봤자……\n"
.stringn "아내와 아이들에게 피해만 줄 뿐이야.\n"
.stringn "\x0701그렇지 않아요!\n"
.stringn "그야, 저는……\n"
.stringn "저는, 아빠를 만나고 싶은걸요!\n"
.stringn "\x0713……요파.\n"
.stringn "\x0701형들한테는……\n"
.stringn "난 괜찮다고, 외롭지 않다고\n"
.stringn "항상 말했어요.\n"
.stringn "하지만 사실은, 아빠를 만나고 싶었어요.\n"
.stringn "만나서 여러 가질 얘기하고 싶었어요……\n"
.stringn "\x0713……\n"
.stringn "\x0701하지만 우리 아빠는\n"
.stringn "죽어 버렸으니까…… 이제 못 만나요.\n"
.stringn "하지만 아저씨는 아직 살아 있잖아요?\n"
.stringn "\x0713그렇……구나.\n"
.stringn "하지만 이미 늦었어……\n"
.stringn "\x0701늦지 않았어요……\n"
.stringn "그야 아저씨는 아직 살아 있으니까요.\n"
.stringn "그분들도 아직 아빠랑\n"
.stringn "만날 수 있어요……\n"
.stringn "그러니까, 만나러 가 줘요.\n"
.stringn "분명, 분명 기다리고 있을 거예요……\n"
.stringn "\x0713……\n"
.stringn "………요파……"
db 0
.align 4
//MYELL_8_LOFA_TAURONEO_A

//0x276F4
Text_276D4:
.stringn "\x05FL|LOFA|TAURONEO||\x0C01\x0713우리 집안은 대대로 데인의\n"
.stringn "무인으로서 이름을 떨치고 있었단다.\n"
.stringn "아버지도 나도, 데인의 장군으로서\n"
.stringn "데인 왕가를 모셔 왔지.\n"
.stringn "그것이 우리 가문의 자랑이었다.\n"
.stringn "\x0701그럼, 조쉬씨도……?\n"
.stringn "\x0713나는 당연하다는 듯이 아들 조쉬를\n"
.stringn "데인군에 입대시킬 생각으로 키웠지.\n"
.stringn "그리고 조쉬도 내 기대에\n"
.stringn "응하려고 해 주었다……고, 생각한단다.\n"
.stringn "최연소로 기사 훈장을 받고,\n"
.stringn "친위대에 임명되었으니까.\n"
.stringn "하지만……\n"
.stringn "\x0701……어떻게 됐는데요?\n"
.stringn "\x0713아슈나드의 측근으로 출진했다가……\n"
.stringn "빈사 상태로 중상을\n"
.stringn "입고 귀환했다.\n"
.stringn "목숨은 건졌지만……\n"
.stringn "……두 번 다시는 걸을 수 없게 되어 버렸지.\n"
.stringn "\x0701…………그럴 수가……\n"
.stringn "\x0713아내는 미친 듯이 한탄했다.\n"
.stringn "이런 일이 두 번 다시 일어나선 안 된다며\n"
.stringn "내가 군에서 물러나고,\n"
.stringn "평화로운 생활을 하길 원했지.\n"
.stringn "하지만 나는 승낙할 수 없었다.\n"
.stringn "우리 집안은 대대로 장군으로서\n"
.stringn "이름을 떨쳐 왔으니까.\n"
.stringn "이대로 군을 그만두고 도망가기에는\n"
.stringn "지금까지 이어져 온 우리 집안의\n"
.stringn "무인으로서의 이름이 허락하지 않았지.\n"
.stringn "나는 아직 나이가 어린 차남을 길러,\n"
.stringn "데인군의 장수로 뒤를 잇게 해\n"
.stringn "체면을 지키려고 했다.\n"
.stringn "\x0701그러면 안 되죠……\n"
.stringn "\x0713그러게나 말이다……\n"
.stringn "하지만 그때의 나는 어리석었다.\n"
.stringn "그런 것조차도 모를 정도로.\n"
.stringn "……깨닫고 나니,\n"
.stringn "아내와 아이들은 집을 떠나고 없더구나.\n"
.stringn "그리고 나는……\n"
.stringn "무수한 훈장이 달린 저택에서\n"
.stringn "혼자 살아가게 됐지.\n"
.stringn "…………몇 년이고……"
db 0
.align 4
//MYELL_8_LOFA_TAURONEO_B

//0x273B0
Text_27390:
.stringn "\x05FL|LOFA|TAURONEO||\x0C01\x0713!\n"
.stringn "조쉬……?\n"
.stringn "\x0701응……?\n"
.stringn "\x0713……아니, 그럴 리가 없지.\n"
.stringn "미안하군, 사람을 잘못 봤다.\n"
.stringn "……소년, 네 이름은?\n"
.stringn "\x0701요파예요.\n"
.stringn "\x0713요파, 너 같은 어린애가\n"
.stringn "왜 이런 곳에 있는 거냐?\n"
.stringn "전장은 어린애가 있을 곳이 아니다.\n"
.stringn "너의 부모님께선 왜\n"
.stringn "이런 일을 허락하신 거지?\n"
.stringn "\x0701저…… 부모님이 없어요.\n"
.stringn "엄마는 집을 나갔고,\n"
.stringn "아빠는 죽었으니까……\n"
.stringn "\x0713그랬던…… 건가.\n"
.stringn "미안하다.\n"
.stringn "괴로운 일을 생각나게 했구나.\n"
.stringn "\x0701괜찮아요.\n"
.stringn "지금은 모두와 함께니까.\n"
.stringn "……아저씨,\n"
.stringn "저 누구 닮았어요?\n"
.stringn "\x0713내…… 아들을 닮았다.\n"
.stringn "조쉬는 장남의 이름이지.\n"
.stringn "하지만 조쉬는 벌써 성인이란다.\n"
.stringn "너 같은 소년이었던 건\n"
.stringn "벌써 몇 년 전의 이야기인데……\n"
.stringn "그런데도 잘못 보다니……\n"
.stringn "나도 망령이 든 것 같군.\n"
.stringn "\x0701그 조쉬씨는\n"
.stringn "지금 어디에 있는데요?\n"
.stringn "\x0713……모른다.\n"
.stringn "\x0701네?\n"
.stringn "\x0713나는 아내와 이혼했거든.\n"
.stringn "그때 이후로\n"
.stringn "벌써 몇 년이나 만나지 못했지……"
db 0
.align 4
//MYELL_8_LOFA_TAURONEO_C

//0x28548
Text_28528:
.stringn "\x05FL|ULYSSES|LUCHINO||\x070-\x0C01\x0C13\x0701루키노 공, 오늘만큼은\n"
.stringn "달콤한 대답을\n"
.stringn "들려주시길.\n"
.stringn "\x0713율리시스 백작…\n"
.stringn "나는 당신의 그\n"
.stringn "까불거리는 태도가 겉모습뿐이라는 거 알아.\n"
.stringn "크리미아의 충신으로서…\n"
.stringn "의지하고 있어.\n"
.stringn "그래… 분하지만 인정할게.\n"
.stringn "나는 당신을 좋게 생각하고 있어.\n"
.stringn "\x0701그럼, 제 마음을\n"
.stringn "받아 주시는 거군요?\n"
.stringn "\x0713…그래.\n"
.stringn "이 전쟁이 끝나고……\n"
.stringn "크리미아가 무사히 부흥한다면\n"
.stringn "생각해 볼게.\n"
.stringn "\x0701오오, 루키노!\n"
.stringn "내가 가장 사랑하는 그대여!!\n"
.stringn "\x0713율리시스…\n"
.stringn "정말 미워할 수 없는 사람이야.\n"
.stringn "아, 이런.\n"
.stringn "엘린시아님의 준비를\n"
.stringn "도우러 갈 시간이네.\n"
.stringn "\x0701기, 기다려 주시길. 루키노!\n"
.stringn "오늘 저녁의 예정은?\n"
.stringn "괜찮다면 저와 함께…\n"
.stringn "\x0713미안해.\n"
.stringn "엘린시아님의 용무가 있어.\n"
.stringn "당분간 시간은 낼 수 없겠네.\n"
.stringn "\x0701이런… 아직도\n"
.stringn "앞길이 막막하군요."
db 0
.align 4
//MYELL_8_LUCHINO_ULYSSES_A

//0x282B8
Text_28298:
.stringn "\x05FL|LUCHINO|ULYSSES||\x0701율리시스 백작!\n"
.stringn "어, 어디 있어!?\n"
.stringn "\x071-\x0713오오, 루키노 공…\n"
.stringn "당신답지 않게\n"
.stringn "뭘 그리 당황하면서…\n"
.stringn "\x0701사, 상처는?\n"
.stringn "괜찮은 거야!?\n"
.stringn "\x0713흠, 제 몸에\n"
.stringn "딱히 불편한 점은\n"
.stringn "없습니다만?\n"
.stringn "\x0701……그래…?\n"
.stringn "얼빠진 모습을 한\n"
.stringn "콧수염 난 광대가\n"
.stringn "크게 다쳤다고 들어서…\n"
.stringn "틀림없이 당신일 거라고 생각했는데…\n"
.stringn "착각한 모양이네……\n"
.stringn "\x0713…루키노 공,\n"
.stringn "저를 너무나 걱정한 나머지…\n"
.stringn "그렇게나 당황했던 겁니까.\n"
.stringn "이것 참 귀엽기가 따로 없군요.\n"
.stringn "\x0701뭐!?\n"
.stringn "아, 아니야…\n"
.stringn "\x0713이젠 숨겨도 소용없습니다.\n"
.stringn "그대의 마음,\n"
.stringn "확실히 받았으니 말이지요.\n"
.stringn "\x0701아니라고 했잖아!?\n"
.stringn "\x0713부정하면 부정할수록\n"
.stringn "겉으로 드러나는 것이 사람의 마음이죠.\n"
.stringn "\x0701정말! 사람 말 좀 들으라고!!"
db 0
.align 4
//MYELL_8_LUCHINO_ULYSSES_B

//0x28020
Text_28000:
.stringn "\x05FL|ULYSSES|LUCHINO||\x070-\x0C01\x071-\x0713어머 율리시스 백작.\n"
.stringn "안녕하신지.\n"
.stringn "\x0701오오… 루키노 공.\n"
.stringn "그 아름다운 손을 빌려,\n"
.stringn "인사를 전하는\n"
.stringn "영예를 안겨 주실 수 있겠습니까?\n"
.stringn "\x0713사양할게.\n"
.stringn "방금 전까지 검을 손질해서\n"
.stringn "손가락 끝이 기름투성이거든.\n"
.stringn "\x0701저는 전혀 상관없습니다만?\n"
.stringn "\x0713내가 상관있어.\n"
.stringn "미안하지만 포기하도록 해.\n"
.stringn "\x0701후우, 쌀쌀맞게 대해지니\n"
.stringn "더욱 마음이 끌리고…\n"
.stringn "도망칠 기미를 보이니\n"
.stringn "더욱 쫓고 싶어지는 것이 인지상정.\n"
.stringn "언제까지 이 가련한\n"
.stringn "사랑의 하수인을 사로잡고 있을 셈입니까.\n"
.stringn "제 마음의 주인 루키노 공.\n"
.stringn "\x0713내가… 다른 귀부인들처럼\n"
.stringn "그런 농간에 넘어갈 거라고\n"
.stringn "생각하지 마.\n"
.stringn "이제 그만 포기하는 게 어때?\n"
.stringn "끈질긴 남자는 미움받기 쉬운 법이야.\n"
.stringn "\x0701이런 이런, 이거 매섭군요."
db 0
.align 4
//MYELL_8_LUCHINO_ULYSSES_C

//0x292AC
Text_2928C:
.stringn "\x05FL|STELLA|?|MAKAROV||\x0705……\n"
.stringn "\x0718이~봐.\n"
.stringn "스텔라씨!\n"
.stringn "\x0705!\n"
.stringn "\x0C23\x0C05\x0C05\x0701안녕하세요.\n"
.stringn "마카로프님.\n"
.stringn "\x0723이거, 돌려줄게.\n"
.stringn "\x0701…이 펜던트에\n"
.stringn "무슨 문제라도 있었나요?\n"
.stringn "\x0723아니, 굉장히\n"
.stringn "좋은 물건이었어.\n"
.stringn "최소 5000골드는\n"
.stringn "받아낼 수 있을 것 같던데…\n"
.stringn "\x0701그렇다면 어째서…\n"
.stringn "\x0723고물상에 들어갔더니\n"
.stringn "여동생하고 딱 마주쳐 버렸거든.\n"
.stringn "어디서 구했냐, 라든가\n"
.stringn "훔친 건 아니냐, 라든가…\n"
.stringn "여러 가지로 추궁을 받아서 말이야…\n"
.stringn "\x0701이건… 제가\n"
.stringn "마카로프님께 드린 거예요.\n"
.stringn "\x0723물론 그 말대로야. 하지만…\n"
.stringn "여자를 협박하다니 최악이야!\n"
.stringn "라면서 울어 버리더라고…\n"
.stringn "그래서 뭐, 포기하기로 했어.\n"
.stringn "\x0701그렇군요…\n"
.stringn "알겠습니다.\n"
.stringn "\x0723그건 그렇고,\n"
.stringn "너도 참 복 받았다.\n"
.stringn "그런 값비싼 펜던트를\n"
.stringn "아까운 기색도 없이 남에게 주다니.\n"
.stringn "우리 여동생은 싸구려 하나도\n"
.stringn "못 사는 처지인데 말이지.\n"
.stringn "아~아. 여신님은 불공평해.\n"
.stringn "귀족들 편만 들고.\n"
.stringn "\x0701…죄…죄송합니다……\n"
.stringn "\x0723아니, 딱히\n"
.stringn "너한테 사과받고 싶은 게…\n"
.stringn "\x0701이 펜던트는…\n"
.stringn "그렇게나 비싼 물건이었군요?\n"
.stringn "…저… 이건… 정말 좋아했던 할머님의\n"
.stringn "유품이어서 걸고 있었을 뿐……\n"
.stringn "아무것도… 몰랐는데……\n"
.stringn "\x0723켁! 유품!?\n"
.stringn "어, 어째서 그렇게 소중한 걸\n"
.stringn "나 같은 놈에게…\n"
.stringn "\x0701이 펜던트와 떨어지더라도…\n"
.stringn "할머님과의 추억은…\n"
.stringn "제 가슴속에 남아 있습니다.\n"
.stringn "그러니까… 곤란하신 분의\n"
.stringn "도움이 되는 편이 낫다고 생각했어요.\n"
.stringn "\x0723너… 너 정말……\n"
.stringn "미안! 정말로 미안했어!!\n"
.stringn "나는 도박 때문에\n"
.stringn "너한테서 돈을 뜯어내려고 했는데…\n"
.stringn "진심으로 반성하고 있어.\n"
.stringn "죄송합니다! 용서해 주세요!!\n"
.stringn "\x0701그럴 수가…\n"
.stringn "마카로프님, 저는\n"
.stringn "아무것도 신경 쓰지 않아요.\n"
.stringn "\x0723스텔라씨… 당신\n"
.stringn "여신님보다도 상냥한 여자구나.\n"
.stringn "\x0701………그…\n"
.stringn "그렇지 않아요.\n"
.stringn "\x0723아니. 이젠 진짜로\n"
.stringn "눈부시기 시작했어.\n"
.stringn "\x0701놀리지 마세요.\n"
.stringn "마카로프님 같은\n"
.stringn "멋진 남성분께…\n"
.stringn "그런 식으로 보여 지다니…\n"
.stringn "…저…… 부끄러워요…\n"
.stringn "\x0723어?\n"
.stringn "멋지다니… 내가?\n"
.stringn "\x0701어, 어멋…\n"
.stringn "…나도 참… 상스럽게…!\n"
.stringn "시, 실례하겠습니다!!\n"
.stringn "\x0723…………………\n"
.stringn "……저렇게 자라 오면\n"
.stringn "남자 보는 눈도 안 자라는 건가.\n"
.stringn "불쌍하구만……"
db 0
.align 4
//MYELL_8_MAKAROV_STELLA_A_a

