.stringn "\x0701………그…\n"
.stringn "그렇지 않아요.\n"
.stringn "\x0723아니. 이젠 진짜로\n"
.stringn "눈부시기 시작했어.\n"
.stringn "\x0701놀리지 마세요.\n"
.stringn "마카로프님 같은\n"
.stringn "멋진 남성분께…\n"
.stringn "그런 식으로 보여 지다니…\n"
.stringn "…저…… 부끄러워요…\n"
.stringn "\x0723어?\n"
.stringn "멋지다니… 내가?\n"
.stringn "\x0701어, 어멋…\n"
.stringn "…나도 참… 상스럽게…!\n"
.stringn "시, 실례하겠습니다!!\n"
.stringn "\x0723…………………\n"
.stringn "……저렇게 자라 오면\n"
.stringn "남자 보는 눈도 안 자라는 건가.\n"
.stringn "불쌍하구만……"
db 0
.align 4
//MYELL_8_MAKAROV_STELLA_A_b

//0x28E88
Text_28E68:
.stringn "\x05FL|MAKAROV|STELLA||\x0C01\x071-\x0713아, 안녕하세요.\n"
.stringn "마카로프님.\n"
.stringn "\x0701안녕, 스텔라씨.\n"
.stringn "당신하고는 자주 만나네.\n"
.stringn "꽤나 인연이 있을지도 모르겠는걸~\n"
.stringn "\x0713그, 그런가요?\n"
.stringn "그렇다면… 영광입니다.\n"
.stringn "\x0701인연이라고 하니\n"
.stringn "조금 부탁이 있는데 말이야.\n"
.stringn "\x0713뭔가요?\n"
.stringn "제가 할 수 있는 일이라면 할게요.\n"
.stringn "\x0701돈 좀 빌려주면 안 될까?\n"
.stringn "\x0713돈…이요?\n"
.stringn "\x0701그래, 아주 조금이면 되는데.\n"
.stringn "어떻게 안 되려나?\n"
.stringn "\x0713……어떡하죠?\n"
.stringn "저, 돈은 1골드도\n"
.stringn "가지고 있지 않아요.\n"
.stringn "\x0701단 1골드도?\n"
.stringn "이 군에서 받은 월급은\n"
.stringn "어디다 썼길래.\n"
.stringn "\x0713마을에 나갔을 때…\n"
.stringn "무척 곤란해 보이는 분이 계시길래…\n"
.stringn "그분께 드렸어요.\n"
.stringn "\x0701우왓, 말도 안 돼.\n"
.stringn "어차피 베풀 거라면 남이 아니라\n"
.stringn "아는 사람에게 해 주면 좋을 텐데.\n"
.stringn "나 참…\n"
.stringn "\x0713죄, 죄송합니다.\n"
.stringn "마카로프님께서 곤란하실 거라고는\n"
.stringn "생각하지 못해서…\n"
.stringn "\x0701으~… 알았어.\n"
.stringn "그럼 다른 사람한테 빌려야겠다.\n"
.stringn "\x0713자, 잠깐만요.\n"
.stringn "\x0701음~?\n"
.stringn "\x0713이걸로는 안 될까요?\n"
.stringn "\x0701오! 뭐야\n"
.stringn "딱 봐도 비싸 보이는 펜던트잖아!\n"
.stringn "이거, 받아도 되는 거야?\n"
.stringn "\x0713네.\n"
.stringn "\x0701크~ 고마워!\n"
.stringn "당신 좋은 여자구나.\n"
.stringn "그럼 이만! 또 보자!!\n"
.stringn "\x0713………"
db 0
.align 4
//MYELL_8_MAKAROV_STELLA_B

//0x28828
Text_28808:
.stringn "\x05FL|STELLA|MAKAROV||\x070-\x0C01\x0C13\x0701안녕하세요, 기사님.\n"
.stringn "\x0713음? 그, 그래…\n"
.stringn "나한테 인사하는 거야?\n"
.stringn "\x0701네.\n"
.stringn "저는 스텔라라고 합니다.\n"
.stringn "기사님의 성함은?\n"
.stringn "\x0713기사님이라고 불릴 정도는 아닌데…\n"
.stringn "나는 마카로프야.\n"
.stringn "잘 부탁해, 스텔라씨.\n"
.stringn "\x0701저야말로요.\n"
.stringn "그리고… 마카로프님.\n"
.stringn "이걸 떨어뜨리셨더라고요.\n"
.stringn "\x0713어라, 어느새…\n"
.stringn "\x0701예쁜 꽃이네요.\n"
.stringn "\x0713그치? 근처에 피어 있었던 것 치곤\n"
.stringn "괜찮지 않아?\n"
.stringn "\x0701어머, 직접 따신 건가요?\n"
.stringn "마카로프님은 무척 우아한\n"
.stringn "취미를 가지고 계시군요.\n"
.stringn "\x0713아니, 그게.\n"
.stringn "여동생 기분 풀어 주려고 조금 따 왔어.\n"
.stringn "\x0701자상한 오라버니시네요.\n"
.stringn "아차, 꽃이 시들기 전에\n"
.stringn "여동생분께 가져다 드려야죠.\n"
.stringn "여기요.\n"
.stringn "\x0713아, 한 송이 정도는 가져도 돼.\n"
.stringn "\x0701…네?\n"
.stringn "\x0713주워 준 보답이야.\n"
.stringn "너랑 잘 어울리는 것 같고.\n"
.stringn "그럼 이만 실례할게~\n"
.stringn "\x0701가, 감사합니다!\n"
.stringn "…………마카로프님."
db 0
.align 4
//MYELL_8_MAKAROV_STELLA_C_a

//0x28B58
