//MYELL_8_MAKAROV_STELLA_C_b

//0x2AD9C
Text_2AD7C:
.stringn "\x05FL|MAKAROV|ULYSSES||\x0C01\x071-\x0713왜 그러나, 마카로프?\n"
.stringn "\x0701………\n"
.stringn "\x0713자네의 열정과 끈기에 지친 내가\n"
.stringn "이렇게 함께 와 즐기고\n"
.stringn "도박장을 뒤로한 지금…\n"
.stringn "무엇이 자네의 얼굴을\n"
.stringn "찌푸리게 만드는 거지?\n"
.stringn "\x0701율리시스…\n"
.stringn "당신 나한테 거짓말했지?\n"
.stringn "\x0713글쎄?\n"
.stringn "내가 자네에게 거짓말을 할 이유가\n"
.stringn "있을 리 없지 않나.\n"
.stringn "\x0701도박장 가 본 적\n"
.stringn "없다고 했잖아.\n"
.stringn "근데 당신 엄청\n"
.stringn "익숙해 보였고… 게다가 잘하던데.\n"
.stringn "나는 망했는데,\n"
.stringn "당신은 대박났잖아.\n"
.stringn "얼굴이 안 썩는 게 더 이상하다고.\n"
.stringn "\x0713거짓말은 하지 않았네.\n"
.stringn "도박장에 발을 들여놓는 건\n"
.stringn "내 생애에 있어\n"
.stringn "이번이 처음이었으니.\n"
.stringn "단지… 귀족들의 유희에도\n"
.stringn "비슷한 도박이 있는데,\n"
.stringn "나는 그것에 정통하다네.\n"
.stringn "그것뿐이야.\n"
.stringn "\x0701젠장, 부자가\n"
.stringn "돈을 더 잘 벌다니\n"
.stringn "세상은 잘못되어 있어엇!\n"
.stringn "\x0713내게 있어… 손에 넣은\n"
.stringn "골드는 큰 의미가 없네.\n"
.stringn "자네가 이번 판은 운에 달렸다고\n"
.stringn "내게 말했었지.\n"
.stringn "하지만 승부에서 압승했다.\n"
.stringn "훌륭한 결과를 얻을 수 있었으니\n"
.stringn "나는 지극히 만족하고 있네.\n"
.stringn "\x0701그럼, 돈은 필요 없는 거야?\n"
.stringn "그렇다면 내가 받아가도…\n"
.stringn "\x0713그렇게는 안 되지.\n"
.stringn "전쟁에는 일단 돈이 드는 법.\n"
.stringn "저축은 많을수록 좋으니까.\n"
.stringn "\x0701…걱정하지 않아도\n"
.stringn "이번 전쟁은 크리미아의 승리일걸.\n"
.stringn "\x0713호오? 어째서 그리 생각하는지\n"
.stringn "들려줄 수 있겠나?\n"
.stringn "\x0701당신같이 운이 좋은 남자가\n"
.stringn "곁에 있잖아.\n"
.stringn "두 번이나 질 리가 없지.\n"
.stringn "\x0713과연.\n"
.stringn "자네에게는 선견지명이 있는 것 같군.\n"
.stringn "\x0701그러니까, 돈은 나한테…\n"
.stringn "\x0713크리미아가 이 전쟁에서 승리한다면\n"
.stringn "내가 얼마든지\n"
.stringn "자네 지갑을 돈으로 축여 주겠네.\n"
.stringn "\x0701저, 정말이야!?\n"
.stringn "\x0713나는 할 수도 없는 약속은 하지 않는다네.\n"
.stringn "거짓말도 할 필요가 없지.\n"
.stringn "돈을 벌 수단은\n"
.stringn "얼마든지 갖고 있으니.\n"
.stringn "\x0701조, 좋~아!\n"
.stringn "일생일대의 큰 도박이라 생각하고\n"
.stringn "힘내 봐야지."
db 0
.align 4
//MYELL_8_MAKAROV_ULYSSES_A

//0x2A910
Text_2A8F0:
.stringn "\x05FL|MAKAROV|ULYSSES||\x070-\x0C01\x071-\x0C13\x0701저기, 율리시스 공.\n"
.stringn "나하고 당신은 이미 친구 맞지?\n"
.stringn "\x0713물론이다.\n"
.stringn "몇 번이나 술잔을 기울이며…\n"
.stringn "서로의 가문 내력도 이야기했지.\n"
.stringn "나와 자네가 우호를 쌓는 것에\n"
.stringn "더 이상 아무런 장애도 없네.\n"
.stringn "\x0701그럼 지금부터 같이\n"
.stringn "재미있는 놀이를 하러 가자고.\n"
.stringn "율리시스는 모를 만한\n"
.stringn "서민들의 놀이인데 말이지.\n"
.stringn "이게 해 보면 푹 빠진다니까.\n"
.stringn "\x0713오호. 서민의 유희라…\n"
.stringn "그래서, 그건\n"
.stringn "어떠한 것이지?\n"
.stringn "\x0701단순해.\n"
.stringn "돈을 걸고, 뒤집혀 있는 나무패에\n"
.stringn "그려져 있는 무늬를 맞추는 거야.\n"
.stringn "정답이라면 배당금을 받고,\n"
.stringn "빗나가면 돈을 잃지. 그것뿐이야.\n"
.stringn "\x0713과연,\n"
.stringn "마카로프는 나를\n"
.stringn "도박장으로 이끌려고 하는 건가.\n"
.stringn "\x0701어어 자, 잠깐…\n"
.stringn "당신 설마\n"
.stringn "도박장에 가 본 적 있어?\n"
.stringn "\x0713아니, 지식으로만 알고 있을 뿐\n"
.stringn "실제로 발을 들인 적은\n"
.stringn "없다네.\n"
.stringn "흠, 흥미가 없지는 않지.\n"
.stringn "\x0701그럼 내가 안내할 테니까\n"
.stringn "가 보자구.\n"
.stringn "당신 정도의 부자라면\n"
.stringn "실컷 놀아도 거스름돈이 남으니까\n"
.stringn "처음이라고 걱정할 필요도 없고.\n"
.stringn "\x0713…아니, 사양하도록 하겠네.\n"
.stringn "\x0701뭐어!? 왜?\n"
.stringn "\x0713조국이 위험에 처했는데\n"
.stringn "도박장에서 게으름을 피울 순 없지.\n"
.stringn "그럼, 슬슬 실례하겠네.\n"
.stringn "자네도 너무 흥겨운 나머지\n"
.stringn "도를 넘지 않도록 주의하게나.\n"
.stringn "\x0701아아! …가 버렸다.\n"
.stringn "내 지갑……"
db 0
.align 4
//MYELL_8_MAKAROV_ULYSSES_B

//0x2A1FC
Text_2A1DC:
.stringn "\x05FL|ULYSSES|MAKAROV|?|CRIMEA1||\x0C05\x071-\x0713흐음~ 이 군은\n"
.stringn "광대를 부를 정도의 여유가\n"
.stringn "있었구나.\n"
.stringn "그 데인을 상대로 싸우고 있으니\n"
.stringn "좀 더 살벌할 줄 알았는데.\n"
.stringn "\x0705…흠.\n"
.stringn "\x0701지금의 언동은 혹시 나를 향해\n"
.stringn "말한 것인가?\n"
.stringn "베그니온의 용병 기사 마카로프 공.\n"
.stringn "\x0713우왓!?\n"
.stringn "어, 어떻게 광대가\n"
.stringn "내 이름을… 아니\n"
.stringn "그렇구만.\n"
.stringn "너, 그런 묘기를 부리는구나?\n"
.stringn "알아맞히는 게 특기인 거지?\n"
.stringn "그렇다면 꽤 솜씨가 좋은걸.\n"
.stringn "지금 건 정답이었거든.\n"
.stringn "\x0701나를 광대라 평하는 건가?\n"
.stringn "그럴 수 있네.\n"
.stringn "한때의 모습이긴 하나, 일시적으로\n"
.stringn "그것을 생업으로 삼고 있었으니.\n"
.stringn "아아, 그 시절을 떠올리니\n"
.stringn "앞으로 닥칠 고난도 아무렇지 않구나.\n"
.stringn "조국 해방의 여명까지,\n"
.stringn "내가 이 몸을\n"
.stringn "어떻게 변화시켰는지…\n"
.stringn "\x0713하하, 당신\n"
.stringn "재미있는 사람이구만.\n"
.stringn "오늘 밤에 내 천막으로\n"
.stringn "술이라도 마시러 오지 않을래?\n"
.stringn "\x0701매력적인 제안이지만,\n"
.stringn "오늘 밤은 선약이 있다네.\n"
.stringn "다음 기회 때 이쪽에서\n"
.stringn "권유하려고 생각하는데\n"
.stringn "그걸로 어떻겠나?\n"
.stringn "\x0713그게 좋다면\n"
.stringn "나는 상관없어.\n"
.stringn "\x0701의견이 일치한 것 같군.\n"
.stringn "그럼 실례.\n"
.stringn "\x0713하~ 지금까지\n"
.stringn "본 적 없는 느낌의 남자인걸.\n"
.stringn "다음에 만나는 게 기대되는구만.\n"
.stringn "\x0728이봐! 거기 너!!\n"
.stringn "\x0713응~?\n"
.stringn "\x0C11\x0C34\x0711나한테 볼일이라도 있어?\n"
.stringn "크리미아 병사님.\n"
.stringn "\x0734김빠지게 대답하지 마라!\n"
.stringn "너도 지금은 크리미아군에\n"
.stringn "소속되어 있지 않나!?\n"
.stringn "\x0711아, 그렇구나.\n"
.stringn "아이크씨가 크리미아군의\n"
.stringn "총대장이 되었으니까,\n"
.stringn "나도 자동으로 크리미아병이 된 거구만.\n"
.stringn "하하, 이제부터 당신이랑 동료네.\n"
.stringn "\x0734웃기는 남자로군…\n"
.stringn "아이크 장군님 직속\n"
.stringn "용병단의 일원이니\n"
.stringn "이번엔 봐주겠다만……\n"
.stringn "한 가지 충고해 주지.\n"
.stringn "네놈이 방금까지 이야기를 나눈 상대는\n"
.stringn "페일 백작님이시다!\n"
.stringn "\x0711뭐?\n"
.stringn "\x0734페일 백작 율리시스님은,\n"
.stringn "돌아가신 왕제 전하의 필두 문관으로\n"
.stringn "근무했을 정도로\n"
.stringn "크리미아 왕궁의 중진이시다.\n"
.stringn "네놈 따위가 함부로\n"
.stringn "입을 놀릴 상대가 아니야.\n"
.stringn "알았다면 앞으로는\n"
.stringn "태도를 고치도록.\n"
.stringn "알겠나!?\n"
.stringn "\x0711그 광대가…\n"
.stringn "크리미아의 귀족이라고?\n"
.stringn "………그렇다면,\n"
.stringn "좋은 돈줄이 될지도 모르겠는걸.\n"
.stringn "친해져서 손해 볼 건 없지."
db 0
.align 4
//MYELL_8_MAKAROV_ULYSSES_C

//0x2BCB4
Text_2BC94:
.stringn "\x05FL|TANIS|MARCIA||\x0C01\x0713그러니까 그……\n"
.stringn "벌한다고 하셨던 건\n"
.stringn "봐주셨으면 좋겠어요……\n"
.stringn "\x0701탈영엔 가장 무거운 벌을 내리는 게 철칙이다.\n"
.stringn "네게만 특례를 줄 수는 없어.\n"
.stringn "\x0713하아……\n"
.stringn "부대장님은 나빠요……\n"
.stringn "\x0701왜 내가 나쁜 것이냐!\n"
.stringn "나는 네가 탈영했으니까……\n"
.stringn "\x0713그야, 부대장님은\n"
.stringn "항상 그렇잖아요.\n"
.stringn "시그룬 대장님과는 다르게,\n"
.stringn "우리에 대해 칭찬해 주신 적은\n"
.stringn "한 번도 없었고……\n"
.stringn "이쪽 사정은 봐 주고\n"
.stringn "계신 것 같지도 않고……\n"
.stringn "\x0701정말이지, 답답한 녀석이군.\n"
.stringn "왜 내가 너에게\n"
.stringn "이렇게까지 말하고 있다고 생각하나!\n"
.stringn "\x0713네?\n"
.stringn "\x0701다른 단원이었다면 이렇게까지 안 한다.\n"
.stringn "마샤, 난\n"
.stringn "네게 기대하고 있었다.\n"
.stringn "너라면 장래에 대장님이나 내 뒤를 이어\n"
.stringn "기사단을 맡아 줄 거라고 생각했는데.\n"
.stringn "\x0713네에!?\n"
.stringn "왜, 왜 갑자기\n"
.stringn "그런 말씀을 하시는 거예요?\n"
.stringn "베그니온에 있었을 때\n"
.stringn "그런 말은 한 마디도……\n"
.stringn "\x0701당연하지!\n"
.stringn "내 입으로 그런 말을 할 수 있을 것 같나.\n"
.stringn "하지만 어쩔 수 없지.\n"
.stringn "내가 대장님께 진언해서,\n"
.stringn "기사단에 복귀할 수 있도록 해 주마.\n"
.stringn "탈영은 불문에 부치겠다. 그러니 돌아와라.\n"
.stringn "\x0713부대장님……\n"
.stringn "가……감사합니다!"
db 0
.align 4
//MYELL_8_MARCIA_TANIS_A

//0x2B884
Text_2B864:
.stringn "\x05FL|TANIS|MARCIA||\x0701마샤!\n"
.stringn "\x0713히익!?\n"
.stringn "부, 부대장님……!\n"
.stringn "\x0701이전의 상관을 상대로\n"
.stringn "한심한 비명을 지르지 마라.\n"
.stringn "\x0713그, 그치만 부대장님……\n"
.stringn "아직도 화나셨잖아요?\n"
.stringn "\x0701물론이다.\n"
.stringn "마샤, 네가 기사단을\n"
.stringn "떠난 이유는 뭐지?\n"
.stringn "너는 임무의 엄격함을 견디지 못해\n"
.stringn "도망갈 정도로 연약한 자는 아니다.\n"
.stringn "이성과의 연애 때문에\n"
.stringn "문제를 일으킬 만한 여자도 아니지.\n"
.stringn "왜 나에게 한 마디 상의도 없이 떠났나?\n"
.stringn "\x0713사실은 그~……\n"
.stringn "오빠가 빚을 많이 져서……\n"
.stringn "행방불명이 된 상태였거든요.\n"
.stringn "\x0701빚……?\n"
.stringn "\x0713그래서 대신 제가 있던\n"
.stringn "병영에 빚쟁이가 찾아오게 돼서\n"
.stringn "오빠의 행방을 찾으려고 했어요.\n"
.stringn "그러다가 아이크씨 일행과 만나서,\n"
.stringn "해적으로부터 도움을 받은 것을 계기로\n"
.stringn "함께하게 되었습니다.\n"
.stringn "그치만 오빠는 역시 찾지 못했기에……\n"
.stringn "\x0701……\n"
.stringn "\x0713그래서, 아이크씨를 따라가서\n"
.stringn "여기저기 여행하다 보면\n"
.stringn "오빠의 행방을 알 수 있을까 싶다가\n"
.stringn "지금에 이르렀습니다.……\n"
.stringn "\x0701……과연. 사정은 알았다.\n"
.stringn "설마 빚을 지고서 야반도주라니……\n"
.stringn "과거의 상관으로서,\n"
.stringn "다소라도 동정을 금할 길이 없군.\n"
.stringn "\x0713그, 그럼……\n"
.stringn "\x0701하지만 탈영은 탈영이다.\n"
.stringn "여기서의 임무가 끝나면, 너를\n"
.stringn "벌할 수밖에 없어.\n"
.stringn "\x0713그, 그럴 수가아……"
db 0
.align 4
//MYELL_8_MARCIA_TANIS_B

//0x2B3BC
Text_2B39C:
.stringn "\x05FL|TANIS|MARCIA||\x0C01\x0713어……어라?\n"
.stringn "\x0701……오랜만이군, 마샤.\n"
.stringn "\x0713타, 타니스 부대장님!?\n"
.stringn "어……어째서 여기에?\n"
.stringn "\x0701그건 내가 할 말이다.\n"
.stringn "나는 친위 기사단 부대장으로서\n"
.stringn "칙명을 받아 이 임무를 맡고 있지.\n"
.stringn "설마 이곳에서\n"
.stringn "과거의 부하와 만날 줄이야.\n"
.stringn "\x0713그, 그랬군요!\n"
.stringn "데인에 온 이후로 부대장님이 함께 계셨다니\n"
.stringn "전혀 눈치채지 못했어요!\n"
.stringn "엄청난 우연이네요, 네!\n"
.stringn "\x0701그래. 귀여운 부하와\n"
.stringn "드디어 만나게 되어서 기쁘군.\n"
.stringn "나는 오랫동안\n"
.stringn "네 행방을 쫓고 있었으니 말이지……\n"
.stringn "\x0713부, 부대장님,\n"
.stringn "눈이 안 웃고 있는……데요……\n"
.stringn "혹시…… 화나셨나요?\n"
.stringn "\x0701그래, 네 말대로다.\n"
.stringn "나는 매우 화가 많이 났지.\n"
.stringn "무단으로 베그니온 천마 기사단을 떠난\n"
.stringn "탈영병 마샤에게 어떤 벌을\n"
.stringn "내릴까 생각 중이다.\n"
.stringn "\x0713타, 탈영이라니요!\n"
.stringn "제대로 『그만두겠습니다』라고\n"
.stringn "편지에 써서 남기……\n"
.stringn "\x0701네가 어린애냐!\n"
.stringn "그런 휘갈겨 쓴 편지 한 장으로\n"
.stringn "제대가 허용될 줄 안 거냐!\n"
.stringn "베그니온 기사단원의 무게를 알아라!\n"
.stringn "\x0713죄, 죄……죄송합니다!\n"
.stringn "그렇지만 그때는 급했단 말이에요……\n"
.stringn "\x0701……시그룬 대장님은 상냥하신 분이지.\n"
.stringn "네가 부대를 떠난 건에 대해서는\n"
.stringn "불문에 부치라고 하셨다.\n"
.stringn "\x0713헉……\n"
.stringn "\x0701하지만 내가 반대했다.\n"
.stringn "어떻게든 데려와\n"
.stringn "마땅한 벌을 받게 할 거라고 보고해 뒀지.\n"
.stringn "각오해라.\n"
.stringn "\x0713아! 저, 갑자기 급한 일이 생각났어요!\n"
.stringn "……실례하겠습니다!\n"
.stringn "\x0701이봐,\n"
.stringn "또 도망가는 거냐 마샤!"
db 0
.align 4
//MYELL_8_MARCIA_TANIS_C

//0x2C61C
Text_2C5FC:
.stringn "\x05FL|MORDY|MIST||\x0C01\x071-\x0713어라, 모우디씨.\n"
.stringn "무슨 일 있었어?\n"
.stringn "\x0701미스트.\n"
.stringn "아이크는 어딨나?\n"
.stringn "\x0713아, 오빠라면\n"
.stringn "티아마트씨네랑 같이 있을걸?\n"
.stringn "근데 곧 있으면 여기도 올 거야.\n"
.stringn "\x0701알았다.\n"
.stringn "……미스트는 아이크랑 사이좋나?\n"
.stringn "\x0713글쎄, 잘 모르겠네.\n"
.stringn "그냥 평범하다고 생각해.\n"
.stringn "\x0701아이크는 좋은 베오크다.\n"
.stringn "만난 지 얼마 안 된 모우디에게\n"
.stringn "바로 마음을 열어줬다.\n"
.stringn "베오크인데도,\n"
.stringn "마치 수아족 동포 같다.\n"
.stringn "아이크는 대단하다고 생각한다.\n"
.stringn "\x0713아하하, 그런가?\n"
.stringn "오빠는 좀 이상하니까.\n"
.stringn "\x0701그런가? 그래도 모우디는\n"
.stringn "아이크가 좋다.\n"
.stringn "……미스트.\n"
.stringn "지금이니까 모우디는 미스트에게 말한다.\n"
.stringn "비웃지 마라.\n"
.stringn "\x0713응? 뭔데?\n"
.stringn "\x0701처음에 미스트에게 빨래를 주워 줬을 때,\n"
.stringn "사실은 모우디도 무서웠다.\n"
.stringn "\x0713무서웠다고……?\n"
.stringn "모우디씨가?\n"
.stringn "\x0701그렇다. 미스트에게 거절당할까 봐 무서웠다.\n"
.stringn "미스트가 두려워서 기절할까 봐 무서웠다.\n"
.stringn "두근두근해서, 엄청 긴장하고 있었다.\n"
.stringn "\x0713뭐야…… 그런 거였구나.\n"
.stringn "후후, 뭔가 이상하다.\n"
.stringn "똑같네, 나랑.\n"
.stringn "\x0701그래, 똑같다."
db 0
.align 4
//MYELL_8_MIST_MORDY_A

//0x2C2F4
Text_2C2D4:
.stringn "\x05FL|MORDY|MIST||\x070-\x0C01\x071-\x0713모우디씨! 안녕!\n"
.stringn "\x0701미스트, 기분이 좋아 보인다.\n"
.stringn "\x0713응, 나\n"
.stringn "기운이 넘쳐나!\n"
.stringn "\x0701잘됐다.\n"
.stringn "\x0713저기, 나,\n"
.stringn "나, 성격은 밝은 편이라고 생각해!\n"
.stringn "취미는 빨래, 청소,\n"
.stringn "바느질은 잘 못 하는데, 그리고…\n"
.stringn "\x0701그래.\n"
.stringn "\x0713그리고 그리고……\n"
.stringn "또 뭐가 있었지?\n"
.stringn "어, 그게,\n"
.stringn "그게…………\n"
.stringn "\x0701미스트.\n"
.stringn "천천히 말해도, 된다.\n"
.stringn "\x0713어……?\n"
.stringn "\x0701미스트는 라구즈와 얘기해 본 경험이 적다.\n"
.stringn "그러니까, 무섭다는 거 안다.\n"
.stringn "그치만 마음은 이미, 전달됐다.\n"
.stringn "미스트는 진심으로, 우리들과\n"
.stringn "친하게 지내려고 노력하고 있다……\n"
.stringn "잘 알고 있다.\n"
.stringn "\x0713…………\n"
.stringn "\x0701그러니까, 무리하지 않아도 된다.\n"
.stringn "서로,\n"
.stringn "조금씩 익숙해지면 된다.\n"
.stringn "모우디도, 미스트와 같은\n"
.stringn "마음이다.\n"
.stringn "\x0713모우디씨……\n"
.stringn "응…… 고마워.\n"
.stringn "왠지 엄청 편해졌어.\n"
.stringn "그래, 무리하지 말고\n"
.stringn "자연스럽게 하는 게 가장 중요하니까.\n"
.stringn "\x0701그래."
db 0
.align 4
//MYELL_8_MIST_MORDY_B

//0x2C098
Text_2C078:
.stringn "\x05FL|MIST|MORDY||\x0708기다려~\n"
.stringn "기다리라니까~!\n"
.stringn "\x0703어라? 어라라?\n"
.stringn "어디로 간 거지……\n"
.stringn "분명 이쪽에……\n"
.stringn "\x0711이건가?\n"
.stringn "\x0703우왓!\n"
.stringn "모, 모우디씨……\n"
.stringn "깜짝 놀랐네.\n"
.stringn "\x0711미안하다. 놀라게 했다.\n"
.stringn "거기서 주웠다.\n"
.stringn "이게 미스트가 찾던 건가?\n"
.stringn "\x0703아…… 으, 응,\n"
.stringn "빨래를 걷다가\n"
.stringn "날아가 버려서……\n"
.stringn "고마워, 모우디씨.\n"
.stringn "\x0711별거 아니다.\n"
.stringn "\x0703저……저기, 모우디씨.\n"
.stringn "\x0711뭐냐?\n"
.stringn "\x0703음…… 그…… 저기.\n"
.stringn "……미안, 아무것도 아니야.\n"
.stringn "\x0711알았다.\n"
.stringn "그럼, 모우디는 이만 가 본다.\n"
.stringn "\x0703하아……\n"
.stringn "나는 정말 바보야……\n"
.stringn "왜 오빠처럼\n"
.stringn "평범하게 못 대하는 걸까……\n"
.stringn "좀 더 힘내야겠어."
db 0
.align 4
//MYELL_8_MIST_MORDY_C

//0x2D48C
Text_2D46C:
.stringn "\x05FL|MIST|TIAMAT||\x070-\x0C03\x071-\x0711미스트, 잠깐 이쪽으로 와봐.\n"
.stringn "\x0703뭔데?\n"
.stringn "\x0711자, 내가 주는 선물.\n"
.stringn "\x0703이건 전에 봤던 옷이잖아!\n"
.stringn "내가 가장 마음에 들어했던……!\n"
.stringn "\x0711역시.\n"
.stringn "같이 간 보람이 있었네.\n"
.stringn "\x0703고마워, 티아마트씨.\n"
.stringn "\x0711후후후……\n"
.stringn "미스트가 기뻐하는 얼굴을\n"
.stringn "볼 수 있어서 다행이야.\n"
.stringn "솔직히 말하자면\n"
.stringn "조금 미스트가 걱정됐어.\n"
.stringn "갑자기 전장에 나가게 돼서\n"
.stringn "그 무거운 부담감에\n"
.stringn "언젠가 짓눌리는 게 아닐까 하고.\n"
.stringn "그래서 내가 할 수 있는 일은\n"
.stringn "뭐든지 해 주고 싶었어.\n"
.stringn "\x0703티아마트씨……\n"
.stringn "\x0711있지, 미스트.\n"
.stringn "앞으로 혹시 뭔가 괴로운 일이 있는데,\n"
.stringn "만약 아이크에게 말하기 어려운 거라면…\n"
.stringn "나를 의지해 줘.\n"
.stringn "에르나처럼은\n"
.stringn "될 수 없을지도 모르지만,\n"
.stringn "널 생각하는 마음은 변함없으니까.\n"
.stringn "\x0703응…… 응…… 고마워……\n"
.stringn "나…… 엄청 기뻐\n"
.stringn "티아마트씨.\n"
.stringn "에헤헤… 왠지 벌써 이 옷,\n"
.stringn "아까워서 못 입을 것 같아……"
db 0
.align 4
//MYELL_8_MIST_TIAMAT_A

//0x2D204
Text_2D1E4:
.stringn "\x05FL|MIST|TIAMAT||\x0C03\x0C11\x0703아, 지난번에 미안했어,\n"
.stringn "티아마트씨.\n"
.stringn "모처럼 같이 옷을 사러\n"
.stringn "가 줬는데……\n"
.stringn "\x0711그런 건 괜찮아.\n"
.stringn "그래도 모처럼 간 거니까 과감히\n"
.stringn "샀으면 좋았을 텐데.\n"
.stringn "\x0703응, 하지만 막상 때가 되면\n"
.stringn "이것저것 고민을 하게 돼서……\n"
.stringn "\x0711미스트는 식료품을 사 둔다든가,\n"
.stringn "모두를 위해 물건을 사는 건 잘하는데 말이야.\n"
.stringn "그런 점은\n"
.stringn "점점 에르나를 닮아가네.\n"
.stringn "\x0703엄마를?\n"
.stringn "\x0711그래.\n"
.stringn "너는 성실한 것도\n"
.stringn "에르나를 닮았어.\n"
.stringn "그래도 미스트, 너는 좀 더\n"
.stringn "누군가에게 응석을 부려도 괜찮다고 생각해.\n"
.stringn "곁에 있는 게 나라서\n"
.stringn "미덥지 않을지도 모르겠지만……\n"
.stringn "\x0703그렇지 않아.\n"
.stringn "난 티아마트씨를\n"
.stringn "언니라고 생각하고 있는걸.\n"
.stringn "\x0711고마워, 미스트."
db 0
.align 4
//MYELL_8_MIST_TIAMAT_B

//0x2C9B4
Text_2C994:
.stringn "\x05FL|MIST|TIAMAT||\x070-\x0C03\x071-\x0711어머 미스트, 빨래하니?\n"
.stringn "나도 도와줄게.\n"
.stringn "\x0703응? 괜찮아!\n"
.stringn "티아마트씨는\n"
.stringn "전투로 지쳤을 테니까.\n"
.stringn "\x0711그건 너도 마찬가지잖니?\n"
.stringn "괜찮으니까 도와줄게.\n"
.stringn "그건 그렇고 굉장한 양인걸.\n"
.stringn "\x0703응. 겸사겸사\n"
.stringn "다른 사람들 몫도 맡고 있어.\n"
.stringn "항상 오빠를\n"
.stringn "도와주는 답례로.\n"
.stringn "\x0711후후, 친절한 것도 좋지만\n"
.stringn "피곤하지 않은 범위 내에서 해야지.\n"
.stringn "…어머, 이거 찢어졌네.\n"
.stringn "\x0703아, 오빠 거다.\n"
.stringn "……계속 싸워서 그런지\n"
.stringn "꽤 낡아졌나 보네.\n"
.stringn "다음에 마을에서 새 걸로 사야겠다.\n"
.stringn "단장이 너덜너덜한 옷을 입고 있으면\n"
.stringn "멋이 안 사니까.\n"
.stringn "\x0711그러는 미스트도…\n"
.stringn "여기, 잠깐 봐봐.\n"
.stringn "네 옷도\n"
.stringn "소매 쪽이 찢어졌어.\n"
.stringn "\x0703아.\n"
.stringn "진짜네.\n"
.stringn "\x0711정말, 어쩔 수 없다니까.\n"
.stringn "그래, 다음에 같이 마을에 가지 않을래?\n"
.stringn "새 옷들을 좀 사야겠어.\n"
.stringn "\x0703응? 그래도 돼?\n"
.stringn "할 일이 이렇게나 많은데.\n"
.stringn "\x0711미스트도 그럴 나이니까\n"
.stringn "그런 쪽에도 신경을 쓰라고\n"
.stringn "항상 말했잖니.\n"
.stringn "\x0703응.\n"
.stringn "내 나름대로 신경을 쓰고 있다고\n"
.stringn "생각했는데…\n"
.stringn "\x0711말만 해서는 안 돼.\n"
.stringn "행동을 해야지.\n"
.stringn "그럼 다음에 같이 가는 거다.\n"
.stringn "\x0703네~에."
db 0
.align 4
//MYELL_8_MIST_TIAMAT_C_a

