//MYELL_8_MIST_TIAMAT_C_b

//0x2DBB4
Text_2DB94:
.stringn "\x05FL|MORDY|SOANEVALCKE||\x0C01\x071-\x0C13\x0701…손.\n"
.stringn "\x0713……답을 찾은 건가?\n"
.stringn "\x0701………【인붙이】…\n"
.stringn "베오크는……\n"
.stringn "라구즈와의… 혼혈 아이를 그렇게 부른다.\n"
.stringn "손은, 라구즈의 피를\n"
.stringn "가지고 있는 건가?\n"
.stringn "\x0713그래.\n"
.stringn "…그 증거로 인이, 왼쪽 관자놀이에\n"
.stringn "나타나 있다.\n"
.stringn "\x0701…………\n"
.stringn "\x0713무리하지 않아도 된다.\n"
.stringn "나랑 더는 얘기하고 싶지 않지?\n"
.stringn "\x0701…모우디는… 잘 모르겠다.\n"
.stringn "갈리아의 전설에는…\n"
.stringn "【무부모】가 불길하다고… 나와 있다.\n"
.stringn "【무부모】가 태어나면……\n"
.stringn "대지의 파멸이 100년 가까워진다고…\n"
.stringn "\x0713그래. 나는… 라구즈들에게\n"
.stringn "【무부모】라고 불리는 자.\n"
.stringn "결코 태어나는 게 가능할 리 없는 아이.\n"
.stringn "그래서 【무부모】지… 잘들 지껄이더군.\n"
.stringn "라구즈는… 그렇게\n"
.stringn "우리들 혼혈의 인을 가진 자들을……\n"
.stringn "처음부터 없었던 것처럼 취급하고 있다.\n"
.stringn "베오크도 【인붙이】라며\n"
.stringn "우리를 박해하고 있지만……\n"
.stringn "존재의 부정까지는 하지 않는다.\n"
.stringn "그래서 우리들은…\n"
.stringn "베오크 이상으로 라구즈를 혐오하지.\n"
.stringn "\x0701왜?\n"
.stringn "왜, 【무부모】가 태어나나?\n"
.stringn "다른 종족끼리는 아이가 생길 리 없을 터다.\n"
.stringn "그건, 이 세계를 창조한\n"
.stringn "여신 아스타르테의 결정이니까.\n"
.stringn "\x0713내가 알기로는…\n"
.stringn "야수·새·용… 어느 종족이라도\n"
.stringn "확실히 그들 안에서만 자식을 가질 수 있다.\n"
.stringn "하지만… 베오크와 다른 종족 사이에서는\n"
.stringn "극히 드물게…… 아이가 태어나기도 하지.\n"
.stringn "꺼림칙하게도 혼혈의 인은…\n"
.stringn "한 번이라도 연관된 혈족에게……\n"
.stringn "은밀하게 내려져 오고 있다는 거다.\n"
.stringn "여신의 결정을 어긴 것은, 나인가?\n"
.stringn "아니지. 내 조상 중 누군가가 한 짓이다.\n"
.stringn "양친도 조부모도\n"
.stringn "일족 모두가 베오크라고?\n"
.stringn "아주 오래 전… 누군가가 라구즈의 피를 가져왔고,\n"
.stringn "그 죄가… 수많은 대를 지나며\n"
.stringn "나에게도 나타났지. 나는 그저 태어난 것뿐인데.\n"
.stringn "처음부터 『부정』의 낙인이 찍혀 있었다.\n"
.stringn "\x0701……\n"
.stringn "\x0713라구즈의 피는, 내게\n"
.stringn "특별한 힘을 주었다.\n"
.stringn "이 힘을 써서… 편안하게 살고 있는 놈들을\n"
.stringn "없애 버릴까 생각도 했지만… 관뒀다.\n"
.stringn "내게도 동료가 있었으니까.\n"
.stringn "나처럼 혼혈의 인을 숨기기 위해…\n"
.stringn "세상으로부터 쫓겨난 자들이……\n"
.stringn "\x0701손은, 왜\n"
.stringn "모우디에게 다가온 건가?\n"
.stringn "갈리아에 흥미가… 있다고\n"
.stringn "한 건 어째서인가?\n"
.stringn "\x0713갈리아의 수아족에게 흥미가 있었다.\n"
.stringn "베그니온에 사는 녀석들이랑은\n"
.stringn "털색이 달라 보여서 말이지.\n"
.stringn "내 동료들 사이에선…\n"
.stringn "베오크와 손을 잡을 정도로\n"
.stringn "개방적인 나라라면,\n"
.stringn "우리 같은 자들에 대해서도\n"
.stringn "관용적일 거라는 주장이 있었다.\n"
.stringn "갈리아와 크리미아…\n"
.stringn "그 중 한쪽이라면\n"
.stringn "우리들을 받아 줄\n"
.stringn "장소가 되지 않을까 했었지……\n"
.stringn "……물론, 그런\n"
.stringn "형편 좋은 일은 없었던 것 같군.\n"
.stringn "\x0701손…\n"
.stringn "\x0713자 그럼, 너와 어울리는 것도\n"
.stringn "여기까지인가.\n"
.stringn "잠시 동안… 이 싸움이 끝날 때까지는\n"
.stringn "네 눈앞을 서성거리게 되겠지만\n"
.stringn "그 정도는 참아 줘.\n"
.stringn "두 번 다시 말을 안 걸 테니…\n"
.stringn "\x0701싫다!\n"
.stringn "눈앞에 있는 손을\n"
.stringn "안 본 척할 수는 없다.\n"
.stringn "\x0713모우디…\n"
.stringn "여신의 결정은 어쩔 거냐?\n"
.stringn "베오크보다 자연에 가까운 라구즈는…\n"
.stringn "그 이치를 중요하게 여기는 존재일 텐데?\n"
.stringn "\x0701모우디는 여신을 만난 적이 없다.\n"
.stringn "만약… 만난다면 불평하겠다.\n"
.stringn "손을 괴롭히지 말라고.\n"
.stringn "모우디의 소중한 친구라고.\n"
.stringn "\x0713훗, 여신에게 불평한다라…\n"
.stringn "반대로 나는 태어나서 처음으로\n"
.stringn "그녀에게 감사하고 싶군.\n"
.stringn "\x0701왜?\n"
.stringn "\x0713모우디를 만날 수 있었으니까.\n"
.stringn "이런 운명이라면 나쁘지 않지."
db 0
.align 4
//MYELL_8_MORDY_SOANVALCKE_A

//0x2D9C0
Text_2D9A0:
.stringn "\x05FL|SOANEVALCKE|MORDY||\x070-\x0C01\x0713손!!\n"
.stringn "\x0701뭐냐, 모우디.\n"
.stringn "그렇게나 숨을 헐떡이면서.\n"
.stringn "\x0713혐오는 『엄청 싫다』,\n"
.stringn "무지는 『머리가 나쁘다』라고 들었다.\n"
.stringn "왜, 손은\n"
.stringn "자기 나라를 싫어하나?\n"
.stringn "모우디를 멍청이 취급하나?\n"
.stringn "\x0701…조사한 건가.\n"
.stringn "생각보다 머리는 잘 돌아가는 듯하군.\n"
.stringn "그럼 “무지”하다는 건 철회하지.\n"
.stringn "\x0713손!\n"
.stringn "모우디의 질문에 대답해라.\n"
.stringn "\x0701……모처럼이니\n"
.stringn "더 조사해 봐.\n"
.stringn "나는 【인붙이】다.\n"
.stringn "그래서 나라를 혐오하고,\n"
.stringn "무지한 라구즈들을 증오하지.\n"
.stringn "\x0713…라구즈를… 증오해?\n"
.stringn "『인부치』니까…?\n"
.stringn "……손은… 뭐 하는 사람이지?"
db 0
.align 4
//MYELL_8_MORDY_SOANVALCKE_B

//0x2D7CC
Text_2D7AC:
.stringn "\x05FL|SOANEVALCKE|MORDY||\x070-\x0C01\x071-\x0713손!\n"
.stringn "여기에 있었구나.\n"
.stringn "\x0701…그래.\n"
.stringn "\x0713갈리아 얘기는 이제 됐나?\n"
.stringn "모우디는 아직도\n"
.stringn "해 줄 이야기가 많이 있다.\n"
.stringn "\x0701……모우디는\n"
.stringn "자기 나라를 좋아하나?\n"
.stringn "\x0713그렇다. 갈리아는 좋은 나라다.\n"
.stringn "모우디한테는,\n"
.stringn "세계 제일로 굉장한 나라다.\n"
.stringn "\x0701그런가.\n"
.stringn "\x0713손은 어떤가?\n"
.stringn "베그니온이 좋나?\n"
.stringn "\x0701…혐오하고 있다.\n"
.stringn "\x0713『혀모』?\n"
.stringn "그건 무슨 의미인가?\n"
.stringn "\x0701너는 몰라도 돼.\n"
.stringn "무지한 채로 있는 편이 행복하니까.\n"
.stringn "\x0713『무디』……\n"
.stringn "……으음… 모우디는\n"
.stringn "현대어를 잘 모르겠다……"
db 0
.align 4
//MYELL_8_MORDY_SOANVALCKE_C

//0x2ECC4
Text_2ECA4:
.stringn "\x05FL|VULCI|MORDY||\x0C01\x071-\x0713우르키, 좋은 생각이 났다.\n"
.stringn "\x0701뭐지?\n"
.stringn "\x0713모우디가 눈이 되겠다.\n"
.stringn "보이는 것이 있으면 너한테 주겠다.\n"
.stringn "그러니까, 모우디를 태우고\n"
.stringn "같이 숲으로 가면 된다!\n"
.stringn "\x0701………………\n"
.stringn "아니…… 그건 못 한다…\n"
.stringn "너는 너무 무거워.\n"
.stringn "내 힘으로는 너를 태울 수 없다.\n"
.stringn "\x0713으으…… 그렇구나. 미안.\n"
.stringn "모우디는 밤에도 보인다,\n"
.stringn "너는 날 수 있다,\n"
.stringn "그래서 좋은 생각인 줄 알았다……\n"
.stringn "\x0701…………\n"
.stringn "\x0713모우디, 열심히 생각했는데……\n"
.stringn "……미안, 우르키.\n"
.stringn "\x0701아니……\n"
.stringn "……뭐어, 만약의 이야기지만.\n"
.stringn "내가 좀 더 힘을 기르고,\n"
.stringn "네가 좀 더 가벼워진다면……\n"
.stringn "가능할지도 모르겠군.\n"
.stringn "\x0713그렇구나! 그러면 우르키가 사는\n"
.stringn "페니키스에도 가 볼 수 있겠다!\n"
.stringn "모우디, 힘내겠다!\n"
.stringn "그렇구나… 모우디는 가벼워지는 역할이다.\n"
.stringn "……으으…… 잘 생각해 보니 어렵다……\n"
.stringn "좋다, 내일부터 먹는 것을 줄여 보겠다!\n"
.stringn "\x0701아니…… 만약이라고…………\n"
.stringn "……………………\n"
.stringn "………………………………\n"
.stringn "………적당히 말한 것이었다만……"
db 0
.align 4
//MYELL_8_MORDY_VULCI_A

//0x2E964
Text_2E944:
.stringn "\x05FL|VULCI|MORDY||\x0C01\x0C13\x0701……모우디.\n"
.stringn "\x0713왜 그러나, 우르키?\n"
.stringn "\x0701네게 물어보고 싶은 게 있다.\n"
.stringn "\x0713응? 뭔가?\n"
.stringn "\x0701너희 수아족은 밤에도\n"
.stringn "시력에 문제가 없는 것 같더군\n"
.stringn "……우리들은 밤에 눈이 안 보인다.\n"
.stringn "어둠 속에서 눈을 뜨고 있어도\n"
.stringn "아무것도 안 보이지.\n"
.stringn "\x0713으음, 그거 불편하겠다.\n"
.stringn "확실히 어두우면 잘 보기 힘들지만,\n"
.stringn "약간의 불빛이 있으면 잘 보인다.\n"
.stringn "너도 모우디처럼\n"
.stringn "달빛으로 보면 된다.\n"
.stringn "\x0701……그렇게 할 수 있다면 좋겠지만.\n"
.stringn "조익족에게는 아무래도 무리다.\n"
.stringn "\x0713그렇구나.\n"
.stringn "\x0701……나는 밤의 풍경을 본 적이 없다.\n"
.stringn "동포들 중 누구도 밤의 세계를 모르지.\n"
.stringn "나는 한 번이라도 밤의 숲을 보고 싶다.\n"
.stringn "밤이 되면 숲의 나무들은 어떻게 보일까?\n"
.stringn "왜 비가 오지 않아도 아침이 되면\n"
.stringn "잎사귀에 물방울이 맺혀 있는 거지?\n"
.stringn "밤의 숲은 알 수 없는 것들뿐이다.\n"
.stringn "도대체 어떤 느낌이지?\n"
.stringn "\x0713밤의 숲은 고요하지만,\n"
.stringn "낮에는 생물의 숨결이 살아 있다.\n"
.stringn "낮과 밤은 전혀 다른 숲이다.\n"
.stringn "\x0701……그런가.\n"
.stringn "한번 보고 싶군."
db 0
.align 4
//MYELL_8_MORDY_VULCI_B

//0x2E6AC
Text_2E68C:
.stringn "\x05FL|VULCI|MORDY||\x0C01\x0713우르키, 뭐 물어봐도 되나?\n"
.stringn "\x0701……그래.\n"
.stringn "뭐지?\n"
.stringn "\x0713조익족은 하늘을 난다.\n"
.stringn "하늘을 난다는 건 어떤 기분인가?\n"
.stringn "\x0701……\n"
.stringn "……딱히 어떤 기분이 드는 건 아니다.\n"
.stringn "\x0713으음…… 그런가.\n"
.stringn "그런 거구나.\n"
.stringn "모우디는 아직,\n"
.stringn "하늘을 날아 본 적이 없어서\n"
.stringn "물어보고 싶었다.\n"
.stringn "\x0701……그래, 그렇겠지.\n"
.stringn "\x0713우르키가 사는 페니키스는\n"
.stringn "어떤 곳인가?\n"
.stringn "역시, 날 수 없으면 못 가는 건가?\n"
.stringn "\x0701그래……\n"
.stringn "배로 찾아온다 한들\n"
.stringn "페니키스에는 항구가 없다. 필요가 없으니까.\n"
.stringn "우리의 도움 없이는 상륙하기 어렵겠지.\n"
.stringn "\x0713그렇구나……\n"
.stringn "아쉽다……\n"
.stringn "\x0701……너는 페니키스에 가 보고 싶나?\n"
.stringn "\x0713그렇다! 가 보고 싶다!\n"
.stringn "이 전쟁에서 여러 베오크와 라구즈와 만났다!\n"
.stringn "모두가 살던 곳으로\n"
.stringn "모우디는 가 보고 싶다!\n"
.stringn "\x0701……그런가."
db 0
.align 4
//MYELL_8_MORDY_VULCI_C

//0x2F694
Text_2F674:
.stringn "\x05FL|MWARIM|ZIHARK||\x0C01\x071-\x0713무와림.\n"
.stringn "\x0701뭐야, 지하크.\n"
.stringn "\x0713네게 주려고 이걸 가져왔어.\n"
.stringn "\x0701……이건?\n"
.stringn "\x0713수아족은 이 풀의 향기를\n"
.stringn "엄청 좋아하지?\n"
.stringn "좀처럼 나지 않는 풀이지만,\n"
.stringn "향기를 맡는 것만으로도\n"
.stringn "차분한 기분이 된다고 들었어.\n"
.stringn "\x0701……\n"
.stringn "\x0713혹시,\n"
.stringn "풀을 착각했나?\n"
.stringn "\x0701……아니.\n"
.stringn "하지만 그 풀을 좋아하는 건\n"
.stringn "수아족들 중에서도 고양이들뿐이다.\n"
.stringn "우리들 호랑이한테는…\n"
.stringn "그런 습성이 없어.\n"
.stringn "\x0713뭐야… 그런 거였구나.\n"
.stringn "미안해. 옛날에\n"
.stringn "연인이 그랬으니까…\n"
.stringn "틀림없이 다 그럴 거라고\n"
.stringn "생각했었어.\n"
.stringn "\x0701……연인?\n"
.stringn "네 연인은\n"
.stringn "수아족이었나?\n"
.stringn "\x0713그래.\n"
.stringn "\x0701……그렇군.\n"
.stringn "베오크와 맺어지는 라구즈도 있다고…\n"
.stringn "이야기로는 들은 적이 있었지만……\n"
.stringn "그… 힘들었겠구나.\n"
.stringn "\x0713그렇지…\n"
.stringn "결국 맺어지지는\n"
.stringn "못했지만……\n"
.stringn "나는 지금도…\n"
.stringn "그녀 이외의 여자를 사랑한 적이 없어.\n"
.stringn "\x0701……그 풀을,\n"
.stringn "받을 수 있을까.\n"
.stringn "\x0713어? 하지만……\n"
.stringn "\x0701상관없어.\n"
.stringn "이걸 가져와 준\n"
.stringn "네 마음을 받고 싶다.\n"
.stringn "\x0713그렇구나…\n"
.stringn "고마워.\n"
.stringn "너는 상냥한 라구즈구나."
db 0
.align 4
//MYELL_8_MWARIM_ZIHARK_A

//0x2F2EC
Text_2F2CC:
.stringn "\x05FL|MWARIM|ZIHARK||\x0C01\x0C13\x0701……지하크.\n"
.stringn "\x0713안녕, 무와림.\n"
.stringn "또 만났네.\n"
.stringn "\x0701……숫돌 가루는 찾았나?\n"
.stringn "\x0713아니, 공교롭게도 못 찾았어.\n"
.stringn "누군가한테 다시 빌리는 것도 그러니까\n"
.stringn "이제부터 새로운 걸\n"
.stringn "사러 가려고 하던 참이야.\n"
.stringn "\x0701……이건 쓸 수 있나?\n"
.stringn "\x0713응? 이건…\n"
.stringn "아주 좋은 숫돌 가루인걸.\n"
.stringn "라구즈인 네가\n"
.stringn "왜 이런 걸 가지고 있어?\n"
.stringn "\x0701……옛날 버릇이다.\n"
.stringn "\x0713옛날…?\n"
.stringn "\x0701귀족의 노예였던 시절……\n"
.stringn "주인은 자주 검을 연마했다.\n"
.stringn "언제나 갑자기 가지고 오는데,\n"
.stringn "그 자리에서 바로 닦지 않으면\n"
.stringn "호되게 매질을 당했지.\n"
.stringn "그래서…다.\n"
.stringn "\x0713……미안해.\n"
.stringn "싫은 일을\n"
.stringn "생각나게 해 버렸네.\n"
.stringn "\x0701상관없다.\n"
.stringn "괜찮다면\n"
.stringn "그 검도 닦아 줄까?\n"
.stringn "\x0713아니, 진정한 검사라면\n"
.stringn "자신의 검은 자기가 손질하는 법이야.\n"
.stringn "마음만으로도 기뻐.\n"
.stringn "\x0701그럼, 이 가루만이라도\n"
.stringn "써 줘.\n"
.stringn "나에겐 이제 필요 없는 거니까.\n"
.stringn "\x0713무와림…\n"
.stringn "고마워, 도움이 됐어.\n"
.stringn "사례라고 하긴 좀 그렇지만…\n"
.stringn "같이 식사라도 어때?\n"
.stringn "\x0701…그렇군. 너와 함께라면…\n"
.stringn "즐거운 식사를 할 수 있을 것 같다."
db 0
.align 4
//MYELL_8_MWARIM_ZIHARK_B

//0x2F034
Text_2F014:
.stringn "\x05FL|ZIHARK|MWARIM||\x0703이상하네.\n"
.stringn "방금 전까진 있었는데\n"
.stringn "대체 어디로 간 거야……\n"
.stringn "\x0711…무슨 일 있나?\n"
.stringn "\x0703아, 무와림.\n"
.stringn "“숫돌 가루”가 보이질 않아서.\n"
.stringn "\x0711숫돌 가루?\n"
.stringn "\x0703검을 손질하는 데 쓰는 도구야.\n"
.stringn "칼날은 그냥 두면 녹슬게 되니까.\n"
.stringn "기름으로 닦거나, 숫돌 가루를 치거나……\n"
.stringn "\x0711……고운 돌가루를 넣은 주머니 말인가?\n"
.stringn "\x0703그래, 그거.\n"
.stringn "혹시 주웠어?\n"
.stringn "\x0711……아니.\n"
.stringn "옛날에 본 적이 있었을 뿐이다.\n"
.stringn "숫돌 가루라고 불리는 줄은 몰랐는데.\n"
.stringn "\x0703근처에서 떨어뜨리진 않았고,\n"
.stringn "행군 도중에\n"
.stringn "잃어버린 건가……\n"
.stringn "어쩔 수 없지, 아이크 단장한테서\n"
.stringn "조금 빌려야겠다.\n"
.stringn "\x0711……베오크는 불편하겠군.\n"
.stringn "\x0703그러게나 말이야.\n"
.stringn "우리는 무기가 없으면 아무것도 할 수 없지.\n"
.stringn "이럴 때는 항상\n"
.stringn "라구즈가 부럽다는 생각이 들어.\n"
.stringn "\x0711…………"
db 0
.align 4
//MYELL_8_MWARIM_ZIHARK_C

//0x30318
Text_302F8:
.stringn "\x05FL|OSCAR|TANIS||\x070-\x0C01\x0713오스카.\n"
.stringn "? 어디 가는 거지?\n"
.stringn "\x0701네, 지금부터 식사 준비를 하러……\n"
.stringn "뭔가 용무가 있으신가요?\n"
.stringn "\x0713아니, 별일은 아니다만……\n"
.stringn "네게 고맙다는 말을 해 두고 싶었다.\n"
.stringn "네 보좌 덕분에\n"
.stringn "충분히 내 힘을 발휘할 수 있었지.\n"
.stringn "이렇게 편안하게 싸울 수 있었던 적은 없다.\n"
.stringn "가능하다면 너를\n"
.stringn "베그니온으로 데려가고 싶을 정도군.\n"
.stringn "\x0701감사합니다.\n"
.stringn "\x0713그나저나……\n"
.stringn "오스카가 요리를 하는 건가?\n"
.stringn "\x0701네. 용병단끼리 행동할 때는 자주 했지만,\n"
.stringn "지금은 가끔씩 이렇게 도우러 갑니다.\n"
.stringn "\x0713호오, 재주가 좋군.\n"
.stringn "\x0701그런가요?\n"
.stringn "\x0713한심한 이야기지만,\n"
.stringn "난 달걀 껍데기 하나도 제대로 못 깐다.\n"
.stringn "야영지에서 딱 한 번 요리한 적이 있었는데…\n"
.stringn "계란이 아니라 껍데기를 먹이고 싶은 거냐는\n"
.stringn "말을 들은 적이 있었지.\n"
.stringn "\x0701……그렇군요…\n"
.stringn "\x0713어처구니없지?\n"
.stringn "\x0701아뇨, 그 정도로 현란하게 검을\n"
.stringn "잘 다루시는데 의외라고 생각했을 뿐입니다.\n"
.stringn "혹시, 실례가 되지 않는다면……\n"
.stringn "제가 가르쳐 드려도 괜찮을까요?\n"
.stringn "\x0713네가 요리를?\n"
.stringn "\x0701싫지 않으시다면요.\n"
.stringn "\x0713흠, 너라면 가르치는 일도 잘 하겠지.\n"
.stringn "좋아, 교습을 부탁하마."
db 0
.align 4
//MYELL_8_OSCAR_TANIS_A

//0x2FD18
Text_2FCF8:
.stringn "\x05FL|OSCAR|TANIS||\x070-\x0C01\x0C13\x0701타니스님. 지난번의 용맹한 돌격……\n"
.stringn "훌륭했습니다.\n"
.stringn "\x0713물론이다. 우리는 베그니온 기사.\n"
.stringn "조국과 신사님의 이름으로\n"
.stringn "불명예스러운 싸움을 할 수는 없지.\n"
.stringn "\x0701타니스님의 무예는\n"
.stringn "저도 소문으로 들은 적이 있습니다.\n"
.stringn "최대 속도로는\n"
.stringn "빛의 속도에도 비유된다는\n"
.stringn "천마 기사대의 총돌격……\n"
.stringn "\x0713호오, 알고 있었나.\n"
.stringn "\x0701그러나 타니스님.\n"
.stringn "실례를 무릅쓰고 말씀드립니다만,\n"
.stringn "그 전술은 병사의 수가 우위일 때\n"
.stringn "성립된다고 할 수 있지 않을까요?\n"
.stringn "\x0713음……\n"
.stringn "확실히 그건 인정하지.\n"
.stringn "이번 전투에서는 베그니온군의 전술을\n"
.stringn "그대로 쓸 수 없겠지.\n"
.stringn "\x0701네.\n"
.stringn "우리 군은 항상 병력이 적고,\n"
.stringn "장비마저 충분히 갖추지 못한 자도 간혹 있죠.\n"
.stringn "베그니온과 같은 윤택한 자금과 병력은\n"
.stringn "도저히 바랄 수 없는 것이 현실입니다.\n"
.stringn "\x0713그렇지.\n"
.stringn "그럼 어떻게 하면 되지?\n"
.stringn "네 의견을 듣고 싶군.\n"
.stringn "\x0701우리가 계속해 온 것은\n"
.stringn "개개인을 살리는 싸움이었습니다.\n"
.stringn "이런 연전에서는 우선 죽지 않는 것을\n"
.stringn "첫 번째로 생각해야 합니다.\n"
.stringn "비록 전투에서 이기더라도 희생이 크다면\n"
.stringn "다음 전투에서는 이길 수 없으니까요.\n"
.stringn "설령 불명예스러운 비난을 받는 한이 있어도\n"
.stringn "부상을 당했을 때는 곧바로 이탈하고,\n"
.stringn "다른 동료에게 맡기는 겁니다……\n"
.stringn "\x0713과연……\n"
.stringn "개인적으로는 약간 불만이지만\n"
.stringn "유효하다는 점은 인정하지 않을 수 없군.\n"
.stringn "\x0701가능하다면 타니스님께서도\n"
.stringn "항상 아군과 연계하여 싸우시도록\n"
.stringn "부탁하고 싶습니다.\n"
.stringn "\x0713하지만 이 군에서 나와 연계를 취할\n"
.stringn "천마 기사는 좀처럼 없다.\n"
.stringn "누가 나를 보좌하지?\n"
.stringn "\x0701그럼, 제가 그 역할을 맡겠습니다.\n"
.stringn "\x0713네가?\n"
.stringn "\x0701네, 아직 미숙하지만요.\n"
.stringn "\x0713……아니, 너라면 좋다.\n"
.stringn "너에 대한 것은 조금이나마 알고 있지.\n"
.stringn "다른 정체를 알 수 없는 용병들과는 달리\n"
.stringn "믿을 수 있을 것 같군.\n"
.stringn "\x0701영광입니다.\n"
.stringn "\x0713하지만 내게 네가 탄 말을 기다릴 여유는 없다.\n"
.stringn "나를 보좌한다면\n"
.stringn "나를 따라올 수 있어야겠지.\n"
.stringn "\x0701넵, 노력하겠습니다."
db 0
.align 4
//MYELL_8_OSCAR_TANIS_B

//0x2FA40
Text_2FA20:
.stringn "\x05FL|TANIS|OSCAR||\x0703음? 잠깐 기다리도록.\n"
.stringn "\x0711네?\n"
.stringn "\x0703지금 이 천을 떨어뜨린 건\n"
.stringn "너인가?\n"
.stringn "\x0711이건…… 죄송합니다.\n"
.stringn "타니스님께서\n"
.stringn "직접 주워 주시다니.\n"
.stringn "\x0703네 이름은?\n"
.stringn "\x0711네, 인사가 늦었군요.\n"
.stringn "처음 뵙겠습니다.\n"
.stringn "저는 그레일 용병단의\n"
.stringn "오스카라고 합니다.\n"
.stringn "\x0703흠, 너도 아이크 장군이\n"
.stringn "이끌고 있는 용병단의 일원인가.\n"
.stringn "알았다.\n"
.stringn "내 부하들은 최소한만 데리고 왔지만\n"
.stringn "우리 베그니온 기사는 비록 수가 적더라도\n"
.stringn "남 못지 않지. 전장에서 보여 주겠다.\n"
.stringn "\x0711유명한 베그니온 천마 기사의 힘은\n"
.stringn "잘 알고 있습니다.\n"
.stringn "앞으로 잘 부탁드립니다.\n"
.stringn "\x0703그래.\n"
.stringn "\x0711그럼, 실례하겠습니다.\n"
.stringn "정말 감사했습니다.\n"
.stringn "\x0703흠……\n"
.stringn "제법 예의가 바른 청년인걸.\n"
.stringn "용병이라 하면 천박하고 저속한\n"
.stringn "남자들밖에 없다고 단정짓고 있었다만……\n"
.stringn "과연 아이크 장군의 부하로군."
db 0
.align 4
//MYELL_8_OSCAR_TANIS_C

//0x30D14
Text_30CF4:
.stringn "\x05FL|RIEUSION|TANIS||\x0C01\x0713뤼시온 왕자님.\n"
.stringn "지난번에는… 위험했습니다.\n"
.stringn "도와주셔서 감사합니다.\n"
.stringn "\x0701…어쨌든\n"
.stringn "무사히 끝나서 다행이다.\n"
.stringn "언제나 날렵하게 움직이던 네가…\n"
.stringn "적을 눈앞에 두고\n"
.stringn "갑자기… 움직임을 멈춰서 놀랐거든.\n"
.stringn "\x0713자신도 모르는 사이에…\n"
.stringn "피로가 쌓였던 것 같습니다.\n"
.stringn "그때 뤼시온 왕자님께서\n"
.stringn "【주가】를 불러 주시지 않았다면…\n"
.stringn "상당히 위험한 상황에 빠졌을 겁니다.\n"
.stringn "재차 감사드립니다.\n"
.stringn "\x0701……이런데도, 내가\n"
.stringn "전장에서 쓸모없다고 생각하는 건가?\n"
.stringn "\x0713아니요, 전부 제 자만이었습니다.\n"
.stringn "지키라는 명령을 받았으면서\n"
.stringn "역으로 보호받다니…\n"
.stringn "이만큼 한심한 일도 없습니다.\n"
.stringn "\x0701알았다면\n"
.stringn "그걸로 됐어.\n"
.stringn "\x0713하지만… 이렇게 된 이상,\n"
.stringn "이 군에 있어도 폐가 될 뿐……\n"
.stringn "이 발로 베그니온에 돌아가\n"
.stringn "신사님께 야단을 맞으려고 합니다.\n"
.stringn "\x0701자, 잠깐만!\n"
.stringn "단 한 번 실패했다고…\n"
.stringn "그렇게까지 할 필요는 없지 않나.\n"
.stringn "\x0713아뇨… 임무에 모두\n"
.stringn "실패한 제게는……\n"
.stringn "이제 제대의 길밖에 남아 있지 않습니다.\n"
.stringn "\x0701그럼…!\n"
.stringn "내 호위를 맡기겠다.\n"
.stringn "그렇게 하면\n"
.stringn "신사의 임무를 하나 완수할 수 있겠지.\n"
.stringn "\x0713그런… 저 따위가 호위라니,\n"
.stringn "왕자님께 짐이 될 뿐입니다.\n"
.stringn "\x0701내가 너를 지키겠다.\n"
.stringn "이름뿐인 호위라도 좋으니까,\n"
.stringn "여기 남아서 임무를 완수해 다오.\n"
.stringn "\x0713뤼시온 왕자님…\n"
.stringn "그럼 삼가 호위 임무를 맡겠습니다.\n"
.stringn "부족하지만 앞으로도\n"
.stringn "잘 부탁드립니다."
db 0
.align 4
//MYELL_8_RIEUSION_TANIS_A

//0x30A4C
Text_30A2C:
.stringn "\x05FL|RIEUSION|TANIS||\x0C01\x071-\x0713뤼시온 왕자님.\n"
.stringn "\x0701…너인가.\n"
.stringn "\x0713보아하니…\n"
.stringn "지난번의 부상도 순조롭게 회복된 것 같아\n"
.stringn "다행입니다.\n"
.stringn "\x0701……\n"
.stringn "\x0713무례를 무릅쓰고 말씀드리겠습니다.\n"
.stringn "역시, 당신 같은 분께서\n"
.stringn "전장에 나서는 것은\n"
.stringn "무모하지 않습니까?\n"
.stringn "당신을 지키기 위해서는\n"
.stringn "여러 병사들의 손을 빌려야 합니다.\n"
.stringn "적어도 제게 전속 호위를\n"
.stringn "맡겨 주신다면…\n"
.stringn "조금은 상태가 나아……\n"
.stringn "\x0701…아이크가\n"
.stringn "내 힘이 필요 없다고 말하지 않는 한…\n"
.stringn "전장에 나갈 거다.\n"
.stringn "그 외에는 누구의 지시도 받지 않겠어.\n"
.stringn "\x0713뤼시온 왕자님!\n"
.stringn "\x0701…지난번 전투에서…… 네가\n"
.stringn "도와준 것에 대해서는 감사하고 있다.\n"
.stringn "하지만 몇 번이고 말하는데… 호위는 필요 없다.\n"
.stringn "날 따라다니는 건 그만해 줘.\n"
.stringn "\x0713…흐음. 칙명이 아니라면\n"
.stringn "나도 억지로 하고 싶은 건 아니다만…\n"
.stringn "꽤… 곤란하게 됐군."
db 0
.align 4
//MYELL_8_RIEUSION_TANIS_B

//0x306D8
Text_306B8:
.stringn "\x05FL|RIEUSION|TANIS||\x0C01\x0713뤼시온 왕자님,\n"
.stringn "잠깐 괜찮으십니까.\n"
.stringn "\x0701너는 확실히……\n"
.stringn "신사의…?\n"
.stringn "\x0713네.\n"
.stringn "신사 친위대 부대장을 맡고 있는\n"
.stringn "타니스라고 합니다.\n"
.stringn "\x0701…나한테 무슨 볼일이지?\n"
.stringn "\x0713신사님께 가능한 만큼\n"
.stringn "왕자님을 지켜드리라는 명령을 받았습니다.\n"
.stringn "앞으로 잘 부탁드립니다.\n"
.stringn "\x070120년 전의 속죄…라는 건가.\n"
.stringn "안타깝게 됐지만 필요 없어.\n"
.stringn "내 몸 정도는 스스로 지킬 수 있다.\n"
.stringn "\x0713하지만 왕자님.\n"
.stringn "백로 민족이 일체 싸울 수 있는 기술을\n"
.stringn "가지고 있지 않다는 것은…\n"
.stringn "베그니온에선\n"
.stringn "어린아이들도 아는 사실입니다.\n"
.stringn "전장에서… 싸우지도 않고\n"
.stringn "어떻게 자신을\n"
.stringn "지키실 생각이십니까?\n"
.stringn "\x0701그런 건\n"
.stringn "너하고 관계없다.\n"
.stringn "\x0713…저는 칙명을 받고 있습니다.\n"
.stringn "확실한 이유도 듣지 못한 채\n"
.stringn "명령을 포기할 수는 없습니다.\n"
.stringn "\x0701베오크의 방식에\n"
.stringn "내가 따를 이유는 없어.\n"
.stringn "…얘기는 이걸로 끝이다. 실례하지.\n"
.stringn "\x0713……이거야 원, 보기와는 다르게\n"
.stringn "기가 센 왕자님이로군.\n"
.stringn "쉽게 지키게 해 주진 않을 것 같은데.\n"
.stringn "그럼, 어떻게 하면 좋을까…"
db 0
.align 4
//MYELL_8_RIEUSION_TANIS_C

//0x3184C
Text_3182C:
.stringn "\x05FL|TOPUCK|RIEUSION||\x0C01\x0C13\x0701저기 있잖아… 안 되는 거야?\n"
.stringn "\x0713………\n"
.stringn "\x0701사실은 할 수 있는 거지?\n"
.stringn "부탁이야, 해 주라.\n"
.stringn "지금 당장이 아니더라도 괜찮으니까.\n"
.stringn "\x0713…무리다.\n"
.stringn "\x0701…우리들이\n"
.stringn "아무것도 가진 게 없어서 그러는 거야?\n"
.stringn "그래서 안 도와주는 거야?\n"
.stringn "\x0713내가 대가를 바라고\n"
.stringn "행동한다고 말할 셈이냐!?\n"
.stringn "\x0701그, 그치만…!\n"
.stringn "신사를 용서했을 때는…\n"
.stringn "그렇게 대단한 일도 할 수 있었잖아!!\n"
.stringn "\x0713그건…\n"
.stringn "그런 조건 아래였으니 가능했던 일이다.\n"
.stringn "\x0701? …잘 모르겠는데.\n"
.stringn "\x0713…우선, 그곳은 셀리노스의 숲이었다.\n"
.stringn "성스러운 제단 위에서\n"
.stringn "가문의 정식 의식으로서 거행했지.\n"
.stringn "그리고 무엇보다도…\n"
.stringn "그때는 리아네가 있었다.\n"
.stringn "【재생】의 주가는\n"
.stringn "혼자서 노래한다면 큰 효력을 발휘할 수 없어.\n"
.stringn "\x0701………그럼,\n"
.stringn "그럼 그 공주님이 있으면 되는 거 아냐?\n"
.stringn "\x0713이해력이 나쁘군…\n"
.stringn "만약 리아네와 내가\n"
.stringn "쓰러질 때까지 노래한다고 해도,\n"
.stringn "모래를 흙으로 바꿀 수는 없다.\n"
.stringn "그 사막이 아주 먼 옛날\n"
.stringn "풍요로운 흙이었다고 해도…\n"
.stringn "몇백 년 전으로 되돌릴 만한 힘은 없어.\n"
.stringn "알겠나?\n"
.stringn "\x0701………쳇\n"
.stringn "\x0713어째서 내 주가가 필요하지?\n"
.stringn "아이크에게…\n"
.stringn "너희의 일은\n"
.stringn "신사가 맡아 주게 되었다고 들었다.\n"
.stringn "\x0701신사는… 라구즈 노예와 관한 일은\n"
.stringn "어떻게든 해 준다고 했지만…\n"
.stringn "만약, 그게 베오크랑\n"
.stringn "같은 마을에 살게 해 준다는 얘기라면…\n"
.stringn "곤란하다고 생각하거든.\n"
.stringn "그야 그렇잖아?\n"
.stringn "아무리 신사가 허락한다 해도,\n"
.stringn "다른 베오크들은… 역시\n"
.stringn "라구즈를 싫어하고……\n"
.stringn "나도… 동료들이 힘들어하는 건\n"
.stringn "역시, 싫고……\n"
.stringn "\x0713그건… 확실히\n"
.stringn "무리인 이야기군.\n"
.stringn "\x0701그래서…\n"
.stringn "사막을 어떻게든 되살리고 싶었어.\n"
.stringn "라구즈끼리 살 수 있는 마을을\n"
.stringn "만들 수는 없을까 생각한 거지.\n"
.stringn "\x0713………아직은 미래의 일이지만,\n"
.stringn "만약 셀리노스의 숲이\n"
.stringn "다시 우리 손으로 돌아온다면… 같이 살겠나?\n"
.stringn "\x0701그, 그래도 돼!?\n"
.stringn "\x0713물론이다.\n"
.stringn "\x0701고마워!\n"
.stringn "모두 기뻐할 거야!!\n"
.stringn "\x0713단, 숲속의 동물들을\n"
.stringn "포식하는 건 금지다.\n"
.stringn "\x0701응…? 그럼, 밥은\n"
.stringn "어떻게 먹어?\n"
.stringn "\x0713물과 나무 열매가 풍족하다.\n"
.stringn "\x0701내 동료들은\n"
.stringn "수아족들이 많다고,\n"
.stringn "걔네는 육식이란 말이야!\n"
.stringn "\x0713익숙해져라.\n"
.stringn "\x0701……일단, 모두와 상담해 볼게.\n"
.stringn "근데 다들…\n"
.stringn "고기를 전혀 먹지 못하니까\n"
.stringn "사막이 더 좋다고 말하지 않을까…"
db 0
.align 4
//MYELL_8_RIEUSION_TOPUCK_A

//0x31604
Text_315E4:
.stringn "\x05FL|TOPUCK|RIEUSION||\x070-\x0C01\x0C13\x0701백로 민족의 왕자!\n"
.stringn "\x0713…뤼시온이다.\n"
.stringn "\x0701그럼, 뤼시온 왕자!\n"
.stringn "지금 시간 있어?\n"
.stringn "\x0713뭐어… 상관없다.\n"
.stringn "지난번에 했던 라구즈를 위해\n"
.stringn "주가를 불러달라는 얘기지?\n"
.stringn "\x0701맞아. 기억해 줬구나.\n"
.stringn "너 좋은 녀석인걸.\n"
.stringn "\x0713……내용은?\n"
.stringn "\x0701저기, 네 노래로…\n"
.stringn "사막의 모래를,\n"
.stringn "흙으로 바꿔 줬으면 좋겠어.\n"
.stringn "\x0713모래를 흙…으로?\n"
.stringn "\x0701응. 싱싱한\n"
.stringn "작물이 잔뜩 자라는 흙.\n"
.stringn "그러면 거기에\n"
.stringn "우리들의 마을을 만들려고.\n"
.stringn "\x0713………말도 안 되는 소리.\n"
.stringn "주가는 그렇게 만능한 것이 아니다!\n"
.stringn "\x0701앗, 야!\n"
.stringn "…가 버렸잖아.\n"
.stringn "백로 민족은 화를 잘 내네.\n"
.stringn "저렇게나 착하게 생겼는데."
db 0
.align 4
//MYELL_8_RIEUSION_TOPUCK_B

//0x311E8
Text_311C8:
.stringn "\x05FL|RIEUSION|TOPUCK||\x0C01\x071-\x0713아, 백로 민족의 왕자다!\n"
.stringn "\x0701누구냐, 넌?\n"
.stringn "\x0713난 토팍이야.\n"
.stringn "나, 당신한테\n"
.stringn "물어보고 싶은 게 있어서.\n"
.stringn "\x0701당돌한 녀석이군.\n"
.stringn "물어볼 게 뭐지?\n"
.stringn "\x0713그 노래의 효과는 아무 데나 통하는 거야?\n"
.stringn "\x0701주가 말인가?\n"
.stringn "\x0713색이 없었던 숲을\n"
.stringn "한 방에 바꿔 버렸던 노래.\n"
.stringn "\x0701【재생】의 주가로군.\n"
.stringn "………그래서?\n"
.stringn "\x0713저기, 그거…\n"
.stringn "우리들을 위해서도\n"
.stringn "불러 주면 안 될까?\n"
.stringn "\x0701우리들?\n"
.stringn "\x0713응. 나랑\n"
.stringn "그라느 사막에서 기다리고 있는…\n"
.stringn "라구즈 동료들에게.\n"
.stringn "\x0701그럼, 네가…\n"
.stringn "라구즈 노예 해방군의 두목…\n"
.stringn "이런 어린아이였을 줄은.\n"
.stringn "\x0713…어린애면 안 되는 거냐구.\n"
.stringn "\x0701그런 뜻은 아니지만…\n"
.stringn "그 베그니온에서\n"
.stringn "라구즈를 돕기 위해 힘쓰는\n"
.stringn "베오크가 있다고 들어서\n"
.stringn "어떤 자인가 했는데…\n"
.stringn "상상과는 많이 다르군.\n"
.stringn "\x0713그것보다, 저기,\n"
.stringn "어떻게 할 거야.\n"
.stringn "도와주지 않을래?\n"
.stringn "\x0701라구즈를 위한 일이니\n"
.stringn "힘을 아낄 생각은 없다만…\n"
.stringn "대체 뭘 하면 되는 거지?\n"
.stringn "\x0713앗싸! 그러니까 말이지…\n"
.stringn "아, 근데 어떡하지?\n"
.stringn "\x0701?\n"
.stringn "\x0713나 아직\n"
.stringn "전투 준비를 안 했었어.\n"
.stringn "제대로 얘기하고 싶으니까\n"
.stringn "시간 날 때 올게.\n"
.stringn "그럼, 또 보자!\n"
.stringn "\x0701…베오크 아이는\n"
.stringn "꽤나 침착하지 못하군."
db 0
.align 4
//MYELL_8_RIEUSION_TOPUCK_C

//0x32238
Text_32218:
.stringn "\x05FL|SOANEVALCKE|SENERIO||\x070-\x0C01\x0C16\x0701머지않아 전쟁이 끝나겠군.\n"
.stringn "너는…\n"
.stringn "앞으로도 베오크들 사이에서\n"
.stringn "자신을 속이면서 살아갈 건가?\n"
.stringn "\x0716………저는,\n"
.stringn "역시… 【인붙이】인 걸까요?\n"
.stringn "\x0701틀림없다.\n"
.stringn "우리들은 동족을 알아볼 수 있어.\n"
.stringn "\x0716………\n"
.stringn "\x0701숨기는 동안에는 괜찮겠지.\n"
.stringn "그 인이 【정령의 부적】이 아닌 것을\n"
.stringn "알아보는 자는 거의 없다.\n"
.stringn "하지만… 시간 문제야.\n"
.stringn "\x0716………\n"
.stringn "\x0701어렴풋이 느끼고 있겠지만,\n"
.stringn "우리들은… 나이를 먹는 속도가\n"
.stringn "베오크들과는 다르다.\n"
.stringn "이어받은 라구즈의 피에 의해서인지…\n"
.stringn "대체로 성장이 느려지지.\n"
.stringn "\x0716…3년 정도 전까지는\n"
.stringn "평범하게 자라고 있다고……\n"
.stringn "……생각하고 있었는데.\n"
.stringn "\x0701더 이상 같은 장소에서 지낼 순 없다.\n"
.stringn "베오크들도 언젠가 알아차릴 테니까.\n"
.stringn "\x0716그래도…\n"
.stringn "저는 아이크의 곁에 있고 싶습니다.\n"
.stringn "\x0701………\n"
.stringn "어쩔 수 없는 상황이 되었을 땐,\n"
.stringn "그라느 사막으로 와라.\n"
.stringn "그곳에 너의 동료들이 있다는 걸\n"
.stringn "……잊지 마라.\n"
.stringn "\x0716……………"
db 0
.align 4
//MYELL_8_SENERIO_SOANVALCKE_A

//0x320AC
Text_3208C:
.stringn "\x05FL|SENERIO|SOANEVALCKE||\x0705………\n"
.stringn "\x071-\x0713베오크 무리에서 지내면서도\n"
.stringn "잘 적응하지 못한 모양이군.\n"
.stringn "\x0C05\x0701!!\n"
.stringn "또… 당신입니까.\n"
.stringn "\x0713그라느 사막에 있는\n"
.stringn "숨겨진 마을로 오지 않겠나?\n"
.stringn "너와 같은… 인을 가진 자들끼리\n"
.stringn "서로 기대며 살아가고 있다.\n"
.stringn "\x0701당신은… 뭔가 착각을\n"
.stringn "하고 있는 것 같습니다만……\n"
.stringn "어쨌든, 괜한 참견입니다.\n"
.stringn "…제가 있을 곳은……\n"
.stringn "……여기뿐이니까요.\n"
.stringn "\x0713그런가…\n"
.stringn "그럼, 강요하진 않겠다.\n"
.stringn "\x0701…………"
db 0
.align 4
//MYELL_8_SENERIO_SOANVALCKE_B

//0x31F80
Text_31F60:
.stringn "\x05FL|SENERIO|SOANEVALCKE||\x0C01\x0713………\n"
.stringn "\x0701……뭔가 용건이라도?\n"
.stringn "\x0713그렇게 경계하지 마라.\n"
.stringn "나는… 네 동료니까.\n"
.stringn "\x0701!!\n"
.stringn "\x0713……그 모습… 자신을 속이며\n"
.stringn "이방 안에서 살아온 것 같군.\n"
.stringn "\x0701…………\n"
.stringn "저, 저는……\n"
.stringn "\x0713느닷없이\n"
.stringn "말을 꺼냈으니 그야 당황했겠지.\n"
.stringn "일단 물러나겠다.\n"
.stringn "…나중에 천천히 얘기하자고.\n"
.stringn "\x0701………………"
db 0
.align 4
//MYELL_8_SENERIO_SOANVALCKE_C

//0x32CF4
Text_32CD4:
.stringn "\x05FL|STELLA|SOTHE||\x0C01\x0C13\x0701아…… 소더씨.\n"
.stringn "지난번에는\n"
.stringn "정말로 감사했습니다.\n"
.stringn "\x0713……별로,\n"
.stringn "몇 번이고 고맙다고 하지 마.\n"
.stringn "\x0701그렇지만……\n"
.stringn "\x0713너희들 귀족은 간단히\n"
.stringn "고맙다는 말을 안 할 줄 알았는데\n"
.stringn "……너는 다르구나.\n"
.stringn "\x0701그런가요?\n"
.stringn "\x0713그래.\n"
.stringn "귀족들은 우리들 평민을 짓밟고\n"
.stringn "자기들만 태평하게 잘 살고 있잖아.\n"
.stringn "태어날 때부터 그걸\n"
.stringn "당연하게 생각하고 있고…\n"
.stringn "죽을 때까지 먹을 것과 잘 곳을\n"
.stringn "고민할 필요도 없지……\n"
.stringn "정말이지, 부러운 신분이야.\n"
.stringn "\x0701그렇지만, 자유는 없습니다……\n"
.stringn "제 오빠들은 군인으로서 집안의 자랑이\n"
.stringn "되어 빛나는 삶을 살고 있어요.\n"
.stringn "하지만 언니들은 모두 얼굴도 모르는\n"
.stringn "상대의 집에 시집을 갑니다……\n"
.stringn "거기에 사랑은 없고, 울며 지낸다는 편지를\n"
.stringn "몇 년마다 한 번씩 받을 뿐이죠……\n"
.stringn "여자는 가문의 권력을 잇는 도구에 불과합니다.\n"
.stringn "\x0713…………\n"
.stringn "너도……\n"
.stringn "그렇게 될 운명이었다는 거고……\n"
.stringn "\x0701네…… 하지만 그게 자신의 운명이라며\n"
.stringn "포기하고 싶지는 않았어요.\n"
.stringn "그러니까 저는…… 이 싸움이 끝날 때까지\n"
.stringn "이곳을 떠날 생각이 없습니다.\n"
.stringn "\x0713……그렇구나.\n"
.stringn "넌 내가 아는 귀족과는 전혀 다르네.\n"
.stringn "요즘 계속 네가 노력하는 걸 보고\n"
.stringn "그런 생각이 들었어.\n"
.stringn "열심히 노력하면 살려고 하는 게\n"
.stringn "우리랑 똑같아. 아무것도 다르지 않아.\n"
.stringn "귀족의 변덕이라고 생각해서 미안했다.\n"
.stringn "\x0701가……감사합니다……\n"
.stringn "\x0713앞으로도 힘내 줘.\n"
.stringn "스스로 자신의 인생을 쟁취하기 위해서.\n"
.stringn "\x0701……네!"
db 0
.align 4
//MYELL_8_SOTHE_STELLA_A

//0x32854
Text_32834:
.stringn "\x05FL|STELLA|SOTHE||\x070-\x0C01\x0C13\x0701아…… 여기는……?\n"
.stringn "\x0713…………\n"
.stringn "\x0701저, 어떻게 된 거죠……?\n"
.stringn "\x0713너, 쓰러져 있었어.\n"
.stringn "그냥 놔두려고 했는데……\n"
.stringn "왠지 신경 쓰여서.\n"
.stringn "\x0701죄송합니다……\n"
.stringn "\x0713내 알 바는 아니지만……\n"
.stringn "너, 무리하는 거 아니야?\n"
.stringn "행군을 따라가는 것도 힘든 것 같고,\n"
.stringn "그 상태로는 몸이 망가질걸.\n"
.stringn "\x0701죄송합니다……\n"
.stringn "싸움은……\n"
.stringn "이렇게나 가혹하군요.\n"
.stringn "매일 힘든 행군이 계속되고……\n"
.stringn "적의 습격에 겁을 먹어서\n"
.stringn "밤에 안심하고 잘 수도 없어요…\n"
.stringn "자신의 나약함을 뼈저리게 느끼고 있습니다…\n"
.stringn "\x0713……아가씨 주제에 무리하니까 그런 거야.\n"
.stringn "여기에 너를\n"
.stringn "모시는 집사나 시녀는 없어.\n"
.stringn "집으로 돌아가면 지금까지처럼\n"
.stringn "아무 불편 없이 살 수 있을걸.\n"
.stringn "\x0701……아무 불편 없이, 인가요.\n"
.stringn "하지만 저택으로 돌아가면……\n"
.stringn "제게 자유는 없습니다.\n"
.stringn "\x0713……?\n"
.stringn "\x0701제게는 부모님이 정해 주신 약혼자가 있습니다.\n"
.stringn "상대는 저보다 30살이나 연상이죠……\n"
.stringn "제 아버지보다 연세가 많으신 분이에요.\n"
.stringn "\x0713……\n"
.stringn "\x0701저는…… 자신의 의지로 살고 싶어서\n"
.stringn "베그니온 기사단에 지원했습니다……\n"
.stringn "가족들에게 격렬하게 반대받았습니다만……\n"
.stringn "오래 갈 리가 없다고 생각하셨나 봐요.\n"
.stringn "곤란해하면서 집으로\n"
.stringn "돌아올 것이 틀림없다고……\n"
.stringn "그러니까…… 아직, 돌아갈 수는 없습니다.\n"
.stringn "\x0713…………\n"
.stringn "……나랑은 관계없어.\n"
.stringn "그러니까 네 마음대로 하면 돼.\n"
.stringn "\x0701네…… 감사합니다."
db 0
.align 4
//MYELL_8_SOTHE_STELLA_B

//0x32544
Text_32524:
.stringn "\x05FL|STELLA|SOTHE||\x070-\x0C01\x0C13\x0701소더씨.\n"
.stringn "무기 손질 중이신가요?\n"
.stringn "\x0713어, 그렇긴 한데.\n"
.stringn "\x0701저기……\n"
.stringn "잠깐 괜찮으신가요?\n"
.stringn "\x0713? 나한테 무슨 볼일 있어?\n"
.stringn "\x0701소더씨는 단검을 사용하시죠?\n"
.stringn "확실히…… 검은 도끼에 강한 무기죠.\n"
.stringn "그럼… 도끼는 대체 어떤 무기에\n"
.stringn "유효한가요?\n"
.stringn "\x0713……너, 그런 것도 모르면서\n"
.stringn "용병을 하고 있는 거야?\n"
.stringn "\x0701네, 네에…… 죄송합니다.\n"
.stringn "용병이 된 지 아직 얼마 안 됐고……\n"
.stringn "저는 활을 사용하니까요……\n"
.stringn "\x0713흐~음……\n"
.stringn "너, 용병이 되기 전에는 뭘 했었는데?\n"
.stringn "\x0701아, 아무것도…… 하지 않았습니다.\n"
.stringn "\x0713아무것도? 아무것도 안 하고\n"
.stringn "먹고살 수 있을 리가 없잖아.\n"
.stringn "…………혹시……\n"
.stringn "너, 귀족이야?\n"
.stringn "그 말투도 그렇고, 무지한 것도 그렇고…\n"
.stringn "……잘나신 귀족님께서 왜 이런 싸움에?\n"
.stringn "\x0701………………\n"
.stringn "\x0713……하긴, 내가 물을 게 아닌가.\n"
.stringn "뭐…… 괜찮겠지.\n"
.stringn "귀족의 취미로는."
db 0
.align 4
//MYELL_8_SOTHE_STELLA_C

//0x33520
Text_33500:
.stringn "\x05FL|TOPUCK|SOTHE||\x0C01\x0C13\x0701아.\n"
.stringn "\x0713아직도 포기 안 한 거야?\n"
.stringn "끈질겨…\n"
.stringn "\x0701그렇게 싫으면\n"
.stringn "이제 부탁 안 할 거야!\n"
.stringn "너 따윈 됐어, 저리로 가 버려!!\n"
.stringn "\x0713……뭔데.\n"
.stringn "왜 그렇게\n"
.stringn "친구에 집착하는 거야?\n"
.stringn "\x0701무와림이 걱정한단 말이야…\n"
.stringn "\x0713무와림?\n"
.stringn "아아… 그 호랑이.\n"
.stringn "\x0701나한테…\n"
.stringn "베오크 친구가 없는 게\n"
.stringn "자기 탓이라면서\n"
.stringn "괴로운 얼굴을 하고 있으니까…\n"
.stringn "그래서, 너랑 친구가 돼서\n"
.stringn "기쁘게 해 주고 싶었어.\n"
.stringn "\x0713그런 거였구만.\n"
.stringn "그렇다면 처음부터 그렇게 말하라고.\n"
.stringn "\x0701그럼 친구해 주는 거지!?\n"
.stringn "\x0713그래.\n"
.stringn "\x0701…갑자기 왜?\n"
.stringn "\x0713키워 준 부모 같은 존재잖아?\n"
.stringn "걱정시키고 싶지 않은 마음이라면\n"
.stringn "잘 아니까.\n"
.stringn "나도… 부모 대신\n"
.stringn "굉장히 소중한 사람이 있고……\n"
.stringn "\x0701그렇구나!\n"
.stringn "너도 그런 거구나!?\n"
.stringn "헤헤, 뭔가 친근한걸.\n"
.stringn "\x0713협력은 하겠지만,\n"
.stringn "진짜 친구가 되는 건 아니니까\n"
.stringn "그럴 상황이 아닐 땐\n"
.stringn "끈적대지 마라?\n"
.stringn "\x0701뭐야.\n"
.stringn "어차피 하는 거\n"
.stringn "제대로 친구하자고!\n"
.stringn "\x0713싫어."
db 0
.align 4
//MYELL_8_SOTHE_TOPUCK_A_a

//0x33868
Text_33848:
.stringn "\x05FL|TOPUCK|SOTHE||\x0C01\x0C13\x0701아.\n"
.stringn "\x0713아직도 포기 안 한 거야?\n"
.stringn "끈질겨…\n"
.stringn "\x0701그렇게 싫으면\n"
.stringn "이제 부탁 안 할 거야!\n"
.stringn "너 따윈 됐어, 저리로 가 버려!!\n"
.stringn "\x0713……뭔데.\n"
.stringn "왜 그렇게\n"
.stringn "친구에 집착하는 거야?\n"
.stringn "\x0701무와림이 걱정한단 말이야…\n"
.stringn "\x0713무와림?\n"
.stringn "아아… 그 호랑이.\n"
.stringn "\x0701아직, 살아 있었을 때……\n"
.stringn "나한테… 베오크 친구가 없는 게\n"
.stringn "자기 탓이라면서 엄청 걱정했거든.\n"
.stringn "그러니까 만약, 너하고 친구가 된다면…\n"
.stringn "그 녀석도 안심할 것 같아서.\n"
.stringn "\x0713그런 거였구만.\n"
.stringn "그렇다면 처음부터 그렇게 말하라고.\n"
.stringn "\x0701그럼 친구해 주는 거지!?\n"
.stringn "\x0713그래.\n"
.stringn "\x0701…갑자기 왜?\n"
.stringn "\x0713키워 준 부모 같은 존재잖아?\n"
.stringn "걱정시키고 싶지 않은 마음이라면\n"
.stringn "잘 아니까.\n"
.stringn "나도… 부모 대신\n"
.stringn "굉장히 소중한 사람이 있고……\n"
.stringn "\x0701그렇구나!\n"
.stringn "너도 그런 거구나!?\n"
.stringn "헤헤, 뭔가 친근한걸.\n"
.stringn "\x0713협력은 하겠지만,\n"
.stringn "진짜 친구가 되는 건 아니니까\n"
.stringn "그럴 상황이 아닐 땐\n"
.stringn "끈적대지 마라?\n"
.stringn "\x0701뭐야.\n"
.stringn "어차피 하는 거\n"
.stringn "제대로 친구하자고!\n"
.stringn "\x0713싫어."
db 0
.align 4
//MYELL_8_SOTHE_TOPUCK_A_b

//0x333FC
Text_333DC:
.stringn "\x05FL|SOTHE|TOPUCK||\x0C05\x0713야.\n"
.stringn "\x0705……\n"
.stringn "\x0713우리\n"
.stringn "나이도 비슷하잖아~\n"
.stringn "모처럼이니까 사이좋게 지내자고.\n"
.stringn "\x0705친분을 쌓는 건 좋아하지 않아.\n"
.stringn "\x0713너는 그렇겠지만 말이야~\n"
.stringn "나는 너랑\n"
.stringn "친구가 되고 싶다구.\n"
.stringn "\x0705……내 알 바 아니야.\n"
.stringn "\x0713뭐야!\n"
.stringn "적당히 해야 될 거 아니야,\n"
.stringn "닳는 것도 아닌데!!"
db 0
.align 4
//MYELL_8_SOTHE_TOPUCK_B

//0x33200
Text_331E0:
.stringn "\x05FL|SOTHE|TOPUCK||\x0C01\x071-\x0713앗, 너.\n"
.stringn "야, 저번에\n"
.stringn "나랑 임무 같이 했었지?\n"
.stringn "\x0701……기억 안 나.\n"
.stringn "\x0713뭐야……\n"
.stringn "난 기억하고 있었는데.\n"
.stringn "그렇게 작은 무기로\n"
.stringn "적이랑 대등하게 싸웠잖아?\n"
.stringn "나랑 나이가 비슷해 보이는데\n"
.stringn "굉장하다고 생각했어.\n"
.stringn "아, 난 토팍이라고 해.\n"
.stringn "이래 봬도\n"
.stringn "남 못지 않은 마법사라구.\n"
.stringn "\x0701……\n"
.stringn "\x0713네 이름은?\n"
.stringn "\x0701……소더.\n"
.stringn "\x0713소더구나! 잘 부탁해!\n"
.stringn "근데 소더는\n"
.stringn "왜 여기서 용병 일을 하고 있는 거야?\n"
.stringn "\x0701……말 안 하고 싶은데.\n"
.stringn "\x0713야, 야!\n"
.stringn "뭐야 저 녀석.\n"
.stringn "완전 재수 없잖아!!"
db 0
.align 4
//MYELL_8_SOTHE_TOPUCK_C

//0x340C0
Text_340A0:
.stringn "\x05FL|ULYSSES|VOLKE||\x0C01\x0713무슨 일이지…\n"
.stringn "아직도 내게 볼일이 있는 건가?\n"
.stringn "\x0701아이크 장군과의\n"
.stringn "계약이 종료되는 것은 언제지?\n"
.stringn "\x0713왜 그걸 묻는 거냐.\n"
.stringn "\x0701의뢰하고 싶은 일이 생겼다네.\n"
.stringn "…자네밖에 할 수 없는 일이야.\n"
.stringn "\x0713당신을 잘 안다고 생각했는데…\n"
.stringn "그렇게 다급한 듯한 표정은…\n"
.stringn "처음 보는군.\n"
.stringn "\x070120만이다.\n"
.stringn "\x0713?\n"
.stringn "\x070120만을 준비하지.\n"
.stringn "즉시 일에 들어가 주게.\n"
.stringn "\x0713공교롭게도…\n"
.stringn "나는 겸업을 할 생각은 없다.\n"
.stringn "물론, 지금 맡고 있는 일을\n"
.stringn "중간에 관둘 생각도 없지.\n"
.stringn "\x0701……\n"
.stringn "\x0713…얼마 남지 않았다.\n"
.stringn "이 싸움이 마무리되면…\n"
.stringn "나와 아이크의 계약은 끝나지.\n"
.stringn "어떤 식으로든… 말이다.\n"
.stringn "그렇게 자유로운 몸이 된다면…\n"
.stringn "이 발로 직접 당신이 있는 곳에\n"
.stringn "용건을 들으러 가 주마.\n"
.stringn "\x0701…무슨 바람이 분 건가?\n"
.stringn "\x0713페일 백작,\n"
.stringn "나는 당신이 마음에 든다.\n"
.stringn "당신의 일을 끝내고 돈을\n"
.stringn "제때 받지 못한 적은 단 한 번도 없었지.\n"
.stringn "\x0701내가 우수한 고용주란 말인가.\n"
.stringn "칭찬을 받으니 영광이군.\n"
.stringn "그럼, 어쨌든\n"
.stringn "이 싸움을 끝내는 수밖에 없겠군.\n"
.stringn "자네를 기다리고 있는 다음 일도…\n"
.stringn "매우 시급한 일이니 말일세."
db 0
.align 4
//MYELL_8_ULYSSES_VOKE_A

//0x33E5C
Text_33E3C:
.stringn "\x05FL|VOLKE|ULYSSES||\x070-\x0C01\x071-\x0C13\x0701…빠르군.\n"
.stringn "\x0713여러 가지 유익한 정보를 얻을 수 있었네.\n"
.stringn "대부분은 지난번에\n"
.stringn "공주님께서 아이크 장군에게\n"
.stringn "들으셨다고 하는 정보와 일치하지만…\n"
.stringn "듣지도 못했던 세세한 사실들까지\n"
.stringn "어느 것이나 참… 흥미롭군.\n"
.stringn "\x0701당신에게는…\n"
.stringn "눈에 불을 켜고 달려들 만한 것들뿐인가.\n"
.stringn "\x0713아무튼, 이걸로 자네와\n"
.stringn "아이크 장군에 대한 의심은…\n"
.stringn "일단 거두었다고 해 두지.\n"
.stringn "\x0701그것참 고맙군.\n"
.stringn "\x0713할 이야기는 그것뿐이네.\n"
.stringn "\x0701…페일 백작.\n"
.stringn "\x0713뭔가?\n"
.stringn "\x0701아무래도 당신에게는…\n"
.stringn "지금 있는 곳보다는 어둠의 세계가\n"
.stringn "어울리는 것 같은데.\n"
.stringn "이번 기회에\n"
.stringn "이쪽으로 오지 않겠나?\n"
.stringn "\x0713내 충성과 헌신은\n"
.stringn "언제나 크리미아 왕가와 함께할 것이네.\n"
.stringn "\x0701………"
db 0
.align 4
//MYELL_8_ULYSSES_VOKE_B

//0x33BD8
Text_33BB8:
.stringn "\x05FL|VOLKE|ULYSSES||\x0701…………\n"
.stringn "거기 숨어 있는 남자.\n"
.stringn "다섯을 다 세기 전에 나와라.\n"
.stringn "5, 4, 3…\n"
.stringn "\x0713…대단하군.\n"
.stringn "과연 【불 끄는 자】.\n"
.stringn "이 거리에서 나를 알아차릴 줄이야.\n"
.stringn "\x0701페일 백작…\n"
.stringn "당신이었나.\n"
.stringn "\x0713이런 곳에서\n"
.stringn "자네의 모습을 보게 되다니\n"
.stringn "생각도 못 했다네.\n"
.stringn "…누구 밑에서 움직이고 있는 거지?\n"
.stringn "\x0701당신이라면\n"
.stringn "이미 조사를 끝냈을 텐데.\n"
.stringn "그걸 믿으면 된다.\n"
.stringn "\x0713진실이라… 아이크 장군 밑에서\n"
.stringn "크리미아를 위해\n"
.stringn "일하고 있다는 건가?\n"
.stringn "\x0701정확히는,\n"
.stringn "아이크 개인의 아래서다.\n"
.stringn "\x0713어째서지?\n"
.stringn "\x070110만이다.\n"
.stringn "\x071310만?\n"
.stringn "\x0701대답의 대가다.\n"
.stringn "\x0713훗,\n"
.stringn "그 액수를 제시한 시점에서\n"
.stringn "대답할 생각은 없는 것이로군.\n"
.stringn "\x0701……\n"
.stringn "\x0713아이크 장군…\n"
.stringn "저 남자를 그림자로 삼아\n"
.stringn "무슨 일을 꾸미고 있는 건지……\n"
.stringn "시급히 조사할 필요가 있겠어."
db 0
.align 4
//MYELL_8_ULYSSES_VOKE_C

